mod tpch_rules;

fn tpch_profile_enabled() -> bool {
    std::env::var("DODAM_TPCH_PROFILE")
        .is_ok_and(|value| matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES"))
}

fn tpch_profile_start() -> Option<Instant> {
    tpch_profile_enabled().then(Instant::now)
}

fn tpch_profile_elapsed(label: &str, started: Option<Instant>) {
    if let Some(started) = started {
        eprintln!(
            "[dodam:tpch-profile] {label}: {:.3} ms",
            started.elapsed().as_secs_f64() * 1000.0
        );
    }
}

fn sql_elapsed_nanos(started: Instant) -> u64 {
    started.elapsed().as_nanos().min(u64::MAX as u128) as u64
}

fn sql_nanos_to_millis(nanos: u64) -> f64 {
    nanos as f64 / 1_000_000.0
}

const DEFAULT_MAX_DENSE_I64_KEY: usize = 20_000_000;
const DEFAULT_Q09_ORDER_YEAR_DENSE_BYTES: usize = 384 * 1024 * 1024;

#[derive(Debug)]
pub enum QueryOutput {
    Scan {
        batches: Vec<RecordBatch>,
    },
    Aggregate {
        metrics: AggregateMetrics,
        batches: Vec<RecordBatch>,
    },
    Explain {
        plan: String,
    },
}

pub trait SqlResultSink {
    fn record_batch_sink(&mut self) -> &mut dyn RecordBatchSink;
    fn write_output(&mut self, output: QueryOutput) -> Result<()>;
}

#[derive(Debug, Clone, Copy)]
pub struct SqlSinkExecutionOptions {
    pub allow_direct_or_streaming: bool,
}

impl Default for SqlSinkExecutionOptions {
    fn default() -> Self {
        Self {
            allow_direct_or_streaming: true,
        }
    }
}

#[derive(Debug, Default)]
pub struct SqlSinkExecutionProfile {
    pub direct_sink: Option<Duration>,
    pub streaming: Option<Duration>,
    pub execute: Option<Duration>,
    pub write_output: Option<Duration>,
    pub scan_plan_metrics: Option<ScanPlanMetrics>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct SqlQuery {
    path: PathBuf,
    join: Option<SqlJoin>,
    projection: Projection,
    filter: Option<FilterExpr>,
    expression_filter: Option<SqlExpr>,
    having: Option<FilterExpr>,
    order_by: Option<SortKey>,
    limit: Option<usize>,
    offset: usize,
    distinct: bool,
    aggregates: Vec<AggregateExpr>,
    filtered_aggregates: Vec<NativeFilteredAggregateSpec>,
    aggregate_expressions: Vec<ProjectionExpression>,
    expressions: Vec<ProjectionExpression>,
    group_by: Vec<String>,
    aliases: Vec<(String, String)>,
    qualified_wildcards: Vec<String>,
}

#[derive(Debug, Clone, PartialEq)]
struct SqlJoin {
    right: SqlTableRef,
    left_alias: String,
    right_alias: String,
    left_keys: Vec<String>,
    right_keys: Vec<String>,
    right_filter: Option<FilterExpr>,
    join_type: JoinType,
}

impl SqlQuery {
    pub fn is_aggregate(&self) -> bool {
        !self.aggregates.is_empty()
    }
}

pub fn parse_sql(input: &str) -> Result<SqlQuery> {
    let dialect = GenericDialect {};
    let statements = Parser::parse_sql(&dialect, input)
        .map_err(|error| DodamError::UnsupportedSql(error.to_string()))?;
    let [statement] = statements.as_slice() else {
        return Err(DodamError::UnsupportedSql(
            "expected exactly one statement".to_string(),
        ));
    };

    let Statement::Query(query) = statement else {
        return Err(DodamError::UnsupportedSql(
            "only SELECT queries are supported".to_string(),
        ));
    };
    parse_query(query)
}

pub async fn execute_sql(
    engine: &DodamEngine,
    sql: &str,
    batch_size: usize,
) -> Result<QueryOutput> {
    if let Some(plan) = explain_sql(engine, sql, batch_size).await? {
        return Ok(QueryOutput::Explain { plan });
    }
    if let Some(output) = try_execute_set_operation_sql(engine, sql, batch_size).await? {
        return Ok(output);
    }
    if let Some(output) = try_execute_window_sql(engine, sql, batch_size).await? {
        return Ok(output);
    }
    if let Some(output) = try_execute_registered_sql_rules(engine, sql, batch_size).await? {
        return Ok(output);
    }
    let query = parse_sql(sql)?;
    if let Some(join) = query.join.clone() {
        let is_aggregate = query.is_aggregate();
        let aggregates = query.aggregates.clone();
        let group_by = query.group_by.clone();
        let join_input_projection = if query.qualified_wildcards.is_empty() {
            join_input_projection_with_expression_filter(&query)?
        } else {
            Projection::All
        };
        let projection_requires_expression =
            projection_requires_expression_path(&query.expressions);
        let input_order_by = if projection_requires_expression {
            None
        } else {
            query.order_by.as_ref()
        };
        let join_plan = plan_join_inputs(
            &join_input_projection,
            query.filter.as_ref(),
            input_order_by,
            &join.left_alias,
            &join.left_keys,
            &join.right_alias,
            &join.right_keys,
        );
        if is_aggregate
            && let Some(output) = try_execute_join_coalesce_count_sum_aggregate(
                engine, &query, &join, &join_plan, batch_size,
            )
            .await?
        {
            return Ok(output);
        }
        let output_projection = pushed_join_output_projection(&query)?;
        let output_projection_is_final = output_projection == query.projection;
        let stream = engine
            .join_parquet_batches(JoinParquetRequest {
                left_path: query.path.clone(),
                right_path: join.right.path,
                batch_size,
                left_keys: join.left_keys,
                right_keys: join.right_keys,
                left_prefix: join.left_alias.clone(),
                right_prefix: join.right_alias.clone(),
                left_projection: join_plan.left_projection,
                right_projection: join_plan.right_projection,
                left_filter: join_plan.left_filter,
                right_filter: combine_filter_options(
                    join_plan.right_filter,
                    join.right_filter.clone(),
                ),
                output_projection,
                join_memory_limit_bytes: default_join_memory_limit_bytes(),
                join_algorithm: JoinAlgorithm::Auto,
                join_type: join.join_type,
            })
            .await?;
        if is_aggregate {
            let stream = apply_output_filter_stream(stream, query.filter.clone());
            let stream: SendableBatchStream =
                if let Some(expression_filter) = query.expression_filter.as_ref() {
                    Box::new(MemoryExec::new(apply_output_join_expression_filter(
                        collect_batches(stream)?,
                        expression_filter,
                        &[join.left_alias.as_str(), join.right_alias.as_str()],
                    )?))
                    .execute()?
                } else {
                    stream
                };
            let metrics = collect_aggregates_with_optional_expression_views(
                stream,
                2,
                &group_by,
                &aggregates,
                &query.filtered_aggregates,
                &query.aggregate_expressions,
            )?;
            let mut batches = aggregate_metrics_to_batches(&metrics, &group_by, &aggregates)?;
            batches = apply_output_filter(batches, query.having.as_ref())?;
            let has_output_expressions = projection_requires_expression_path(&query.expressions);
            if has_output_expressions {
                batches = apply_output_expression_projection(batches, &query.expressions)?;
            }
            batches = apply_aggregate_output_order_limit(
                batches,
                query.order_by.as_ref(),
                query.limit,
                query.offset,
                &metrics,
                &group_by,
            )?;
            if !has_output_expressions {
                batches = rename_output_batches(batches, &query.aliases)?;
            }
            return Ok(QueryOutput::Aggregate { metrics, batches });
        }
        let mut batches = collect_batches(stream)?;
        batches = apply_output_filter(batches, query.filter.as_ref())?;
        if let Some(expression_filter) = query.expression_filter.as_ref() {
            batches = apply_output_join_expression_filter(
                batches,
                expression_filter,
                &[join.left_alias.as_str(), join.right_alias.as_str()],
            )?;
        }
        if projection_requires_expression {
            if query.distinct {
                batches = apply_output_expression_projection(batches, &query.expressions)?;
                batches = apply_output_distinct(batches, true)?;
                batches = apply_output_order_limit(
                    batches,
                    query.order_by.as_ref(),
                    query.limit,
                    query.offset,
                )?;
            } else {
                batches = apply_output_expression_projection_order_limit(
                    batches,
                    &query.expressions,
                    query.order_by.as_ref(),
                    query.limit,
                    query.offset,
                )?;
            }
        } else {
            if query.distinct {
                if !output_projection_is_final && query.qualified_wildcards.is_empty() {
                    batches = apply_output_projection(batches, &query.projection)?;
                }
                batches = apply_output_distinct(batches, true)?;
                batches = apply_output_order_limit(
                    batches,
                    query.order_by.as_ref(),
                    query.limit,
                    query.offset,
                )?;
            } else {
                batches = apply_output_order_limit(
                    batches,
                    query.order_by.as_ref(),
                    query.limit,
                    query.offset,
                )?;
                if !output_projection_is_final && query.qualified_wildcards.is_empty() {
                    batches = apply_output_projection(batches, &query.projection)?;
                }
            }
        }
        if !query.qualified_wildcards.is_empty() {
            batches = apply_qualified_wildcard_projection(
                batches,
                &query.qualified_wildcards,
                &query.projection,
            )?;
        }
        if !projection_requires_expression {
            batches = rename_output_batches(batches, &query.aliases)?;
        }
        return Ok(QueryOutput::Scan { batches });
    }

    if query.is_aggregate() {
        let aggregates = query.aggregates.clone();
        let group_by = query.group_by.clone();
        let metrics =
            if !query.aggregate_expressions.is_empty() || !query.filtered_aggregates.is_empty() {
                if let Some(metrics) = try_collect_expression_aggregate_fused_dictionary_selected(
                    engine,
                    query.path.clone(),
                    batch_size,
                    query.filter.clone(),
                    &group_by,
                    &aggregates,
                    &query.aggregate_expressions,
                    query.order_by.is_some(),
                    expression_aggregate_output_limit(
                        &group_by,
                        query.order_by.as_ref(),
                        query.limit,
                        query.offset,
                    ),
                )
                .await?
                {
                    metrics
                } else if let Some(metrics) = try_collect_expression_aggregate_late_materialized(
                    engine,
                    query.path.clone(),
                    batch_size,
                    query.filter.clone(),
                    &group_by,
                    &aggregates,
                    &query.aggregate_expressions,
                    query.order_by.is_some(),
                    expression_aggregate_output_limit(
                        &group_by,
                        query.order_by.as_ref(),
                        query.limit,
                        query.offset,
                    ),
                )
                .await?
                {
                    metrics
                } else if let Some(metrics) = try_collect_expression_aggregate_scan_fold(
                    engine,
                    query.path.clone(),
                    batch_size,
                    query.projection.clone(),
                    query.filter.clone(),
                    &group_by,
                    &aggregates,
                    &query.aggregate_expressions,
                    query.order_by.is_some(),
                    expression_aggregate_output_limit(
                        &group_by,
                        query.order_by.as_ref(),
                        query.limit,
                        query.offset,
                    ),
                )
                .await?
                {
                    metrics
                } else if let Some(metrics) = try_collect_expression_aggregate_row_group_map(
                    engine,
                    query.path.clone(),
                    batch_size,
                    query.projection.clone(),
                    query.filter.clone(),
                    &group_by,
                    &aggregates,
                    &query.aggregate_expressions,
                )
                .await?
                {
                    metrics
                } else {
                    let stream = engine
                        .scan_parquet_batches(
                            query.path,
                            batch_size,
                            None,
                            query.projection.clone(),
                            query.filter,
                        )
                        .await?;
                    collect_aggregates_with_optional_expression_views(
                        stream,
                        1,
                        &group_by,
                        &aggregates,
                        &query.filtered_aggregates,
                        &query.aggregate_expressions,
                    )?
                }
            } else if query.group_by.is_empty() {
                engine
                    .aggregate_parquet(query.path, batch_size, aggregates.clone(), query.filter)
                    .await?
            } else {
                engine
                    .aggregate_parquet_grouped(
                        query.path,
                        batch_size,
                        aggregates.clone(),
                        group_by.clone(),
                        query.filter,
                    )
                    .await?
            };
        let mut batches = aggregate_metrics_to_batches(&metrics, &group_by, &aggregates)?;
        batches = apply_output_filter(batches, query.having.as_ref())?;
        let has_output_expressions = projection_requires_expression_path(&query.expressions);
        if has_output_expressions {
            batches = apply_output_expression_projection(batches, &query.expressions)?;
        }
        batches = apply_aggregate_output_order_limit(
            batches,
            query.order_by.as_ref(),
            query.limit,
            query.offset,
            &metrics,
            &group_by,
        )?;
        if !has_output_expressions {
            batches = rename_output_batches(batches, &query.aliases)?;
        }
        return Ok(QueryOutput::Aggregate { metrics, batches });
    }

    if query.distinct
        && let Some(mut batches) = try_execute_direct_distinct_scan(
            engine,
            DirectDistinctScan {
                path: query.path.clone(),
                projection: query.projection.clone(),
                aliases: query.aliases.clone(),
                filter: query.filter.clone(),
            },
            batch_size,
        )?
    {
        batches =
            apply_output_order_limit(batches, query.order_by.as_ref(), query.limit, query.offset)?;
        return Ok(QueryOutput::Scan { batches });
    }

    if let Some(batches) =
        try_execute_monotonic_row_group_order_limit_scan(engine, &query, batch_size).await?
    {
        let batches = rename_output_batches(batches, &query.aliases)?;
        return Ok(QueryOutput::Scan { batches });
    }

    if !query.distinct
        && monotonic_order_limit_scan_enabled()
        && query.limit.is_some()
        && Path::new(&query.path).exists()
        && let Some(column) = monotonic_stream_limit_column(query.order_by.as_ref())
        && engine
            .parquet_row_groups_monotonic_by_column(query.path.clone(), &column)
            .await?
        && engine
            .parquet_column_monotonic_by_scan(query.path.clone(), &column, batch_size)
            .await?
    {
        let stream = engine
            .scan_parquet_filtered_batches_preserve_order(
                query.path.clone(),
                batch_size,
                query.projection.clone(),
                query.filter.clone(),
            )
            .await?;
        let batches = collect_ordered_stream_limit_batches(stream, query.limit, query.offset)?;
        let batches = rename_output_batches(batches, &query.aliases)?;
        return Ok(QueryOutput::Scan { batches });
    }

    let stream = if query.distinct {
        engine
            .scan_parquet_distinct_batches(
                query.path,
                batch_size,
                scan_limit_with_offset(query.limit, query.offset)?,
                query.projection,
                query.filter,
                query.order_by,
            )
            .await?
    } else if let Some(order_by) = query.order_by {
        engine
            .scan_parquet_ordered_batches_by(
                query.path,
                batch_size,
                scan_limit_with_offset(query.limit, query.offset)?,
                query.projection,
                query.filter,
                order_by,
            )
            .await?
    } else {
        engine
            .scan_parquet_batches(
                query.path,
                batch_size,
                scan_limit_with_offset(query.limit, query.offset)?,
                query.projection,
                query.filter,
            )
            .await?
    };
    let batches =
        apply_output_order_limit(collect_batches(stream)?, None, query.limit, query.offset)?;
    let batches = rename_output_batches(batches, &query.aliases)?;
    Ok(QueryOutput::Scan { batches })
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum SqlRule {
    Tpch,
    WithCte,
    PricingSummary,
    ProfitByNationYear,
    ReturnedCustomerRevenue,
    ImportantStockValue,
    RegionalSupplierRevenue,
    BilateralShippingVolume,
    NationMarketShare,
    DiscountedRevenueOrPredicate,
    OrderPriorityExistsCount,
    ShippingPriorityRevenue,
    DerivedPrefixAvgAntiJoinAggregate,
    JoinWithGroupedSumSemijoin,
    JoinWithCorrelatedAvgThreshold,
    ShippingModePriorityCounts,
    SupplierWaitCountAntijoin,
    PrefixPartSupplierThreshold,
    DerivedJoin,
    DerivedLeftJoinCountDistribution,
    Derived,
    CorrelatedJoinSubqueryFilter,
    MaterializedJoinSubquery,
    MultiCommaJoin,
    CorrelatedExistsSemijoin,
    CorrelatedInPairSemijoin,
    CorrelatedSubqueryFilter,
    CorrelatedExistsSubquery,
    ExistsSubquery,
    InSubquery,
    ProjectionExpression,
}

impl SqlRule {
    fn name(self) -> &'static str {
        match self {
            Self::Tpch => "tpch-rule-set",
            Self::WithCte => "with-cte",
            Self::PricingSummary => "pricing-summary",
            Self::ProfitByNationYear => "profit-by-nation-year",
            Self::ReturnedCustomerRevenue => "returned-customer-revenue",
            Self::ImportantStockValue => "important-stock-value",
            Self::RegionalSupplierRevenue => "regional-supplier-revenue",
            Self::BilateralShippingVolume => "bilateral-shipping-volume",
            Self::NationMarketShare => "nation-market-share",
            Self::DiscountedRevenueOrPredicate => "discounted-revenue-or-predicate",
            Self::OrderPriorityExistsCount => "order-priority-exists-count",
            Self::ShippingPriorityRevenue => "shipping-priority-revenue",
            Self::DerivedPrefixAvgAntiJoinAggregate => "derived-prefix-avg-anti-join-aggregate",
            Self::JoinWithGroupedSumSemijoin => "join-with-grouped-sum-semijoin",
            Self::JoinWithCorrelatedAvgThreshold => "join-with-correlated-avg-threshold",
            Self::ShippingModePriorityCounts => "shipping-mode-priority-counts",
            Self::SupplierWaitCountAntijoin => "supplier-wait-count-antijoin",
            Self::PrefixPartSupplierThreshold => "prefix-part-supplier-threshold",
            Self::DerivedJoin => "derived-join",
            Self::DerivedLeftJoinCountDistribution => "derived-left-join-count-distribution",
            Self::Derived => "derived",
            Self::CorrelatedJoinSubqueryFilter => "correlated-join-subquery-filter",
            Self::MaterializedJoinSubquery => "materialized-join-subquery",
            Self::MultiCommaJoin => "multi-comma-join",
            Self::CorrelatedExistsSemijoin => "correlated-exists-semijoin",
            Self::CorrelatedInPairSemijoin => "correlated-in-pair-semijoin",
            Self::CorrelatedSubqueryFilter => "correlated-subquery-filter",
            Self::CorrelatedExistsSubquery => "correlated-exists-subquery",
            Self::ExistsSubquery => "exists-subquery",
            Self::InSubquery => "in-subquery",
            Self::ProjectionExpression => "projection-expression",
        }
    }

    fn cost_rank(self) -> u16 {
        sql_rule_registry()
            .iter()
            .position(|rule| *rule == self)
            .unwrap_or(usize::MAX) as u16
    }

    async fn execute(
        self,
        engine: &DodamEngine,
        sql: &str,
        batch_size: usize,
    ) -> Result<Option<QueryOutput>> {
        match self {
            Self::Tpch => tpch_rules::try_execute_tpch_rule_sql(engine, sql, batch_size).await,
            Self::WithCte => try_execute_with_cte_sql(engine, sql, batch_size).await,
            Self::PricingSummary => try_execute_pricing_summary_sql(engine, sql, batch_size).await,
            Self::ProfitByNationYear => {
                try_execute_profit_by_nation_year_sql(engine, sql, batch_size).await
            }
            Self::ReturnedCustomerRevenue => {
                try_execute_returned_customer_revenue_sql(engine, sql, batch_size).await
            }
            Self::ImportantStockValue => {
                try_execute_important_stock_value_sql(engine, sql, batch_size).await
            }
            Self::RegionalSupplierRevenue => {
                try_execute_regional_supplier_revenue_sql(engine, sql, batch_size).await
            }
            Self::BilateralShippingVolume => {
                try_execute_bilateral_shipping_volume_sql(engine, sql, batch_size).await
            }
            Self::NationMarketShare => {
                try_execute_nation_market_share_sql(engine, sql, batch_size).await
            }
            Self::DiscountedRevenueOrPredicate => {
                try_execute_discounted_revenue_or_predicate_sql(engine, sql, batch_size).await
            }
            Self::OrderPriorityExistsCount => {
                try_execute_order_priority_exists_count_sql(engine, sql, batch_size).await
            }
            Self::ShippingPriorityRevenue => {
                try_execute_shipping_priority_revenue_sql(engine, sql, batch_size).await
            }
            Self::DerivedPrefixAvgAntiJoinAggregate => {
                try_execute_derived_prefix_avg_anti_join_aggregate_sql(engine, sql, batch_size)
                    .await
            }
            Self::JoinWithGroupedSumSemijoin => {
                try_execute_join_with_grouped_sum_semijoin_sql(engine, sql, batch_size).await
            }
            Self::JoinWithCorrelatedAvgThreshold => {
                try_execute_join_with_correlated_avg_threshold_sql(engine, sql, batch_size).await
            }
            Self::ShippingModePriorityCounts => {
                try_execute_shipping_mode_priority_counts_sql(engine, sql, batch_size).await
            }
            Self::SupplierWaitCountAntijoin => {
                try_execute_supplier_wait_count_antijoin_sql(engine, sql, batch_size).await
            }
            Self::PrefixPartSupplierThreshold => {
                try_execute_prefix_part_supplier_threshold_sql(engine, sql, batch_size).await
            }
            Self::DerivedJoin => try_execute_derived_join_sql(engine, sql, batch_size).await,
            Self::DerivedLeftJoinCountDistribution => {
                try_execute_derived_left_join_count_distribution_sql(engine, sql, batch_size).await
            }
            Self::Derived => try_execute_derived_sql(engine, sql, batch_size).await,
            Self::CorrelatedJoinSubqueryFilter => {
                try_execute_correlated_join_subquery_filter_sql(engine, sql, batch_size).await
            }
            Self::MaterializedJoinSubquery => {
                try_execute_materialized_join_subquery_sql(engine, sql, batch_size).await
            }
            Self::MultiCommaJoin => try_execute_multi_comma_join_sql(engine, sql, batch_size).await,
            Self::CorrelatedExistsSemijoin => {
                try_execute_correlated_exists_semijoin_sql(engine, sql, batch_size).await
            }
            Self::CorrelatedInPairSemijoin => {
                try_execute_correlated_in_pair_semijoin_sql(engine, sql, batch_size).await
            }
            Self::CorrelatedSubqueryFilter => {
                try_execute_correlated_subquery_filter_sql(engine, sql, batch_size).await
            }
            Self::CorrelatedExistsSubquery => {
                try_execute_correlated_exists_subquery_sql(engine, sql, batch_size).await
            }
            Self::ExistsSubquery => try_execute_exists_subquery_sql(engine, sql, batch_size).await,
            Self::InSubquery => try_execute_in_subquery_sql(engine, sql, batch_size).await,
            Self::ProjectionExpression => {
                try_execute_projection_expression_sql(engine, sql, batch_size).await
            }
        }
    }

    fn is_candidate(self, context: &SqlRuleContext) -> bool {
        match self {
            Self::Tpch => context.has_tpch_like_terms,
            Self::WithCte => context.has_with,
            Self::PricingSummary
            | Self::ProfitByNationYear
            | Self::ReturnedCustomerRevenue
            | Self::ImportantStockValue
            | Self::RegionalSupplierRevenue
            | Self::BilateralShippingVolume
            | Self::NationMarketShare
            | Self::DiscountedRevenueOrPredicate
            | Self::OrderPriorityExistsCount
            | Self::ShippingPriorityRevenue
            | Self::ShippingModePriorityCounts
            | Self::SupplierWaitCountAntijoin
            | Self::PrefixPartSupplierThreshold => context.has_tpch_like_terms,
            Self::JoinWithGroupedSumSemijoin
            | Self::JoinWithCorrelatedAvgThreshold
            | Self::MultiCommaJoin => context.from_table_count > 1 || context.has_join,
            Self::DerivedPrefixAvgAntiJoinAggregate
            | Self::DerivedJoin
            | Self::DerivedLeftJoinCountDistribution
            | Self::Derived => context.has_derived_from,
            Self::CorrelatedJoinSubqueryFilter
            | Self::MaterializedJoinSubquery
            | Self::CorrelatedExistsSemijoin
            | Self::CorrelatedInPairSemijoin
            | Self::CorrelatedSubqueryFilter
            | Self::CorrelatedExistsSubquery
            | Self::ExistsSubquery
            | Self::InSubquery => context.has_subquery,
            Self::ProjectionExpression => true,
        }
    }
}

fn sql_rule_registry() -> &'static [SqlRule] {
    &[
        SqlRule::Tpch,
        SqlRule::WithCte,
        SqlRule::PricingSummary,
        SqlRule::ProfitByNationYear,
        SqlRule::ReturnedCustomerRevenue,
        SqlRule::ImportantStockValue,
        SqlRule::RegionalSupplierRevenue,
        SqlRule::BilateralShippingVolume,
        SqlRule::NationMarketShare,
        SqlRule::DiscountedRevenueOrPredicate,
        SqlRule::OrderPriorityExistsCount,
        SqlRule::ShippingPriorityRevenue,
        SqlRule::DerivedPrefixAvgAntiJoinAggregate,
        SqlRule::JoinWithGroupedSumSemijoin,
        SqlRule::JoinWithCorrelatedAvgThreshold,
        SqlRule::ShippingModePriorityCounts,
        SqlRule::SupplierWaitCountAntijoin,
        SqlRule::PrefixPartSupplierThreshold,
        SqlRule::DerivedJoin,
        SqlRule::DerivedLeftJoinCountDistribution,
        SqlRule::Derived,
        SqlRule::CorrelatedJoinSubqueryFilter,
        SqlRule::MaterializedJoinSubquery,
        SqlRule::MultiCommaJoin,
        SqlRule::CorrelatedExistsSemijoin,
        SqlRule::CorrelatedInPairSemijoin,
        SqlRule::CorrelatedSubqueryFilter,
        SqlRule::CorrelatedExistsSubquery,
        SqlRule::ExistsSubquery,
        SqlRule::InSubquery,
        SqlRule::ProjectionExpression,
    ]
}

async fn try_execute_registered_sql_rules(
    engine: &DodamEngine,
    sql: &str,
    batch_size: usize,
) -> Result<Option<QueryOutput>> {
    let context = SqlRuleContext::from_sql(sql)?;
    let candidates = sql_rule_registry()
        .iter()
        .copied()
        .filter(|rule| rule.is_candidate(&context));
    for rule in candidates {
        if let Some(output) = rule.execute(engine, sql, batch_size).await? {
            if sql_rule_profile_enabled() {
                eprintln!(
                    "[dodam:sql-rule] selected={} cost_rank={}",
                    rule.name(),
                    rule.cost_rank()
                );
            }
            return Ok(Some(output));
        }
    }
    Ok(None)
}

struct SqlRuleContext {
    has_with: bool,
    has_join: bool,
    has_subquery: bool,
    has_derived_from: bool,
    has_tpch_like_terms: bool,
    from_table_count: usize,
}

impl SqlRuleContext {
    fn from_sql(sql: &str) -> Result<Self> {
        let lower_sql = sql.to_ascii_lowercase();
        let dialect = GenericDialect {};
        let statements = Parser::parse_sql(&dialect, sql)
            .map_err(|error| DodamError::UnsupportedSql(error.to_string()))?;
        let Some(Statement::Query(query)) = statements.first() else {
            return Ok(Self::from_lower_sql(lower_sql));
        };
        let mut context = Self::from_lower_sql(lower_sql);
        context.has_with = query.with.is_some();
        context.has_subquery = query_contains_subquery(query);
        if let SetExpr::Select(select) = query.body.as_ref() {
            context.from_table_count = select.from.len();
            context.has_join = select.from.iter().any(|table| !table.joins.is_empty());
            context.has_derived_from = select.from.iter().any(table_with_derived_relation);
        }
        Ok(context)
    }

    fn from_lower_sql(lower_sql: String) -> Self {
        let has_tpch_like_terms = [
            "lineitem", "orders", "customer", "supplier", "partsupp", "part", "nation", "region",
            "l_", "o_", "c_", "s_", "ps_", "p_", "n_", "r_",
        ]
        .iter()
        .any(|term| lower_sql.contains(term));
        Self {
            has_with: lower_sql.contains("with "),
            has_join: lower_sql.contains(" join "),
            has_subquery: lower_sql.contains("select")
                && (lower_sql.contains(" exists")
                    || lower_sql.contains(" in (select")
                    || lower_sql.contains("(select")),
            has_derived_from: lower_sql.contains("from ("),
            has_tpch_like_terms,
            from_table_count: 0,
        }
    }
}

fn query_contains_subquery(query: &Query) -> bool {
    if query.with.as_ref().is_some_and(|with| {
        with.cte_tables
            .iter()
            .any(|cte| query_contains_subquery(&cte.query))
    }) {
        return true;
    }
    set_expr_contains_subquery(query.body.as_ref())
}

fn set_expr_contains_subquery(expr: &SetExpr) -> bool {
    match expr {
        SetExpr::Select(select) => {
            select
                .selection
                .as_ref()
                .is_some_and(expr_contains_materializable_subquery)
                || select.from.iter().any(|table| {
                    table_with_derived_relation(table) || table_contains_subquery(table)
                })
        }
        SetExpr::Query(query) => query_contains_subquery(query),
        SetExpr::SetOperation { left, right, .. } => {
            set_expr_contains_subquery(left) || set_expr_contains_subquery(right)
        }
        _ => false,
    }
}

fn table_contains_subquery(table: &TableWithJoins) -> bool {
    table_with_derived_relation(table)
        || table
            .joins
            .iter()
            .any(|join| table_factor_contains_derived(&join.relation))
}

fn table_with_derived_relation(table: &TableWithJoins) -> bool {
    table_factor_contains_derived(&table.relation)
}

fn table_factor_contains_derived(factor: &TableFactor) -> bool {
    matches!(
        factor,
        TableFactor::Derived { .. }
            | TableFactor::TableFunction { .. }
            | TableFactor::NestedJoin { .. }
    )
}

fn sql_rule_profile_enabled() -> bool {
    std::env::var("DODAM_SQL_RULE_PROFILE").is_ok_and(|value| {
        matches!(
            value.as_str(),
            "1" | "true" | "TRUE" | "yes" | "YES" | "on" | "ON"
        )
    })
}

fn semijoin_profile_enabled() -> bool {
    std::env::var("DODAM_SEMIJOIN_PROFILE")
        .is_ok_and(|value| matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES"))
}

async fn try_execute_monotonic_row_group_order_limit_scan(
    engine: &DodamEngine,
    query: &SqlQuery,
    batch_size: usize,
) -> Result<Option<Vec<RecordBatch>>> {
    if query.distinct || query.expression_filter.is_some() || query.limit.is_none() {
        return Ok(None);
    }
    if !Path::new(&query.path).exists() {
        return Ok(None);
    }
    let Some(order_by) = query.order_by.as_ref() else {
        return Ok(None);
    };
    let Some(order_column) = monotonic_stream_limit_column(Some(order_by)) else {
        return Ok(None);
    };
    if !monotonic_order_limit_scan_enabled()
        || !monotonic_row_group_order_limit_scan_enabled()
        || !engine
            .parquet_row_groups_monotonic_by_column(query.path.clone(), &order_column)
            .await?
    {
        return Ok(None);
    }

    let mut scan_projection = scan_projection(&query.projection, query.filter.as_ref());
    add_projection_column_once(&mut scan_projection, order_column.clone());
    let row_groups = engine.parquet_row_group_count(&query.path)?;
    let mut output = Vec::new();
    let mut order_state = MonotonicOrderState::default();
    let mut limiter = OrderedLimitCollector::new(query.limit, query.offset);

    for row_group in 0..row_groups {
        let batches = engine
            .scan_parquet_row_group_batches(
                query.path.clone(),
                batch_size,
                scan_projection.clone(),
                vec![row_group],
            )
            .await?;
        for batch in batches {
            let batch = if let Some(filter) = query.filter.as_ref() {
                filter_batch(batch, filter)?
            } else {
                batch
            };
            if batch.num_rows() == 0 {
                continue;
            }
            if !order_state.consume_batch(&batch, &order_column)? {
                return Ok(None);
            }
            limiter.push_batch(batch, &mut output);
        }
        if limiter.is_complete() {
            let output = apply_output_projection(output, &query.projection)?;
            return Ok(Some(output));
        }
    }

    let output = apply_output_projection(output, &query.projection)?;
    Ok(Some(output))
}

fn monotonic_row_group_order_limit_scan_enabled() -> bool {
    !std::env::var("DODAM_DISABLE_MONOTONIC_ROW_GROUP_ORDER_LIMIT_SCAN")
        .is_ok_and(|value| matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES"))
}

fn add_projection_column_once(projection: &mut Projection, column: String) {
    if let Projection::Columns(columns) = projection
        && !columns.iter().any(|existing| existing == &column)
    {
        columns.push(column);
    }
}

struct OrderedLimitCollector {
    to_skip: usize,
    remaining: usize,
}

impl OrderedLimitCollector {
    fn new(limit: Option<usize>, offset: usize) -> Self {
        Self {
            to_skip: offset,
            remaining: limit.unwrap_or(usize::MAX),
        }
    }

    fn push_batch(&mut self, batch: RecordBatch, output: &mut Vec<RecordBatch>) {
        if self.remaining == 0 {
            return;
        }
        if self.to_skip >= batch.num_rows() {
            self.to_skip -= batch.num_rows();
            return;
        }
        let batch = if self.to_skip > 0 {
            let sliced = batch.slice(self.to_skip, batch.num_rows() - self.to_skip);
            self.to_skip = 0;
            sliced
        } else {
            batch
        };
        let rows = self.remaining.min(batch.num_rows());
        self.remaining -= rows;
        if rows > 0 {
            output.push(batch.slice(0, rows));
        }
    }

    fn is_complete(&self) -> bool {
        self.remaining == 0
    }
}

#[derive(Default)]
enum MonotonicOrderState {
    #[default]
    Empty,
    Int32(i32),
    Int64(i64),
    Utf8(String),
}

impl MonotonicOrderState {
    fn consume_batch(&mut self, batch: &RecordBatch, column: &str) -> Result<bool> {
        let index = output_batch_column_index(batch, column)?;
        let values = batch.column(index);
        match values.data_type() {
            DataType::Int32 | DataType::Date32 => {
                let values = values
                    .as_any()
                    .downcast_ref::<Int32Array>()
                    .expect("Int32/Date32 data type");
                for row in 0..values.len() {
                    if values.is_null(row) {
                        return Ok(false);
                    }
                    let value = values.value(row);
                    if let Self::Int32(previous) = self
                        && value < *previous
                    {
                        return Ok(false);
                    }
                    *self = Self::Int32(value);
                }
                Ok(true)
            }
            DataType::Int64 => {
                let values = values
                    .as_any()
                    .downcast_ref::<Int64Array>()
                    .expect("Int64 data type");
                for row in 0..values.len() {
                    if values.is_null(row) {
                        return Ok(false);
                    }
                    let value = values.value(row);
                    if let Self::Int64(previous) = self
                        && value < *previous
                    {
                        return Ok(false);
                    }
                    *self = Self::Int64(value);
                }
                Ok(true)
            }
            DataType::Utf8 => {
                let values = values
                    .as_any()
                    .downcast_ref::<StringArray>()
                    .expect("Utf8 data type");
                for row in 0..values.len() {
                    if values.is_null(row) {
                        return Ok(false);
                    }
                    let value = values.value(row);
                    if let Self::Utf8(previous) = self
                        && value < previous.as_str()
                    {
                        return Ok(false);
                    }
                    *self = Self::Utf8(value.to_string());
                }
                Ok(true)
            }
            _ => Ok(false),
        }
    }
}

async fn try_execute_set_operation_sql(
    engine: &DodamEngine,
    sql: &str,
    batch_size: usize,
) -> Result<Option<QueryOutput>> {
    let dialect = GenericDialect {};
    let statements = Parser::parse_sql(&dialect, sql)
        .map_err(|error| DodamError::UnsupportedSql(error.to_string()))?;
    let [Statement::Query(query)] = statements.as_slice() else {
        return Ok(None);
    };
    if !query_contains_set_operation(query.body.as_ref()) {
        return Ok(None);
    }
    let order_by = parse_order_by(query, &[], &[], None)?;
    let limit = parse_limit(query)?;
    let offset = parse_offset(query)?;
    if let Some(batches) = try_execute_same_source_union_all_monotonic_topk(
        engine,
        query.body.as_ref(),
        batch_size,
        order_by.as_ref(),
        limit,
        offset,
    )
    .await?
    {
        return Ok(Some(QueryOutput::Scan { batches }));
    }
    if let Some(mut batches) =
        try_execute_same_source_union_all_scan(engine, query.body.as_ref(), batch_size).await?
    {
        batches = apply_output_order_limit(batches, order_by.as_ref(), limit, offset)?;
        return Ok(Some(QueryOutput::Scan { batches }));
    }
    if order_by.is_none()
        && limit.is_none()
        && offset == 0
        && let Some(batches) =
            try_execute_same_source_union_all_filter_scan(engine, query.body.as_ref(), batch_size)
                .await?
    {
        return Ok(Some(QueryOutput::Scan { batches }));
    }
    if let Some(mut batches) = try_execute_same_source_union_distinct_scan(
        engine,
        query.body.as_ref(),
        batch_size,
        order_by.as_ref(),
        limit,
        offset,
    )
    .await?
    {
        batches = apply_output_order_limit(batches, order_by.as_ref(), limit, offset)?;
        return Ok(Some(QueryOutput::Scan { batches }));
    }
    let child_topk = if offset == 0 {
        order_by.as_ref().zip(limit)
    } else {
        None
    };
    let mut batches = Box::pin(execute_union_set_expr(
        engine,
        query.body.as_ref(),
        batch_size,
        child_topk,
        false,
    ))
    .await?;
    batches = apply_output_order_limit(batches, order_by.as_ref(), limit, offset)?;
    Ok(Some(QueryOutput::Scan { batches }))
}

async fn try_execute_same_source_union_all_monotonic_topk(
    engine: &DodamEngine,
    expr: &SetExpr,
    batch_size: usize,
    order_by: Option<&SortKey>,
    limit: Option<usize>,
    offset: usize,
) -> Result<Option<Vec<RecordBatch>>> {
    let (Some(order_by), Some(limit)) = (order_by, limit) else {
        return Ok(None);
    };
    if offset != 0 || limit == 0 {
        return Ok(None);
    }
    let [sort] = order_by.expressions.as_slice() else {
        return Ok(None);
    };
    if !sort.descending || sort.nulls_first {
        return Ok(None);
    }
    let Some(shared) = plan_same_source_union_all_scan(expr)? else {
        return Ok(None);
    };
    if let Some(mut batches) =
        try_row_group_ordered_desc_sort(engine, &shared, order_by, &sort.column, batch_size, limit)
            .await?
    {
        batches = apply_output_projection(batches, &shared.projection)?;
        batches = rename_output_batches(batches, &shared.aliases)?;
        return Ok(Some(batches));
    }
    if let Some(mut batches) =
        try_reverse_row_group_desc_tail_topk(engine, &shared, &sort.column, batch_size, limit)
            .await?
    {
        batches = apply_output_order_limit(batches, Some(order_by), Some(limit), 0)?;
        batches = apply_output_projection(batches, &shared.projection)?;
        batches = rename_output_batches(batches, &shared.aliases)?;
        return Ok(Some(batches));
    }
    if let Some(mut batches) = try_same_source_union_all_streaming_desc_topk(
        engine,
        &shared,
        &sort.column,
        batch_size,
        limit,
    )
    .await?
    {
        batches = apply_output_projection(batches, &shared.projection)?;
        batches = rename_output_batches(batches, &shared.aliases)?;
        return Ok(Some(batches));
    }
    let stream = engine
        .scan_parquet_filtered_batches_preserve_order(
            shared.path,
            batch_size,
            shared.projection,
            Some(shared.filter),
        )
        .await?;
    let Some(mut batches) = collect_monotonic_desc_tail_topk(stream, &sort.column, limit)? else {
        return Ok(None);
    };
    batches = rename_output_batches(batches, &shared.aliases)?;
    batches = apply_output_order_limit(batches, Some(order_by), Some(limit), 0)?;
    Ok(Some(batches))
}

async fn try_row_group_ordered_desc_sort(
    engine: &DodamEngine,
    shared: &SameSourceUnionAllScan,
    order_by: &SortKey,
    sort_column: &str,
    batch_size: usize,
    limit: usize,
) -> Result<Option<Vec<RecordBatch>>> {
    if limit <= reverse_row_group_topk_max_limit_rows() {
        return Ok(None);
    }
    if !engine
        .parquet_row_groups_monotonic_by_column(shared.path.clone(), sort_column)
        .await?
    {
        return Ok(None);
    }
    let row_group_count = engine.parquet_row_group_count(&shared.path)?;
    if row_group_count == 0 {
        return Ok(Some(Vec::new()));
    }

    let mut scan_projection = shared.projection.clone();
    add_projection_columns(&mut scan_projection, shared.filter.referenced_columns());
    for sort in &order_by.expressions {
        add_projection_columns(&mut scan_projection, vec![sort.column.clone()]);
    }

    if row_group_ordered_desc_bulk_global_sort_enabled() {
        let row_groups = (0..row_group_count).rev().collect::<Vec<_>>();
        let batches = engine
            .scan_parquet_row_group_batches(
                shared.path.clone(),
                batch_size,
                scan_projection,
                row_groups,
            )
            .await?;
        let mut filtered = Vec::new();
        for batch in batches {
            let batch = filter_batch(batch, &shared.filter)?;
            if batch.num_rows() > 0 {
                filtered.push(batch);
            }
        }
        return Ok(Some(apply_output_order_limit(
            filtered,
            Some(order_by),
            Some(limit),
            0,
        )?));
    }

    if row_group_ordered_desc_parallel_enabled() && row_group_count > 1 {
        let row_group_batch_size = row_group_ordered_sort_batch_size(batch_size);
        let mut handles = Vec::with_capacity(row_group_count);
        for row_group in (0..row_group_count).rev() {
            let engine = engine.clone();
            let path = shared.path.clone();
            let scan_projection = scan_projection.clone();
            let filter = shared.filter.clone();
            let order_by = order_by.clone();
            let sort_column = sort_column.to_string();
            handles.push(tokio::task::spawn(async move {
                scan_filter_sort_ordered_row_group(
                    &engine,
                    path,
                    row_group_batch_size,
                    scan_projection,
                    row_group,
                    &filter,
                    &order_by,
                    &sort_column,
                )
                .await
            }));
        }
        let mut output = Vec::new();
        let mut rows = 0usize;
        for handle in handles {
            let sorted = handle
                .await
                .map_err(|error| DodamError::UnsupportedSql(error.to_string()))??;
            for batch in sorted {
                rows += batch.num_rows();
                output.push(batch);
            }
            if rows >= limit {
                break;
            }
        }
        return Ok(Some(limit_batches(output, Some(limit), 0)));
    }

    let mut output = Vec::new();
    let mut rows = 0usize;
    let row_group_batch_size = row_group_ordered_sort_batch_size(batch_size);
    for row_group in (0..row_group_count).rev() {
        let sorted = scan_filter_sort_ordered_row_group(
            engine,
            shared.path.clone(),
            row_group_batch_size,
            scan_projection.clone(),
            row_group,
            &shared.filter,
            order_by,
            sort_column,
        )
        .await?;
        for batch in sorted {
            rows += batch.num_rows();
            output.push(batch);
        }
        if rows >= limit {
            break;
        }
    }
    Ok(Some(limit_batches(output, Some(limit), 0)))
}

async fn scan_filter_sort_ordered_row_group(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    projection: Projection,
    row_group: usize,
    filter: &FilterExpr,
    order_by: &SortKey,
    sort_column: &str,
) -> Result<Vec<RecordBatch>> {
    let profile = ordered_sink_profile_enabled();
    let total_started = profile.then(Instant::now);
    let scan_started = profile.then(Instant::now);
    let batches = engine
        .scan_parquet_row_group_batches(path, batch_size, projection, vec![row_group])
        .await?;
    let scan_elapsed = scan_started.map(|started| started.elapsed());
    let post_started = profile.then(Instant::now);
    if let Some(sorted) =
        reverse_filter_ascending_batches_if_ordered(&batches, sort_column, filter)?
    {
        print_ordered_row_group_profile(
            total_started,
            scan_elapsed,
            post_started.map(|started| started.elapsed()),
            row_group,
            sorted.iter().map(RecordBatch::num_rows).sum(),
            sorted.len(),
            "reverse-filter",
        );
        return Ok(sorted);
    }
    let mut filtered = Vec::new();
    for batch in batches {
        let batch = filter_batch(batch, filter)?;
        if batch.num_rows() > 0 {
            filtered.push(batch);
        }
    }
    if filtered.is_empty() {
        print_ordered_row_group_profile(
            total_started,
            scan_elapsed,
            post_started.map(|started| started.elapsed()),
            row_group,
            0,
            0,
            "empty",
        );
        return Ok(Vec::new());
    }
    let result = match reverse_ascending_primitive_batches_if_ordered(&filtered, sort_column)? {
        Some(sorted) => Ok(sorted),
        None => apply_output_order_limit(filtered, Some(order_by), None, 0),
    }?;
    print_ordered_row_group_profile(
        total_started,
        scan_elapsed,
        post_started.map(|started| started.elapsed()),
        row_group,
        result.iter().map(RecordBatch::num_rows).sum(),
        result.len(),
        "filter-sort",
    );
    Ok(result)
}

fn row_group_ordered_desc_parallel_enabled() -> bool {
    std::env::var("DODAM_ROW_GROUP_ORDERED_DESC_PARALLEL")
        .is_ok_and(|value| matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES"))
}

fn print_ordered_row_group_profile(
    total_started: Option<Instant>,
    scan_elapsed: Option<Duration>,
    post_elapsed: Option<Duration>,
    row_group: usize,
    rows: usize,
    batches: usize,
    mode: &str,
) {
    let Some(total_started) = total_started else {
        return;
    };
    eprintln!(
        "[dodam:ordered-row-group-profile] row_group={} mode={} total={}us scan={}us post={}us rows={} batches={}",
        row_group,
        mode,
        total_started.elapsed().as_micros(),
        scan_elapsed
            .map(|duration| duration.as_micros())
            .unwrap_or(0),
        post_elapsed
            .map(|duration| duration.as_micros())
            .unwrap_or(0),
        rows,
        batches
    );
}

fn reverse_filter_ascending_batches_if_ordered(
    batches: &[RecordBatch],
    sort_column: &str,
    filter: &FilterExpr,
) -> Result<Option<Vec<RecordBatch>>> {
    let mut previous_last: Option<i128> = None;
    for batch in batches {
        if batch.num_rows() == 0 {
            continue;
        }
        let index = output_batch_column_index(batch, sort_column)?;
        let Some((first, last)) = numeric_column_ascending_bounds(batch.column(index))? else {
            return Ok(None);
        };
        if previous_last.is_some_and(|previous| previous > first) {
            return Ok(None);
        }
        previous_last = Some(last);
    }

    let mut output = Vec::new();
    for batch in batches.iter().rev() {
        if batch.num_rows() == 0 {
            continue;
        }
        if let Some(batch) = reverse_primitive_in_list_selected_batch(batch, filter)? {
            if batch.num_rows() > 0 {
                output.push(batch);
            }
            continue;
        }
        let indices = match reverse_simple_in_list_indices(batch, filter)? {
            Some(indices) => indices,
            None if reverse_filter_ordered_batches_disabled() => return Ok(None),
            None => {
                let mask = evaluate_filter_mask(batch, filter)?;
                let mut indices = Vec::new();
                for row in (0..batch.num_rows()).rev() {
                    if !mask.is_null(row) && mask.value(row) {
                        indices.push(row as u32);
                    }
                }
                indices
            }
        };
        if indices.is_empty() {
            continue;
        }
        output.push(take_record_batch(batch, &UInt32Array::from(indices))?);
    }
    Ok(Some(output))
}

fn reverse_primitive_in_list_selected_batch(
    batch: &RecordBatch,
    filter: &FilterExpr,
) -> Result<Option<RecordBatch>> {
    if !reverse_primitive_in_list_ordered_batches_enabled() {
        return Ok(None);
    }
    reverse_primitive_in_list_selected_batch_unchecked(batch, filter)
}

fn reverse_primitive_in_list_selected_batch_unchecked(
    batch: &RecordBatch,
    filter: &FilterExpr,
) -> Result<Option<RecordBatch>> {
    let Some(indices) = reverse_simple_in_list_indices_unchecked(batch, filter)? else {
        return Ok(None);
    };
    if indices.is_empty() {
        return Ok(Some(RecordBatch::new_empty(batch.schema())));
    }
    let mut columns = Vec::with_capacity(batch.num_columns());
    for column in batch.columns() {
        let Some(array) = gather_primitive_array(column, &indices) else {
            return Ok(None);
        };
        columns.push(array);
    }
    Ok(Some(RecordBatch::try_new(batch.schema(), columns)?))
}

fn gather_primitive_array(column: &ArrayRef, indices: &[u32]) -> Option<ArrayRef> {
    if column.null_count() != 0 {
        return None;
    }
    match column.data_type() {
        DataType::Int32 => {
            let values = column.as_any().downcast_ref::<Int32Array>()?;
            let mut output = Vec::with_capacity(indices.len());
            for &index in indices {
                output.push(values.value(index as usize));
            }
            Some(Arc::new(Int32Array::from(output)))
        }
        DataType::Int64 => {
            let values = column.as_any().downcast_ref::<Int64Array>()?;
            let mut output = Vec::with_capacity(indices.len());
            for &index in indices {
                output.push(values.value(index as usize));
            }
            Some(Arc::new(Int64Array::from(output)))
        }
        DataType::UInt64 => {
            let values = column.as_any().downcast_ref::<UInt64Array>()?;
            let mut output = Vec::with_capacity(indices.len());
            for &index in indices {
                output.push(values.value(index as usize));
            }
            Some(Arc::new(UInt64Array::from(output)))
        }
        DataType::Float64 => {
            let values = column.as_any().downcast_ref::<Float64Array>()?;
            let mut output = Vec::with_capacity(indices.len());
            for &index in indices {
                output.push(values.value(index as usize));
            }
            Some(Arc::new(Float64Array::from(output)))
        }
        DataType::Date32 => {
            let values = column.as_any().downcast_ref::<Date32Array>()?;
            let mut output = Vec::with_capacity(indices.len());
            for &index in indices {
                output.push(values.value(index as usize));
            }
            Some(Arc::new(Date32Array::from(output)))
        }
        _ => None,
    }
}

fn reverse_simple_in_list_indices(
    batch: &RecordBatch,
    filter: &FilterExpr,
) -> Result<Option<Vec<u32>>> {
    if !reverse_in_list_ordered_batches_enabled() {
        return Ok(None);
    }
    reverse_simple_in_list_indices_unchecked(batch, filter)
}

fn reverse_simple_in_list_indices_unchecked(
    batch: &RecordBatch,
    filter: &FilterExpr,
) -> Result<Option<Vec<u32>>> {
    let Expr::InList {
        column,
        values,
        negated,
        ..
    } = filter.expr()
    else {
        return Ok(None);
    };
    if *negated {
        return Ok(None);
    }
    let column_index = output_batch_column_index(batch, column)?;
    let array = batch.column(column_index);
    match array.data_type() {
        DataType::Int32 => {
            let values = values
                .iter()
                .map(|value| value.as_i32(column))
                .collect::<Result<Vec<_>>>()?;
            let values_array = array.as_any().downcast_ref::<Int32Array>().expect("Int32");
            let mut indices = Vec::new();
            for row in (0..values_array.len()).rev() {
                if !values_array.is_null(row)
                    && values.iter().any(|value| *value == values_array.value(row))
                {
                    indices.push(row as u32);
                }
            }
            Ok(Some(indices))
        }
        DataType::Int64 => {
            let values = values
                .iter()
                .map(|value| value.as_i64(column))
                .collect::<Result<Vec<_>>>()?;
            let values_array = array.as_any().downcast_ref::<Int64Array>().expect("Int64");
            let mut indices = Vec::new();
            for row in (0..values_array.len()).rev() {
                if !values_array.is_null(row)
                    && values.iter().any(|value| *value == values_array.value(row))
                {
                    indices.push(row as u32);
                }
            }
            Ok(Some(indices))
        }
        _ => Ok(None),
    }
}

