fn monotonic_stream_limit_column(order_by: Option<&SortKey>) -> Option<String> {
    let [sort] = order_by?.expressions.as_slice() else {
        return None;
    };
    (!sort.descending && !sort.nulls_first).then(|| sort.column.clone())
}

