#[allow(clippy::too_many_arguments)]
fn q09_profit_decimal_batch_matched_index(
    orderkey_values: &[i64],
    partkey_values: &[i64],
    suppkey_values: &[i64],
    quantity_values: &[i128],
    extendedprice_values: &[i128],
    discount_values: &[i128],
    discount_scale: f64,
    revenue_scale: f64,
    quantity_scale: f64,
    dense_part_keys: &[bool],
    supplier_nations: &AdaptiveI64Map<i64>,
    order_years: &Q09OrderYears,
    dense_order_years: Option<(&[i32], i64, i32)>,
    supply_costs: &Q09SupplyCosts,
    collect_profile: bool,
) -> Q09ProfitPartial {
    let mut groups = Q09ProfitGroups::default();
    let mut profile = Q09ProfitProfile::default();
    if collect_profile {
        profile.rows = partkey_values.len();
    }
    let started = collect_profile.then(Instant::now);
    let mut matched_rows = Vec::new();
    for (row, partkey) in partkey_values.iter().copied().enumerate() {
        let Some(index) = usize::try_from(partkey).ok() else {
            continue;
        };
        if dense_part_keys.get(index).copied().unwrap_or(false) {
            matched_rows.push(row);
        }
    }
    if let Some(started) = started {
        profile.part_nanos = profile
            .part_nanos
            .saturating_add(sql_elapsed_nanos(started));
    }
    if collect_profile {
        profile.part_hits = matched_rows.len();
    }

    for row in matched_rows {
        let started = collect_profile.then(Instant::now);
        let o_year = q09_order_year_get(order_years, dense_order_years, orderkey_values[row]);
        if let Some(started) = started {
            profile.order_nanos = profile
                .order_nanos
                .saturating_add(sql_elapsed_nanos(started));
        }
        let Some(o_year) = o_year else {
            continue;
        };
        if collect_profile {
            profile.order_hits += 1;
        }
        let suppkey = suppkey_values[row];
        let started = collect_profile.then(Instant::now);
        let nationkey = supplier_nations.get(suppkey);
        if let Some(started) = started {
            profile.supplier_nanos = profile
                .supplier_nanos
                .saturating_add(sql_elapsed_nanos(started));
        }
        let Some(nationkey) = nationkey else {
            continue;
        };
        if collect_profile {
            profile.supplier_hits += 1;
        }
        let partkey = partkey_values[row];
        let started = collect_profile.then(Instant::now);
        let supplycost = supply_costs.get(partkey, suppkey);
        if let Some(started) = started {
            profile.supply_nanos = profile
                .supply_nanos
                .saturating_add(sql_elapsed_nanos(started));
        }
        let Some(supplycost) = supplycost else {
            continue;
        };
        if collect_profile {
            profile.supply_hits += 1;
        }
        let started = collect_profile.then(Instant::now);
        let amount = (extendedprice_values[row] as f64)
            * (discount_scale - discount_values[row] as f64)
            * revenue_scale
            - supplycost * (quantity_values[row] as f64) * quantity_scale;
        if let Some(started) = started {
            profile.amount_nanos = profile
                .amount_nanos
                .saturating_add(sql_elapsed_nanos(started));
        }
        groups.add(nationkey, o_year, amount);
        if collect_profile {
            profile.amount_rows += 1;
        }
    }

    Q09ProfitPartial { groups, profile }
}

fn q09_output(rows: Vec<Q09Row>) -> Result<QueryOutput> {
    let batch = RecordBatch::try_new(
        Arc::new(Schema::new(vec![
            Field::new("nation", DataType::Utf8, false),
            Field::new("o_year", DataType::Int64, false),
            Field::new("sum_profit", DataType::Float64, false),
        ])),
        vec![
            Arc::new(StringArray::from_iter_values(
                rows.iter().map(|row| row.nation.as_str()),
            )),
            Arc::new(Int64Array::from_iter_values(
                rows.iter().map(|row| i64::from(row.o_year)),
            )),
            Arc::new(Float64Array::from_iter_values(
                rows.iter().map(|row| row.sum_profit),
            )),
        ],
    )?;
    Ok(QueryOutput::Aggregate {
        metrics: AggregateMetrics::default(),
        batches: vec![batch],
    })
}

fn q11_shape(select: &Select, query: &Query, selection: &SqlExpr) -> bool {
    let projection = select
        .projection
        .iter()
        .map(|item| item.to_string().to_ascii_lowercase())
        .collect::<Vec<_>>()
        .join(", ");
    let group_by = select.group_by.to_string().to_ascii_lowercase();
    let having = select
        .having
        .as_ref()
        .map(|expr| expr.to_string().to_ascii_lowercase())
        .unwrap_or_default();
    let order_by = query
        .order_by
        .as_ref()
        .map(|order_by| order_by.to_string().to_ascii_lowercase())
        .unwrap_or_default();
    let selection = selection.to_string().to_ascii_lowercase();
    select.from.len() == 3
        && select.projection.len() == 2
        && projection.contains("ps_partkey")
        && projection.contains("sum(ps_supplycost * ps_availqty)")
        && group_by.contains("ps_partkey")
        && having.contains("sum(ps_supplycost * ps_availqty)")
        && having.contains("* 0.0001")
        && order_by.contains("value desc")
        && selection.contains("ps_suppkey = s_suppkey")
        && selection.contains("s_nationkey = n_nationkey")
        && selection.contains("n_name")
}

async fn try_execute_important_stock_value_sql(
    engine: &DodamEngine,
    sql: &str,
    batch_size: usize,
) -> Result<Option<QueryOutput>> {
    let dialect = GenericDialect {};
    let statements = Parser::parse_sql(&dialect, sql)
        .map_err(|error| DodamError::UnsupportedSql(error.to_string()))?;
    let [Statement::Query(query)] = statements.as_slice() else {
        return Ok(None);
    };
    let SetExpr::Select(select) = query.body.as_ref() else {
        return Ok(None);
    };
    let Some(selection) = select.selection.as_ref() else {
        return Ok(None);
    };
    if !q11_shape(select, query, selection) {
        return Ok(None);
    }
    if !matches!(parse_limit(query), Ok(None)) {
        return Ok(None);
    }
    reject_query_features(query)?;
    reject_select_features(select)?;
    let Some(tables) = parse_comma_join_table_refs(select)? else {
        return Ok(None);
    };
    if tables.len() != 3 {
        return Ok(None);
    }
    let mut partsupp = None;
    let mut supplier = None;
    let mut nation = None;
    for table in tables {
        let alias = table_ref_alias_or_name(&table);
        if alias.eq_ignore_ascii_case("partsupp") {
            partsupp = Some(table);
        } else if alias.eq_ignore_ascii_case("supplier") {
            supplier = Some(table);
        } else if alias.eq_ignore_ascii_case("nation") {
            nation = Some(table);
        }
    }
    let (Some(partsupp), Some(supplier), Some(nation)) = (partsupp, supplier, nation) else {
        return Ok(None);
    };
    let mut conjuncts = Vec::new();
    collect_sql_and_conjuncts(selection, &mut conjuncts);
    let Some(nation_name) = string_equality_literal(&conjuncts, "n_name")? else {
        return Ok(None);
    };

    let stage = tpch_profile_start();
    let nation_keys = q21_nation_keys(engine, nation.path, batch_size, &nation_name).await?;
    tpch_profile_elapsed("Q11 nation keys", stage);
    if nation_keys.is_empty() {
        return Ok(Some(q11_output(Vec::new())?));
    }

    let stage = tpch_profile_start();
    let supplier_keys = q11_supplier_keys(engine, supplier.path, batch_size, &nation_keys).await?;
    tpch_profile_elapsed("Q11 supplier keys", stage);
    if supplier_keys.is_empty() {
        return Ok(Some(q11_output(Vec::new())?));
    }

    let stage = tpch_profile_start();
    let rows = q11_important_stock_rows(engine, partsupp.path, batch_size, &supplier_keys).await?;
    tpch_profile_elapsed("Q11 stock values", stage);
    Ok(Some(q11_output(rows)?))
}

async fn q11_supplier_keys(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    nation_keys: &HashSet<i64>,
) -> Result<AdaptiveI64Set> {
    let mut stream = engine
        .scan_parquet_batches(
            path,
            batch_size,
            None,
            Projection::Columns(vec!["s_suppkey".to_string(), "s_nationkey".to_string()]),
            None,
        )
        .await?;
    let mut suppliers = AdaptiveI64Set::new_dense();
    while let Some(batch) = stream.next() {
        let batch = batch?;
        let suppkeys = batch_column(&batch, "s_suppkey")?;
        let nationkeys = batch_column(&batch, "s_nationkey")?;
        if let (Some(suppkeys), Some(nationkeys)) = (
            suppkeys.as_any().downcast_ref::<Int64Array>(),
            nationkeys.as_any().downcast_ref::<Int64Array>(),
        ) {
            if suppkeys.null_count() == 0 && nationkeys.null_count() == 0 {
                for (&suppkey, &nationkey) in suppkeys.values().iter().zip(nationkeys.values()) {
                    if nation_keys.contains(&nationkey) {
                        suppliers.insert(suppkey);
                    }
                }
                continue;
            }
        }
        for row in 0..batch.num_rows() {
            let (Some(suppkey), Some(nationkey)) = (
                numeric_i64_value(suppkeys, row)?,
                numeric_i64_value(nationkeys, row)?,
            ) else {
                continue;
            };
            if nation_keys.contains(&nationkey) {
                suppliers.insert(suppkey);
            }
        }
    }
    Ok(suppliers)
}

async fn q11_important_stock_rows(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    supplier_keys: &AdaptiveI64Set,
) -> Result<Vec<Q11Row>> {
    if q11_late_materialized_enabled() {
        if let Some(rows) =
            q11_important_stock_rows_late(engine, path.clone(), batch_size, supplier_keys).await?
        {
            return Ok(rows);
        }
    }
    let mut stream = engine
        .scan_parquet_batches(
            path,
            batch_size,
            None,
            Projection::Columns(vec![
                "ps_partkey".to_string(),
                "ps_suppkey".to_string(),
                "ps_supplycost".to_string(),
                "ps_availqty".to_string(),
            ]),
            None,
        )
        .await?;
    let supplier_keys = Arc::new(supplier_keys.clone());
    let (values, total) = parallel_batch_fold(
        &mut stream,
        move |batch| q11_important_stock_batch(batch, &supplier_keys),
        (fast_hash_map::<i64, f64>(), 0.0_f64),
        |(values, total), (batch_values, batch_total)| {
            *total += batch_total;
            for (partkey, value) in batch_values {
                *values.entry(partkey).or_insert(0.0) += value;
            }
        },
        "Q11 partsupp value",
    )?;
    let threshold = total * 0.0001;
    let mut rows = values
        .into_iter()
        .filter_map(|(ps_partkey, value)| {
            (value > threshold).then_some(Q11Row { ps_partkey, value })
        })
        .collect::<Vec<_>>();
    rows.sort_by(|left, right| {
        right
            .value
            .partial_cmp(&left.value)
            .unwrap_or(std::cmp::Ordering::Equal)
            .then_with(|| left.ps_partkey.cmp(&right.ps_partkey))
    });
    Ok(rows)
}

async fn q11_important_stock_rows_late(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    supplier_keys: &AdaptiveI64Set,
) -> Result<Option<Vec<Q11Row>>> {
    let supplier_keys = Arc::new(supplier_keys.clone());
    let max_dense_partkey = engine
        .parquet_i64_column_max(path.clone(), "ps_partkey")
        .await?
        .and_then(|max_key| adaptive_dense_index(max_key, DEFAULT_MAX_DENSE_I64_KEY));
    let Some(chunks) = engine
        .late_materialized_parquet_map_pruned_with_policy_view(
            path,
            batch_size,
            Projection::Columns(vec!["ps_suppkey".to_string()]),
            Projection::Columns(vec![
                "ps_partkey".to_string(),
                "ps_supplycost".to_string(),
                "ps_availqty".to_string(),
            ]),
            Vec::new(),
            q11_late_materialized_row_group_chunk(),
            LateMaterializationPolicy::selective_with_selector_run_ratio(
                q11_late_materialized_max_selected_ratio(),
                q11_late_materialized_max_selector_run_ratio(),
            ),
            {
                let supplier_keys = supplier_keys.clone();
                move || Q11LateStockState {
                    supplier_keys: supplier_keys.clone(),
                    values: Vec::new(),
                    total: 0.0,
                }
            },
            q11_late_build_suppkey_selection_view,
            q11_late_consume_stock_payload_view,
            |state, _metrics| Ok(Some((state.values, state.total))),
        )
        .await?
    else {
        return Ok(None);
    };
    let mut dense_values = DenseI64F64Sum::new();
    if let Some(max_partkey) = max_dense_partkey {
        dense_values.reserve_dense_to(max_partkey);
    }
    let mut fallback_values = max_dense_partkey.is_none().then(fast_hash_map::<i64, f64>);
    let mut total = 0.0_f64;
    let mut metrics = LateMaterializedMetrics::default();
    for chunk in chunks {
        metrics.add(chunk.metrics);
        let (chunk_values, chunk_total) = chunk.output;
        total += chunk_total;
        for (partkey, value) in chunk_values {
            if let Some(values) = fallback_values.as_mut() {
                *values.entry(partkey).or_insert(0.0) += value;
                continue;
            }
            let Some(index) = adaptive_dense_index(partkey, DEFAULT_MAX_DENSE_I64_KEY) else {
                let mut values = fast_hash_map::<i64, f64>();
                for (key, value) in std::mem::replace(&mut dense_values, DenseI64F64Sum::new())
                    .into_filtered_hash(|_| true)
                {
                    values.insert(key, value);
                }
                fallback_values = Some(values);
                let values = fallback_values.get_or_insert_with(fast_hash_map);
                *values.entry(partkey).or_insert(0.0) += value;
                continue;
            };
            dense_values.add_dense_index(index, value);
        }
    }
    q11_log_late_materialized_profile(metrics, q11_late_materialized_row_group_chunk());
    let rows = if let Some(values) = fallback_values {
        q11_rows_from_values(values, total)
    } else {
        q11_rows_from_dense_values(dense_values, total)
    };
    Ok(Some(rows))
}

fn q11_rows_from_values(values: FastHashMap<i64, f64>, total: f64) -> Vec<Q11Row> {
    let threshold = total * 0.0001;
    let mut rows = values
        .into_iter()
        .filter_map(|(ps_partkey, value)| {
            (value > threshold).then_some(Q11Row { ps_partkey, value })
        })
        .collect::<Vec<_>>();
    rows.sort_by(|left, right| {
        right
            .value
            .partial_cmp(&left.value)
            .unwrap_or(std::cmp::Ordering::Equal)
            .then_with(|| left.ps_partkey.cmp(&right.ps_partkey))
    });
    rows
}

fn q11_rows_from_dense_values(values: DenseI64F64Sum, total: f64) -> Vec<Q11Row> {
    let threshold = total * 0.0001;
    let mut rows = values
        .into_filtered_hash(|value| value > threshold)
        .into_iter()
        .map(|(ps_partkey, value)| Q11Row { ps_partkey, value })
        .collect::<Vec<_>>();
    rows.sort_by(|left, right| {
        right
            .value
            .partial_cmp(&left.value)
            .unwrap_or(std::cmp::Ordering::Equal)
            .then_with(|| left.ps_partkey.cmp(&right.ps_partkey))
    });
    rows
}

fn q11_late_materialized_enabled() -> bool {
    std::env::var_os("DODAM_Q11_DISABLE_LATE_MATERIALIZE").is_none()
}

fn q11_late_materialized_row_group_chunk() -> usize {
    std::env::var("DODAM_Q11_LATE_ROW_GROUP_CHUNK")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(1)
}

fn q11_late_materialized_max_selected_ratio() -> f64 {
    std::env::var("DODAM_Q11_LATE_MAX_SELECTED_RATIO")
        .ok()
        .and_then(|value| value.parse::<f64>().ok())
        .filter(|value| value.is_finite())
        .unwrap_or(0.10)
}

fn q11_late_materialized_max_selector_run_ratio() -> f64 {
    std::env::var("DODAM_Q11_LATE_MAX_SELECTOR_RUN_RATIO")
        .ok()
        .and_then(|value| value.parse::<f64>().ok())
        .filter(|value| value.is_finite())
        .unwrap_or(0.20)
}

fn q11_log_late_materialized_profile(metrics: LateMaterializedMetrics, row_group_chunk: usize) {
    if !tpch_profile_enabled() {
        return;
    }
    let ratio = if metrics.total_rows == 0 {
        0.0
    } else {
        metrics.selected_rows as f64 / metrics.total_rows as f64
    };
    eprintln!(
        "[dodam:tpch-profile] Q11 partsupp: late_materialized rows={} selected={} ratio={:.6} selector_runs={} row_group_chunk={}",
        metrics.total_rows, metrics.selected_rows, ratio, metrics.selector_runs, row_group_chunk
    );
}

struct Q11LateStockState {
    supplier_keys: Arc<AdaptiveI64Set>,
    values: Vec<(i64, f64)>,
    total: f64,
}

fn q11_late_build_suppkey_selection_batch(
    batch: RecordBatch,
    selection: &mut LateSelectionBuilder,
    state: &mut Q11LateStockState,
) -> Result<Option<()>> {
    let suppkeys = batch_column(&batch, "ps_suppkey")?;
    let Some(suppkeys) = suppkeys.as_any().downcast_ref::<Int64Array>() else {
        return Ok(None);
    };
    let dense_supplier_keys = state.supplier_keys.dense_contains_slice();
    if suppkeys.null_count() == 0 {
        for &suppkey in suppkeys.values() {
            selection.push(
                state
                    .supplier_keys
                    .contains_cached(dense_supplier_keys, suppkey),
            );
        }
        return Ok(Some(()));
    }
    for row in 0..suppkeys.len() {
        let selected = suppkeys.is_valid(row)
            && state
                .supplier_keys
                .contains_cached(dense_supplier_keys, suppkeys.value(row));
        selection.push(selected);
    }
    Ok(Some(()))
}

fn q11_late_build_suppkey_selection_view(
    view: BatchView<'_>,
    selection: &mut LateSelectionBuilder,
    state: &mut Q11LateStockState,
) -> Result<Option<()>> {
    if view.num_columns() == 1 {
        let Some(suppkeys) = view.i64_vector(0) else {
            return Ok(None);
        };
        let dense_supplier_keys = state.supplier_keys.dense_contains_slice();
        if let Some(suppkey_values) = suppkeys.values_if_null_free() {
            for &suppkey in suppkey_values {
                selection.push(
                    state
                        .supplier_keys
                        .contains_cached(dense_supplier_keys, suppkey),
                );
            }
            return Ok(Some(()));
        }
        for row in 0..suppkeys.len() {
            let selected = !suppkeys.is_null(row)
                && state
                    .supplier_keys
                    .contains_cached(dense_supplier_keys, suppkeys.value(row));
            selection.push(selected);
        }
        return Ok(Some(()));
    }
    let Some(batch) = view.try_record_batch() else {
        return Ok(None);
    };
    q11_late_build_suppkey_selection_batch(batch.clone(), selection, state)
}

fn q11_late_consume_stock_payload_batch(
    batch: RecordBatch,
    state: &mut Q11LateStockState,
) -> Result<Option<()>> {
    let partkeys = batch_column(&batch, "ps_partkey")?;
    let supplycosts = batch_column(&batch, "ps_supplycost")?;
    let availqtys = batch_column(&batch, "ps_availqty")?;
    if let (Some(partkeys), Some(supplycosts), Some(availqtys)) = (
        partkeys.as_any().downcast_ref::<Int64Array>(),
        decimal_input(supplycosts)?,
        availqtys.as_any().downcast_ref::<Int32Array>(),
    ) {
        q11_late_consume_stock_payload_typed(partkeys, supplycosts, availqtys, state);
        return Ok(Some(()));
    }
    for row in 0..batch.num_rows() {
        let (Some(partkey), Some(supplycost), Some(availqty)) = (
            numeric_i64_value(partkeys, row)?,
            numeric_f64_value(supplycosts, row)?,
            numeric_f64_value(availqtys, row)?,
        ) else {
            continue;
        };
        let value = supplycost * availqty;
        state.total += value;
        state.values.push((partkey, value));
    }
    Ok(Some(()))
}

fn q11_late_consume_stock_payload_view(
    view: BatchView<'_>,
    state: &mut Q11LateStockState,
) -> Result<Option<()>> {
    if view.num_columns() == 3
        && let (Some(partkeys), Some(supplycosts), Some(availqtys)) = (
            view.i64_vector(0),
            view.decimal128_vector(1),
            view.i32_vector(2),
        )
    {
        q11_late_consume_stock_payload_vector_typed(partkeys, supplycosts, availqtys, state);
        return Ok(Some(()));
    }
    let Some(batch) = view.try_record_batch() else {
        return Ok(None);
    };
    q11_late_consume_stock_payload_batch(batch.clone(), state)
}

fn q11_late_consume_stock_payload_vector_typed(
    partkeys: I64VectorView<'_>,
    supplycosts: Decimal128VectorView<'_>,
    availqtys: I32VectorView<'_>,
    state: &mut Q11LateStockState,
) {
    let supplycost_values = supplycosts.raw_values();
    let supplycost_scale = supplycosts.scale();
    if let (Some(partkey_values), Some(availqty_values)) = (
        partkeys.values_if_null_free(),
        availqtys.values_if_null_free(),
    ) && supplycosts.null_count() == 0
    {
        for ((&partkey, &supplycost), &availqty) in partkey_values
            .iter()
            .zip(supplycost_values)
            .zip(availqty_values)
        {
            let value = (supplycost as f64 / supplycost_scale) * f64::from(availqty);
            state.total += value;
            state.values.push((partkey, value));
        }
        return;
    }
    for row in 0..partkeys.len() {
        if partkeys.is_null(row) || supplycosts.is_null(row) || availqtys.is_null(row) {
            continue;
        }
        let value =
            (supplycost_values[row] as f64 / supplycost_scale) * f64::from(availqtys.value(row));
        state.total += value;
        state.values.push((partkeys.value(row), value));
    }
}

fn q11_late_consume_stock_payload_typed(
    partkeys: &Int64Array,
    supplycosts: DecimalInput<'_>,
    availqtys: &Int32Array,
    state: &mut Q11LateStockState,
) {
    let supplycost_values = supplycosts.raw_values();
    let supplycost_scale = supplycosts.scale;
    if partkeys.null_count() == 0 && supplycosts.null_count() == 0 && availqtys.null_count() == 0 {
        for ((&partkey, &supplycost), &availqty) in partkeys
            .values()
            .iter()
            .zip(supplycost_values)
            .zip(availqtys.values())
        {
            let value = (supplycost as f64 / supplycost_scale) * f64::from(availqty);
            state.total += value;
            state.values.push((partkey, value));
        }
        return;
    }
    for row in 0..partkeys.len() {
        if partkeys.is_null(row) || supplycosts.is_null(row) || availqtys.is_null(row) {
            continue;
        }
        let value =
            (supplycost_values[row] as f64 / supplycost_scale) * f64::from(availqtys.value(row));
        state.total += value;
        state.values.push((partkeys.value(row), value));
    }
}

fn q11_important_stock_batch(
    batch: RecordBatch,
    supplier_keys: &AdaptiveI64Set,
) -> Result<(FastHashMap<i64, f64>, f64)> {
    let partkeys = batch_column(&batch, "ps_partkey")?;
    let suppkeys = batch_column(&batch, "ps_suppkey")?;
    let supplycosts = batch_column(&batch, "ps_supplycost")?;
    let availqtys = batch_column(&batch, "ps_availqty")?;
    if let Some(result) =
        q11_important_stock_batch_typed(partkeys, suppkeys, supplycosts, availqtys, supplier_keys)?
    {
        return Ok(result);
    }
    let mut values = fast_hash_map();
    let mut total = 0.0_f64;
    for row in 0..batch.num_rows() {
        let (Some(partkey), Some(suppkey), Some(supplycost), Some(availqty)) = (
            numeric_i64_value(partkeys, row)?,
            numeric_i64_value(suppkeys, row)?,
            numeric_f64_value(supplycosts, row)?,
            numeric_f64_value(availqtys, row)?,
        ) else {
            continue;
        };
        if !supplier_keys.contains(suppkey) {
            continue;
        }
        let value = supplycost * availqty;
        total += value;
        *values.entry(partkey).or_insert(0.0) += value;
    }
    Ok((values, total))
}

fn q11_important_stock_batch_typed(
    partkeys: &ArrayRef,
    suppkeys: &ArrayRef,
    supplycosts: &ArrayRef,
    availqtys: &ArrayRef,
    supplier_keys: &AdaptiveI64Set,
) -> Result<Option<(FastHashMap<i64, f64>, f64)>> {
    let (Some(partkeys), Some(suppkeys), Some(supplycosts), Some(availqtys)) = (
        partkeys.as_any().downcast_ref::<Int64Array>(),
        suppkeys.as_any().downcast_ref::<Int64Array>(),
        decimal_input(supplycosts)?,
        availqtys.as_any().downcast_ref::<Int32Array>(),
    ) else {
        return Ok(None);
    };
    let mut values = fast_hash_map_with_capacity(partkeys.len().min(supplier_keys.len() * 4));
    let mut total = 0.0_f64;
    let dense_supplier_keys = supplier_keys.dense_contains_slice();
    let supplycost_values = supplycosts.raw_values();
    let supplycost_scale = supplycosts.scale;
    if partkeys.null_count() == 0
        && suppkeys.null_count() == 0
        && supplycosts.null_count() == 0
        && availqtys.null_count() == 0
    {
        for (((&partkey, &suppkey), &supplycost), &availqty) in partkeys
            .values()
            .iter()
            .zip(suppkeys.values())
            .zip(supplycost_values)
            .zip(availqtys.values())
        {
            if !supplier_keys.contains_cached(dense_supplier_keys, suppkey) {
                continue;
            }
            let value = (supplycost as f64 / supplycost_scale) * f64::from(availqty);
            total += value;
            *values.entry(partkey).or_insert(0.0) += value;
        }
        return Ok(Some((values, total)));
    }
    for row in 0..partkeys.len() {
        if partkeys.is_null(row)
            || suppkeys.is_null(row)
            || supplycosts.is_null(row)
            || availqtys.is_null(row)
        {
            continue;
        }
        let suppkey = suppkeys.value(row);
        if !supplier_keys.contains_cached(dense_supplier_keys, suppkey) {
            continue;
        }
        let value =
            (supplycost_values[row] as f64 / supplycost_scale) * f64::from(availqtys.value(row));
        total += value;
        *values.entry(partkeys.value(row)).or_insert(0.0) += value;
    }
    Ok(Some((values, total)))
}

struct Q11Row {
    ps_partkey: i64,
    value: f64,
}

fn q11_output(rows: Vec<Q11Row>) -> Result<QueryOutput> {
    let batch = RecordBatch::try_new(
        Arc::new(Schema::new(vec![
            Field::new("ps_partkey", DataType::Int64, false),
            Field::new("value", DataType::Float64, false),
        ])),
        vec![
            Arc::new(Int64Array::from_iter_values(
                rows.iter().map(|row| row.ps_partkey),
            )),
            Arc::new(Float64Array::from_iter_values(
                rows.iter().map(|row| row.value),
            )),
        ],
    )?;
    Ok(QueryOutput::Aggregate {
        metrics: AggregateMetrics::default(),
        batches: vec![batch],
    })
}

fn string_inequality_literal(conjuncts: &[SqlExpr], column: &str) -> Result<Option<String>> {
    for conjunct in conjuncts {
        let SqlExpr::BinaryOp { left, op, right } = conjunct else {
            continue;
        };
        if *op != BinaryOperator::NotEq {
            continue;
        }
        if sql_expr_column_matches(left, column) {
            if let LiteralValue::Utf8(value) = sql_literal_value(right)? {
                return Ok(Some(value));
            }
        } else if sql_expr_column_matches(right, column)
            && let LiteralValue::Utf8(value) = sql_literal_value(left)?
        {
            return Ok(Some(value));
        }
    }
    Ok(None)
}

fn not_like_prefix_literal(conjuncts: &[SqlExpr], column: &str) -> Result<Option<String>> {
    for conjunct in conjuncts {
        let SqlExpr::Like {
            expr,
            pattern,
            negated,
            ..
        } = conjunct
        else {
            continue;
        };
        if !*negated || !sql_expr_column_matches(expr, column) {
            continue;
        }
        let LiteralValue::Utf8(pattern) = sql_literal_value(pattern)? else {
            continue;
        };
        if let Some(value) = pattern.strip_suffix('%')
            && !value.contains('%')
            && !value.contains('_')
        {
            return Ok(Some(value.to_string()));
        }
    }
    Ok(None)
}

fn numeric_in_i64_literals(conjuncts: &[SqlExpr], column: &str) -> Result<Option<HashSet<i64>>> {
    for conjunct in conjuncts {
        let SqlExpr::InList {
            expr,
            list,
            negated,
        } = conjunct
        else {
            continue;
        };
        if *negated || !sql_expr_column_matches(expr, column) {
            continue;
        }
        let mut values = HashSet::new();
        for item in list {
            values.insert(literal_as_f64(&sql_literal_value(item)?)? as i64);
        }
        return Ok(Some(values));
    }
    Ok(None)
}

fn like_substrings_literal(expr: &SqlExpr, column: &str) -> Result<Option<Vec<String>>> {
    match expr {
        SqlExpr::Like {
            expr,
            pattern,
            negated,
            ..
        } if !*negated && sql_expr_column_matches(expr, column) => {
            let LiteralValue::Utf8(pattern) = sql_literal_value(pattern)? else {
                return Ok(None);
            };
            let parts = pattern
                .split('%')
                .filter(|part| !part.is_empty())
                .map(str::to_string)
                .collect::<Vec<_>>();
            Ok((!parts.is_empty() && !pattern.contains('_')).then_some(parts))
        }
        SqlExpr::Exists { subquery, .. }
        | SqlExpr::InSubquery { subquery, .. }
        | SqlExpr::Subquery(subquery) => {
            if let SetExpr::Select(select) = subquery.body.as_ref()
                && let Some(selection) = select.selection.as_ref()
            {
                return like_substrings_literal(selection, column);
            }
            Ok(None)
        }
        SqlExpr::BinaryOp { left, right, .. } => {
            Ok(like_substrings_literal(left, column)?.or(like_substrings_literal(right, column)?))
        }
        SqlExpr::Nested(expr) | SqlExpr::UnaryOp { expr, .. } => {
            like_substrings_literal(expr, column)
        }
        SqlExpr::InList { expr, list, .. } => {
            if let Some(parts) = like_substrings_literal(expr, column)? {
                return Ok(Some(parts));
            }
            for item in list {
                if let Some(parts) = like_substrings_literal(item, column)? {
                    return Ok(Some(parts));
                }
            }
            Ok(None)
        }
        _ => Ok(None),
    }
}

struct Q16BadSuppliers {
    keys: HashSet<i64>,
    max_suppkey: Option<i64>,
}

async fn q16_bad_suppliers(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    comment_parts: &[String],
) -> Result<Q16BadSuppliers> {
    let comment_part_bytes = comment_parts
        .iter()
        .map(|part| part.as_bytes().to_vec())
        .collect::<Vec<_>>();
    let comment_finders = comment_part_bytes
        .iter()
        .map(|part| Finder::new(part))
        .collect::<Vec<_>>();
    let mut stream = engine
        .scan_parquet_batches(
            path,
            batch_size,
            None,
            Projection::Columns(vec!["s_suppkey".to_string(), "s_comment".to_string()]),
            None,
        )
        .await?;
    let mut suppliers = HashSet::new();
    let mut max_suppkey = None::<i64>;
    while let Some(batch) = stream.next() {
        let batch = batch?;
        let suppkeys = batch_column(&batch, "s_suppkey")?;
        let comments = batch_string_column(&batch, "s_comment")?;
        if let Some(suppkeys) = suppkeys.as_any().downcast_ref::<Int64Array>()
            && suppkeys.null_count() == 0
        {
            let suppkey_values = suppkeys.values().as_ref();
            if comments.null_count() == 0 {
                for (row, &suppkey) in suppkey_values.iter().enumerate() {
                    max_suppkey = Some(max_suppkey.map_or(suppkey, |max_key| max_key.max(suppkey)));
                    if fast_like_substrings_row_matches_non_null(
                        comments,
                        row,
                        &comment_part_bytes,
                        &comment_finders,
                        false,
                    ) {
                        suppliers.insert(suppkey);
                    }
                }
                continue;
            }
            for (row, &suppkey) in suppkey_values.iter().enumerate() {
                max_suppkey = Some(max_suppkey.map_or(suppkey, |max_key| max_key.max(suppkey)));
                if fast_like_substrings_row_matches(
                    comments,
                    row,
                    &comment_part_bytes,
                    &comment_finders,
                    false,
                ) {
                    suppliers.insert(suppkey);
                }
            }
            continue;
        }
        for row in 0..batch.num_rows() {
            let Some(suppkey) = numeric_i64_value(suppkeys, row)? else {
                continue;
            };
            max_suppkey = Some(max_suppkey.map_or(suppkey, |max_key| max_key.max(suppkey)));
            if comments.is_null(row)
                || !fast_like_substrings_row_matches(
                    comments,
                    row,
                    &comment_part_bytes,
                    &comment_finders,
                    false,
                )
            {
                continue;
            }
            suppliers.insert(suppkey);
        }
    }
    Ok(Q16BadSuppliers {
        keys: suppliers,
        max_suppkey,
    })
}

#[derive(Clone, Eq, Hash, PartialEq)]
struct Q16GroupKey {
    brand: String,
    type_name: String,
    size: i64,
}

#[derive(Clone, Copy, Eq, Hash, PartialEq)]
struct Q16GroupIdKey {
    brand_id: usize,
    type_id: usize,
    size: i64,
}

struct Q16PartGroups {
    groups: Vec<Q16GroupKey>,
    part_to_group: AdaptiveI64Map<usize>,
}

async fn q16_part_groups(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    excluded_brand: &str,
    excluded_type_prefix: &str,
    sizes: &AdaptiveI64Set,
) -> Result<Q16PartGroups> {
    let projection = Projection::Columns(vec![
        "p_partkey".to_string(),
        "p_brand".to_string(),
        "p_type".to_string(),
        "p_size".to_string(),
    ]);
    if q16_part_dictionary_strings_enabled() {
        let excluded_brand_owned = Arc::new(excluded_brand.to_string());
        let excluded_type_prefix_owned = Arc::new(excluded_type_prefix.to_string());
        let sizes = Arc::new(sizes.clone());
        if let Some(partials) = engine
            .parquet_row_group_map_dictionary_columns_pruned_view(
                path.clone(),
                batch_size,
                projection.clone(),
                vec!["p_brand".to_string(), "p_type".to_string()],
                Vec::new(),
                q16_part_group_chunk_size(),
                Q16PartGroupPartial::default,
                {
                    let excluded_brand = excluded_brand_owned.clone();
                    let excluded_type_prefix = excluded_type_prefix_owned.clone();
                    let sizes = sizes.clone();
                    move |view, partial| {
                        q16_part_groups_partial_view(
                            view,
                            &excluded_brand,
                            &excluded_type_prefix,
                            &sizes,
                            partial,
                        )?;
                        Ok(Some(()))
                    }
                },
                |partial| Ok(Some(partial)),
            )
            .await?
        {
            return q16_merge_part_group_partials(partials);
        }
    }
    let mut stream = if q16_part_dictionary_strings_enabled() {
        engine
            .scan_parquet_batches_dictionary_columns(
                path,
                batch_size,
                projection,
                vec!["p_brand".to_string(), "p_type".to_string()],
            )
            .await?
    } else {
        engine
            .scan_parquet_batches(path, batch_size, None, projection, None)
            .await?
    };
    let mut brand_ids = fast_hash_map::<String, usize>();
    let mut type_ids = fast_hash_map::<String, usize>();
    let mut brands_by_id = Vec::<String>::new();
    let mut types_by_id = Vec::<String>::new();
    let mut group_ids = FastHashMap::<Q16GroupIdKey, usize>::default();
    let mut groups = Vec::<Q16GroupKey>::new();
    let mut part_to_group = fast_hash_map::<i64, usize>();
    while let Some(batch) = stream.next() {
        let batch = batch?;
        let view = BatchView::new(&batch);
        if let Some(layout) = Q16PartDictionaryView::try_new(view)
            && q16_part_groups_dictionary_typed_batch(
                layout,
                excluded_brand,
                excluded_type_prefix,
                sizes,
                &mut brand_ids,
                &mut type_ids,
                &mut brands_by_id,
                &mut types_by_id,
                &mut group_ids,
                &mut groups,
                &mut part_to_group,
            )?
        {
            continue;
        }
        let size_view = if let Some(values) = view.i32_vector(3) {
            Q16PartSizeView::I32(values)
        } else if let Some(values) = view.i64_vector(3) {
            Q16PartSizeView::I64(values)
        } else {
            let Some(batch) = view.try_record_batch() else {
                return Err(DodamError::UnsupportedSql(
                    "Q16 part-group size raw vector has unsupported type".to_string(),
                ));
            };
            q16_part_groups_batch_fallback(
                batch,
                excluded_brand,
                excluded_type_prefix,
                sizes,
                &mut brand_ids,
                &mut type_ids,
                &mut brands_by_id,
                &mut types_by_id,
                &mut group_ids,
                &mut groups,
                &mut part_to_group,
            )?;
            continue;
        };
        let Some(brands) = view.utf8(1) else {
            return Err(DodamError::UnsupportedSql(
                "p_brand must be Utf8".to_string(),
            ));
        };
        let Some(types) = view.utf8(2) else {
            return Err(DodamError::UnsupportedSql(
                "p_type must be Utf8".to_string(),
            ));
        };
        if let Some(partkeys) = view.i64_vector(0)
            && q16_part_groups_vector_batch(
                partkeys,
                brands,
                types,
                size_view,
                excluded_brand,
                excluded_type_prefix,
                sizes,
                &mut brand_ids,
                &mut type_ids,
                &mut brands_by_id,
                &mut types_by_id,
                &mut group_ids,
                &mut groups,
                &mut part_to_group,
            )?
        {
            continue;
        }
        let Some(batch) = view.try_record_batch() else {
            return Err(DodamError::UnsupportedSql(
                "Q16 part-group raw vector columns have unsupported nullable layout".to_string(),
            ));
        };
        q16_part_groups_batch_fallback(
            batch,
            excluded_brand,
            excluded_type_prefix,
            sizes,
            &mut brand_ids,
            &mut type_ids,
            &mut brands_by_id,
            &mut types_by_id,
            &mut group_ids,
            &mut groups,
            &mut part_to_group,
        )?;
    }
    Ok(Q16PartGroups {
        groups,
        part_to_group: AdaptiveI64Map::from_hash(part_to_group),
    })
}

#[allow(clippy::too_many_arguments)]
fn q16_part_groups_batch_fallback(
    batch: &RecordBatch,
    excluded_brand: &str,
    excluded_type_prefix: &str,
    sizes: &AdaptiveI64Set,
    brand_ids: &mut FastHashMap<String, usize>,
    type_ids: &mut FastHashMap<String, usize>,
    brands_by_id: &mut Vec<String>,
    types_by_id: &mut Vec<String>,
    group_ids: &mut FastHashMap<Q16GroupIdKey, usize>,
    groups: &mut Vec<Q16GroupKey>,
    part_to_group: &mut FastHashMap<i64, usize>,
) -> Result<()> {
    let partkeys = batch_column(batch, "p_partkey")?;
    let part_sizes = batch_column(batch, "p_size")?;
    let brands = batch_string_column(batch, "p_brand")?;
    let types = batch_string_column(batch, "p_type")?;
    if q16_part_groups_typed_batch(
        partkeys,
        brands,
        types,
        part_sizes,
        excluded_brand,
        excluded_type_prefix,
        sizes,
        brand_ids,
        type_ids,
        brands_by_id,
        types_by_id,
        group_ids,
        groups,
        part_to_group,
    )? {
        return Ok(());
    }
    for row in 0..batch.num_rows() {
        let (Some(partkey), Some(size)) = (
            numeric_i64_value(partkeys, row)?,
            numeric_i64_value(part_sizes, row)?,
        ) else {
            continue;
        };
        if !sizes.contains(size) {
            continue;
        }
        if brands.is_null(row)
            || types.is_null(row)
            || brands.value(row) == excluded_brand
            || types.value(row).starts_with(excluded_type_prefix)
        {
            continue;
        }
        let brand_id = q16_intern_string(brand_ids, brands_by_id, brands.value(row));
        let type_id = q16_intern_string(type_ids, types_by_id, types.value(row));
        let key = Q16GroupIdKey {
            brand_id,
            type_id,
            size,
        };
        let group_id = if let Some(group_id) = group_ids.get(&key).copied() {
            group_id
        } else {
            let group_id = groups.len();
            groups.push(Q16GroupKey {
                brand: brands_by_id[brand_id].clone(),
                type_name: types_by_id[type_id].clone(),
                size,
            });
            group_ids.insert(key, group_id);
            group_id
        };
        part_to_group.insert(partkey, group_id);
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn q16_part_groups_vector_batch(
    partkeys: I64VectorView<'_>,
    brands: &StringArray,
    types: &StringArray,
    part_sizes: Q16PartSizeView<'_>,
    excluded_brand: &str,
    excluded_type_prefix: &str,
    sizes: &AdaptiveI64Set,
    brand_ids: &mut FastHashMap<String, usize>,
    type_ids: &mut FastHashMap<String, usize>,
    brands_by_id: &mut Vec<String>,
    types_by_id: &mut Vec<String>,
    group_ids: &mut FastHashMap<Q16GroupIdKey, usize>,
    groups: &mut Vec<Q16GroupKey>,
    part_to_group: &mut FastHashMap<i64, usize>,
) -> Result<bool> {
    let Some(partkey_values) = partkeys.values_if_null_free() else {
        return Ok(false);
    };
    if brands.null_count() != 0 || types.null_count() != 0 || part_sizes.null_count() != 0 {
        return Ok(false);
    }
    for (row, &partkey) in partkey_values.iter().enumerate() {
        let size = part_sizes.value_i64(row);
        if !sizes.contains(size) {
            continue;
        }
        q16_insert_part_group_row(
            partkey,
            size,
            brands.value(row),
            types.value(row),
            excluded_brand,
            excluded_type_prefix,
            brand_ids,
            type_ids,
            brands_by_id,
            types_by_id,
            group_ids,
            groups,
            part_to_group,
        );
    }
    Ok(true)
}

fn q16_part_dictionary_strings_enabled() -> bool {
    std::env::var_os("DODAM_Q16_DISABLE_PART_DICTIONARY_STRINGS").is_none()
}

fn q16_part_group_chunk_size() -> usize {
    std::env::var("DODAM_Q16_PART_GROUP_CHUNK_SIZE")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(2)
}

struct Q16PartGroupPartialRow {
    partkey: i64,
    size: i64,
    brand_id: usize,
    type_id: usize,
}

#[derive(Default)]
struct Q16PartGroupPartial {
    brand_ids: FastHashMap<String, usize>,
    type_ids: FastHashMap<String, usize>,
    brands_by_id: Vec<String>,
    types_by_id: Vec<String>,
    rows: Vec<Q16PartGroupPartialRow>,
}

impl Q16PartGroupPartial {
    fn push_row(&mut self, partkey: i64, size: i64, brand: &str, type_name: &str) {
        let brand_id = q16_intern_string(&mut self.brand_ids, &mut self.brands_by_id, brand);
        let type_id = q16_intern_string(&mut self.type_ids, &mut self.types_by_id, type_name);
        self.rows.push(Q16PartGroupPartialRow {
            partkey,
            size,
            brand_id,
            type_id,
        });
    }

    fn push_ids(&mut self, partkey: i64, size: i64, brand_id: usize, type_id: usize) {
        self.rows.push(Q16PartGroupPartialRow {
            partkey,
            size,
            brand_id,
            type_id,
        });
    }
}

enum Q16PartSizeView<'a> {
    I32(I32VectorView<'a>),
    I64(I64VectorView<'a>),
}

impl Q16PartSizeView<'_> {
    fn null_count(&self) -> usize {
        match self {
            Self::I32(values) => values.values_if_null_free().is_none() as usize,
            Self::I64(values) => values.values_if_null_free().is_none() as usize,
        }
    }

    fn value_i64(&self, row: usize) -> i64 {
        match self {
            Self::I32(values) => i64::from(values.value(row)),
            Self::I64(values) => values.value(row),
        }
    }
}

struct Q16PartDictionaryView<'a> {
    partkeys: I64VectorView<'a>,
    brands: DictionaryI32View<'a>,
    types: DictionaryI32View<'a>,
    sizes: Q16PartSizeView<'a>,
}

impl<'a> Q16PartDictionaryView<'a> {
    fn try_new(view: BatchView<'a>) -> Option<Self> {
        let sizes = if let Some(values) = view.i32_vector(3) {
            Q16PartSizeView::I32(values)
        } else {
            Q16PartSizeView::I64(view.i64_vector(3)?)
        };
        Some(Self {
            partkeys: view.i64_vector(0)?,
            brands: view.dictionary_i32_view(1)?,
            types: view.dictionary_i32_view(2)?,
            sizes,
        })
    }
}

#[allow(clippy::too_many_arguments)]
fn q16_part_groups_dictionary_typed_batch(
    view: Q16PartDictionaryView<'_>,
    excluded_brand: &str,
    excluded_type_prefix: &str,
    sizes: &AdaptiveI64Set,
    brand_ids: &mut FastHashMap<String, usize>,
    type_ids: &mut FastHashMap<String, usize>,
    brands_by_id: &mut Vec<String>,
    types_by_id: &mut Vec<String>,
    group_ids: &mut FastHashMap<Q16GroupIdKey, usize>,
    groups: &mut Vec<Q16GroupKey>,
    part_to_group: &mut FastHashMap<i64, usize>,
) -> Result<bool> {
    if view.partkeys.values_if_null_free().is_none()
        || view.brands.null_count() != 0
        || view.types.null_count() != 0
        || view.sizes.null_count() != 0
    {
        return Ok(false);
    }
    let Some(brand_values) = view.brands.string_values() else {
        return Ok(false);
    };
    let Some(type_values) = view.types.string_values() else {
        return Ok(false);
    };
    let brand_lookup = q16_dictionary_group_string_ids(
        &brand_values,
        Some(excluded_brand.as_bytes()),
        None,
        brand_ids,
        brands_by_id,
    )?;
    let type_lookup = q16_dictionary_group_string_ids(
        &type_values,
        None,
        Some(excluded_type_prefix.as_bytes()),
        type_ids,
        types_by_id,
    )?;
    let brand_keys = view.brands.keys();
    let type_keys = view.types.keys();
    let partkey_values = view
        .partkeys
        .values_if_null_free()
        .expect("checked partkeys");
    for row in 0..partkey_values.len() {
        let size = view.sizes.value_i64(row);
        if !sizes.contains(size) {
            continue;
        }
        let (Some(brand_id), Some(type_id)) = (
            q16_dictionary_lookup_id(&brand_lookup, brand_keys[row]),
            q16_dictionary_lookup_id(&type_lookup, type_keys[row]),
        ) else {
            continue;
        };
        q16_insert_part_group_ids(
            partkey_values[row],
            size,
            brand_id,
            type_id,
            brands_by_id,
            types_by_id,
            group_ids,
            groups,
            part_to_group,
        );
    }
    Ok(true)
}

fn q16_part_groups_partial_view(
    view: BatchView<'_>,
    excluded_brand: &str,
    excluded_type_prefix: &str,
    sizes: &AdaptiveI64Set,
    partial: &mut Q16PartGroupPartial,
) -> Result<()> {
    if let Some(layout) = Q16PartDictionaryView::try_new(view)
        && q16_part_groups_dictionary_partial_batch(
            layout,
            excluded_brand,
            excluded_type_prefix,
            sizes,
            partial,
        )?
    {
        return Ok(());
    }
    let Some(partkeys) = view.i64_vector(0) else {
        return Err(DodamError::UnsupportedSql(
            "Q16 part-group partkey raw vector has unsupported type".to_string(),
        ));
    };
    let Some(brands) = view.utf8(1) else {
        return Err(DodamError::UnsupportedSql(
            "Q16 part-group brand raw vector has unsupported type".to_string(),
        ));
    };
    let Some(types) = view.utf8(2) else {
        return Err(DodamError::UnsupportedSql(
            "Q16 part-group type raw vector has unsupported type".to_string(),
        ));
    };
    let size_view = if let Some(values) = view.i32_vector(3) {
        Q16PartSizeView::I32(values)
    } else {
        let Some(values) = view.i64_vector(3) else {
            return Err(DodamError::UnsupportedSql(
                "Q16 part-group size raw vector has unsupported type".to_string(),
            ));
        };
        Q16PartSizeView::I64(values)
    };
    if partkeys.values_if_null_free().is_none()
        || brands.null_count() != 0
        || types.null_count() != 0
        || size_view.null_count() != 0
    {
        let Some(batch) = view.try_record_batch() else {
            return Err(DodamError::UnsupportedSql(
                "Q16 nullable raw part-group vectors are unsupported".to_string(),
            ));
        };
        return q16_part_groups_partial_batch(
            batch,
            excluded_brand,
            excluded_type_prefix,
            sizes,
            partial,
        );
    }
    for row in 0..partkeys.len() {
        let size = size_view.value_i64(row);
        if !sizes.contains(size) {
            continue;
        }
        let brand = brands.value(row);
        let type_name = types.value(row);
        if brand == excluded_brand || type_name.starts_with(excluded_type_prefix) {
            continue;
        }
        partial.push_row(partkeys.value(row), size, brand, type_name);
    }
    Ok(())
}

fn q16_part_groups_dictionary_partial_batch(
    view: Q16PartDictionaryView<'_>,
    excluded_brand: &str,
    excluded_type_prefix: &str,
    sizes: &AdaptiveI64Set,
    partial: &mut Q16PartGroupPartial,
) -> Result<bool> {
    if view.partkeys.values_if_null_free().is_none()
        || view.brands.null_count() != 0
        || view.types.null_count() != 0
        || view.sizes.null_count() != 0
    {
        return Ok(false);
    }
    let Some(brand_values) = view.brands.string_values() else {
        return Ok(false);
    };
    let Some(type_values) = view.types.string_values() else {
        return Ok(false);
    };
    let brand_lookup = q16_dictionary_group_string_ids(
        &brand_values,
        Some(excluded_brand.as_bytes()),
        None,
        &mut partial.brand_ids,
        &mut partial.brands_by_id,
    )?;
    let type_lookup = q16_dictionary_group_string_ids(
        &type_values,
        None,
        Some(excluded_type_prefix.as_bytes()),
        &mut partial.type_ids,
        &mut partial.types_by_id,
    )?;
    let brand_keys = view.brands.keys();
    let type_keys = view.types.keys();
    let partkey_values = view
        .partkeys
        .values_if_null_free()
        .expect("checked partkeys");
    for row in 0..partkey_values.len() {
        let size = view.sizes.value_i64(row);
        if !sizes.contains(size) {
            continue;
        }
        let (Some(brand_id), Some(type_id)) = (
            q16_dictionary_lookup_id(&brand_lookup, brand_keys[row]),
            q16_dictionary_lookup_id(&type_lookup, type_keys[row]),
        ) else {
            continue;
        };
        partial.push_ids(partkey_values[row], size, brand_id, type_id);
    }
    Ok(true)
}

fn q16_part_groups_partial_batch(
    batch: &RecordBatch,
    excluded_brand: &str,
    excluded_type_prefix: &str,
    sizes: &AdaptiveI64Set,
    partial: &mut Q16PartGroupPartial,
) -> Result<()> {
    let partkeys = batch_column(batch, "p_partkey")?;
    let part_sizes = batch_column(batch, "p_size")?;
    let Some(brands) = batch_string_column(batch, "p_brand").ok() else {
        return Err(DodamError::UnsupportedSql(
            "p_brand must be Utf8".to_string(),
        ));
    };
    let Some(types) = batch_string_column(batch, "p_type").ok() else {
        return Err(DodamError::UnsupportedSql(
            "p_type must be Utf8".to_string(),
        ));
    };
    for row in 0..batch.num_rows() {
        let (Some(partkey), Some(size)) = (
            numeric_i64_value(partkeys, row)?,
            numeric_i64_value(part_sizes, row)?,
        ) else {
            continue;
        };
        if !sizes.contains(size) {
            continue;
        }
        if brands.is_null(row) || types.is_null(row) {
            continue;
        }
        let brand = brands.value(row);
        let type_name = types.value(row);
        if brand == excluded_brand || type_name.starts_with(excluded_type_prefix) {
            continue;
        }
        partial.push_row(partkey, size, brand, type_name);
    }
    Ok(())
}

fn q16_merge_part_group_partials(partials: Vec<Q16PartGroupPartial>) -> Result<Q16PartGroups> {
    let mut brand_ids = fast_hash_map::<String, usize>();
    let mut type_ids = fast_hash_map::<String, usize>();
    let mut brands_by_id = Vec::<String>::new();
    let mut types_by_id = Vec::<String>::new();
    let mut group_ids = FastHashMap::<Q16GroupIdKey, usize>::default();
    let mut groups = Vec::<Q16GroupKey>::new();
    let mut part_to_group = fast_hash_map::<i64, usize>();
    for partial in partials {
        let brand_remap = partial
            .brands_by_id
            .iter()
            .map(|value| q16_intern_string(&mut brand_ids, &mut brands_by_id, value))
            .collect::<Vec<_>>();
        let type_remap = partial
            .types_by_id
            .iter()
            .map(|value| q16_intern_string(&mut type_ids, &mut types_by_id, value))
            .collect::<Vec<_>>();
        for row in partial.rows {
            let Some(&brand_id) = brand_remap.get(row.brand_id) else {
                continue;
            };
            let Some(&type_id) = type_remap.get(row.type_id) else {
                continue;
            };
            q16_insert_part_group_ids(
                row.partkey,
                row.size,
                brand_id,
                type_id,
                &brands_by_id,
                &types_by_id,
                &mut group_ids,
                &mut groups,
                &mut part_to_group,
            );
        }
    }
    Ok(Q16PartGroups {
        groups,
        part_to_group: AdaptiveI64Map::from_hash(part_to_group),
    })
}

fn q16_dictionary_group_string_ids<S: BuildHasher>(
    values: &DictionaryStringValues<'_>,
    excluded_exact: Option<&[u8]>,
    excluded_prefix: Option<&[u8]>,
    ids: &mut HashMap<String, usize, S>,
    strings_by_id: &mut Vec<String>,
) -> Result<Vec<Option<usize>>> {
    let mut lookup = Vec::with_capacity(values.len());
    for index in 0..values.len() {
        let value = values.value_bytes(index);
        if excluded_exact.is_some_and(|excluded| value == excluded)
            || excluded_prefix.is_some_and(|prefix| value.starts_with(prefix))
        {
            lookup.push(None);
            continue;
        }
        let value = std::str::from_utf8(value)
            .map_err(|error| DodamError::UnsupportedSql(error.to_string()))?;
        lookup.push(Some(q16_intern_string(ids, strings_by_id, value)));
    }
    Ok(lookup)
}

fn q16_dictionary_lookup_id(lookup: &[Option<usize>], key: i32) -> Option<usize> {
    let key = usize::try_from(key).ok()?;
    lookup.get(key).copied().flatten()
}

#[allow(clippy::too_many_arguments)]
fn q16_part_groups_typed_batch(
    partkeys: &ArrayRef,
    brands: &StringArray,
    types: &StringArray,
    part_sizes: &ArrayRef,
    excluded_brand: &str,
    excluded_type_prefix: &str,
    sizes: &AdaptiveI64Set,
    brand_ids: &mut FastHashMap<String, usize>,
    type_ids: &mut FastHashMap<String, usize>,
    brands_by_id: &mut Vec<String>,
    types_by_id: &mut Vec<String>,
    group_ids: &mut FastHashMap<Q16GroupIdKey, usize>,
    groups: &mut Vec<Q16GroupKey>,
    part_to_group: &mut FastHashMap<i64, usize>,
) -> Result<bool> {
    let Some(partkeys) = partkeys.as_any().downcast_ref::<Int64Array>() else {
        return Ok(false);
    };
    if partkeys.null_count() != 0 || brands.null_count() != 0 || types.null_count() != 0 {
        return Ok(false);
    }
    if let Some(part_sizes) = part_sizes.as_any().downcast_ref::<Int32Array>() {
        if part_sizes.null_count() != 0 {
            return Ok(false);
        }
        let partkey_values = partkeys.values().as_ref();
        let size_values = part_sizes.values().as_ref();
        for row in 0..partkey_values.len() {
            let size = i64::from(size_values[row]);
            if !sizes.contains(size) {
                continue;
            }
            q16_insert_part_group_row(
                partkey_values[row],
                size,
                brands.value(row),
                types.value(row),
                excluded_brand,
                excluded_type_prefix,
                brand_ids,
                type_ids,
                brands_by_id,
                types_by_id,
                group_ids,
                groups,
                part_to_group,
            );
        }
        return Ok(true);
    }
    if let Some(part_sizes) = part_sizes.as_any().downcast_ref::<Int64Array>() {
        if part_sizes.null_count() != 0 {
            return Ok(false);
        }
        let partkey_values = partkeys.values().as_ref();
        let size_values = part_sizes.values().as_ref();
        for row in 0..partkey_values.len() {
            let size = size_values[row];
            if !sizes.contains(size) {
                continue;
            }
            q16_insert_part_group_row(
                partkey_values[row],
                size,
                brands.value(row),
                types.value(row),
                excluded_brand,
                excluded_type_prefix,
                brand_ids,
                type_ids,
                brands_by_id,
                types_by_id,
                group_ids,
                groups,
                part_to_group,
            );
        }
        return Ok(true);
    }
    Ok(false)
}

#[allow(clippy::too_many_arguments)]
fn q16_insert_part_group_row(
    partkey: i64,
    size: i64,
    brand: &str,
    type_name: &str,
    excluded_brand: &str,
    excluded_type_prefix: &str,
    brand_ids: &mut FastHashMap<String, usize>,
    type_ids: &mut FastHashMap<String, usize>,
    brands_by_id: &mut Vec<String>,
    types_by_id: &mut Vec<String>,
    group_ids: &mut FastHashMap<Q16GroupIdKey, usize>,
    groups: &mut Vec<Q16GroupKey>,
    part_to_group: &mut FastHashMap<i64, usize>,
) {
    if brand == excluded_brand || type_name.starts_with(excluded_type_prefix) {
        return;
    }
    let brand_id = q16_intern_string(brand_ids, brands_by_id, brand);
    let type_id = q16_intern_string(type_ids, types_by_id, type_name);
    q16_insert_part_group_ids(
        partkey,
        size,
        brand_id,
        type_id,
        brands_by_id,
        types_by_id,
        group_ids,
        groups,
        part_to_group,
    );
}

#[allow(clippy::too_many_arguments)]
fn q16_insert_part_group_ids(
    partkey: i64,
    size: i64,
    brand_id: usize,
    type_id: usize,
    brands_by_id: &[String],
    types_by_id: &[String],
    group_ids: &mut FastHashMap<Q16GroupIdKey, usize>,
    groups: &mut Vec<Q16GroupKey>,
    part_to_group: &mut FastHashMap<i64, usize>,
) {
    let key = Q16GroupIdKey {
        brand_id,
        type_id,
        size,
    };
    let group_id = if let Some(group_id) = group_ids.get(&key).copied() {
        group_id
    } else {
        let group_id = groups.len();
        groups.push(Q16GroupKey {
            brand: brands_by_id[brand_id].clone(),
            type_name: types_by_id[type_id].clone(),
            size,
        });
        group_ids.insert(key, group_id);
        group_id
    };
    part_to_group.insert(partkey, group_id);
}

fn q16_intern_string<S: BuildHasher>(
    ids: &mut HashMap<String, usize, S>,
    values: &mut Vec<String>,
    value: &str,
) -> usize {
    if let Some(id) = ids.get(value).copied() {
        return id;
    }
    let id = values.len();
    let value = value.to_string();
    values.push(value.clone());
    ids.insert(value, id);
    id
}

struct Q16Row {
    brand: String,
    type_name: String,
    size: i64,
    supplier_count: u64,
}

async fn q16_supplier_counts(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    part_groups: Q16PartGroups,
    bad_suppliers: Q16BadSuppliers,
) -> Result<Vec<Q16Row>> {
    let groups = part_groups.groups;
    let part_to_group = Arc::new(part_groups.part_to_group);
    let bad_supplier_keys = Arc::new(AdaptiveI64Set::from_hash(bad_suppliers.keys));
    let projection = Projection::Columns(vec!["ps_partkey".to_string(), "ps_suppkey".to_string()]);
    let supplier_counts = if q16_packed_distinct_enabled(groups.len(), bad_suppliers.max_suppkey) {
        let Some(partials) = engine
            .parquet_row_group_map_view(
                path.clone(),
                batch_size,
                projection.clone(),
                q16_supplier_count_chunk_size(),
                PackedU32PairDistinct::new,
                {
                    let part_to_group = part_to_group.clone();
                    let bad_supplier_keys = bad_supplier_keys.clone();
                    move |view, distinct_suppliers| {
                        q16_supplier_counts_packed_view(
                            view,
                            &part_to_group,
                            &bad_supplier_keys,
                            distinct_suppliers,
                        )?;
                        Ok(Some(()))
                    }
                },
                |distinct_suppliers| Ok(Some(distinct_suppliers)),
            )
            .await?
        else {
            return Err(DodamError::UnsupportedSql(
                "Q16 partsupp row-group map is unavailable".to_string(),
            ));
        };
        let mut packed = PackedU32PairDistinct::new();
        for partial in partials {
            q16_merge_supplier_counts_packed(&mut packed, partial);
        }
        packed.counts_by_first(groups.len())
    } else if let Some(layout) = q16_supplier_bitset_layout(groups.len(), bad_suppliers.max_suppkey)
    {
        let Some(partials) = engine
            .parquet_row_group_map_view(
                path.clone(),
                batch_size,
                projection.clone(),
                q16_supplier_count_chunk_size(),
                {
                    let layout = layout.clone();
                    move || Q16GroupSupplierBitset::new(layout.clone())
                },
                {
                    let part_to_group = part_to_group.clone();
                    let bad_supplier_keys = bad_supplier_keys.clone();
                    move |view, distinct_suppliers| {
                        q16_supplier_counts_bitset_view(
                            view,
                            &part_to_group,
                            &bad_supplier_keys,
                            distinct_suppliers,
                        )?;
                        Ok(Some(()))
                    }
                },
                |distinct_suppliers| Ok(Some(distinct_suppliers)),
            )
            .await?
        else {
            return Err(DodamError::UnsupportedSql(
                "Q16 partsupp row-group map is unavailable".to_string(),
            ));
        };
        let mut partial = Q16GroupSupplierBitset::new(layout);
        for batch_partial in partials {
            q16_merge_supplier_bitsets(&mut partial, batch_partial);
        }
        partial.counts()
    } else {
        let Some(partials) = engine
            .parquet_row_group_map_view(
                path,
                batch_size,
                projection,
                q16_supplier_count_chunk_size(),
                FastHashSet::<(usize, i64)>::default,
                {
                    let part_to_group = part_to_group.clone();
                    let bad_supplier_keys = bad_supplier_keys.clone();
                    move |view, distinct_suppliers| {
                        let groups =
                            q16_supplier_counts_view(view, &part_to_group, &bad_supplier_keys)?;
                        q16_merge_supplier_counts(distinct_suppliers, groups);
                        Ok(Some(()))
                    }
                },
                |distinct_suppliers| Ok(Some(distinct_suppliers)),
            )
            .await?
        else {
            return Err(DodamError::UnsupportedSql(
                "Q16 partsupp row-group map is unavailable".to_string(),
            ));
        };
        let mut distinct_suppliers = FastHashSet::<(usize, i64)>::default();
        for partial in partials {
            q16_merge_supplier_counts(&mut distinct_suppliers, partial);
        }
        let mut supplier_counts = vec![0_u64; groups.len()];
        for (group_id, _) in distinct_suppliers {
            if let Some(count) = supplier_counts.get_mut(group_id) {
                *count += 1;
            }
        }
        supplier_counts
    };
    let mut rows = supplier_counts
        .into_iter()
        .enumerate()
        .filter_map(|(group_id, supplier_count)| {
            if supplier_count == 0 {
                return None;
            }
            let group = groups.get(group_id)?;
            Some(Q16Row {
                brand: group.brand.clone(),
                type_name: group.type_name.clone(),
                size: group.size,
                supplier_count,
            })
        })
        .collect::<Vec<_>>();
    rows.sort_by(|left, right| {
        right
            .supplier_count
            .cmp(&left.supplier_count)
            .then_with(|| left.brand.cmp(&right.brand))
            .then_with(|| left.type_name.cmp(&right.type_name))
            .then_with(|| left.size.cmp(&right.size))
    });
    Ok(rows)
}

#[allow(dead_code)]
async fn q16_supplier_counts_stream(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    groups: Vec<Q16GroupKey>,
    part_to_group: Arc<AdaptiveI64Map<usize>>,
    bad_supplier_keys: Arc<AdaptiveI64Set>,
    max_suppkey: Option<i64>,
) -> Result<Vec<Q16Row>> {
    let mut stream = engine
        .scan_parquet_batches(
            path,
            batch_size,
            None,
            Projection::Columns(vec!["ps_partkey".to_string(), "ps_suppkey".to_string()]),
            None,
        )
        .await?;
    let supplier_counts = if q16_packed_distinct_enabled(groups.len(), max_suppkey) {
        let packed = parallel_batch_fold_view_chunks(
            &mut stream,
            q16_supplier_count_chunk_size(),
            PackedU32PairDistinct::new,
            move |view, distinct_suppliers| {
                q16_supplier_counts_packed_view(
                    view,
                    &part_to_group,
                    &bad_supplier_keys,
                    distinct_suppliers,
                )?;
                Ok(Some(()))
            },
            Ok,
            PackedU32PairDistinct::new(),
            q16_merge_supplier_counts_packed,
            "Q16 partsupp supplier counts",
        )?;
        packed.counts_by_first(groups.len())
    } else if let Some(layout) = q16_supplier_bitset_layout(groups.len(), max_suppkey) {
        let layout_for_scan = Arc::new(layout.clone());
        let partial = parallel_batch_fold_view_chunks(
            &mut stream,
            q16_supplier_count_chunk_size(),
            {
                let layout_for_scan = layout_for_scan.clone();
                move || Q16GroupSupplierBitset::new((*layout_for_scan).clone())
            },
            move |view, distinct_suppliers| {
                q16_supplier_counts_bitset_view(
                    view,
                    &part_to_group,
                    &bad_supplier_keys,
                    distinct_suppliers,
                )?;
                Ok(Some(()))
            },
            Ok,
            Q16GroupSupplierBitset::new(layout),
            q16_merge_supplier_bitsets,
            "Q16 partsupp supplier counts",
        )?;
        partial.counts()
    } else {
        let distinct_suppliers = parallel_batch_fold(
            &mut stream,
            move |batch| q16_supplier_counts_batch(batch, &part_to_group, &bad_supplier_keys),
            FastHashSet::<(usize, i64)>::default(),
            q16_merge_supplier_counts,
            "Q16 partsupp supplier counts",
        )?;
        let mut supplier_counts = vec![0_u64; groups.len()];
        for (group_id, _) in distinct_suppliers {
            if let Some(count) = supplier_counts.get_mut(group_id) {
                *count += 1;
            }
        }
        supplier_counts
    };
    let mut rows = supplier_counts
        .into_iter()
        .enumerate()
        .filter_map(|(group_id, supplier_count)| {
            if supplier_count == 0 {
                return None;
            }
            let group = groups.get(group_id)?;
            Some(Q16Row {
                brand: group.brand.clone(),
                type_name: group.type_name.clone(),
                size: group.size,
                supplier_count,
            })
        })
        .collect::<Vec<_>>();
    rows.sort_by(|left, right| {
        right
            .supplier_count
            .cmp(&left.supplier_count)
            .then_with(|| left.brand.cmp(&right.brand))
            .then_with(|| left.type_name.cmp(&right.type_name))
            .then_with(|| left.size.cmp(&right.size))
    });
    Ok(rows)
}

#[derive(Clone)]
struct Q16SupplierBitsetLayout {
    group_count: usize,
    words_per_group: usize,
}

struct Q16GroupSupplierBitset {
    layout: Q16SupplierBitsetLayout,
    words: Vec<u64>,
}

impl Q16GroupSupplierBitset {
    fn new(layout: Q16SupplierBitsetLayout) -> Self {
        let words = vec![0; layout.group_count.saturating_mul(layout.words_per_group)];
        Self { layout, words }
    }

    fn insert(&mut self, group_id: usize, suppkey: i64) {
        if suppkey < 0 || group_id >= self.layout.group_count {
            return;
        }
        let suppkey = suppkey as usize;
        let word = suppkey / 64;
        if word >= self.layout.words_per_group {
            return;
        }
        let index = group_id * self.layout.words_per_group + word;
        self.words[index] |= 1_u64 << (suppkey & 63);
    }

    fn merge(&mut self, other: Q16GroupSupplierBitset) {
        for (left, right) in self.words.iter_mut().zip(other.words) {
            *left |= right;
        }
    }

    fn counts(&self) -> Vec<u64> {
        self.words
            .chunks(self.layout.words_per_group)
            .map(|words| words.iter().map(|word| u64::from(word.count_ones())).sum())
            .collect()
    }
}

fn q16_supplier_bitset_layout(
    group_count: usize,
    max_suppkey: Option<i64>,
) -> Option<Q16SupplierBitsetLayout> {
    if std::env::var_os("DODAM_Q16_ENABLE_SUPPLIER_BITSET").is_none() {
        return None;
    }
    let max_suppkey = max_suppkey?;
    if max_suppkey < 0 || group_count == 0 {
        return None;
    }
    let words_per_group = (usize::try_from(max_suppkey).ok()? + 64) / 64;
    let bytes = group_count.checked_mul(words_per_group)?.checked_mul(8)?;
    if bytes > q16_supplier_bitset_max_bytes() {
        return None;
    }
    Some(Q16SupplierBitsetLayout {
        group_count,
        words_per_group,
    })
}

fn q16_supplier_bitset_max_bytes() -> usize {
    std::env::var("DODAM_Q16_SUPPLIER_BITSET_MAX_BYTES")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(32 * 1024 * 1024)
}

fn q16_supplier_count_chunk_size() -> usize {
    std::env::var("DODAM_Q16_SUPPLIER_COUNT_CHUNK_SIZE")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(4)
}

fn q16_packed_distinct_enabled(group_count: usize, max_suppkey: Option<i64>) -> bool {
    std::env::var_os("DODAM_Q16_DISABLE_PACKED_DISTINCT").is_none()
        && group_count <= u32::MAX as usize
        && max_suppkey.is_some_and(|key| key >= 0 && key <= u32::MAX as i64)
}

fn q16_supplier_counts_packed_batch(
    batch: RecordBatch,
    part_to_group: &AdaptiveI64Map<usize>,
    bad_suppliers: &AdaptiveI64Set,
    distinct_suppliers: &mut PackedU32PairDistinct,
) -> Result<()> {
    let partkeys = batch_column(&batch, "ps_partkey")?;
    let suppkeys = batch_column(&batch, "ps_suppkey")?;
    if let Some(keys) = Q16SupplierKeyView::try_new(partkeys, suppkeys)
        && q16_supplier_counts_packed_typed(keys, part_to_group, bad_suppliers, distinct_suppliers)
    {
        return Ok(());
    }
    for row in 0..batch.num_rows() {
        let (Some(partkey), Some(suppkey)) = (
            numeric_i64_value(partkeys, row)?,
            numeric_i64_value(suppkeys, row)?,
        ) else {
            continue;
        };
        if bad_suppliers.contains(suppkey) {
            continue;
        }
        let Some(group_id) = part_to_group.get(partkey) else {
            continue;
        };
        if !distinct_suppliers.push(group_id, suppkey) {
            return Err(DodamError::UnsupportedSql(
                "packed distinct key is out of range".to_string(),
            ));
        }
    }
    Ok(())
}

#[derive(Clone, Copy)]
struct Q16SupplierKeyView<'a> {
    partkeys: I64VectorView<'a>,
    suppkeys: I64VectorView<'a>,
}

impl<'a> Q16SupplierKeyView<'a> {
    fn try_new(partkeys: &'a ArrayRef, suppkeys: &'a ArrayRef) -> Option<Self> {
        Some(Self {
            partkeys: I64VectorView::Arrow(partkeys.as_any().downcast_ref::<Int64Array>()?),
            suppkeys: I64VectorView::Arrow(suppkeys.as_any().downcast_ref::<Int64Array>()?),
        })
    }

    fn try_new_view(view: BatchView<'a>) -> Option<Self> {
        Some(Self {
            partkeys: view.i64_vector(0)?,
            suppkeys: view.i64_vector(1)?,
        })
    }
}

fn q16_supplier_counts_packed_view(
    view: BatchView<'_>,
    part_to_group: &AdaptiveI64Map<usize>,
    bad_suppliers: &AdaptiveI64Set,
    distinct_suppliers: &mut PackedU32PairDistinct,
) -> Result<()> {
    if view.num_columns() == 2
        && let Some(keys) = Q16SupplierKeyView::try_new_view(view)
        && q16_supplier_counts_packed_typed(keys, part_to_group, bad_suppliers, distinct_suppliers)
    {
        return Ok(());
    }
    let Some(batch) = view.try_record_batch() else {
        return Err(DodamError::UnsupportedSql(
            "Q16 packed supplier-count raw vector columns have unsupported types".to_string(),
        ));
    };
    q16_supplier_counts_packed_batch(
        batch.clone(),
        part_to_group,
        bad_suppliers,
        distinct_suppliers,
    )
}

fn q16_supplier_counts_packed_typed(
    keys: Q16SupplierKeyView<'_>,
    part_to_group: &AdaptiveI64Map<usize>,
    bad_suppliers: &AdaptiveI64Set,
    distinct_suppliers: &mut PackedU32PairDistinct,
) -> bool {
    let partkeys = keys.partkeys;
    let suppkeys = keys.suppkeys;
    if let (Some(partkey_values), Some(suppkey_values)) = (
        partkeys.values_if_null_free(),
        suppkeys.values_if_null_free(),
    ) {
        if let (Some((group_values, group_present)), Some(bad_present)) = (
            part_to_group.dense_slices(),
            bad_suppliers.dense_contains_slice(),
        ) {
            for row in 0..partkey_values.len() {
                let suppkey = suppkey_values[row];
                if let Ok(suppkey_index) = usize::try_from(suppkey)
                    && bad_present.get(suppkey_index).copied().unwrap_or(false)
                {
                    continue;
                }
                let Ok(partkey_index) = usize::try_from(partkey_values[row]) else {
                    continue;
                };
                if partkey_index >= group_present.len() || !group_present[partkey_index] {
                    continue;
                }
                if !distinct_suppliers.push(group_values[partkey_index], suppkey) {
                    return false;
                }
            }
            return true;
        }
        for row in 0..partkey_values.len() {
            let suppkey = suppkey_values[row];
            if bad_suppliers.contains(suppkey) {
                continue;
            }
            let Some(group_id) = part_to_group.get(partkey_values[row]) else {
                continue;
            };
            if !distinct_suppliers.push(group_id, suppkey) {
                return false;
            }
        }
        return true;
    }
    for row in 0..partkeys.len() {
        if partkeys.is_null(row) || suppkeys.is_null(row) {
            continue;
        }
        let suppkey = suppkeys.value(row);
        if bad_suppliers.contains(suppkey) {
            continue;
        }
        let Some(group_id) = part_to_group.get(partkeys.value(row)) else {
            continue;
        };
        if !distinct_suppliers.push(group_id, suppkey) {
            return false;
        }
    }
    true
}

