fn q16_output(rows: Vec<Q16Row>) -> Result<QueryOutput> {
    let batch = RecordBatch::try_new(
        Arc::new(Schema::new(vec![
            Field::new("p_brand", DataType::Utf8, false),
            Field::new("p_type", DataType::Utf8, false),
            Field::new("p_size", DataType::Int64, false),
            Field::new("supplier_cnt", DataType::UInt64, false),
        ])),
        vec![
            Arc::new(StringArray::from_iter_values(
                rows.iter().map(|row| row.brand.as_str()),
            )),
            Arc::new(StringArray::from_iter_values(
                rows.iter().map(|row| row.type_name.as_str()),
            )),
            Arc::new(Int64Array::from_iter_values(
                rows.iter().map(|row| row.size),
            )),
            Arc::new(UInt64Array::from_iter_values(
                rows.iter().map(|row| row.supplier_count),
            )),
        ],
    )?;
    Ok(QueryOutput::Aggregate {
        metrics: AggregateMetrics::default(),
        batches: vec![batch],
    })
}

fn q12_shape(select: &Select, query: &Query, selection: &SqlExpr) -> bool {
    let projection = select
        .projection
        .iter()
        .map(|item| item.to_string().to_ascii_lowercase())
        .collect::<Vec<_>>()
        .join(", ");
    let group_by = select.group_by.to_string().to_ascii_lowercase();
    let order_by = query
        .order_by
        .as_ref()
        .map(|order_by| order_by.to_string().to_ascii_lowercase())
        .unwrap_or_default();
    let selection = selection.to_string().to_ascii_lowercase();
    select.from.len() == 2
        && select.projection.len() == 3
        && projection.contains("l_shipmode")
        && projection.contains("high_line_count")
        && projection.contains("low_line_count")
        && projection.contains("o_orderpriority = '1-urgent'")
        && projection.contains("o_orderpriority = '2-high'")
        && group_by.contains("l_shipmode")
        && order_by.contains("l_shipmode")
        && selection.contains("o_orderkey = l_orderkey")
        && selection.contains("l_shipmode in")
        && selection.contains("l_commitdate < l_receiptdate")
        && selection.contains("l_shipdate < l_commitdate")
        && selection.contains("l_receiptdate")
}

async fn try_execute_shipping_mode_priority_counts_sql(
    engine: &DodamEngine,
    sql: &str,
    batch_size: usize,
) -> Result<Option<QueryOutput>> {
    let dialect = GenericDialect {};
    let statements = Parser::parse_sql(&dialect, sql)
        .map_err(|error| DodamError::UnsupportedSql(error.to_string()))?;
    let [Statement::Query(query)] = statements.as_slice() else {
        return Ok(None);
    };
    let SetExpr::Select(select) = query.body.as_ref() else {
        return Ok(None);
    };
    let Some(selection) = select.selection.as_ref() else {
        return Ok(None);
    };
    if !q12_shape(select, query, selection) {
        return Ok(None);
    }
    reject_query_features(query)?;
    reject_select_features(select)?;
    let Some(tables) = parse_comma_join_table_refs(select)? else {
        return Ok(None);
    };
    if tables.len() != 2 {
        return Ok(None);
    }
    let mut orders = None;
    let mut lineitem = None;
    for table in tables {
        let alias = table_ref_alias_or_name(&table);
        if alias.eq_ignore_ascii_case("orders") {
            orders = Some(table);
        } else if alias.eq_ignore_ascii_case("lineitem") {
            lineitem = Some(table);
        }
    }
    let (Some(orders), Some(lineitem)) = (orders, lineitem) else {
        return Ok(None);
    };
    let mut conjuncts = Vec::new();
    collect_sql_and_conjuncts(selection, &mut conjuncts);
    let Some(shipmodes) = string_in_literals(&conjuncts, "l_shipmode")? else {
        return Ok(None);
    };
    if shipmodes.len() != 2 {
        return Ok(None);
    }
    let Some((start_days, end_days)) = date_range_bounds(&conjuncts, "l_receiptdate")? else {
        return Ok(None);
    };
    let mut shipmodes = shipmodes.into_iter().collect::<Vec<_>>();
    shipmodes.sort();

    let pending = q12_filtered_lineitem_counts(
        engine,
        lineitem.path,
        batch_size,
        &shipmodes,
        start_days,
        end_days,
    )
    .await?;
    let mut rows = if pending.is_empty() {
        shipmodes
            .iter()
            .map(|shipmode| Q12Row {
                shipmode: shipmode.clone(),
                high_line_count: 0,
                low_line_count: 0,
            })
            .collect()
    } else {
        q12_shipping_mode_counts_from_orders(engine, orders.path, batch_size, &shipmodes, &pending)
            .await?
    };
    rows.sort_by(|left, right| left.shipmode.cmp(&right.shipmode));
    Ok(Some(q12_output(rows)?))
}

fn string_in_literals(conjuncts: &[SqlExpr], column: &str) -> Result<Option<HashSet<String>>> {
    for conjunct in conjuncts {
        let SqlExpr::InList {
            expr,
            list,
            negated,
        } = conjunct
        else {
            continue;
        };
        if *negated || !sql_expr_column_matches(expr, column) {
            continue;
        }
        let mut values = HashSet::new();
        for item in list {
            let LiteralValue::Utf8(value) = sql_literal_value(item)? else {
                return Ok(None);
            };
            values.insert(value);
        }
        return Ok(Some(values));
    }
    Ok(None)
}

#[derive(Clone, Copy, Default)]
struct Q12State {
    high_line_count: u64,
    low_line_count: u64,
}

struct Q12Row {
    shipmode: String,
    high_line_count: u64,
    low_line_count: u64,
}

#[derive(Clone, Copy, Default)]
struct Q12PendingOrder {
    counts: [u64; 2],
}

type Q12PendingMap = FastHashMap<i64, Q12PendingOrder>;

fn q12_pending_map_new() -> Q12PendingMap {
    fast_hash_map_with_capacity(q12_pending_map_initial_capacity())
}

fn q12_pending_map_initial_capacity() -> usize {
    std::env::var("DODAM_Q12_PENDING_MAP_INITIAL_CAPACITY")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .unwrap_or(4096)
}

#[inline(always)]
fn q12_pending_increment(pending: &mut Q12PendingMap, orderkey: i64, mode_index: usize) {
    pending.entry(orderkey).or_default().counts[mode_index] += 1;
}

struct Q12PendingRunAccumulator<'a> {
    pending: &'a mut Q12PendingMap,
    current_key: Option<i64>,
    counts: [u64; 2],
    combine_runs: bool,
}

impl<'a> Q12PendingRunAccumulator<'a> {
    fn new(pending: &'a mut Q12PendingMap) -> Self {
        Self {
            pending,
            current_key: None,
            counts: [0, 0],
            combine_runs: q12_pending_run_accumulator_enabled(),
        }
    }

    #[inline(always)]
    fn increment(&mut self, orderkey: i64, mode_index: usize) {
        if !self.combine_runs {
            q12_pending_increment(self.pending, orderkey, mode_index);
            return;
        }
        if self.current_key == Some(orderkey) {
            self.counts[mode_index] += 1;
            return;
        }
        self.flush();
        self.current_key = Some(orderkey);
        self.counts = [0, 0];
        self.counts[mode_index] = 1;
    }

    #[inline(always)]
    fn flush(&mut self) {
        if !self.combine_runs {
            return;
        }
        let Some(orderkey) = self.current_key.take() else {
            return;
        };
        let counts = self.counts;
        if counts[0] != 0 || counts[1] != 0 {
            q12_pending_add_order(self.pending, orderkey, Q12PendingOrder { counts });
        }
    }

    fn finish(mut self) {
        self.flush();
    }
}

fn q12_pending_run_accumulator_enabled() -> bool {
    std::env::var("DODAM_Q12_ENABLE_PENDING_RUN_ACCUMULATOR")
        .is_ok_and(|value| matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES"))
}

#[inline(always)]
fn q12_pending_add_order(pending: &mut Q12PendingMap, orderkey: i64, order: Q12PendingOrder) {
    if let Some(target) = pending.get_mut(&orderkey) {
        target.counts[0] += order.counts[0];
        target.counts[1] += order.counts[1];
        return;
    }
    pending.insert(orderkey, order);
}

#[derive(Default)]
struct Q12OrdersPartial {
    groups: [Q12State; 2],
    profile: Q12OrdersProfile,
}

#[derive(Default)]
struct Q12OrdersProfile {
    batches: usize,
    typed_batches: usize,
    fallback_batches: usize,
    rows: usize,
    null_rows: usize,
    lookup_hits: usize,
    lookup_misses: usize,
    priority_rows: usize,
    apply_rows: usize,
    lookup_samples: usize,
    priority_samples: usize,
    apply_samples: usize,
    total_nanos: u64,
    lookup_nanos: u64,
    priority_nanos: u64,
    apply_nanos: u64,
}

impl Q12OrdersProfile {
    fn add(&mut self, other: Self) {
        self.batches = self.batches.saturating_add(other.batches);
        self.typed_batches = self.typed_batches.saturating_add(other.typed_batches);
        self.fallback_batches = self.fallback_batches.saturating_add(other.fallback_batches);
        self.rows = self.rows.saturating_add(other.rows);
        self.null_rows = self.null_rows.saturating_add(other.null_rows);
        self.lookup_hits = self.lookup_hits.saturating_add(other.lookup_hits);
        self.lookup_misses = self.lookup_misses.saturating_add(other.lookup_misses);
        self.priority_rows = self.priority_rows.saturating_add(other.priority_rows);
        self.apply_rows = self.apply_rows.saturating_add(other.apply_rows);
        self.lookup_samples = self.lookup_samples.saturating_add(other.lookup_samples);
        self.priority_samples = self.priority_samples.saturating_add(other.priority_samples);
        self.apply_samples = self.apply_samples.saturating_add(other.apply_samples);
        self.total_nanos = self.total_nanos.saturating_add(other.total_nanos);
        self.lookup_nanos = self.lookup_nanos.saturating_add(other.lookup_nanos);
        self.priority_nanos = self.priority_nanos.saturating_add(other.priority_nanos);
        self.apply_nanos = self.apply_nanos.saturating_add(other.apply_nanos);
    }
}

async fn q12_filtered_lineitem_counts(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    shipmodes: &[String],
    start_days: i32,
    end_days: i32,
) -> Result<Q12PendingMap> {
    if q12_late_materialized_enabled()
        && let Some(pending) = q12_filtered_lineitem_counts_late_materialized(
            engine,
            path.clone(),
            batch_size,
            shipmodes,
            start_days,
            end_days,
        )
        .await?
    {
        return Ok(pending);
    }
    let projection = Projection::Columns(vec![
        "l_orderkey".to_string(),
        "l_shipmode".to_string(),
        "l_commitdate".to_string(),
        "l_receiptdate".to_string(),
        "l_shipdate".to_string(),
    ]);
    let shipmodes = Arc::new(shipmodes.to_vec());
    if q12_lineitem_row_filter_enabled() {
        return q12_filtered_lineitem_counts_row_filtered(
            engine, path, batch_size, projection, shipmodes, start_days, end_days,
        )
        .await;
    }
    if q12_direct_lineitem_selected_payload_enabled()
        && let Some(pending) = q12_filtered_lineitem_counts_direct_selected_payload(
            engine,
            path.clone(),
            shipmodes.clone(),
            start_days,
            end_days,
        )
        .await?
    {
        return Ok(pending);
    }
    if q12_direct_lineitem_raw_enabled()
        && let Some(pending) = q12_filtered_lineitem_counts_direct_raw(
            engine,
            path.clone(),
            batch_size,
            shipmodes.clone(),
            start_days,
            end_days,
        )
        .await?
    {
        return Ok(pending);
    }
    if q12_direct_lineitem_dict_raw_enabled()
        && let Some(pending) = q12_filtered_lineitem_counts_direct_dict_raw(
            engine,
            path.clone(),
            batch_size,
            shipmodes.clone(),
            start_days,
            end_days,
        )
        .await?
    {
        return Ok(pending);
    }
    if q12_direct_lineitem_page_raw_enabled()
        && let Some(pending) = q12_filtered_lineitem_counts_direct_page_raw(
            engine,
            path.clone(),
            batch_size,
            shipmodes.clone(),
            start_days,
            end_days,
        )
        .await?
    {
        return Ok(pending);
    }
    if q12_row_group_map_enabled()
        && let Some(partials) = q12_filtered_lineitem_counts_row_group_map(
            engine,
            path.clone(),
            batch_size,
            projection.clone(),
            shipmodes.clone(),
            start_days,
            end_days,
        )
        .await?
    {
        let mut pending = q12_pending_map_new();
        for partial in partials {
            q12_merge_pending_orders(&mut pending, partial);
        }
        return Ok(pending);
    }
    q12_filtered_lineitem_counts_stream(
        engine, path, batch_size, projection, shipmodes, start_days, end_days,
    )
    .await
}

async fn q12_filtered_lineitem_counts_direct_selected_payload(
    engine: &DodamEngine,
    path: PathBuf,
    shipmodes: Arc<Vec<String>>,
    start_days: i32,
    end_days: i32,
) -> Result<Option<Q12PendingMap>> {
    engine
        .scan_parquet_i64_byte_array_selected_by_i32x3_dictionary_fold(
            path,
            [
                "l_orderkey",
                "l_shipmode",
                "l_commitdate",
                "l_receiptdate",
                "l_shipdate",
            ],
            q12_receiptdate_pruning_predicates(start_days, end_days),
            q12_row_group_map_chunk(),
            q12_pending_map_new,
            move |commitdate, receiptdate, shipdate| {
                q12_lineitem_dates_match(commitdate, receiptdate, shipdate, start_days, end_days)
            },
            {
                let shipmodes = shipmodes.clone();
                move |pending, orderkeys, mode_ids, dictionary| {
                    q12_filtered_lineitem_counts_selected_payload_into(
                        orderkeys, mode_ids, dictionary, &shipmodes, pending,
                    );
                    Ok(())
                }
            },
            Ok,
            |pending, partial| {
                q12_merge_pending_orders(pending, partial);
                Ok(())
            },
        )
        .await
}

