enum DirectI64ishVector<'a> {
    I64(I64VectorView<'a>),
    I32(I32VectorView<'a>),
}

impl<'a> DirectI64ishVector<'a> {
    fn from_batch(batch: BatchView<'a>, index: usize) -> Option<Self> {
        batch
            .i64_vector(index)
            .map(Self::I64)
            .or_else(|| batch.i32_vector(index).map(Self::I32))
    }

    fn len(&self) -> usize {
        match self {
            Self::I64(values) => values.len(),
            Self::I32(values) => values.len(),
        }
    }

    fn has_nulls(&self) -> bool {
        match self {
            Self::I64(values) => values.values_if_null_free().is_none(),
            Self::I32(values) => values.values_if_null_free().is_none(),
        }
    }

    fn is_null(&self, row: usize) -> bool {
        match self {
            Self::I64(values) => values.is_null(row),
            Self::I32(values) => values.is_null(row),
        }
    }

    fn value(&self, row: usize) -> i64 {
        match self {
            Self::I64(values) => values.value(row),
            Self::I32(values) => i64::from(values.value(row)),
        }
    }

    fn i64_values_if_null_free(&self) -> Option<&'a [i64]> {
        match self {
            Self::I64(values) => values.values_if_null_free(),
            Self::I32(_) => None,
        }
    }

    fn i32_values_if_null_free(&self) -> Option<&'a [i32]> {
        match self {
            Self::I64(_) => None,
            Self::I32(values) => values.values_if_null_free(),
        }
    }
}

fn i64_filter_values_as_i32(values: &[i64]) -> Option<Vec<i32>> {
    values
        .iter()
        .copied()
        .map(i32::try_from)
        .collect::<std::result::Result<Vec<_>, _>>()
        .ok()
}

fn try_direct_join_coalesce_left_aggregate(
    engine: &DodamEngine,
    path: &Path,
    batch_size: usize,
    filter: Option<&FilterExpr>,
    key_column: &str,
    group_column: &str,
    sum_column: &str,
    right_lookup: &AdaptiveI64Map<usize>,
) -> Result<Option<DirectJoinCoalesceLeftAggregate>> {
    if !direct_join_coalesce_left_aggregate_enabled() {
        return Ok(None);
    }
    let Some(filter) = direct_join_left_i64_filter(filter, group_column)? else {
        return Ok(None);
    };
    let row_groups = (0..engine.parquet_row_group_count(path)?).collect::<Vec<_>>();
    let candidates = [
        [
            DirectPrimitiveColumnType::I64,
            DirectPrimitiveColumnType::I64,
            DirectPrimitiveColumnType::I64,
        ],
        [
            DirectPrimitiveColumnType::I64,
            DirectPrimitiveColumnType::I32,
            DirectPrimitiveColumnType::I64,
        ],
        [
            DirectPrimitiveColumnType::I32,
            DirectPrimitiveColumnType::I64,
            DirectPrimitiveColumnType::I64,
        ],
        [
            DirectPrimitiveColumnType::I32,
            DirectPrimitiveColumnType::I32,
            DirectPrimitiveColumnType::I64,
        ],
        [
            DirectPrimitiveColumnType::I64,
            DirectPrimitiveColumnType::I64,
            DirectPrimitiveColumnType::I32,
        ],
        [
            DirectPrimitiveColumnType::I64,
            DirectPrimitiveColumnType::I32,
            DirectPrimitiveColumnType::I32,
        ],
        [
            DirectPrimitiveColumnType::I32,
            DirectPrimitiveColumnType::I64,
            DirectPrimitiveColumnType::I32,
        ],
        [
            DirectPrimitiveColumnType::I32,
            DirectPrimitiveColumnType::I32,
            DirectPrimitiveColumnType::I32,
        ],
    ];
    for [key_type, group_type, sum_type] in candidates {
        let specs = [
            DirectPrimitiveColumnSpec {
                name: key_column,
                column_type: key_type,
            },
            DirectPrimitiveColumnSpec {
                name: group_column,
                column_type: group_type,
            },
            DirectPrimitiveColumnSpec {
                name: sum_column,
                column_type: sum_type,
            },
        ];
        let mut groups = JoinCoalesceGroupAccumulator::new();
        let mut selected_positions = Vec::<usize>::with_capacity(batch_size);
        let mut rows = 0usize;
        let scanned = engine.scan_parquet_primitive_columns_view(
            path,
            batch_size,
            &row_groups,
            &specs,
            |batch| {
                let Some(key) = DirectI64ishVector::from_batch(batch, 0) else {
                    return Err(DodamError::UnsupportedSql(
                        "direct join fusion key column is not i64-like".to_string(),
                    ));
                };
                let Some(group) = DirectI64ishVector::from_batch(batch, 1) else {
                    return Err(DodamError::UnsupportedSql(
                        "direct join fusion group column is not i64-like".to_string(),
                    ));
                };
                let Some(sum) = DirectI64ishVector::from_batch(batch, 2) else {
                    return Err(DodamError::UnsupportedSql(
                        "direct join fusion sum column is not i64-like".to_string(),
                    ));
                };
                let dense_lookup = right_lookup.dense_slices();
                match filter {
                    DirectI64Filter::All => {
                        rows = rows.saturating_add(key.len());
                        accumulate_direct_join_coalesce_rows(
                            &mut groups,
                            &key,
                            &group,
                            &sum,
                            right_lookup,
                            dense_lookup,
                            0..key.len(),
                        );
                    }
                    DirectI64Filter::None => {}
                    _ => {
                        filter.push_selected_positions(&group, &mut selected_positions);
                        rows = rows.saturating_add(selected_positions.len());
                        accumulate_direct_join_coalesce_rows(
                            &mut groups,
                            &key,
                            &group,
                            &sum,
                            right_lookup,
                            dense_lookup,
                            selected_positions.iter().copied(),
                        );
                    }
                }
                Ok(())
            },
        )?;
        if let Some(metrics) = scanned {
            trace_join_coalesce_fusion(
                "accept-direct-left",
                &format!(
                    "types={key_type:?}/{group_type:?}/{sum_type:?} rows={} batches={}",
                    rows, metrics.batches
                ),
            );
            return Ok(Some(DirectJoinCoalesceLeftAggregate {
                groups: groups.into_entries(),
                rows,
                batches: metrics.batches,
                aggregate_nanos: metrics.consume_nanos,
            }));
        }
    }
    Ok(None)
}

fn accumulate_direct_join_coalesce_rows(
    groups: &mut JoinCoalesceGroupAccumulator,
    key: &DirectI64ishVector<'_>,
    group: &DirectI64ishVector<'_>,
    sum: &DirectI64ishVector<'_>,
    right_lookup: &AdaptiveI64Map<usize>,
    dense_lookup: Option<(&[usize], &[bool])>,
    rows: impl IntoIterator<Item = usize>,
) {
    if !key.has_nulls() && !group.has_nulls() && !sum.has_nulls() {
        for row in rows {
            if let Some(class_id) = right_lookup.get_cached(dense_lookup, key.value(row)) {
                groups.update_non_null(group.value(row), class_id, sum.value(row));
            }
        }
        return;
    }
    for row in rows {
        if key.is_null(row) {
            continue;
        }
        let Some(class_id) = right_lookup.get_cached(dense_lookup, key.value(row)) else {
            continue;
        };
        groups.update(
            (!group.is_null(row)).then(|| group.value(row)),
            class_id,
            (!sum.is_null(row)).then(|| sum.value(row)),
        );
    }
}

fn direct_join_coalesce_left_aggregate_enabled() -> bool {
    std::env::var("DODAM_ENABLE_DIRECT_JOIN_COALESCE_LEFT_AGGREGATE")
        .is_ok_and(|value| matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES"))
}

fn direct_join_left_i64_filter(
    filter: Option<&FilterExpr>,
    group_column: &str,
) -> Result<Option<DirectI64Filter>> {
    let Some(filter) = filter else {
        return Ok(Some(DirectI64Filter::All));
    };
    match filter.expr() {
        Expr::Boolean(Some(true)) => Ok(Some(DirectI64Filter::All)),
        Expr::Boolean(Some(false) | None) => Ok(Some(DirectI64Filter::None)),
        Expr::InList {
            column,
            values,
            negated: false,
            has_null: false,
        } if column == group_column => {
            let mut parsed_values = Vec::with_capacity(values.len());
            for value in values {
                parsed_values.push(value.as_i64(column)?);
            }
            parsed_values.sort_unstable();
            parsed_values.dedup();
            if parsed_values.len() <= 8 {
                return Ok(Some(DirectI64Filter::TinyIn(parsed_values)));
            }
            Ok(Some(DirectI64Filter::In(
                parsed_values.into_iter().collect(),
            )))
        }
        _ => Ok(None),
    }
}

struct UniqueI64ToUtf8IdLookup {
    lookup: AdaptiveI64Map<usize>,
    values: Vec<Option<String>>,
}

fn build_unique_i64_to_utf8_id_lookup(
    batches: &[RecordBatch],
    key_column: &str,
    value_column: &str,
) -> Result<Option<UniqueI64ToUtf8IdLookup>> {
    let mut lookup = FastHashMap::default();
    let mut value_ids = FastHashMap::<Option<String>, usize>::default();
    let mut values = Vec::<Option<String>>::new();
    for batch in batches {
        let key = i64_array_like(batch, key_column)?;
        let value = string_array(batch, value_column)?;
        for row in 0..batch.num_rows() {
            if key.is_null(row) {
                continue;
            }
            let payload = (!value.is_null(row)).then(|| value.value(row).to_string());
            let value_id = if let Some(value_id) = value_ids.get(&payload).copied() {
                value_id
            } else {
                let value_id = values.len();
                values.push(payload.clone());
                value_ids.insert(payload, value_id);
                value_id
            };
            if lookup.insert(key.value(row), value_id).is_some() {
                return Ok(None);
            }
        }
    }
    let lookup = AdaptiveI64Map::from_hash(lookup);
    Ok(Some(UniqueI64ToUtf8IdLookup { lookup, values }))
}

fn i64_array_like<'a>(batch: &'a RecordBatch, column: &str) -> Result<I64LikeColumn<'a>> {
    let index = batch_column_index(batch, column)?;
    let array = batch.column(index);
    match array.data_type() {
        DataType::Int32 => Ok(I64LikeColumn::Int32(
            array
                .as_any()
                .downcast_ref::<Int32Array>()
                .expect("Int32 data type"),
        )),
        DataType::Int64 => Ok(I64LikeColumn::Int64(
            array
                .as_any()
                .downcast_ref::<Int64Array>()
                .expect("Int64 data type"),
        )),
        other => Err(DodamError::UnsupportedSql(format!(
            "join aggregate fusion requires integer column {column}, got {other:?}"
        ))),
    }
}

enum I64LikeColumn<'a> {
    Int32(&'a Int32Array),
    Int64(&'a Int64Array),
}

impl I64LikeColumn<'_> {
    fn has_nulls(&self) -> bool {
        match self {
            Self::Int32(values) => values.null_count() > 0,
            Self::Int64(values) => values.null_count() > 0,
        }
    }

    fn is_null(&self, row: usize) -> bool {
        match self {
            Self::Int32(values) => values.is_null(row),
            Self::Int64(values) => values.is_null(row),
        }
    }

    fn value(&self, row: usize) -> i64 {
        match self {
            Self::Int32(values) => i64::from(values.value(row)),
            Self::Int64(values) => values.value(row),
        }
    }
}

fn string_array<'a>(batch: &'a RecordBatch, column: &str) -> Result<&'a StringArray> {
    let index = batch_column_index(batch, column)?;
    batch
        .column(index)
        .as_any()
        .downcast_ref::<StringArray>()
        .ok_or_else(|| DodamError::UnsupportedSql(format!("{column} must be Utf8")))
}

fn unique_columns(columns: impl IntoIterator<Item = String>) -> Vec<String> {
    let mut output = Vec::new();
    for column in columns {
        add_column_once(&mut output, column);
    }
    output
}

fn join_column_belongs_to(column: &str, alias: &str) -> bool {
    column
        .strip_prefix(alias)
        .and_then(|rest| rest.strip_prefix('.'))
        .is_some()
}

fn compare_join_fused_group_keys(left: &[GroupValue], right: &[GroupValue]) -> std::cmp::Ordering {
    for (left, right) in left.iter().zip(right.iter()) {
        let ordering = match (left, right) {
            (GroupValue::Int64(left), GroupValue::Int64(right)) => left.cmp(right),
            (GroupValue::Utf8(left), GroupValue::Utf8(right)) => left.cmp(right),
            _ => std::cmp::Ordering::Equal,
        };
        if ordering != std::cmp::Ordering::Equal {
            return ordering;
        }
    }
    left.len().cmp(&right.len())
}

fn same_join_column(left: &str, right: &str) -> bool {
    if let (Some((left_function, left_argument)), Some((right_function, right_argument))) =
        (aggregate_column_parts(left), aggregate_column_parts(right))
        && left_function.eq_ignore_ascii_case(right_function)
        && same_join_column(left_argument, right_argument)
    {
        return true;
    }
    left == right
        || left.rsplit('.').next() == Some(right)
        || right.rsplit('.').next() == Some(left)
}

async fn try_execute_derived_left_join_count_distribution_sql(
    engine: &DodamEngine,
    sql: &str,
    batch_size: usize,
) -> Result<Option<QueryOutput>> {
    let dialect = GenericDialect {};
    let statements = Parser::parse_sql(&dialect, sql)
        .map_err(|error| DodamError::UnsupportedSql(error.to_string()))?;
    let [Statement::Query(query)] = statements.as_slice() else {
        return Ok(None);
    };
    let SetExpr::Select(select) = query.body.as_ref() else {
        return Ok(None);
    };
    let Some((subquery, alias)) = parse_derived_from(select)? else {
        return Ok(None);
    };
    reject_query_features(query)?;
    reject_select_features(select)?;

    let outer_group_by = parse_group_by(select, Some(&alias))?;
    let projection = parse_projection(select, &outer_group_by, Some(&alias))?;
    if parse_distinct(select)?
        || outer_group_by.len() != 1
        || !matches!(projection.aggregates.as_slice(), [AggregateExpr::CountStar])
        || !projection.aggregate_expressions.is_empty()
        || projection_requires_expression_path(&projection.expressions)
        || select.selection.is_some()
        || select.having.is_some()
    {
        return Ok(None);
    }
    let order_by = parse_order_by(
        query,
        &projection.aliases,
        &projection.ordinal_targets,
        Some(&alias),
    )?;
    let limit = parse_limit(query)?;

    let inner = match parse_query(subquery) {
        Ok(inner) => inner,
        Err(DodamError::UnsupportedSql(_))
        | Err(DodamError::UnknownColumn(_))
        | Err(DodamError::UnknownTableQualifier(_)) => {
            return Ok(None);
        }
        Err(error) => return Err(error),
    };
    let Some(join) = &inner.join else {
        return Ok(None);
    };
    if inner.distinct
        || inner.filter.is_some()
        || inner.having.is_some()
        || inner.order_by.is_some()
        || inner.limit.is_some()
        || !inner.aggregate_expressions.is_empty()
        || projection_requires_expression_path(&inner.expressions)
        || join.join_type != JoinType::Left
        || join.left_keys.len() != 1
        || join.right_keys.len() != 1
        || inner.group_by.len() != 1
        || !same_join_column(&inner.group_by[0], &join.left_keys[0])
    {
        return Ok(None);
    }
    let [AggregateExpr::Count(count_column)] = inner.aggregates.as_slice() else {
        return Ok(None);
    };
    if resolve_inner_output_column_index(&inner, &outer_group_by[0]) != Some(inner.group_by.len()) {
        return Ok(None);
    }
    if !inner.path.exists() {
        return Ok(None);
    }

    let dense_counts = collect_dense_right_counts(engine, join, count_column, batch_size).await?;
    if dense_counts.is_empty() {
        return Ok(None);
    }
    let groups =
        collect_left_count_distribution(engine, &inner.path, join, &dense_counts, batch_size)
            .await?;
    let rows = groups
        .iter()
        .map(|group| match group.values[0].value {
            AggregateValue::Count(value) => value as usize,
            _ => 0,
        })
        .sum();
    let metrics = AggregateMetrics {
        fragments: 2,
        batches: 1,
        rows,
        values: Vec::new(),
        groups,
        ..AggregateMetrics::default()
    };
    let mut batches =
        aggregate_metrics_to_batches(&metrics, &outer_group_by, &projection.aggregates)?;
    batches = apply_output_order_limit(batches, order_by.as_ref(), limit, 0)?;
    batches = rename_output_batches(batches, &projection.aliases)?;
    Ok(Some(QueryOutput::Aggregate { metrics, batches }))
}

async fn collect_dense_right_counts(
    engine: &DodamEngine,
    join: &SqlJoin,
    count_column: &str,
    batch_size: usize,
) -> Result<Vec<u32>> {
    let count_column = strip_column_prefix(count_column, &join.right_alias);
    let count_column_required = count_column != join.right_keys[0]
        && !parquet_column_is_non_nullable(&join.right.path, &count_column)?;
    let mut right_projection = vec![join.right_keys[0].clone()];
    if count_column_required {
        add_column_once(&mut right_projection, count_column.clone());
    }
    if let Some(filter) = &join.right_filter {
        for column in filter.referenced_columns() {
            add_column_once(
                &mut right_projection,
                strip_column_prefix(&column, &join.right_alias),
            );
        }
    }
    let right_key_index_hint = projected_column_index(&right_projection, &join.right_keys[0]);
    let count_index_hint = count_column_required
        .then(|| projected_column_index(&right_projection, &count_column))
        .flatten();
    let right_projection_for_scan = right_projection.clone();
    let direct_filter = join
        .right_filter
        .as_ref()
        .filter(|filter| expr_is_like_only(filter.expr()));
    let fast_like_filter = direct_filter
        .filter(|_| fast_like_distribution_enabled())
        .and_then(|filter| fast_like_substrings_filter(filter.expr()));
    let fast_like_finders = fast_like_filter.as_ref().map(|filter| {
        filter
            .parts
            .iter()
            .map(|part| Finder::new(part))
            .collect::<Vec<_>>()
    });
    let eval_filter = direct_filter.filter(|_| fast_like_filter.is_none());
    if dense_right_count_row_group_map_enabled()
        && !count_column_required
        && eval_filter.is_none()
        && let Some(filter) = fast_like_filter.clone()
        && let Some(counts) = collect_dense_right_counts_fast_like_row_group_map(
            engine,
            join.right.path.clone(),
            batch_size,
            Projection::Columns(right_projection_for_scan.clone()),
            join.right_keys[0].clone(),
            filter,
        )
        .await?
    {
        return Ok(counts);
    }
    let mut right_stream = engine
        .scan_parquet_batches(
            join.right.path.clone(),
            batch_size,
            None,
            Projection::Columns(right_projection_for_scan),
            if direct_filter.is_some() {
                None
            } else {
                join.right_filter.clone()
            },
        )
        .await?;
    let mut dense_counts = Vec::<u32>::new();
    while let Some(batch) = right_stream.next() {
        let batch = batch?;
        let fast_like_strings = fast_like_filter
            .as_ref()
            .map(|filter| batch_string_column(&batch, &filter.column))
            .transpose()?;
        let key_index =
            batch_projected_column_index(&batch, right_key_index_hint, &join.right_keys[0])?;
        let count_index = if count_column_required {
            Some(batch_projected_column_index(
                &batch,
                count_index_hint,
                &count_column,
            )?)
        } else {
            None
        };
        let Some(keys) = batch
            .column(key_index)
            .as_any()
            .downcast_ref::<Int64Array>()
        else {
            return Ok(Vec::new());
        };
        let values = count_index.map(|index| batch.column(index));
        let mask = eval_filter
            .map(|filter| evaluate_filter_mask(&batch, filter))
            .transpose()?;
        if mask.is_none()
            && values.is_none()
            && keys.null_count() == 0
            && let (Some(filter), Some(strings), Some(finders)) = (
                fast_like_filter.as_ref(),
                fast_like_strings.as_ref(),
                fast_like_finders.as_ref(),
            )
        {
            let key_values = keys.values().as_ref();
            if strings.null_count() == 0 {
                if let Some((first, second)) = fast_like_two_substring_finders(finders) {
                    for (row, &key) in key_values.iter().enumerate() {
                        if !fast_like_two_substrings_row_matches_non_null(
                            strings,
                            row,
                            &filter.parts[0],
                            &filter.parts[1],
                            first,
                            second,
                            filter.negated,
                        ) {
                            continue;
                        }
                        if key < 0 || key > 10_000_000 {
                            return Ok(Vec::new());
                        }
                        let index = key as usize;
                        if dense_counts.len() <= index {
                            dense_counts.resize(index + 1, 0);
                        }
                        dense_counts[index] =
                            dense_counts[index].checked_add(1).ok_or_else(|| {
                                DodamError::InvalidFilter("dense count overflow".to_string())
                            })?;
                    }
                    continue;
                }
                for (row, &key) in key_values.iter().enumerate() {
                    if !fast_like_substrings_row_matches_non_null(
                        strings,
                        row,
                        &filter.parts,
                        finders,
                        filter.negated,
                    ) {
                        continue;
                    }
                    if key < 0 || key > 10_000_000 {
                        return Ok(Vec::new());
                    }
                    let index = key as usize;
                    if dense_counts.len() <= index {
                        dense_counts.resize(index + 1, 0);
                    }
                    dense_counts[index] = dense_counts[index].checked_add(1).ok_or_else(|| {
                        DodamError::InvalidFilter("dense count overflow".to_string())
                    })?;
                }
                continue;
            }
            if let Some((first, second)) = fast_like_two_substring_finders(finders) {
                for (row, &key) in key_values.iter().enumerate() {
                    if !fast_like_two_substrings_row_matches(
                        strings,
                        row,
                        &filter.parts[0],
                        &filter.parts[1],
                        first,
                        second,
                        filter.negated,
                    ) {
                        continue;
                    }
                    if key < 0 || key > 10_000_000 {
                        return Ok(Vec::new());
                    }
                    let index = key as usize;
                    if dense_counts.len() <= index {
                        dense_counts.resize(index + 1, 0);
                    }
                    dense_counts[index] = dense_counts[index].checked_add(1).ok_or_else(|| {
                        DodamError::InvalidFilter("dense count overflow".to_string())
                    })?;
                }
                continue;
            }
            for (row, &key) in key_values.iter().enumerate() {
                if !fast_like_substrings_row_matches(
                    strings,
                    row,
                    &filter.parts,
                    finders,
                    filter.negated,
                ) {
                    continue;
                }
                if key < 0 || key > 10_000_000 {
                    return Ok(Vec::new());
                }
                let index = key as usize;
                if dense_counts.len() <= index {
                    dense_counts.resize(index + 1, 0);
                }
                dense_counts[index] = dense_counts[index]
                    .checked_add(1)
                    .ok_or_else(|| DodamError::InvalidFilter("dense count overflow".to_string()))?;
            }
            continue;
        }
        for row in 0..batch.num_rows() {
            if let (Some(filter), Some(strings), Some(finders)) = (
                fast_like_filter.as_ref(),
                fast_like_strings.as_ref(),
                fast_like_finders.as_ref(),
            ) && !fast_like_substrings_row_matches(
                strings,
                row,
                &filter.parts,
                finders,
                filter.negated,
            ) {
                continue;
            }
            if mask
                .as_ref()
                .is_some_and(|mask| mask.is_null(row) || !mask.value(row))
            {
                continue;
            }
            if keys.is_null(row) || values.is_some_and(|values| values.is_null(row)) {
                continue;
            }
            let key = keys.value(row);
            if key < 0 || key > 10_000_000 {
                return Ok(Vec::new());
            }
            let index = key as usize;
            if dense_counts.len() <= index {
                dense_counts.resize(index + 1, 0);
            }
            dense_counts[index] = dense_counts[index]
                .checked_add(1)
                .ok_or_else(|| DodamError::InvalidFilter("dense count overflow".to_string()))?;
        }
    }
    Ok(dense_counts)
}

async fn collect_dense_right_counts_fast_like_row_group_map(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    projection: Projection,
    key_column: String,
    filter: FastLikeSubstrings,
) -> Result<Option<Vec<u32>>> {
    let filter = Arc::new(filter);
    let Some(partials) = engine
        .parquet_row_group_map_view(
            path,
            batch_size,
            projection,
            dense_right_count_row_group_chunk(),
            Vec::<u32>::new,
            {
                let filter = filter.clone();
                let key_column = key_column.clone();
                move |view, counts| {
                    collect_dense_right_counts_fast_like_view(view, &key_column, &filter, counts)
                }
            },
            |counts| Ok(Some(counts)),
        )
        .await?
    else {
        return Ok(None);
    };
    let mut counts = Vec::<u32>::new();
    for partial in partials {
        if counts.len() < partial.len() {
            counts.resize(partial.len(), 0);
        }
        for (index, count) in partial.into_iter().enumerate() {
            counts[index] = counts[index]
                .checked_add(count)
                .ok_or_else(|| DodamError::InvalidFilter("dense count overflow".to_string()))?;
        }
    }
    Ok(Some(counts))
}

fn collect_dense_right_counts_fast_like_batch(
    batch: RecordBatch,
    key_column: &str,
    filter: &FastLikeSubstrings,
    counts: &mut Vec<u32>,
) -> Result<Option<()>> {
    let key_index = batch_column_index(&batch, key_column)?;
    let Some(keys) = batch
        .column(key_index)
        .as_any()
        .downcast_ref::<Int64Array>()
    else {
        return Ok(None);
    };
    let strings = batch_string_column(&batch, &filter.column)?;
    let finders = filter
        .parts
        .iter()
        .map(|part| Finder::new(part))
        .collect::<Vec<_>>();
    if keys.null_count() == 0 && strings.null_count() == 0 {
        let key_values = keys.values().as_ref();
        if let Some((first, second)) = fast_like_two_substring_finders(&finders) {
            for (row, &key) in key_values.iter().enumerate() {
                if fast_like_two_substrings_row_matches_non_null(
                    strings,
                    row,
                    &filter.parts[0],
                    &filter.parts[1],
                    first,
                    second,
                    filter.negated,
                ) {
                    dense_count_increment(counts, key)?;
                }
            }
            return Ok(Some(()));
        }
        for (row, &key) in key_values.iter().enumerate() {
            if fast_like_substrings_row_matches_non_null(
                strings,
                row,
                &filter.parts,
                &finders,
                filter.negated,
            ) {
                dense_count_increment(counts, key)?;
            }
        }
        return Ok(Some(()));
    }
    if let Some((first, second)) = fast_like_two_substring_finders(&finders) {
        for row in 0..keys.len() {
            if keys.is_valid(row)
                && fast_like_two_substrings_row_matches(
                    strings,
                    row,
                    &filter.parts[0],
                    &filter.parts[1],
                    first,
                    second,
                    filter.negated,
                )
            {
                dense_count_increment(counts, keys.value(row))?;
            }
        }
        return Ok(Some(()));
    }
    for row in 0..keys.len() {
        if keys.is_valid(row)
            && fast_like_substrings_row_matches(
                strings,
                row,
                &filter.parts,
                &finders,
                filter.negated,
            )
        {
            dense_count_increment(counts, keys.value(row))?;
        }
    }
    Ok(Some(()))
}

fn collect_dense_right_counts_fast_like_view(
    view: BatchView<'_>,
    key_column: &str,
    filter: &FastLikeSubstrings,
    counts: &mut Vec<u32>,
) -> Result<Option<()>> {
    let Some(batch) = view.try_record_batch() else {
        return Ok(None);
    };
    let key_index = batch_column_index(batch, key_column)?;
    let Some(keys) = batch
        .column(key_index)
        .as_any()
        .downcast_ref::<Int64Array>()
    else {
        return Ok(None);
    };
    let string_index = batch_column_index(batch, &filter.column)?;
    let Some(strings) = view.utf8(string_index) else {
        return collect_dense_right_counts_fast_like_batch(
            batch.clone(),
            key_column,
            filter,
            counts,
        );
    };
    let finders = filter
        .parts
        .iter()
        .map(|part| Finder::new(part))
        .collect::<Vec<_>>();
    if keys.null_count() == 0 && strings.null_count() == 0 {
        let key_values = keys.values().as_ref();
        if let Some((first, second)) = fast_like_two_substring_finders(&finders) {
            for (row, &key) in key_values.iter().enumerate() {
                if fast_like_two_substrings_row_matches_non_null(
                    strings,
                    row,
                    &filter.parts[0],
                    &filter.parts[1],
                    first,
                    second,
                    filter.negated,
                ) {
                    dense_count_increment(counts, key)?;
                }
            }
            return Ok(Some(()));
        }
        for (row, &key) in key_values.iter().enumerate() {
            if fast_like_substrings_row_matches_non_null(
                strings,
                row,
                &filter.parts,
                &finders,
                filter.negated,
            ) {
                dense_count_increment(counts, key)?;
            }
        }
        return Ok(Some(()));
    }
    if let Some((first, second)) = fast_like_two_substring_finders(&finders) {
        for row in 0..keys.len() {
            if keys.is_valid(row)
                && fast_like_two_substrings_row_matches(
                    strings,
                    row,
                    &filter.parts[0],
                    &filter.parts[1],
                    first,
                    second,
                    filter.negated,
                )
            {
                dense_count_increment(counts, keys.value(row))?;
            }
        }
        return Ok(Some(()));
    }
    for row in 0..keys.len() {
        if keys.is_valid(row)
            && fast_like_substrings_row_matches(
                strings,
                row,
                &filter.parts,
                &finders,
                filter.negated,
            )
        {
            dense_count_increment(counts, keys.value(row))?;
        }
    }
    Ok(Some(()))
}

fn dense_count_increment(counts: &mut Vec<u32>, key: i64) -> Result<()> {
    if !(0..=10_000_000).contains(&key) {
        return Err(DodamError::InvalidFilter(
            "dense count key out of supported range".to_string(),
        ));
    }
    let index = key as usize;
    if counts.len() <= index {
        counts.resize(index + 1, 0);
    }
    counts[index] = counts[index]
        .checked_add(1)
        .ok_or_else(|| DodamError::InvalidFilter("dense count overflow".to_string()))?;
    Ok(())
}

fn dense_right_count_row_group_map_enabled() -> bool {
    std::env::var("DODAM_DISABLE_DENSE_RIGHT_COUNT_ROW_GROUP_MAP")
        .map(|value| !matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES"))
        .unwrap_or(true)
}

fn dense_right_count_row_group_chunk() -> usize {
    std::env::var("DODAM_DENSE_RIGHT_COUNT_ROW_GROUP_CHUNK")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(16)
}

#[derive(Clone)]
struct FastLikeSubstrings {
    column: String,
    parts: Vec<Vec<u8>>,
    negated: bool,
}

fn fast_like_distribution_enabled() -> bool {
    std::env::var("DODAM_DISABLE_FAST_LIKE_DISTRIBUTION")
        .map(|value| !matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES"))
        .unwrap_or(true)
}

fn fast_like_substrings_filter(expr: &Expr) -> Option<FastLikeSubstrings> {
    match expr {
        Expr::Like {
            column,
            pattern,
            negated,
            escape,
            case_insensitive,
        } => {
            if *case_insensitive
                || escape.is_some()
                || !pattern.starts_with('%')
                || !pattern.ends_with('%')
                || pattern.contains('_')
            {
                return None;
            }
            let parts = pattern
                .split('%')
                .filter(|part| !part.is_empty())
                .map(|part| part.as_bytes().to_vec())
                .collect::<Vec<_>>();
            (!parts.is_empty()).then(|| FastLikeSubstrings {
                column: column.clone(),
                parts,
                negated: *negated,
            })
        }
        Expr::Not(expr) => {
            let mut filter = fast_like_substrings_filter(expr)?;
            filter.negated = !filter.negated;
            Some(filter)
        }
        _ => None,
    }
}

fn fast_like_substrings_row_matches(
    strings: &StringArray,
    row: usize,
    parts: &[Vec<u8>],
    finders: &[Finder<'_>],
    negated: bool,
) -> bool {
    if strings.is_null(row) {
        return false;
    }
    let mut haystack = bytes_string_parts(strings.value_offsets(), strings.value_data(), row);
    for (part, finder) in parts.iter().zip(finders) {
        let Some(index) = finder.find(haystack) else {
            return negated;
        };
        haystack = &haystack[index + part.len()..];
    }
    !negated
}

fn fast_like_substrings_row_matches_non_null(
    strings: &StringArray,
    row: usize,
    parts: &[Vec<u8>],
    finders: &[Finder<'_>],
    negated: bool,
) -> bool {
    let mut haystack = bytes_string_parts(strings.value_offsets(), strings.value_data(), row);
    for (part, finder) in parts.iter().zip(finders) {
        let Some(index) = finder.find(haystack) else {
            return negated;
        };
        haystack = &haystack[index + part.len()..];
    }
    !negated
}

fn fast_like_two_substring_finders<'a>(
    finders: &'a [Finder<'a>],
) -> Option<(&'a Finder<'a>, &'a Finder<'a>)> {
    if let [first, second] = finders {
        Some((first, second))
    } else {
        None
    }
}

fn fast_like_two_substrings_row_matches(
    strings: &StringArray,
    row: usize,
    first_part: &[u8],
    second_part: &[u8],
    first_finder: &Finder<'_>,
    second_finder: &Finder<'_>,
    negated: bool,
) -> bool {
    if strings.is_null(row) {
        return false;
    }
    fast_like_two_substrings_row_matches_non_null(
        strings,
        row,
        first_part,
        second_part,
        first_finder,
        second_finder,
        negated,
    )
}

fn fast_like_two_substrings_row_matches_non_null(
    strings: &StringArray,
    row: usize,
    first_part: &[u8],
    _second_part: &[u8],
    first_finder: &Finder<'_>,
    second_finder: &Finder<'_>,
    negated: bool,
) -> bool {
    let haystack = bytes_string_parts(strings.value_offsets(), strings.value_data(), row);
    let matched = first_finder
        .find(haystack)
        .and_then(|index| second_finder.find(&haystack[index + first_part.len()..]))
        .is_some();
    matched != negated
}

fn expr_is_like_only(expr: &Expr) -> bool {
    match expr {
        Expr::Like { .. } => true,
        Expr::Not(expr) => expr_is_like_only(expr),
        Expr::And(left, right) | Expr::Or(left, right) => {
            expr_is_like_only(left) && expr_is_like_only(right)
        }
        Expr::Boolean(_)
        | Expr::Comparison(_)
        | Expr::ColumnComparison { .. }
        | Expr::InList { .. }
        | Expr::IsNull { .. } => false,
    }
}

fn parquet_column_is_non_nullable(path: &PathBuf, column: &str) -> Result<bool> {
    if !path.is_file() {
        return Ok(false);
    }
    let file = File::open(path)?;
    let builder = ParquetRecordBatchReaderBuilder::try_new(file)?;
    Ok(builder
        .schema()
        .fields()
        .iter()
        .find(|field| field.name() == column)
        .is_some_and(|field| !field.is_nullable()))
}

async fn collect_left_count_distribution(
    engine: &DodamEngine,
    left_path: &PathBuf,
    join: &SqlJoin,
    dense_counts: &[u32],
    batch_size: usize,
) -> Result<Vec<GroupAggregateResult>> {
    let mut left_stream = engine
        .scan_parquet_batches(
            left_path.clone(),
            batch_size,
            None,
            Projection::Columns(vec![join.left_keys[0].clone()]),
            None,
        )
        .await?;
    let left_key_index_hint = Some(0);
    let mut distribution = Vec::<u64>::new();
    while let Some(batch) = left_stream.next() {
        let batch = batch?;
        let key_index =
            batch_projected_column_index(&batch, left_key_index_hint, &join.left_keys[0])?;
        let Some(keys) = batch
            .column(key_index)
            .as_any()
            .downcast_ref::<Int64Array>()
        else {
            return Ok(Vec::new());
        };
        if keys.null_count() == 0 {
            for key in keys.values().as_ref() {
                let count = if *key >= 0 {
                    dense_counts.get(*key as usize).copied().unwrap_or(0)
                } else {
                    0
                };
                let index = count as usize;
                if distribution.len() <= index {
                    distribution.resize(index + 1, 0);
                }
                distribution[index] += 1;
            }
            continue;
        }
        for row in 0..batch.num_rows() {
            let count = if keys.is_valid(row) {
                let key = keys.value(row);
                if key >= 0 {
                    dense_counts.get(key as usize).copied().unwrap_or(0)
                } else {
                    0
                }
            } else {
                0
            };
            let index = count as usize;
            if distribution.len() <= index {
                distribution.resize(index + 1, 0);
            }
            distribution[index] += 1;
        }
    }
    Ok(distribution
        .into_iter()
        .enumerate()
        .filter(|(_, rows)| *rows > 0)
        .map(|(count, rows)| GroupAggregateResult {
            keys: vec![GroupValue::UInt64(Some(count as u64))],
            values: vec![AggregateResult {
                expr: AggregateExpr::CountStar,
                value: AggregateValue::Count(rows),
            }],
        })
        .collect())
}

fn resolve_inner_output_column_index(inner: &SqlQuery, column: &str) -> Option<usize> {
    if let Some(index) = inner
        .group_by
        .iter()
        .position(|group| same_join_column(group, column))
    {
        return Some(index);
    }
    if let Some(index) = inner
        .aggregates
        .iter()
        .position(|aggregate| aggregate.to_string() == column)
    {
        return Some(inner.group_by.len() + index);
    }
    let (_, target) = inner.aliases.iter().find(|(alias, _)| alias == column)?;
    if let Some(index) = inner
        .group_by
        .iter()
        .position(|group| same_join_column(group, target))
    {
        return Some(index);
    }
    inner
        .aggregates
        .iter()
        .position(|aggregate| aggregate.to_string() == *target)
        .map(|index| inner.group_by.len() + index)
}

fn batch_column_index(batch: &RecordBatch, column: &str) -> Result<usize> {
    if let Some(index) = batch
        .schema()
        .fields()
        .iter()
        .position(|field| same_join_column(field.name(), column))
    {
        return Ok(index);
    }
    Err(DodamError::UnknownColumn(column.to_string()))
}

fn projected_column_index(projection: &[String], column: &str) -> Option<usize> {
    projection
        .iter()
        .position(|projected| same_join_column(projected, column))
}

fn batch_projected_column_index(
    batch: &RecordBatch,
    index_hint: Option<usize>,
    column: &str,
) -> Result<usize> {
    if let Some(index) = index_hint
        && batch
            .schema()
            .fields()
            .get(index)
            .is_some_and(|field| same_join_column(field.name(), column))
    {
        return Ok(index);
    }
    batch_column_index(batch, column)
}

fn try_count_derived_aggregate_groups(
    inner_metrics: &AggregateMetrics,
    inner_batches: &[RecordBatch],
    group_by: &[String],
    projection: &ParsedProjection,
    filter: Option<&FilterExpr>,
    having: Option<&FilterExpr>,
    order_by: Option<&SortKey>,
    limit: Option<usize>,
) -> Result<Option<QueryOutput>> {
    if group_by.len() != 1
        || !matches!(projection.aggregates.as_slice(), [AggregateExpr::CountStar])
        || !projection.aggregate_expressions.is_empty()
        || projection_requires_expression_path(&projection.expressions)
        || filter.is_some()
        || having.is_some()
        || inner_metrics.groups.is_empty()
    {
        return Ok(None);
    }
    let Some(schema_batch) = inner_batches.first() else {
        return Ok(None);
    };
    let Some(output_column_index) = schema_batch
        .schema()
        .fields()
        .iter()
        .position(|field| field.name() == &group_by[0])
    else {
        return Ok(None);
    };
    let inner_key_count = inner_metrics.groups[0].keys.len();
    let mut counts: HashMap<GroupValue, u64> = HashMap::new();
    for group in &inner_metrics.groups {
        let key = if output_column_index < inner_key_count {
            group.keys[output_column_index].clone()
        } else {
            let value_index = output_column_index - inner_key_count;
            let Some(value) = group.values.get(value_index) else {
                return Ok(None);
            };
            let Some(key) = aggregate_value_to_group_value(&value.value) else {
                return Ok(None);
            };
            key
        };
        *counts.entry(key).or_insert(0) += 1;
    }
    let mut groups = counts
        .into_iter()
        .map(|(key, count)| GroupAggregateResult {
            keys: vec![key],
            values: vec![AggregateResult {
                expr: AggregateExpr::CountStar,
                value: AggregateValue::Count(count),
            }],
        })
        .collect::<Vec<_>>();
    groups.sort_by(|left, right| left.keys[0].to_string().cmp(&right.keys[0].to_string()));
    let metrics = AggregateMetrics {
        fragments: 1,
        batches: 1,
        rows: inner_metrics.groups.len(),
        values: Vec::new(),
        groups,
        ..AggregateMetrics::default()
    };
    let mut batches = aggregate_metrics_to_batches(&metrics, group_by, &projection.aggregates)?;
    batches = apply_output_order_limit(batches, order_by, limit, 0)?;
    batches = rename_output_batches(batches, &projection.aliases)?;
    Ok(Some(QueryOutput::Aggregate { metrics, batches }))
}

fn aggregate_value_to_group_value(value: &AggregateValue) -> Option<GroupValue> {
    match value {
        AggregateValue::Count(value) => Some(GroupValue::UInt64(Some(*value))),
        AggregateValue::Int64(value) => Some(GroupValue::Int64(*value)),
        AggregateValue::Date32(value) => Some(GroupValue::Date32(*value)),
        AggregateValue::Date64(value) => Some(GroupValue::Date64(*value)),
        AggregateValue::Decimal128(value, precision, scale) => {
            Some(GroupValue::Decimal128(*value, *precision, *scale))
        }
        AggregateValue::Utf8(value) => Some(GroupValue::Utf8(value.clone())),
        AggregateValue::Float64(_) | AggregateValue::TimestampMillisecond(_, _) => None,
    }
}

async fn try_execute_derived_sql(
    engine: &DodamEngine,
    sql: &str,
    batch_size: usize,
) -> Result<Option<QueryOutput>> {
    let dialect = GenericDialect {};
    let statements = Parser::parse_sql(&dialect, sql)
        .map_err(|error| DodamError::UnsupportedSql(error.to_string()))?;
    let [Statement::Query(query)] = statements.as_slice() else {
        return Ok(None);
    };
    let SetExpr::Select(select) = query.body.as_ref() else {
        return Ok(None);
    };
    let Some((subquery, alias)) = parse_derived_from(select)? else {
        return Ok(None);
    };
    reject_query_features(query)?;
    reject_select_features(select)?;

    let distinct = parse_distinct(select)?;
    let inner_has_materializable_subquery = match subquery.body.as_ref() {
        SetExpr::Select(inner_select) => inner_select
            .selection
            .as_ref()
            .is_some_and(expr_contains_materializable_subquery),
        _ => false,
    };
    let parsed_inner = match parse_query(subquery) {
        Ok(query) => Some(query),
        Err(DodamError::UnsupportedSql(_))
        | Err(DodamError::UnknownColumn(_))
        | Err(DodamError::UnknownTableQualifier(_)) => None,
        Err(error) => return Err(error),
    };
    let inner_output = if let Some(parsed_inner) = parsed_inner {
        if !inner_has_materializable_subquery
            && let Some(output) =
                execute_parsed_join_query(engine, parsed_inner, batch_size).await?
        {
            output
        } else {
            Box::pin(execute_sql(engine, &subquery.to_string(), batch_size)).await?
        }
    } else {
        Box::pin(execute_sql(engine, &subquery.to_string(), batch_size)).await?
    };
    let group_by = parse_group_by(select, Some(&alias))?;
    let parsed_projection = parse_projection(select, &group_by, Some(&alias))?;
    let filter = select
        .selection
        .as_ref()
        .map(|expr| parse_filter(expr, &[], Some(&alias), false))
        .transpose()?;
    let having = select
        .having
        .as_ref()
        .map(|expr| parse_filter(expr, &parsed_projection.aliases, None, true))
        .transpose()?;
    let order_by = parse_order_by(
        query,
        &parsed_projection.aliases,
        &parsed_projection.ordinal_targets,
        Some(&alias),
    )?;
    let limit = parse_limit(query)?;

    if let QueryOutput::Aggregate {
        metrics: inner_metrics,
        batches: inner_batches,
    } = &inner_output
    {
        if let Some(output) = try_count_derived_aggregate_groups(
            inner_metrics,
            inner_batches,
            &group_by,
            &parsed_projection,
            filter.as_ref(),
            having.as_ref(),
            order_by.as_ref(),
            limit,
        )? {
            return Ok(Some(output));
        }
    }

    let inner_batches = query_output_batches(inner_output)?;
    if !parsed_projection.aggregates.is_empty() {
        let mut filtered_batches = apply_output_filter(inner_batches, filter.as_ref())?;
        filtered_batches = append_aggregate_expression_columns(
            filtered_batches,
            &parsed_projection.aggregate_expressions,
        )?;
        let stream = Box::new(MemoryExec::new(filtered_batches)).execute()?;
        let metrics = if group_by.is_empty() {
            collect_aggregates(stream, 1, &parsed_projection.aggregates)?
        } else {
            collect_grouped_aggregates(stream, 1, &group_by, &parsed_projection.aggregates)?
        };
        let mut batches =
            aggregate_metrics_to_batches(&metrics, &group_by, &parsed_projection.aggregates)?;
        batches = apply_output_filter(batches, having.as_ref())?;
        let has_output_expressions =
            projection_requires_expression_path(&parsed_projection.expressions);
        if has_output_expressions {
            batches = apply_output_expression_projection(batches, &parsed_projection.expressions)?;
        }
        batches = apply_output_order_limit(batches, order_by.as_ref(), limit, 0)?;
        if !has_output_expressions {
            batches = rename_output_batches(batches, &parsed_projection.aliases)?;
        }
        return Ok(Some(QueryOutput::Aggregate { metrics, batches }));
    }

    validate_distinct(
        distinct,
        &parsed_projection.projection,
        &parsed_projection.aggregates,
        order_by.as_ref(),
    )?;
    let mut batches = apply_output_filter(inner_batches, filter.as_ref())?;
    let projection_requires_expression =
        projection_requires_expression_path(&parsed_projection.expressions);
    batches = if projection_requires_expression {
        apply_output_expression_projection(batches, &parsed_projection.expressions)?
    } else {
        apply_output_projection(batches, &parsed_projection.projection)?
    };
    if distinct {
        batches = collect_batches(
            Box::new(DistinctExec::new(Box::new(MemoryExec::new(batches)))).execute()?,
        )?;
    }
    batches = apply_output_order_limit(batches, order_by.as_ref(), limit, 0)?;
    if !projection_requires_expression {
        batches = rename_output_batches(batches, &parsed_projection.aliases)?;
    }
    Ok(Some(QueryOutput::Scan { batches }))
}

async fn try_execute_multi_comma_join_sql(
    engine: &DodamEngine,
    sql: &str,
    batch_size: usize,
) -> Result<Option<QueryOutput>> {
    let dialect = GenericDialect {};
    let statements = Parser::parse_sql(&dialect, sql)
        .map_err(|error| DodamError::UnsupportedSql(error.to_string()))?;
    let [Statement::Query(query)] = statements.as_slice() else {
        return Ok(None);
    };
    let SetExpr::Select(select) = query.body.as_ref() else {
        return Ok(None);
    };
    let Some(tables) = parse_comma_join_table_refs(select)? else {
        return Ok(None);
    };
    if tables.len() <= 2 {
        return Ok(None);
    }
    reject_query_features(query)?;
    reject_select_features(select)?;
    let aliases = tables
        .iter()
        .map(table_ref_alias_or_name)
        .collect::<Vec<_>>();
    let alias_refs = aliases.iter().map(String::as_str).collect::<Vec<_>>();
    let mut conjuncts = Vec::new();
    let selection = select.selection.as_ref().ok_or_else(|| {
        DodamError::UnsupportedSql("comma join requires an equality predicate in WHERE".to_string())
    })?;
    collect_sql_and_conjuncts(selection, &mut conjuncts);

    let mut used_conjuncts = vec![false; conjuncts.len()];
    let scan_filters =
        comma_join_single_table_filters(&conjuncts, &aliases, &alias_refs, &mut used_conjuncts)?;
    let group_by = parse_join_group_by(select, &alias_refs)?;
    let projection = parse_join_projection(select, &alias_refs, &group_by)?;
    let distinct = parse_distinct(select)?;
    validate_distinct(
        distinct,
        &projection.projection,
        &projection.aggregates,
        None,
    )?;
    let having = select
        .having
        .as_ref()
        .map(|expr| parse_join_filter(expr, &projection.aliases, &alias_refs, true))
        .transpose()?;
    let order_by = parse_join_order_by(
        query,
        &projection.aliases,
        &projection.ordinal_targets,
        &alias_refs,
    )?;
    let limit = parse_limit(query)?;
    let scan_projections = comma_join_scan_projections(
        &conjuncts,
        &aliases,
        &alias_refs,
        &group_by,
        &projection,
        having.as_ref(),
        order_by.as_ref(),
    )?;
    let final_columns = comma_join_final_columns(
        &alias_refs,
        &group_by,
        &projection,
        having.as_ref(),
        order_by.as_ref(),
    )?;
    let mut scanned = Vec::with_capacity(tables.len());
    let mut row_counts = Vec::with_capacity(tables.len());
    for index in 0..tables.len() {
        let batches = scan_table_for_comma_join(
            engine,
            &tables[index],
            batch_size,
            scan_filters[index].as_ref(),
            &scan_projections[index],
        )
        .await?;
        row_counts.push(record_batch_rows(&batches));
        scanned.push(Some(batches));
    }
    let join_cost_model =
        CommaJoinCostModel::new(&scanned, &row_counts, &aliases, &alias_refs, &conjuncts)?;
    let use_ndv_join_order = true;
    let start_index = join_cost_model.choose_start_index().unwrap_or_else(|| {
        row_counts
            .iter()
            .enumerate()
            .min_by_key(|(_, rows)| *rows)
            .map(|(index, _)| index)
            .expect("at least one comma join table")
    });
    let mut current = scanned[start_index].take().expect("start input scanned");
    let mut current_rows = row_counts[start_index];
    let mut joined_aliases = vec![aliases[start_index].clone()];
    let mut remaining = (0..tables.len())
        .filter(|index| *index != start_index)
        .collect::<Vec<_>>();
    while !remaining.is_empty() {
        let mut candidates = Vec::new();
        for (remaining_index, table_index) in remaining.iter().copied().enumerate() {
            let alias = &aliases[table_index];
            let mut left_keys = Vec::new();
            let mut right_keys = Vec::new();
            let mut conjunct_indexes = Vec::new();
            for (index, conjunct) in conjuncts.iter().enumerate() {
                if used_conjuncts[index] {
                    continue;
                }
                if let Some((left_key, right_key)) =
                    comma_join_keys_for_next(conjunct, &joined_aliases, alias, &alias_refs)?
                {
                    left_keys.push(left_key);
                    right_keys.push(right_key);
                    conjunct_indexes.push(index);
                }
            }
            if !left_keys.is_empty() {
                candidates.push((
                    remaining_index,
                    table_index,
                    left_keys,
                    right_keys,
                    conjunct_indexes,
                ));
            }
        }
        let selected = if candidates.len() <= 1 || !use_ndv_join_order {
            candidates.into_iter().next()
        } else {
            let mut selected = None;
            for candidate in candidates {
                let (_, table_index, left_keys, right_keys, _) = &candidate;
                let right = scanned[*table_index]
                    .as_ref()
                    .expect("remaining input scanned");
                let score = estimate_join_output_rows(
                    &current,
                    right,
                    current_rows,
                    row_counts[*table_index],
                    left_keys,
                    right_keys,
                )?
                .saturating_mul(
                    estimated_batches_row_width(&current)
                        .saturating_add(join_cost_model.table_width(*table_index)),
                );
                if selected
                    .as_ref()
                    .is_none_or(|(_, selected_score)| score < *selected_score)
                {
                    selected = Some((candidate, score));
                }
            }
            selected.map(|(candidate, _)| candidate)
        };
        let Some((remaining_index, table_index, left_keys, right_keys, conjunct_indexes)) =
            selected
        else {
            return Err(DodamError::UnsupportedSql(format!(
                "comma join could not find equality predicate for remaining tables: {}",
                remaining
                    .iter()
                    .map(|index| aliases[*index].as_str())
                    .collect::<Vec<_>>()
                    .join(", ")
            )));
        };
        for index in conjunct_indexes {
            used_conjuncts[index] = true;
        }
        remaining.remove(remaining_index);
        let alias = &aliases[table_index];
        let right = scanned[table_index]
            .take()
            .expect("remaining input scanned");
        let right_rows = row_counts[table_index];
        let left_prefix = if joined_aliases.len() == 1 {
            joined_aliases[0].as_str()
        } else {
            "__dodam_join"
        };
        let build_side = if current_rows <= right_rows {
            JoinBuildSide::Left
        } else {
            JoinBuildSide::Right
        };
        let stream = Box::new(HashJoinExec::new(
            Box::new(MemoryExec::new(current)),
            Box::new(MemoryExec::new(right)),
            left_keys,
            right_keys,
            left_prefix.to_string(),
            alias.clone(),
            build_side,
            JoinType::Inner,
            Projection::All,
        ))
        .execute()?;
        current = collect_batches(stream)?;
        current_rows = record_batch_rows(&current);
        if left_prefix == "__dodam_join" {
            current = strip_batch_field_prefix(current, "__dodam_join.")?;
        }
        joined_aliases.push(alias.clone());
        current = prune_comma_join_current_columns(
            current,
            &joined_aliases,
            &alias_refs,
            &conjuncts,
            &used_conjuncts,
            &final_columns,
        )?;
    }

    let residual = conjuncts
        .into_iter()
        .enumerate()
        .filter_map(|(index, conjunct)| (!used_conjuncts[index]).then_some(conjunct))
        .collect::<Vec<_>>();
    let residual = combine_sql_and_conjuncts(residual);
    let (filter_residual, subquery_residual) = split_subquery_residual(residual);
    let (filter, expression_filter) = parse_join_filter_plan(
        filter_residual.as_ref(),
        &projection.aliases,
        &alias_refs,
        false,
    )?;

    let mut batches = apply_output_filter(current, filter.as_ref())?;
    if let Some(expression_filter) = expression_filter.as_ref() {
        batches = apply_output_join_expression_filter(batches, expression_filter, &alias_refs)?;
    }
    if let Some(residual) = subquery_residual.as_ref() {
        if let Some(optimized) =
            try_apply_correlated_min_equality_filter(engine, batches.clone(), residual, batch_size)
                .await?
        {
            batches = optimized;
        } else {
            batches = apply_correlated_subquery_filter_batches(
                engine,
                batches,
                &residual.to_string(),
                batch_size,
            )
            .await?;
        }
    }
    if !projection.aggregates.is_empty() {
        batches = append_aggregate_expression_columns(batches, &projection.aggregate_expressions)?;
        let stream = Box::new(MemoryExec::new(batches)).execute()?;
        let metrics = if group_by.is_empty() {
            collect_aggregates(stream, 1, &projection.aggregates)?
        } else {
            collect_grouped_aggregates(stream, 1, &group_by, &projection.aggregates)?
        };
        let mut batches =
            aggregate_metrics_to_batches(&metrics, &group_by, &projection.aggregates)?;
        batches = apply_output_filter(batches, having.as_ref())?;
        let has_output_expressions = projection_requires_expression_path(&projection.expressions);
        if has_output_expressions {
            batches = apply_output_expression_projection(batches, &projection.expressions)?;
        }
        batches = apply_output_order_limit(batches, order_by.as_ref(), limit, 0)?;
        if !has_output_expressions {
            batches = rename_output_batches(batches, &projection.aliases)?;
        }
        return Ok(Some(QueryOutput::Aggregate { metrics, batches }));
    }
    let projection_requires_expression =
        projection_requires_expression_path(&projection.expressions);
    batches = if projection_requires_expression {
        apply_output_expression_projection_order_limit(
            batches,
            &projection.expressions,
            order_by.as_ref(),
            limit,
            0,
        )?
    } else {
        apply_output_projection(batches, &projection.projection)?
    };
    if distinct {
        batches = collect_batches(
            Box::new(DistinctExec::new(Box::new(MemoryExec::new(batches)))).execute()?,
        )?;
    }
    if !projection_requires_expression {
        batches = apply_output_order_limit(batches, order_by.as_ref(), limit, 0)?;
    }
    if !projection_requires_expression {
        batches = rename_output_batches(batches, &projection.aliases)?;
    }
    Ok(Some(QueryOutput::Scan { batches }))
}

fn record_batch_rows(batches: &[RecordBatch]) -> usize {
    batches.iter().map(RecordBatch::num_rows).sum()
}

fn estimated_batches_row_width(batches: &[RecordBatch]) -> u128 {
    batches
        .first()
        .map(|batch| {
            batch
                .schema()
                .fields()
                .iter()
                .map(|field| estimated_type_width(field.data_type()))
                .sum::<u128>()
                .max(1)
        })
        .unwrap_or(1)
}

fn estimated_type_width(data_type: &DataType) -> u128 {
    match data_type {
        DataType::Boolean => 1,
        DataType::Int8 | DataType::UInt8 => 1,
        DataType::Int16 | DataType::UInt16 => 2,
        DataType::Int32 | DataType::UInt32 | DataType::Float32 | DataType::Date32 => 4,
        DataType::Int64
        | DataType::UInt64
        | DataType::Float64
        | DataType::Date64
        | DataType::Time64(_)
        | DataType::Timestamp(_, _) => 8,
        DataType::Decimal128(_, _) => 16,
        DataType::Decimal256(_, _) => 32,
        DataType::Utf8 | DataType::LargeUtf8 => 24,
        DataType::Binary | DataType::LargeBinary => 24,
        DataType::List(_) | DataType::LargeList(_) | DataType::FixedSizeList(_, _) => 32,
        DataType::Struct(fields) => fields
            .iter()
            .map(|field| estimated_type_width(field.data_type()))
            .sum::<u128>()
            .max(1),
        _ => 16,
    }
}

fn estimate_join_output_rows(
    left: &[RecordBatch],
    right: &[RecordBatch],
    left_rows: usize,
    right_rows: usize,
    left_keys: &[String],
    right_keys: &[String],
) -> Result<u128> {
    let left_ndv = sampled_key_ndv(left, left_keys, 100_000)?.max(1);
    let right_ndv = sampled_key_ndv(right, right_keys, 100_000)?.max(1);
    let denominator = left_ndv.max(right_ndv) as u128;
    Ok((left_rows as u128).saturating_mul(right_rows as u128) / denominator)
}

#[derive(Clone)]
struct CommaJoinTableCostStats {
    rows: u128,
    row_width: u128,
    key_ndv: HashMap<String, u128>,
}

#[derive(Clone)]
struct CommaJoinCostEdge {
    left: usize,
    left_key: String,
    right: usize,
    right_key: String,
}

struct CommaJoinCostModel {
    tables: Vec<CommaJoinTableCostStats>,
    edges: Vec<CommaJoinCostEdge>,
}

impl CommaJoinCostModel {
    fn new(
        scanned: &[Option<Vec<RecordBatch>>],
        row_counts: &[usize],
        aliases: &[String],
        alias_refs: &[&str],
        conjuncts: &[SqlExpr],
    ) -> Result<Self> {
        let mut edges = Vec::new();
        let mut key_columns = vec![Vec::<String>::new(); aliases.len()];
        for conjunct in conjuncts {
            let Some((left_alias, left_key, right_alias, right_key)) =
                comma_join_base_edge(conjunct, alias_refs)?
            else {
                continue;
            };
            let Some(left) = aliases
                .iter()
                .position(|alias| alias.eq_ignore_ascii_case(left_alias))
            else {
                continue;
            };
            let Some(right) = aliases
                .iter()
                .position(|alias| alias.eq_ignore_ascii_case(right_alias))
            else {
                continue;
            };
            add_column_once(&mut key_columns[left], left_key.clone());
            add_column_once(&mut key_columns[right], right_key.clone());
            edges.push(CommaJoinCostEdge {
                left,
                left_key,
                right,
                right_key,
            });
        }

        let mut tables = Vec::with_capacity(scanned.len());
        for (index, batches) in scanned.iter().enumerate() {
            let batches = batches.as_ref().expect("comma join input scanned");
            let mut key_ndv = HashMap::new();
            for key in &key_columns[index] {
                key_ndv.insert(
                    key.clone(),
                    sampled_key_ndv(batches, &[key.clone()], 100_000)? as u128,
                );
            }
            tables.push(CommaJoinTableCostStats {
                rows: row_counts[index].max(1) as u128,
                row_width: estimated_batches_row_width(batches),
                key_ndv,
            });
        }

        Ok(Self { tables, edges })
    }

    fn choose_start_index(&self) -> Option<usize> {
        (0..self.tables.len())
            .filter_map(|start| {
                self.estimate_greedy_plan_cost(start)
                    .map(|cost| (start, cost))
            })
            .min_by_key(|(_, cost)| *cost)
            .map(|(start, _)| start)
    }

    fn table_width(&self, table_index: usize) -> u128 {
        self.tables[table_index].row_width
    }

    fn estimate_greedy_plan_cost(&self, start: usize) -> Option<u128> {
        let mut joined = vec![false; self.tables.len()];
        joined[start] = true;
        let mut joined_count = 1usize;
        let mut rows = self.tables[start].rows;
        let mut row_width = self.tables[start].row_width;
        let mut total_cost = rows.saturating_mul(row_width);

        while joined_count < self.tables.len() {
            let mut selected = None;
            for table_index in 0..self.tables.len() {
                if joined[table_index] {
                    continue;
                }
                let edges = self
                    .edges
                    .iter()
                    .filter(|edge| {
                        (edge.left == table_index && joined[edge.right])
                            || (edge.right == table_index && joined[edge.left])
                    })
                    .collect::<Vec<_>>();
                if edges.is_empty() {
                    continue;
                }
                let output_rows = self.estimate_join_rows(rows, table_index, &edges);
                let output_width = row_width.saturating_add(self.tables[table_index].row_width);
                let build_cost = rows.saturating_mul(row_width).min(
                    self.tables[table_index]
                        .rows
                        .saturating_mul(self.tables[table_index].row_width),
                );
                let step_cost = output_rows
                    .saturating_mul(output_width)
                    .saturating_add(build_cost);
                if selected
                    .as_ref()
                    .is_none_or(|(_, selected_cost, _)| step_cost < *selected_cost)
                {
                    selected = Some((table_index, step_cost, output_rows));
                }
            }
            let (table_index, step_cost, output_rows) = selected?;
            joined[table_index] = true;
            joined_count += 1;
            rows = output_rows.max(1);
            row_width = row_width.saturating_add(self.tables[table_index].row_width);
            total_cost = total_cost.saturating_add(step_cost);
        }

        Some(total_cost)
    }

    fn estimate_join_rows(
        &self,
        current_rows: u128,
        next_table: usize,
        edges: &[&CommaJoinCostEdge],
    ) -> u128 {
        let next_rows = self.tables[next_table].rows;
        let denominator = edges
            .iter()
            .map(|edge| {
                let (left_ndv, right_ndv) = self.edge_ndv(edge);
                left_ndv.max(right_ndv).max(1)
            })
            .max()
            .unwrap_or(1);
        current_rows.saturating_mul(next_rows) / denominator
    }

    fn edge_ndv(&self, edge: &CommaJoinCostEdge) -> (u128, u128) {
        (
            self.tables[edge.left]
                .key_ndv
                .get(&edge.left_key)
                .copied()
                .unwrap_or(self.tables[edge.left].rows)
                .max(1),
            self.tables[edge.right]
                .key_ndv
                .get(&edge.right_key)
                .copied()
                .unwrap_or(self.tables[edge.right].rows)
                .max(1),
        )
    }
}

fn sampled_key_ndv(batches: &[RecordBatch], keys: &[String], sample_rows: usize) -> Result<usize> {
    let mut values = HashSet::new();
    let mut sampled = 0usize;
    for batch in batches {
        if sampled >= sample_rows {
            break;
        }
        let key_indices = keys
            .iter()
            .map(|key| batch_column_index(batch, key))
            .collect::<Result<Vec<_>>>()?;
        for row in 0..batch.num_rows() {
            if sampled >= sample_rows {
                break;
            }
            sampled += 1;
            let mut parts = Vec::with_capacity(key_indices.len());
            let mut has_null = false;
            for index in &key_indices {
                match semijoin_key_at(batch.column(*index), row)? {
                    Some(value) => parts.push(value),
                    None => {
                        has_null = true;
                        break;
                    }
                }
            }
            if !has_null {
                values.insert(parts.join("\x1f"));
            }
        }
    }
    Ok(values.len())
}

fn comma_join_single_table_filters(
    conjuncts: &[SqlExpr],
    aliases: &[String],
    alias_refs: &[&str],
    used_conjuncts: &mut [bool],
) -> Result<Vec<Option<FilterExpr>>> {
    let mut filters = vec![Vec::<SqlExpr>::new(); aliases.len()];
    for (index, conjunct) in conjuncts.iter().enumerate() {
        if expr_contains_materializable_subquery(conjunct) {
            continue;
        }
        let Some(alias) = single_table_conjunct_alias(conjunct, alias_refs)? else {
            continue;
        };
        let Some(table_index) = aliases
            .iter()
            .position(|candidate| candidate.eq_ignore_ascii_case(alias))
        else {
            continue;
        };
        if parse_filter(conjunct, &[], Some(alias), false).is_err() {
            continue;
        }
        filters[table_index].push(conjunct.clone());
        used_conjuncts[index] = true;
    }
    filters
        .into_iter()
        .zip(aliases)
        .map(|(filters, alias)| {
            let Some(expr) = combine_sql_and_conjuncts(filters) else {
                return Ok(None);
            };
            parse_filter(&expr, &[], Some(alias), false).map(Some)
        })
        .collect()
}

fn comma_join_scan_projections(
    conjuncts: &[SqlExpr],
    aliases: &[String],
    alias_refs: &[&str],
    group_by: &[String],
    projection: &ParsedProjection,
    having: Option<&FilterExpr>,
    order_by: Option<&SortKey>,
) -> Result<Vec<Projection>> {
    if conjuncts.iter().any(expr_contains_materializable_subquery) {
        return Ok(vec![Projection::All; aliases.len()]);
    }

    let mut columns = vec![Vec::<String>::new(); aliases.len()];
    for conjunct in conjuncts {
        add_comma_join_expr_columns(&mut columns, conjunct, aliases, alias_refs)?;
    }
    for column in group_by {
        add_comma_join_column(&mut columns, column, aliases)?;
    }
    if let Projection::Columns(projected) = &projection.projection {
        for column in projected {
            add_comma_join_column(&mut columns, column, aliases)?;
        }
    } else {
        return Ok(vec![Projection::All; aliases.len()]);
    }
    for aggregate in &projection.aggregates {
        if let Some(column) = aggregate.referenced_column() {
            add_comma_join_column(&mut columns, column, aliases)?;
        }
    }
    for expression in &projection.aggregate_expressions {
        for column in join_scalar_expression_columns(&expression.expr, alias_refs)? {
            add_comma_join_column(&mut columns, &column, aliases)?;
        }
    }
    for expression in &projection.expressions {
        for column in join_scalar_expression_columns(&expression.expr, alias_refs)? {
            add_comma_join_column(&mut columns, &column, aliases)?;
        }
    }
    if let Some(having) = having {
        for column in having.referenced_columns() {
            add_comma_join_column(&mut columns, &column, aliases)?;
        }
    }
    if let Some(order_by) = order_by {
        for sort in &order_by.expressions {
            add_comma_join_column(&mut columns, &sort.column, aliases)?;
        }
    }

    Ok(columns
        .into_iter()
        .map(|columns| {
            if columns.is_empty() {
                Projection::All
            } else {
                Projection::Columns(columns)
            }
        })
        .collect())
}

fn comma_join_final_columns(
    alias_refs: &[&str],
    group_by: &[String],
    projection: &ParsedProjection,
    having: Option<&FilterExpr>,
    order_by: Option<&SortKey>,
) -> Result<HashSet<String>> {
    let mut columns = HashSet::new();
    for column in group_by {
        columns.insert(column.clone());
    }
    if let Projection::Columns(projected) = &projection.projection {
        columns.extend(projected.iter().cloned());
    }
    for aggregate in &projection.aggregates {
        if let Some(column) = aggregate.referenced_column() {
            columns.insert(column.to_string());
        }
    }
    for expression in &projection.aggregate_expressions {
        columns.extend(join_scalar_expression_columns(
            &expression.expr,
            alias_refs,
        )?);
    }
    for expression in &projection.expressions {
        columns.extend(join_scalar_expression_columns(
            &expression.expr,
            alias_refs,
        )?);
    }
    if let Some(having) = having {
        columns.extend(having.referenced_columns());
    }
    if let Some(order_by) = order_by {
        columns.extend(order_by.expressions.iter().map(|sort| sort.column.clone()));
    }
    Ok(columns)
}

fn prune_comma_join_current_columns(
    batches: Vec<RecordBatch>,
    joined_aliases: &[String],
    alias_refs: &[&str],
    conjuncts: &[SqlExpr],
    used_conjuncts: &[bool],
    final_columns: &HashSet<String>,
) -> Result<Vec<RecordBatch>> {
    if batches.is_empty() {
        return Ok(batches);
    }
    let mut needed = final_columns.clone();
    for (conjunct, used) in conjuncts.iter().zip(used_conjuncts) {
        if *used {
            continue;
        }
        if expr_contains_materializable_subquery(conjunct) {
            return Ok(batches);
        }
        let mut columns = Vec::new();
        collect_join_column_candidates(conjunct, alias_refs, &mut columns)?;
        needed.extend(columns);
    }
    let schema = batches[0].schema();
    let keep = schema
        .fields()
        .iter()
        .filter_map(|field| {
            let name = field.name();
            if comma_join_field_needed(name, joined_aliases, &needed) {
                Some(name.clone())
            } else {
                None
            }
        })
        .collect::<Vec<_>>();
    if keep.len() == schema.fields().len() {
        return Ok(batches);
    }
    if keep.is_empty() {
        return Ok(batches);
    }
    apply_output_projection(batches, &Projection::Columns(keep))
}

fn comma_join_field_needed(
    field_name: &str,
    joined_aliases: &[String],
    needed: &HashSet<String>,
) -> bool {
    if needed.contains(field_name) {
        return true;
    }
    let Some((alias, column)) = field_name.split_once('.') else {
        return true;
    };
    if !joined_aliases
        .iter()
        .any(|joined| joined.eq_ignore_ascii_case(alias))
    {
        return true;
    }
    needed.contains(&format!("{alias}.{column}"))
}

fn add_comma_join_expr_columns(
    output: &mut [Vec<String>],
    expr: &SqlExpr,
    aliases: &[String],
    alias_refs: &[&str],
) -> Result<()> {
    let mut columns = Vec::new();
    collect_join_column_candidates(expr, alias_refs, &mut columns)?;
    for column in columns {
        add_comma_join_column(output, &column, aliases)?;
    }
    Ok(())
}

fn add_comma_join_column(
    output: &mut [Vec<String>],
    qualified_column: &str,
    aliases: &[String],
) -> Result<()> {
    let Some((alias, column)) = qualified_column.split_once('.') else {
        return Ok(());
    };
    let Some(index) = aliases
        .iter()
        .position(|candidate| candidate.eq_ignore_ascii_case(alias))
    else {
        return Ok(());
    };
    add_column_once(&mut output[index], column.to_string());
    Ok(())
}

fn single_table_conjunct_alias<'a>(
    expr: &SqlExpr,
    table_aliases: &'a [&str],
) -> Result<Option<&'a str>> {
    let mut columns = Vec::new();
    collect_join_column_candidates(expr, table_aliases, &mut columns)?;
    let mut owner: Option<&'a str> = None;
    for column in columns {
        let Some((alias, _)) = column.split_once('.') else {
            return Ok(None);
        };
        let Some(alias) = table_aliases
            .iter()
            .copied()
            .find(|candidate| candidate.eq_ignore_ascii_case(alias))
        else {
            return Ok(None);
        };
        if let Some(existing) = owner {
            if !existing.eq_ignore_ascii_case(alias) {
                return Ok(None);
            }
        } else {
            owner = Some(alias);
        }
    }
    Ok(owner)
}

fn collect_join_column_candidates(
    expr: &SqlExpr,
    table_aliases: &[&str],
    columns: &mut Vec<String>,
) -> Result<()> {
    match expr {
        SqlExpr::BinaryOp { left, right, .. } => {
            collect_join_column_candidates(left, table_aliases, columns)?;
            collect_join_column_candidates(right, table_aliases, columns)?;
        }
        SqlExpr::UnaryOp { expr, .. }
        | SqlExpr::Nested(expr)
        | SqlExpr::IsNull(expr)
        | SqlExpr::IsNotNull(expr)
        | SqlExpr::Cast { expr, .. } => {
            collect_join_column_candidates(expr, table_aliases, columns)?;
        }
        SqlExpr::Identifier(_) | SqlExpr::CompoundIdentifier(_) => {
            for column in join_scalar_expression_columns(
                &parse_join_scalar_sql_expression(expr, table_aliases)?,
                table_aliases,
            )? {
                add_column_once(columns, column);
            }
        }
        SqlExpr::CompoundFieldAccess { .. } => {
            for column in join_scalar_expression_columns(
                &parse_join_scalar_sql_expression(expr, table_aliases)?,
                table_aliases,
            )? {
                add_column_once(columns, column);
            }
        }
        SqlExpr::Function(function) => {
            for arg in function_arg_exprs(function) {
                collect_join_column_candidates(arg, table_aliases, columns)?;
            }
        }
        SqlExpr::Substring {
            expr,
            substring_from,
            substring_for,
            ..
        } => {
            collect_join_column_candidates(expr, table_aliases, columns)?;
            if let Some(expr) = substring_from {
                collect_join_column_candidates(expr, table_aliases, columns)?;
            }
            if let Some(expr) = substring_for {
                collect_join_column_candidates(expr, table_aliases, columns)?;
            }
        }
        SqlExpr::InList { expr, list, .. } => {
            collect_join_column_candidates(expr, table_aliases, columns)?;
            for item in list {
                collect_join_column_candidates(item, table_aliases, columns)?;
            }
        }
        SqlExpr::Between {
            expr, low, high, ..
        } => {
            collect_join_column_candidates(expr, table_aliases, columns)?;
            collect_join_column_candidates(low, table_aliases, columns)?;
            collect_join_column_candidates(high, table_aliases, columns)?;
        }
        SqlExpr::Like { expr, pattern, .. } | SqlExpr::ILike { expr, pattern, .. } => {
            collect_join_column_candidates(expr, table_aliases, columns)?;
            collect_join_column_candidates(pattern, table_aliases, columns)?;
        }
        SqlExpr::Case {
            operand,
            conditions,
            else_result,
            ..
        } => {
            if let Some(operand) = operand {
                collect_join_column_candidates(operand, table_aliases, columns)?;
            }
            for when in conditions {
                collect_join_column_candidates(&when.condition, table_aliases, columns)?;
                collect_join_column_candidates(&when.result, table_aliases, columns)?;
            }
            if let Some(else_result) = else_result {
                collect_join_column_candidates(else_result, table_aliases, columns)?;
            }
        }
        SqlExpr::Value(_) => {}
        SqlExpr::Exists { .. } | SqlExpr::InSubquery { .. } | SqlExpr::Subquery(_) => {}
        _ => {}
    }
    Ok(())
}

async fn scan_table_for_comma_join(
    engine: &DodamEngine,
    table: &SqlTableRef,
    batch_size: usize,
    filter: Option<&FilterExpr>,
    projection: &Projection,
) -> Result<Vec<RecordBatch>> {
    let stream = engine
        .scan_parquet_batches(
            table.path.clone(),
            batch_size,
            None,
            projection.clone(),
            filter.cloned(),
        )
        .await?;
    collect_batches(stream)
}

fn strip_batch_field_prefix(batches: Vec<RecordBatch>, prefix: &str) -> Result<Vec<RecordBatch>> {
    batches
        .into_iter()
        .map(|batch| {
            let fields = batch
                .schema()
                .fields()
                .iter()
                .map(|field| {
                    let name = field
                        .name()
                        .as_str()
                        .strip_prefix(prefix)
                        .unwrap_or(field.name().as_str())
                        .to_string();
                    Arc::new(Field::new(
                        name,
                        field.data_type().clone(),
                        field.is_nullable(),
                    ))
                })
                .collect::<Vec<_>>();
            Ok(RecordBatch::try_new(
                Arc::new(Schema::new(fields)),
                batch.columns().to_vec(),
            )?)
        })
        .collect()
}

fn parse_derived_from(select: &Select) -> Result<Option<(&Query, String)>> {
    let [table] = select.from.as_slice() else {
        return Ok(None);
    };
    if !table.joins.is_empty() {
        return Ok(None);
    }
    let TableFactor::Derived {
        lateral,
        subquery,
        alias,
        sample,
    } = &table.relation
    else {
        return Ok(None);
    };
    if *lateral || sample.is_some() {
        return Err(DodamError::UnsupportedSql(
            "LATERAL and TABLESAMPLE derived tables are not supported".to_string(),
        ));
    }
    let alias = alias.as_ref().ok_or_else(|| {
        DodamError::UnsupportedSql("derived tables must have an alias".to_string())
    })?;
    if !alias.columns.is_empty() || alias.at.is_some() {
        return Err(DodamError::UnsupportedSql(
            "derived table column aliases and AT aliases are not supported".to_string(),
        ));
    }
    Ok(Some((subquery.as_ref(), alias.name.value.clone())))
}

fn query_output_batches(output: QueryOutput) -> Result<Vec<RecordBatch>> {
    match output {
        QueryOutput::Scan { batches } | QueryOutput::Aggregate { batches, .. } => Ok(batches),
        QueryOutput::Explain { .. } => Err(DodamError::UnsupportedSql(
            "EXPLAIN cannot be used as a derived table".to_string(),
        )),
    }
}

fn literal_values_from_single_column_batches(
    batches: Vec<RecordBatch>,
) -> Result<Vec<LiteralValue>> {
    let Some(schema) = batches.first().map(RecordBatch::schema) else {
        return Ok(Vec::new());
    };
    if schema.fields().len() != 1 {
        return Err(DodamError::UnsupportedSql(
            "IN subquery must return exactly one column".to_string(),
        ));
    }
    let mut values = Vec::new();
    for batch in batches {
        let column = batch.column(0);
        for row in 0..batch.num_rows() {
            if column.is_null(row) {
                values.push(LiteralValue::Null);
                continue;
            }
            values.push(literal_value_from_array(column, row)?);
        }
    }
    Ok(values)
}

fn scalar_literal_value_from_batches(batches: Vec<RecordBatch>) -> Result<LiteralValue> {
    let values = literal_values_from_single_column_batches(batches)?;
    match values.as_slice() {
        [] => Ok(LiteralValue::Null),
        [value] => Ok(value.clone()),
        _ => Err(DodamError::UnsupportedSql(
            "scalar subquery must return at most one row".to_string(),
        )),
    }
}

fn non_null_literal_values(list: &[SqlExpr]) -> Result<Vec<LiteralValue>> {
    let mut values = Vec::with_capacity(list.len());
    for expr in list {
        let value = sql_literal_value(expr)?;
        if !matches!(value, LiteralValue::Null) {
            values.push(value);
        }
    }
    Ok(values)
}

fn literal_list_contains_null(list: &[SqlExpr]) -> Result<bool> {
    for expr in list {
        if matches!(sql_literal_value(expr)?, LiteralValue::Null) {
            return Ok(true);
        }
    }
    Ok(false)
}

fn subquery_values_contain_null(values: &[LiteralValue]) -> bool {
    values
        .iter()
        .any(|value| matches!(value, LiteralValue::Null))
}

fn non_null_subquery_values(values: Vec<LiteralValue>) -> Vec<LiteralValue> {
    values
        .into_iter()
        .filter(|value| !matches!(value, LiteralValue::Null))
        .collect()
}

fn evaluate_literal_in_values(
    value: &LiteralValue,
    values: &[LiteralValue],
    negated: bool,
) -> Option<bool> {
    if matches!(value, LiteralValue::Null) {
        return None;
    }
    let has_null = subquery_values_contain_null(values);
    let matched = values
        .iter()
        .filter(|candidate| !matches!(candidate, LiteralValue::Null))
        .any(|candidate| {
            matches!(
                compare_literal_values(value, &BinaryOperator::Eq, candidate),
                Ok(Some(true))
            )
        });
    let result = if matched {
        Some(true)
    } else if has_null {
        None
    } else {
        Some(false)
    };
    if negated {
        result.map(|value| !value)
    } else {
        result
    }
}

fn compare_literal_values(
    left: &LiteralValue,
    op: &BinaryOperator,
    right: &LiteralValue,
) -> Result<Option<bool>> {
    if matches!(left, LiteralValue::Null) || matches!(right, LiteralValue::Null) {
        return Ok(None);
    }
    let ordering = match (left, right) {
        (LiteralValue::Boolean(left), LiteralValue::Boolean(right)) => left.cmp(right),
        (LiteralValue::Int64(left), LiteralValue::Int64(right)) => left.cmp(right),
        (LiteralValue::Float64(left), LiteralValue::Float64(right)) => left
            .partial_cmp(right)
            .ok_or_else(|| DodamError::InvalidFilter(format!("{left} {op} {right}")))?,
        (LiteralValue::Int64(left), LiteralValue::Float64(right)) => (*left as f64)
            .partial_cmp(right)
            .ok_or_else(|| DodamError::InvalidFilter(format!("{left} {op} {right}")))?,
        (LiteralValue::Float64(left), LiteralValue::Int64(right)) => left
            .partial_cmp(&(*right as f64))
            .ok_or_else(|| DodamError::InvalidFilter(format!("{left} {op} {right}")))?,
        (LiteralValue::Utf8(left), LiteralValue::Utf8(right)) => left.cmp(right),
        _ => {
            return Err(DodamError::InvalidFilter(format!("{left} {op} {right}")));
        }
    };
    Ok(Some(match op {
        BinaryOperator::Eq => ordering.is_eq(),
        BinaryOperator::NotEq => !ordering.is_eq(),
        BinaryOperator::Gt => ordering.is_gt(),
        BinaryOperator::GtEq => ordering.is_gt() || ordering.is_eq(),
        BinaryOperator::Lt => ordering.is_lt(),
        BinaryOperator::LtEq => ordering.is_lt() || ordering.is_eq(),
        _ => unreachable!("validated comparison operator"),
    }))
}

fn literal_value_from_array(column: &ArrayRef, row: usize) -> Result<LiteralValue> {
    match column.data_type() {
        DataType::Boolean => {
            let values = column
                .as_any()
                .downcast_ref::<BooleanArray>()
                .expect("Boolean data type");
            Ok(LiteralValue::Boolean(values.value(row)))
        }
        DataType::Int32 => {
            let values = column
                .as_any()
                .downcast_ref::<Int32Array>()
                .expect("Int32 data type");
            Ok(LiteralValue::Int64(i64::from(values.value(row))))
        }
        DataType::Int64 => {
            let values = column
                .as_any()
                .downcast_ref::<Int64Array>()
                .expect("Int64 data type");
            Ok(LiteralValue::Int64(values.value(row)))
        }
        DataType::Float64 => {
            let values = column
                .as_any()
                .downcast_ref::<Float64Array>()
                .expect("Float64 data type");
            Ok(LiteralValue::Float64(values.value(row)))
        }
        DataType::Decimal128(_, scale) => {
            let values = column
                .as_any()
                .downcast_ref::<Decimal128Array>()
                .expect("Decimal128 data type");
            Ok(LiteralValue::Float64(
                values.value(row) as f64 / 10_f64.powi(i32::from(*scale)),
            ))
        }
        DataType::Date32 => {
            let values = column
                .as_any()
                .downcast_ref::<Date32Array>()
                .expect("Date32 data type");
            let (year, month, day) = civil_from_days(i64::from(values.value(row)))?;
            Ok(LiteralValue::Utf8(format!("{year:04}-{month:02}-{day:02}")))
        }
        DataType::Date64 => {
            let values = column
                .as_any()
                .downcast_ref::<Date64Array>()
                .expect("Date64 data type");
            let (year, month, day) = civil_from_days(values.value(row) / 86_400_000)?;
            Ok(LiteralValue::Utf8(format!("{year:04}-{month:02}-{day:02}")))
        }
        DataType::Utf8 => {
            let values = column
                .as_any()
                .downcast_ref::<StringArray>()
                .expect("Utf8 data type");
            Ok(LiteralValue::Utf8(values.value(row).to_string()))
        }
        data_type => Err(DodamError::UnsupportedSql(format!(
            "IN subquery result type {data_type} is not supported yet"
        ))),
    }
}

fn sql_uses_materialized_subquery(sql: &str) -> Result<bool> {
    let dialect = GenericDialect {};
    let statements = Parser::parse_sql(&dialect, sql)
        .map_err(|error| DodamError::UnsupportedSql(error.to_string()))?;
    let [Statement::Query(query)] = statements.as_slice() else {
        return Ok(false);
    };
    let SetExpr::Select(select) = query.body.as_ref() else {
        return Ok(false);
    };
    Ok(parse_derived_from(select)?.is_some()
        || select.selection.as_ref().is_some_and(|expr| {
            top_level_exists_subquery(Some(expr)).is_some()
                || expr_contains_materializable_subquery(expr)
        })
        || select
            .having
            .as_ref()
            .is_some_and(expr_contains_materializable_subquery))
}

fn sql_uses_multi_comma_join(sql: &str) -> Result<bool> {
    let dialect = GenericDialect {};
    let statements = Parser::parse_sql(&dialect, sql)
        .map_err(|error| DodamError::UnsupportedSql(error.to_string()))?;
    let [Statement::Query(query)] = statements.as_slice() else {
        return Ok(false);
    };
    let SetExpr::Select(select) = query.body.as_ref() else {
        return Ok(false);
    };
    Ok(parse_comma_join_table_refs(select)?.is_some_and(|tables| tables.len() > 2))
}

pub async fn try_execute_sql_streaming(
    engine: &DodamEngine,
    sql: &str,
    batch_size: usize,
) -> Result<Option<SendableBatchStream>> {
    if explain_sql(engine, sql, batch_size).await?.is_some() {
        return Ok(None);
    }
    let Some(request) = plan_direct_join_sink_request(sql, batch_size)? else {
        return Ok(None);
    };
    engine.join_parquet_batches(request).await.map(Some)
}

pub async fn try_execute_sql_to_sink(
    engine: &DodamEngine,
    sql: &str,
    batch_size: usize,
    sink: &mut dyn RecordBatchSink,
) -> Result<Option<ScanPlanMetrics>> {
    if explain_sql(engine, sql, batch_size).await?.is_some() {
        return Ok(None);
    }
    if let Some(metrics) =
        try_execute_set_operation_sql_to_sink(engine, sql, batch_size, sink).await?
    {
        return Ok(Some(metrics));
    }
    let Some(request) = plan_direct_join_sink_request(sql, batch_size)? else {
        return Ok(None);
    };
    let plan = engine.plan_parquet_join(request).await?;
    engine.write_join_plan_to_sink(plan, sink).map(Some)
}

pub async fn execute_sql_to_result_sink(
    engine: &DodamEngine,
    sql: &str,
    batch_size: usize,
    sink: &mut dyn SqlResultSink,
    options: SqlSinkExecutionOptions,
) -> Result<SqlSinkExecutionProfile> {
    let mut profile = SqlSinkExecutionProfile::default();
    if options.allow_direct_or_streaming && explain_sql(engine, sql, batch_size).await?.is_none() {
        let direct_started = Instant::now();
        if let Some(metrics) =
            try_execute_set_operation_sql_to_sink(engine, sql, batch_size, sink.record_batch_sink())
                .await?
        {
            profile.direct_sink = Some(direct_started.elapsed());
            profile.scan_plan_metrics = Some(metrics);
            return Ok(profile);
        }
        if let Some(request) = plan_direct_join_sink_request(sql, batch_size)? {
            let plan = engine.plan_parquet_join(request).await?;
            let metrics = engine.write_join_plan_to_sink(plan, sink.record_batch_sink())?;
            profile.direct_sink = Some(direct_started.elapsed());
            profile.scan_plan_metrics = Some(metrics);
            return Ok(profile);
        }
        profile.direct_sink = Some(direct_started.elapsed());
        profile.streaming = Some(Duration::ZERO);
    } else {
        profile.direct_sink = Some(Duration::ZERO);
        profile.streaming = Some(Duration::ZERO);
    }

    let execute_started = Instant::now();
    let output = execute_sql(engine, sql, batch_size).await?;
    profile.execute = Some(execute_started.elapsed());
    let write_started = Instant::now();
    sink.write_output(output)?;
    profile.write_output = Some(write_started.elapsed());
    Ok(profile)
}

async fn try_execute_set_operation_sql_to_sink(
    engine: &DodamEngine,
    sql: &str,
    batch_size: usize,
    sink: &mut dyn RecordBatchSink,
) -> Result<Option<ScanPlanMetrics>> {
    let dialect = GenericDialect {};
    let statements = Parser::parse_sql(&dialect, sql)
        .map_err(|error| DodamError::UnsupportedSql(error.to_string()))?;
    let [Statement::Query(query)] = statements.as_slice() else {
        return Ok(None);
    };
    if !query_contains_set_operation(query.body.as_ref()) {
        return Ok(None);
    }
    if query.fetch.is_some() || !query.locks.is_empty() {
        return Ok(None);
    }
    let order_by = parse_order_by(query, &[], &[], None)?;
    let limit = parse_limit(query)?;
    let offset = parse_offset(query)?;

    if order_by.is_some() || limit.is_some() || offset != 0 {
        if try_write_same_source_union_all_ordered_desc_to_sink(
            engine,
            query.body.as_ref(),
            batch_size,
            order_by.as_ref(),
            limit,
            offset,
            sink,
        )
        .await?
        {
            sink.finish()?;
            return Ok(Some(ScanPlanMetrics::default()));
        }
        return Ok(None);
    }

    if let Some(shared) = plan_same_source_union_all_scan(query.body.as_ref())? {
        if try_write_same_source_union_all_primitive_to_sink(engine, &shared, batch_size, sink)? {
            sink.finish()?;
            return Ok(Some(ScanPlanMetrics::default()));
        }
        let mut stream = engine
            .scan_parquet_batches(
                shared.path,
                batch_size,
                None,
                shared.projection,
                Some(shared.filter),
            )
            .await?;
        write_same_source_union_all_scan_stream_to_sink(&mut stream, &shared.aliases, sink)?;
        sink.finish()?;
        return Ok(Some(stream.into_scan_plan_metrics()));
    }
    if let Some(shared) = plan_same_source_union_all_filter_scan(query.body.as_ref())? {
        let mut stream = engine
            .scan_parquet_batches(
                shared.path.clone(),
                batch_size,
                None,
                shared.scan_projection.clone(),
                Some(shared.prefilter.clone()),
            )
            .await?;
        write_same_source_union_all_filter_scan_stream_to_sink(&mut stream, &shared, sink)?;
        sink.finish()?;
        return Ok(Some(stream.into_scan_plan_metrics()));
    }

    let mut state = UnionAllSinkState::default();
    Box::pin(write_union_all_set_expr_to_sink(
        engine,
        query.body.as_ref(),
        batch_size,
        sink,
        &mut state,
    ))
    .await?;
    sink.finish()?;
    Ok(Some(ScanPlanMetrics::default()))
}

fn write_same_source_union_all_scan_stream_to_sink(
    stream: &mut SendableBatchStream,
    aliases: &[(String, String)],
    sink: &mut dyn RecordBatchSink,
) -> Result<()> {
    let target_rows = same_source_union_scan_write_coalesce_rows();
    if target_rows == 0 {
        for batch in stream.by_ref() {
            let batch = batch?;
            if aliases.is_empty() {
                sink.write_batch(&batch)?;
            } else {
                for renamed in rename_output_batches(vec![batch], aliases)? {
                    sink.write_batch(&renamed)?;
                }
            }
        }
        return Ok(());
    }
    let mut buffered = Vec::<RecordBatch>::new();
    let mut buffered_rows = 0usize;
    for batch in stream.by_ref() {
        let batch = batch?;
        let batches = if aliases.is_empty() {
            vec![batch]
        } else {
            rename_output_batches(vec![batch], aliases)?
        };
        for batch in batches {
            if batch.num_rows() == 0 {
                continue;
            }
            buffered_rows += batch.num_rows();
            buffered.push(batch);
            if buffered_rows >= target_rows {
                flush_record_batch_buffer(&mut buffered, &mut buffered_rows, sink)?;
            }
        }
    }
    flush_record_batch_buffer(&mut buffered, &mut buffered_rows, sink)?;
    Ok(())
}

fn write_same_source_union_all_filter_scan_stream_to_sink(
    stream: &mut SendableBatchStream,
    shared: &SameSourceUnionAllFilterScan,
    sink: &mut dyn RecordBatchSink,
) -> Result<()> {
    for batch in stream.by_ref() {
        let batch = batch?;
        let mut output = Vec::new();
        append_same_source_union_all_filter_batches(&mut output, &batch, shared)?;
        for batch in output {
            sink.write_batch(&batch)?;
        }
    }
    Ok(())
}

fn append_same_source_union_all_filter_batches(
    output: &mut Vec<RecordBatch>,
    batch: &RecordBatch,
    shared: &SameSourceUnionAllFilterScan,
) -> Result<()> {
    for filter in &shared.filters {
        let filtered = filter_batch(batch.clone(), filter)?;
        if filtered.num_rows() == 0 {
            continue;
        }
        let filtered = apply_output_projection(vec![filtered], &shared.projection)?;
        let filtered = rename_output_batches(filtered, &shared.aliases)?;
        output.extend(filtered);
    }
    Ok(())
}

fn same_source_union_scan_write_coalesce_rows() -> usize {
    std::env::var("DODAM_UNION_SCAN_WRITE_COALESCE_ROWS")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .unwrap_or(0)
}

fn flush_record_batch_buffer(
    buffered: &mut Vec<RecordBatch>,
    buffered_rows: &mut usize,
    sink: &mut dyn RecordBatchSink,
) -> Result<()> {
    if buffered.is_empty() {
        return Ok(());
    }
    let batch = if buffered.len() == 1 {
        buffered.pop().expect("checked non-empty buffer")
    } else {
        let schema = buffered[0].schema();
        concat_batches(&schema, buffered.iter())?
    };
    buffered.clear();
    *buffered_rows = 0;
    sink.write_batch(&batch)?;
    Ok(())
}

fn try_write_same_source_union_all_primitive_to_sink(
    engine: &DodamEngine,
    shared: &SameSourceUnionAllScan,
    batch_size: usize,
    sink: &mut dyn RecordBatchSink,
) -> Result<bool> {
    if !same_source_union_primitive_sink_enabled() {
        return Ok(false);
    }
    let Projection::Columns(output_columns) = &shared.projection else {
        return Ok(false);
    };
    let Expr::InList {
        column: filter_column,
        values,
        negated,
        ..
    } = shared.filter.expr()
    else {
        return Ok(false);
    };
    if *negated {
        return Ok(false);
    }
    let mut scan_projection = shared.projection.clone();
    add_projection_columns(&mut scan_projection, vec![filter_column.clone()]);
    let Projection::Columns(scan_columns) = &scan_projection else {
        return Ok(false);
    };
    let Some(column_types) =
        engine.parquet_direct_primitive_column_types(&shared.path, scan_columns)?
    else {
        return Ok(false);
    };
    if !column_types.iter().all(|column_type| {
        matches!(
            column_type,
            DirectPrimitiveColumnType::I32 | DirectPrimitiveColumnType::I64
        )
    }) {
        return Ok(false);
    }
    let Some(filter_index) = scan_columns
        .iter()
        .position(|column| column == filter_column)
    else {
        return Ok(false);
    };
    let filter_values = match column_types[filter_index] {
        DirectPrimitiveColumnType::I32 => PrimitiveFilterValues::I32(
            values
                .iter()
                .map(|value| value.as_i32(filter_column))
                .collect::<Result<Vec<_>>>()?,
        ),
        DirectPrimitiveColumnType::I64 => PrimitiveFilterValues::I64(
            values
                .iter()
                .map(|value| value.as_i64(filter_column))
                .collect::<Result<Vec<_>>>()?,
        ),
        DirectPrimitiveColumnType::Date32
        | DirectPrimitiveColumnType::Decimal128Int64 { .. }
        | DirectPrimitiveColumnType::Decimal128Int64Raw { .. } => return Ok(false),
    };
    let row_group_count = engine.parquet_row_group_count(&shared.path)?;
    if row_group_count == 0 {
        return Ok(true);
    }
    let specs = scan_columns
        .iter()
        .zip(column_types.iter())
        .map(|(name, column_type)| DirectPrimitiveColumnSpec {
            name,
            column_type: *column_type,
        })
        .collect::<Vec<_>>();
    let chunk_size = same_source_union_primitive_chunk_size(row_group_count);
    let row_groups = (0..row_group_count).collect::<Vec<_>>();
    let profile = ordered_sink_profile_enabled();
    let total_started = profile.then(Instant::now);
    let mut metrics = DirectPrimitiveColumnScanMetrics::default();
    let mut concat_elapsed = Duration::ZERO;
    let mut write_elapsed = Duration::ZERO;
    let mut batches_written = 0usize;
    let mut rows_written = 0usize;
    for chunk in row_groups.chunks(chunk_size) {
        let scan_results = std::thread::scope(|scope| {
            let mut handles = Vec::with_capacity(chunk.len());
            let scan_columns_ref = scan_columns;
            let column_types_ref = &column_types;
            let filter_values_ref = &filter_values;
            for (position, row_group) in chunk.iter().copied().enumerate() {
                let engine = engine.clone();
                let path = shared.path.clone();
                let specs = specs.clone();
                handles.push(scope.spawn(move || {
                    let mut row_group_batches = Vec::new();
                    let metrics = engine.scan_parquet_primitive_columns_view(
                        &path,
                        batch_size,
                        &[row_group],
                        &specs,
                        |view| {
                            if let Some(batch) = primitive_ordered_selected_batch(
                                view,
                                scan_columns_ref,
                                column_types_ref,
                                filter_index,
                                filter_values_ref,
                            )? && batch.num_rows() > 0
                            {
                                row_group_batches.push(batch);
                            }
                            Ok(())
                        },
                    )?;
                    Ok::<_, DodamError>((position, row_group_batches, metrics))
                }));
            }
            let mut results = Vec::with_capacity(handles.len());
            for handle in handles {
                match handle.join() {
                    Ok(result) => results.push(result?),
                    Err(_) => {
                        return Err(DodamError::UnsupportedSql(
                            "same-source union primitive scan worker panicked".to_string(),
                        ));
                    }
                }
            }
            Ok::<_, DodamError>(results)
        })?;
        let mut scan_results = scan_results;
        scan_results.sort_by_key(|(position, _, _)| *position);
        let mut chunk_batches = Vec::new();
        for (_, row_group_batches, row_group_metrics) in scan_results {
            if let Some(row_group_metrics) = row_group_metrics {
                metrics.merge_from(row_group_metrics);
            }
            chunk_batches.extend(row_group_batches);
        }
        if chunk_batches.is_empty() {
            continue;
        }
        let concat_started = profile.then(Instant::now);
        let batch = PrimitiveBatch::concat(chunk_batches)?;
        if let Some(started) = concat_started {
            concat_elapsed += started.elapsed();
        }
        if batch.is_empty() {
            continue;
        }
        rows_written += batch.num_rows();
        let write_started = profile.then(Instant::now);
        write_same_source_primitive_batch_to_sink(batch, &scan_projection, shared, sink)?;
        if let Some(started) = write_started {
            write_elapsed += started.elapsed();
            batches_written += 1;
        }
    }
    print_same_source_union_primitive_sink_profile(
        total_started,
        &metrics,
        concat_elapsed,
        write_elapsed,
        batches_written,
        rows_written,
        output_columns.len(),
    );
    Ok(true)
}

fn same_source_union_primitive_sink_enabled() -> bool {
    if std::env::var("DODAM_DISABLE_UNION_PRIMITIVE_SINK")
        .is_ok_and(|value| matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES"))
    {
        return false;
    }
    std::env::var("DODAM_ENABLE_UNION_PRIMITIVE_SINK")
        .is_ok_and(|value| matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES"))
}

fn same_source_union_primitive_chunk_size(row_group_count: usize) -> usize {
    if let Some(value) = std::env::var("DODAM_UNION_PRIMITIVE_ROW_GROUP_CHUNK_SIZE")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|value| *value > 0)
    {
        return value;
    }
    let workers = std::thread::available_parallelism()
        .map(usize::from)
        .unwrap_or(4)
        .min(row_group_count.max(1));
    workers.min(24).max(1)
}

fn print_same_source_union_primitive_sink_profile(
    total_started: Option<Instant>,
    metrics: &DirectPrimitiveColumnScanMetrics,
    concat_elapsed: Duration,
    write_elapsed: Duration,
    batches: usize,
    rows: usize,
    output_columns: usize,
) {
    let Some(total_started) = total_started else {
        return;
    };
    let column_read = metrics
        .column_read_nanos
        .iter()
        .map(|nanos| format!("{:.3}", (*nanos as f64) / 1_000_000.0))
        .collect::<Vec<_>>()
        .join(",");
    eprintln!(
        "[dodam:same-source-union-primitive-sink-profile] total={}us read={:.3}ms consume={:.3}ms concat={}us write={}us row_groups={} batches={} rows={} output_columns={} column_read_ms=[{}]",
        total_started.elapsed().as_micros(),
        (metrics.read_nanos as f64) / 1_000_000.0,
        (metrics.consume_nanos as f64) / 1_000_000.0,
        concat_elapsed.as_micros(),
        write_elapsed.as_micros(),
        metrics.row_groups,
        batches,
        rows,
        output_columns,
        column_read,
    );
}

async fn try_write_same_source_union_all_ordered_desc_to_sink(
    engine: &DodamEngine,
    expr: &SetExpr,
    batch_size: usize,
    order_by: Option<&SortKey>,
    limit: Option<usize>,
    offset: usize,
    sink: &mut dyn RecordBatchSink,
) -> Result<bool> {
    let (Some(order_by), Some(limit)) = (order_by, limit) else {
        return Ok(false);
    };
    if offset != 0 || limit == 0 {
        return Ok(false);
    }
    let [sort] = order_by.expressions.as_slice() else {
        return Ok(false);
    };
    if !sort.descending || sort.nulls_first {
        return Ok(false);
    }
    let Some(shared) = plan_same_source_union_all_scan(expr)? else {
        return Ok(false);
    };
    let row_groups_monotonic = engine
        .parquet_row_groups_monotonic_by_column(shared.path.clone(), &sort.column)
        .await?;
    let row_group_count = engine.parquet_row_group_count(&shared.path)?;
    if row_group_count == 0 {
        return Ok(true);
    }

    let mut scan_projection = shared.projection.clone();
    add_projection_columns(&mut scan_projection, shared.filter.referenced_columns());
    for sort in &order_by.expressions {
        add_projection_columns(&mut scan_projection, vec![sort.column.clone()]);
    }

    if !row_groups_monotonic {
        return try_write_same_source_union_all_streaming_primitive_topk_to_sink(
            engine,
            &shared,
            batch_size,
            &scan_projection,
            &sort.column,
            limit,
            row_group_count,
            sink,
        );
    }

    if try_write_same_source_union_all_ordered_desc_primitive_to_sink(
        engine,
        &shared,
        batch_size,
        &scan_projection,
        &sort.column,
        limit,
        row_group_count,
        sink,
    )? {
        return Ok(true);
    }

    if try_write_same_source_union_all_ordered_desc_chunked_to_sink(
        engine,
        &shared,
        batch_size,
        &scan_projection,
        order_by,
        limit,
        sink,
        row_group_count,
    )
    .await?
    {
        return Ok(true);
    }

    let row_group_batch_size = row_group_ordered_sort_batch_size(batch_size);
    let mut written = 0usize;
    let profile = ordered_sink_profile_enabled();
    let total_started = profile.then(Instant::now);
    let mut scan_sort_elapsed = Duration::ZERO;
    let mut sink_write_elapsed = Duration::ZERO;
    let mut row_groups_scanned = 0usize;
    let mut batches_written = 0usize;
    for row_group in (0..row_group_count).rev() {
        let scan_sort_started = profile.then(Instant::now);
        let sorted = scan_filter_sort_ordered_row_group(
            engine,
            shared.path.clone(),
            row_group_batch_size,
            scan_projection.clone(),
            row_group,
            &shared.filter,
            order_by,
            &sort.column,
        )
        .await?;
        if let Some(started) = scan_sort_started {
            scan_sort_elapsed += started.elapsed();
            row_groups_scanned += 1;
        }
        for batch in sorted {
            if written >= limit {
                print_ordered_sink_profile(
                    total_started,
                    scan_sort_elapsed,
                    sink_write_elapsed,
                    row_groups_scanned,
                    batches_written,
                    written,
                );
                return Ok(true);
            }
            let remaining = limit - written;
            let batch = if batch.num_rows() > remaining {
                batch.slice(0, remaining)
            } else {
                batch
            };
            written += batch.num_rows();
            let sink_write_started = profile.then(Instant::now);
            write_same_source_batch_to_sink(batch, &scan_projection, &shared, sink)?;
            if let Some(started) = sink_write_started {
                sink_write_elapsed += started.elapsed();
                batches_written += 1;
            }
            if written >= limit {
                print_ordered_sink_profile(
                    total_started,
                    scan_sort_elapsed,
                    sink_write_elapsed,
                    row_groups_scanned,
                    batches_written,
                    written,
                );
                return Ok(true);
            }
        }
    }
    print_ordered_sink_profile(
        total_started,
        scan_sort_elapsed,
        sink_write_elapsed,
        row_groups_scanned,
        batches_written,
        written,
    );
    Ok(true)
}

async fn try_write_same_source_union_all_ordered_desc_chunked_to_sink(
    engine: &DodamEngine,
    shared: &SameSourceUnionAllScan,
    batch_size: usize,
    scan_projection: &Projection,
    order_by: &SortKey,
    limit: usize,
    sink: &mut dyn RecordBatchSink,
    row_group_count: usize,
) -> Result<bool> {
    let chunk_size = ordered_sink_row_group_chunk_size(limit, row_group_count);
    if chunk_size <= 1 {
        return Ok(false);
    }
    let mut written = 0usize;
    let profile = ordered_sink_profile_enabled();
    let total_started = profile.then(Instant::now);
    let mut scan_elapsed = Duration::ZERO;
    let mut filter_elapsed = Duration::ZERO;
    let mut sort_elapsed = Duration::ZERO;
    let mut write_elapsed = Duration::ZERO;
    let mut scan_profile = RowGroupBatchScanProfile::default();
    let mut chunks = 0usize;
    let mut batches_written = 0usize;
    let row_groups = (0..row_group_count).rev().collect::<Vec<_>>();
    for chunk in row_groups.chunks(chunk_size) {
        if written >= limit {
            print_ordered_chunked_sink_profile(
                total_started,
                scan_elapsed,
                filter_elapsed,
                sort_elapsed,
                write_elapsed,
                chunks,
                batches_written,
                written,
                chunk_size,
                &scan_profile,
            );
            return Ok(true);
        }
        chunks += 1;
        let scan_started = profile.then(Instant::now);
        let use_row_filter = ordered_sink_row_filter_enabled();
        let (batches, profile_metrics) = if use_row_filter {
            engine
                .scan_parquet_row_group_batches_filtered_profiled(
                    shared.path.clone(),
                    batch_size,
                    scan_projection.clone(),
                    chunk.to_vec(),
                    vec![shared.filter.expr().clone()],
                )
                .await?
        } else {
            engine
                .scan_parquet_row_group_batches_profiled(
                    shared.path.clone(),
                    batch_size,
                    scan_projection.clone(),
                    chunk.to_vec(),
                )
                .await?
        };
        scan_profile.merge_from(profile_metrics);
        if let Some(started) = scan_started {
            scan_elapsed += started.elapsed();
        }
        let filter_started = profile.then(Instant::now);
        let sort_column = order_by
            .expressions
            .first()
            .map(|sort| sort.column.as_str())
            .unwrap_or_default();
        let filtered = if use_row_filter {
            batches
                .into_iter()
                .filter(|batch| batch.num_rows() > 0)
                .collect::<Vec<_>>()
        } else {
            let mut filtered = Vec::new();
            for batch in batches {
                let batch = filter_batch(batch, &shared.filter)?;
                if batch.num_rows() > 0 {
                    filtered.push(batch);
                }
            }
            filtered
        };
        if let Some(started) = filter_started {
            filter_elapsed += started.elapsed();
        }
        if filtered.is_empty() {
            continue;
        }
        let sort_started = profile.then(Instant::now);
        let sorted = match reverse_ascending_primitive_runs_if_ordered(&filtered, sort_column)? {
            Some(sorted) => sorted,
            None => apply_output_order_limit(filtered, Some(order_by), None, 0)?,
        };
        if let Some(started) = sort_started {
            sort_elapsed += started.elapsed();
        }
        for batch in sorted {
            if written >= limit {
                print_ordered_chunked_sink_profile(
                    total_started,
                    scan_elapsed,
                    filter_elapsed,
                    sort_elapsed,
                    write_elapsed,
                    chunks,
                    batches_written,
                    written,
                    chunk_size,
                    &scan_profile,
                );
                return Ok(true);
            }
            let remaining = limit - written;
            let batch = if batch.num_rows() > remaining {
                batch.slice(0, remaining)
            } else {
                batch
            };
            written += batch.num_rows();
            let write_started = profile.then(Instant::now);
            write_same_source_batch_to_sink(batch, scan_projection, shared, sink)?;
            if let Some(started) = write_started {
                write_elapsed += started.elapsed();
                batches_written += 1;
            }
        }
    }
    print_ordered_chunked_sink_profile(
        total_started,
        scan_elapsed,
        filter_elapsed,
        sort_elapsed,
        write_elapsed,
        chunks,
        batches_written,
        written,
        chunk_size,
        &scan_profile,
    );
    Ok(true)
}

fn reverse_ascending_primitive_runs_if_ordered(
    batches: &[RecordBatch],
    sort_column: &str,
) -> Result<Option<Vec<RecordBatch>>> {
    if sort_column.is_empty() || batches.is_empty() {
        return Ok(None);
    }
    if !batches.iter().all(record_batch_supports_fast_reverse) {
        return Ok(None);
    }
    let mut runs = Vec::<(usize, usize)>::new();
    let mut run_start = 0usize;
    let mut previous_last: Option<i128> = None;
    for (index, batch) in batches.iter().enumerate() {
        if batch.num_rows() == 0 {
            continue;
        }
        let column_index = output_batch_column_index(batch, sort_column)?;
        let Some((first, last)) = numeric_column_ascending_bounds(batch.column(column_index))?
        else {
            return Ok(None);
        };
        if previous_last.is_some_and(|previous| previous > first) {
            if run_start == index {
                return Ok(None);
            }
            runs.push((run_start, index));
            run_start = index;
        }
        previous_last = Some(last);
    }
    if run_start < batches.len() {
        runs.push((run_start, batches.len()));
    }
    if runs.is_empty() {
        return Ok(Some(Vec::new()));
    }
    let mut output = Vec::new();
    for (start, end) in runs {
        for batch in batches[start..end].iter().rev() {
            let Some(reversed) = reverse_primitive_record_batch_rows(batch)? else {
                return Ok(None);
            };
            if reversed.num_rows() > 0 {
                output.push(reversed);
            }
        }
    }
    Ok(Some(output))
}

fn ordered_sink_row_filter_enabled() -> bool {
    std::env::var("DODAM_ORDERED_SINK_ROW_FILTER")
        .is_ok_and(|value| matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES"))
}

fn ordered_sink_row_group_chunk_size(limit: usize, row_group_count: usize) -> usize {
    std::env::var("DODAM_ORDERED_SINK_ROW_GROUP_CHUNK_SIZE")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or_else(|| {
            if limit <= reverse_row_group_topk_max_limit_rows() {
                1
            } else if row_group_count >= 96 {
                8
            } else if row_group_count >= 24 {
                4
            } else if row_group_count >= 8 {
                2
            } else {
                1
            }
        })
}

fn ordered_primitive_parallel_chunk_enabled(chunk_len: usize, limit: usize) -> bool {
    if chunk_len <= 1 || limit <= ordered_primitive_sink_auto_max_limit_rows() {
        return false;
    }
    !std::env::var("DODAM_DISABLE_ORDERED_PRIMITIVE_PARALLEL_CHUNK")
        .is_ok_and(|value| matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES"))
}

fn ordered_primitive_sink_row_group_chunk_size(limit: usize, row_group_count: usize) -> usize {
    if let Some(value) = std::env::var("DODAM_ORDERED_SINK_ROW_GROUP_CHUNK_SIZE")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|value| *value > 0)
    {
        return value;
    }
    choose_ordered_primitive_row_group_chunk(OrderedPrimitiveChunkCostInput {
        limit,
        row_groups: row_group_count,
        available_parallelism: std::thread::available_parallelism()
            .map(usize::from)
            .unwrap_or(4),
        small_limit_rows: ordered_primitive_sink_auto_max_limit_rows(),
        max_workers: 24,
    })
}

#[allow(clippy::too_many_arguments)]
fn print_ordered_chunked_sink_profile(
    total_started: Option<Instant>,
    scan_elapsed: Duration,
    filter_elapsed: Duration,
    sort_elapsed: Duration,
    write_elapsed: Duration,
    chunks: usize,
    batches: usize,
    rows: usize,
    chunk_size: usize,
    scan_profile: &RowGroupBatchScanProfile,
) {
    let Some(total_started) = total_started else {
        return;
    };
    eprintln!(
        "[dodam:ordered-chunked-sink-profile] total={}us scan={}us filter={}us sort={}us write={}us chunks={} chunk_size={} batches={} rows={} metadata={}us planning={}us next={}us next_avg={}us next_p95={}us next_max={}us next_calls={} eof_calls={} scan_batches={} scan_rows={} row_groups={}/{} projected_columns={} bytes={}/{} zero_batches={}",
        total_started.elapsed().as_micros(),
        scan_elapsed.as_micros(),
        filter_elapsed.as_micros(),
        sort_elapsed.as_micros(),
        write_elapsed.as_micros(),
        chunks,
        chunk_size,
        batches,
        rows,
        scan_profile.metadata_nanos / 1_000,
        scan_profile.planning_nanos / 1_000,
        scan_profile.next_nanos / 1_000,
        if scan_profile.next_calls == 0 {
            0
        } else {
            (scan_profile.next_nanos / scan_profile.next_calls as u64) / 1_000
        },
        scan_profile.p95_next_nanos / 1_000,
        scan_profile.max_next_nanos / 1_000,
        scan_profile.next_calls,
        scan_profile.eof_calls,
        scan_profile.output_batches,
        scan_profile.output_rows,
        scan_profile.row_groups_scanned,
        scan_profile.row_groups_total,
        scan_profile.projected_columns,
        scan_profile.compressed_bytes_scanned,
        scan_profile.compressed_bytes_total,
        scan_profile.zero_row_batches,
    );
}

fn try_write_same_source_union_all_ordered_desc_primitive_to_sink(
    engine: &DodamEngine,
    shared: &SameSourceUnionAllScan,
    batch_size: usize,
    scan_projection: &Projection,
    sort_column: &str,
    limit: usize,
    row_group_count: usize,
    sink: &mut dyn RecordBatchSink,
) -> Result<bool> {
    let primitive_sink_enabled = ordered_primitive_sink_enabled(limit);
    let fused_page_decoder_enabled = ordered_primitive_fused_page_decoder_enabled();
    if !primitive_sink_enabled && !fused_page_decoder_enabled {
        return Ok(false);
    }
    let Projection::Columns(columns) = scan_projection else {
        return Ok(false);
    };
    let Expr::InList {
        column: filter_column,
        values,
        negated,
        ..
    } = shared.filter.expr()
    else {
        return Ok(false);
    };
    if *negated || !columns.iter().any(|column| column == sort_column) {
        return Ok(false);
    }
    let Some(column_types) = engine.parquet_direct_primitive_column_types(&shared.path, columns)?
    else {
        return Ok(false);
    };
    if !column_types.iter().all(|column_type| {
        matches!(
            column_type,
            DirectPrimitiveColumnType::I32 | DirectPrimitiveColumnType::I64
        )
    }) {
        return Ok(false);
    }
    let Some(filter_index) = columns.iter().position(|column| column == filter_column) else {
        return Ok(false);
    };
    let filter_values = match column_types[filter_index] {
        DirectPrimitiveColumnType::I32 => PrimitiveFilterValues::I32(
            values
                .iter()
                .map(|value| value.as_i32(filter_column))
                .collect::<Result<Vec<_>>>()?,
        ),
        DirectPrimitiveColumnType::I64 => PrimitiveFilterValues::I64(
            values
                .iter()
                .map(|value| value.as_i64(filter_column))
                .collect::<Result<Vec<_>>>()?,
        ),
        DirectPrimitiveColumnType::Date32
        | DirectPrimitiveColumnType::Decimal128Int64 { .. }
        | DirectPrimitiveColumnType::Decimal128Int64Raw { .. } => return Ok(false),
    };
    let specs = columns
        .iter()
        .zip(column_types.iter())
        .map(|(name, column_type)| DirectPrimitiveColumnSpec {
            name,
            column_type: *column_type,
        })
        .collect::<Vec<_>>();
    let mut written = 0usize;
    let mut primitive_metrics = DirectPrimitiveColumnScanMetrics::default();
    let profile = ordered_sink_profile_enabled();
    let total_started = profile.then(Instant::now);
    let mut write_elapsed = Duration::ZERO;
    let mut concat_elapsed = Duration::ZERO;
    let mut slice_elapsed = Duration::ZERO;
    let mut batches_written = 0usize;
    let row_groups = (0..row_group_count).rev().collect::<Vec<_>>();
    let chunk_size = ordered_primitive_sink_row_group_chunk_size(limit, row_group_count).max(1);
    if fused_page_decoder_enabled {
        let filter_i32_values;
        let filter_i64_values;
        let (filter_i32, filter_i64) = match &filter_values {
            PrimitiveFilterValues::I32(values) => {
                filter_i32_values = values.clone();
                (&filter_i32_values[..], &[][..])
            }
            PrimitiveFilterValues::I64(values) => {
                filter_i64_values = values.clone();
                (&[][..], &filter_i64_values[..])
            }
        };
        let mut fused_batches = Vec::new();
        let mut fused_metrics = DirectPrimitiveColumnScanMetrics::default();
        let mut fused_supported = true;
        for chunk in row_groups.chunks(chunk_size) {
            let mut chunk_batches = Vec::new();
            let metrics = match engine.scan_parquet_required_plain_primitive_in_list_desc(
                &shared.path,
                batch_size,
                chunk,
                &specs,
                filter_index,
                filter_i32,
                filter_i64,
                |batch| {
                    let batch = direct_ordered_primitive_batch_to_primitive_batch(
                        batch,
                        columns,
                        &column_types,
                    )?;
                    if !batch.is_empty() {
                        chunk_batches.push(batch);
                    }
                    Ok(())
                },
            )? {
                Some(metrics) => metrics,
                None => {
                    fused_supported = false;
                    break;
                }
            };
            fused_metrics.merge_from(metrics);
            if chunk_batches.is_empty() {
                continue;
            }
            fused_batches.push(PrimitiveBatch::concat(chunk_batches)?);
        }
        if fused_supported {
            primitive_metrics.merge_from(fused_metrics);
            for batch in fused_batches {
                let remaining = limit - written;
                let batch = if batch.num_rows() > remaining {
                    let slice_started = profile.then(Instant::now);
                    let batch = batch.slice(0, remaining)?;
                    if let Some(started) = slice_started {
                        slice_elapsed += started.elapsed();
                    }
                    batch
                } else {
                    batch
                };
                written += batch.num_rows();
                let write_started = profile.then(Instant::now);
                write_same_source_primitive_batch_to_sink(batch, scan_projection, shared, sink)?;
                if let Some(started) = write_started {
                    write_elapsed += started.elapsed();
                    batches_written += 1;
                }
                if written >= limit {
                    break;
                }
            }
            print_ordered_primitive_sink_profile(
                total_started,
                &primitive_metrics,
                write_elapsed,
                concat_elapsed,
                slice_elapsed,
                batches_written,
                written,
            );
            return Ok(true);
        }
        if !primitive_sink_enabled {
            return Ok(false);
        }
    }
    for chunk in row_groups.chunks(chunk_size) {
        let mut chunk_batches = Vec::new();
        if ordered_primitive_parallel_chunk_enabled(chunk.len(), limit) {
            let page_reader_enabled = ordered_primitive_sink_page_reader_enabled();
            let scan_results = std::thread::scope(|scope| {
                let mut handles = Vec::with_capacity(chunk.len());
                let columns_ref = columns;
                let column_types_ref = &column_types;
                let filter_values_ref = &filter_values;
                for (position, row_group) in chunk.iter().copied().enumerate() {
                    let engine = engine.clone();
                    let path = shared.path.clone();
                    let specs = specs.clone();
                    handles.push(scope.spawn(move || {
                        let mut row_group_batches = Vec::new();
                        let metrics = if page_reader_enabled {
                            engine.scan_parquet_primitive_columns_page_view(
                                &path,
                                batch_size,
                                &[row_group],
                                &specs,
                                |view| {
                                    if let Some(batch) = primitive_ordered_selected_batch(
                                        view,
                                        columns_ref,
                                        column_types_ref,
                                        filter_index,
                                        filter_values_ref,
                                    )? && batch.num_rows() > 0
                                    {
                                        row_group_batches.push(batch);
                                    }
                                    Ok(())
                                },
                            )?
                        } else {
                            engine.scan_parquet_primitive_columns_view(
                                &path,
                                batch_size,
                                &[row_group],
                                &specs,
                                |view| {
                                    if let Some(batch) = primitive_ordered_selected_batch(
                                        view,
                                        columns_ref,
                                        column_types_ref,
                                        filter_index,
                                        filter_values_ref,
                                    )? && batch.num_rows() > 0
                                    {
                                        row_group_batches.push(batch);
                                    }
                                    Ok(())
                                },
                            )?
                        };
                        Ok::<_, DodamError>((position, row_group_batches, metrics))
                    }));
                }
                let mut results = Vec::with_capacity(handles.len());
                for handle in handles {
                    match handle.join() {
                        Ok(result) => results.push(result?),
                        Err(_) => {
                            return Err(DodamError::UnsupportedSql(
                                "ordered primitive scan worker panicked".to_string(),
                            ));
                        }
                    }
                }
                Ok::<_, DodamError>(results)
            })?;
            let mut scan_results = scan_results;
            scan_results.sort_by_key(|(position, _, _)| *position);
            for (_, row_group_batches, metrics) in scan_results {
                if let Some(metrics) = metrics {
                    primitive_metrics.merge_from(metrics);
                }
                chunk_batches.extend(row_group_batches.into_iter().rev());
            }
        } else {
            for &row_group in chunk {
                let mut row_group_batches = Vec::new();
                let metrics = if ordered_primitive_sink_page_reader_enabled() {
                    engine.scan_parquet_primitive_columns_page_view(
                        &shared.path,
                        batch_size,
                        &[row_group],
                        &specs,
                        |view| {
                            if written >= limit {
                                return Ok(());
                            }
                            if let Some(batch) = primitive_ordered_selected_batch(
                                view,
                                columns,
                                &column_types,
                                filter_index,
                                &filter_values,
                            )? && batch.num_rows() > 0
                            {
                                row_group_batches.push(batch);
                            }
                            Ok(())
                        },
                    )?
                } else {
                    engine.scan_parquet_primitive_columns_view(
                        &shared.path,
                        batch_size,
                        &[row_group],
                        &specs,
                        |view| {
                            if written >= limit {
                                return Ok(());
                            }
                            if let Some(batch) = primitive_ordered_selected_batch(
                                view,
                                columns,
                                &column_types,
                                filter_index,
                                &filter_values,
                            )? && batch.num_rows() > 0
                            {
                                row_group_batches.push(batch);
                            }
                            Ok(())
                        },
                    )?
                };
                if let Some(metrics) = metrics {
                    primitive_metrics.merge_from(metrics);
                }
                chunk_batches.extend(row_group_batches.into_iter().rev());
                if written
                    + chunk_batches
                        .iter()
                        .map(PrimitiveBatch::num_rows)
                        .sum::<usize>()
                    >= limit
                {
                    break;
                }
            }
        }
        if chunk_batches.is_empty() {
            continue;
        }
        let concat_started = profile.then(Instant::now);
        let batch = PrimitiveBatch::concat(chunk_batches)?;
        if let Some(started) = concat_started {
            concat_elapsed += started.elapsed();
        }
        if batch.is_empty() {
            continue;
        }
        let remaining = limit - written;
        let batch = if batch.num_rows() > remaining {
            let slice_started = profile.then(Instant::now);
            let batch = batch.slice(0, remaining)?;
            if let Some(started) = slice_started {
                slice_elapsed += started.elapsed();
            }
            batch
        } else {
            batch
        };
        written += batch.num_rows();
        let write_started = profile.then(Instant::now);
        write_same_source_primitive_batch_to_sink(batch, scan_projection, shared, sink)?;
        if let Some(started) = write_started {
            write_elapsed += started.elapsed();
            batches_written += 1;
        }
        if written >= limit {
            print_ordered_primitive_sink_profile(
                total_started,
                &primitive_metrics,
                write_elapsed,
                concat_elapsed,
                slice_elapsed,
                batches_written,
                written,
            );
            return Ok(true);
        }
    }
    print_ordered_primitive_sink_profile(
        total_started,
        &primitive_metrics,
        write_elapsed,
        concat_elapsed,
        slice_elapsed,
        batches_written,
        written,
    );
    Ok(true)
}

enum PrimitiveFilterValues {
    I32(Vec<i32>),
    I64(Vec<i64>),
}

fn direct_ordered_primitive_batch_to_primitive_batch(
    batch: DirectOrderedPrimitiveBatch,
    names: &[String],
    column_types: &[DirectPrimitiveColumnType],
) -> Result<PrimitiveBatch> {
    if batch.columns.len() != names.len() || names.len() != column_types.len() {
        return Err(DodamError::UnsupportedSql(
            "primitive batch schema mismatch".to_string(),
        ));
    }
    let columns = batch
        .columns
        .into_iter()
        .zip(names.iter())
        .zip(column_types.iter())
        .map(|((column, name), column_type)| {
            let values = match (column, column_type) {
                (
                    DirectOrderedPrimitiveColumnValues::I32(values),
                    DirectPrimitiveColumnType::I32,
                ) => PrimitiveColumnValues::I32(values),
                (
                    DirectOrderedPrimitiveColumnValues::I64(values),
                    DirectPrimitiveColumnType::I64,
                ) => PrimitiveColumnValues::I64(values),
                _ => {
                    return Err(DodamError::UnsupportedSql(
                        "primitive batch value type mismatch".to_string(),
                    ));
                }
            };
            Ok(PrimitiveColumn {
                name: name.clone(),
                data_type: primitive_output_data_type(column_type)?,
                nullable: false,
                values,
            })
        })
        .collect::<Result<Vec<_>>>()?;
    Ok(PrimitiveBatch { columns })
}

fn primitive_output_data_type(column_type: &DirectPrimitiveColumnType) -> Result<DataType> {
    match column_type {
        DirectPrimitiveColumnType::I32 => Ok(DataType::Int32),
        DirectPrimitiveColumnType::I64 => Ok(DataType::Int64),
        DirectPrimitiveColumnType::Date32 => Ok(DataType::Date32),
        DirectPrimitiveColumnType::Decimal128Int64 { precision, scale }
        | DirectPrimitiveColumnType::Decimal128Int64Raw { precision, scale } => {
            Ok(DataType::Decimal128(*precision, *scale))
        }
    }
}

fn ordered_primitive_sink_enabled(limit: usize) -> bool {
    if std::env::var("DODAM_ENABLE_ORDERED_PRIMITIVE_SINK")
        .is_ok_and(|value| matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES"))
    {
        return true;
    }
    if std::env::var("DODAM_DISABLE_ORDERED_PRIMITIVE_SINK_AUTO")
        .is_ok_and(|value| matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES"))
    {
        return false;
    }
    choose_ordered_primitive_sink(OrderedPrimitiveSinkCostInput {
        limit,
        small_limit_rows: ordered_primitive_sink_auto_max_limit_rows(),
        large_auto_enabled: ordered_primitive_large_sink_auto_enabled(limit),
    })
}

fn ordered_primitive_sink_auto_max_limit_rows() -> usize {
    std::env::var("DODAM_ORDERED_PRIMITIVE_SINK_AUTO_MAX_LIMIT_ROWS")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(16 * 1024)
}

fn ordered_primitive_large_sink_auto_enabled(limit: usize) -> bool {
    if std::env::var("DODAM_DISABLE_ORDERED_PRIMITIVE_LARGE_SINK_AUTO")
        .is_ok_and(|value| matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES"))
    {
        return false;
    }
    limit > ordered_primitive_sink_auto_max_limit_rows()
}

fn ordered_primitive_fused_page_decoder_enabled() -> bool {
    std::env::var("DODAM_ENABLE_ORDERED_PRIMITIVE_FUSED_PAGE_DECODER")
        .is_ok_and(|value| matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES"))
}

fn ordered_primitive_sink_page_reader_enabled() -> bool {
    std::env::var("DODAM_ENABLE_ORDERED_PRIMITIVE_PAGE_READER")
        .is_ok_and(|value| matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES"))
}

fn print_ordered_primitive_sink_profile(
    total_started: Option<Instant>,
    metrics: &DirectPrimitiveColumnScanMetrics,
    write_elapsed: Duration,
    concat_elapsed: Duration,
    slice_elapsed: Duration,
    batches: usize,
    rows: usize,
) {
    let Some(total_started) = total_started else {
        return;
    };
    let column_read = metrics
        .column_read_nanos
        .iter()
        .map(|nanos| format!("{:.3}", (*nanos as f64) / 1_000_000.0))
        .collect::<Vec<_>>()
        .join(",");
    eprintln!(
        "[dodam:ordered-primitive-sink-profile] total={}us read={:.3}ms consume={:.3}ms concat={}us slice={}us write={}us row_groups={} batches={} rows={} column_read_ms=[{}]",
        total_started.elapsed().as_micros(),
        (metrics.read_nanos as f64) / 1_000_000.0,
        (metrics.consume_nanos as f64) / 1_000_000.0,
        concat_elapsed.as_micros(),
        slice_elapsed.as_micros(),
        write_elapsed.as_micros(),
        metrics.row_groups,
        batches,
        rows,
        column_read,
    );
}

fn primitive_ordered_selected_batch(
    view: BatchView<'_>,
    column_names: &[String],
    column_types: &[DirectPrimitiveColumnType],
    filter_index: usize,
    filter_values: &PrimitiveFilterValues,
) -> Result<Option<PrimitiveBatch>> {
    if let Some(batch) = primitive_ordered_selected_batch_null_free_fast(
        view,
        column_names,
        column_types,
        filter_index,
        filter_values,
    )? {
        return Ok(Some(batch));
    }
    if !row_at_time_fallback_enabled() {
        return Ok(None);
    }
    let mut selected = Vec::new();
    match filter_values {
        PrimitiveFilterValues::I32(values) => {
            if !matches!(column_types[filter_index], DirectPrimitiveColumnType::I32) {
                return Ok(None);
            }
            let Some(column) = view.i32_vector(filter_index) else {
                return Ok(None);
            };
            for row in (0..view.num_rows()).rev() {
                if !column.is_null(row) && values.iter().any(|value| *value == column.value(row)) {
                    selected.push(row as u32);
                }
            }
        }
        PrimitiveFilterValues::I64(values) => {
            if !matches!(column_types[filter_index], DirectPrimitiveColumnType::I64) {
                return Ok(None);
            }
            let Some(column) = view.i64_vector(filter_index) else {
                return Ok(None);
            };
            for row in (0..view.num_rows()).rev() {
                if !column.is_null(row) && values.iter().any(|value| *value == column.value(row)) {
                    selected.push(row as u32);
                }
            }
        }
    }
    if selected.is_empty() {
        return primitive_empty_batch(column_names, column_types).map(Some);
    }
    let mut columns = Vec::with_capacity(column_types.len());
    for (index, column_type) in column_types.iter().enumerate() {
        match column_type {
            DirectPrimitiveColumnType::I32 => {
                let Some(column) = view.i32_vector(index) else {
                    return Ok(None);
                };
                let mut output = Vec::with_capacity(selected.len());
                for row in &selected {
                    let row = *row as usize;
                    if column.is_null(row) {
                        return Ok(None);
                    }
                    output.push(column.value(row));
                }
                columns.push(PrimitiveColumn {
                    name: column_names[index].clone(),
                    data_type: primitive_output_data_type(column_type)?,
                    nullable: false,
                    values: PrimitiveColumnValues::I32(output),
                });
            }
            DirectPrimitiveColumnType::I64 => {
                let Some(column) = view.i64_vector(index) else {
                    return Ok(None);
                };
                let mut output = Vec::with_capacity(selected.len());
                for row in &selected {
                    let row = *row as usize;
                    if column.is_null(row) {
                        return Ok(None);
                    }
                    output.push(column.value(row));
                }
                columns.push(PrimitiveColumn {
                    name: column_names[index].clone(),
                    data_type: primitive_output_data_type(column_type)?,
                    nullable: false,
                    values: PrimitiveColumnValues::I64(output),
                });
            }
            DirectPrimitiveColumnType::Date32
            | DirectPrimitiveColumnType::Decimal128Int64 { .. }
            | DirectPrimitiveColumnType::Decimal128Int64Raw { .. } => return Ok(None),
        }
    }
    Ok(Some(PrimitiveBatch { columns }))
}

#[derive(Clone, Copy)]
enum NullFreePrimitiveColumn<'a> {
    I32(&'a [i32]),
    I64(&'a [i64]),
}

enum PrimitiveColumnOutput {
    I32(Vec<i32>),
    I64(Vec<i64>),
}

fn primitive_topk_filter_positions_into(
    column: NullFreePrimitiveColumn<'_>,
    filter_values: &PrimitiveFilterValues,
    selected: &mut Vec<usize>,
) {
    selected.clear();
    match (column, filter_values) {
        (NullFreePrimitiveColumn::I32(values), PrimitiveFilterValues::I32(filter_values)) => {
            reserve_selected_positions(selected, values.len());
            primitive_topk_filter_i32_positions(values, filter_values, selected);
        }
        (NullFreePrimitiveColumn::I64(values), PrimitiveFilterValues::I64(filter_values)) => {
            reserve_selected_positions(selected, values.len());
            primitive_topk_filter_i64_positions(values, filter_values, selected);
        }
        _ => {}
    }
}

fn primitive_topk_filter_positions_with_min_key_into(
    filter_column: NullFreePrimitiveColumn<'_>,
    filter_values: &PrimitiveFilterValues,
    sort_column: NullFreePrimitiveColumn<'_>,
    min_key: i128,
    selected: &mut Vec<usize>,
) {
    selected.clear();
    match (filter_column, filter_values, sort_column) {
        (
            NullFreePrimitiveColumn::I32(filter_values_slice),
            PrimitiveFilterValues::I32(filter_values),
            NullFreePrimitiveColumn::I32(sort_values),
        ) => {
            let min_key = match i32::try_from(min_key) {
                Ok(min_key) => min_key,
                Err(_) if min_key < i128::from(i32::MIN) => {
                    primitive_topk_filter_i32_positions(
                        filter_values_slice,
                        filter_values,
                        selected,
                    );
                    return;
                }
                Err(_) => {
                    selected.clear();
                    return;
                }
            };
            reserve_selected_positions(selected, filter_values_slice.len());
            primitive_topk_filter_i32_positions_with_i32_min_key(
                filter_values_slice,
                filter_values,
                sort_values,
                min_key,
                selected,
            );
        }
        (
            NullFreePrimitiveColumn::I32(filter_values_slice),
            PrimitiveFilterValues::I32(filter_values),
            NullFreePrimitiveColumn::I64(sort_values),
        ) => {
            let min_key = match i64::try_from(min_key) {
                Ok(min_key) => min_key,
                Err(_) if min_key < i128::from(i64::MIN) => {
                    primitive_topk_filter_i32_positions(
                        filter_values_slice,
                        filter_values,
                        selected,
                    );
                    return;
                }
                Err(_) => {
                    selected.clear();
                    return;
                }
            };
            reserve_selected_positions(selected, filter_values_slice.len());
            primitive_topk_filter_i32_positions_with_i64_min_key(
                filter_values_slice,
                filter_values,
                sort_values,
                min_key,
                selected,
            );
        }
        (
            NullFreePrimitiveColumn::I64(filter_values_slice),
            PrimitiveFilterValues::I64(filter_values),
            NullFreePrimitiveColumn::I64(sort_values),
        ) => {
            let min_key = match i64::try_from(min_key) {
                Ok(min_key) => min_key,
                Err(_) if min_key < i128::from(i64::MIN) => {
                    primitive_topk_filter_i64_positions(
                        filter_values_slice,
                        filter_values,
                        selected,
                    );
                    return;
                }
                Err(_) => {
                    selected.clear();
                    return;
                }
            };
            reserve_selected_positions(selected, filter_values_slice.len());
            primitive_topk_filter_i64_positions_with_i64_min_key(
                filter_values_slice,
                filter_values,
                sort_values,
                min_key,
                selected,
            );
        }
        (
            NullFreePrimitiveColumn::I64(filter_values_slice),
            PrimitiveFilterValues::I64(filter_values),
            NullFreePrimitiveColumn::I32(sort_values),
        ) => {
            let min_key = match i32::try_from(min_key) {
                Ok(min_key) => min_key,
                Err(_) if min_key < i128::from(i32::MIN) => {
                    primitive_topk_filter_i64_positions(
                        filter_values_slice,
                        filter_values,
                        selected,
                    );
                    return;
                }
                Err(_) => {
                    selected.clear();
                    return;
                }
            };
            reserve_selected_positions(selected, filter_values_slice.len());
            primitive_topk_filter_i64_positions_with_i32_min_key(
                filter_values_slice,
                filter_values,
                sort_values,
                min_key,
                selected,
            );
        }
        _ => primitive_topk_filter_positions_into(filter_column, filter_values, selected),
    }
}

fn primitive_topk_filter_i32_positions(
    values: &[i32],
    filter_values: &[i32],
    selected: &mut Vec<usize>,
) {
    match filter_values {
        [] => {}
        [a] => push_i32_eq_positions(values, *a, selected),
        [a, b] => push_i32_eq2_positions(values, *a, *b, selected),
        [a, b, c] => push_i32_eq3_positions(values, *a, *b, *c, selected),
        [a, b, c, d] => push_i32_eq4_positions(values, *a, *b, *c, *d, selected),
        _ => {
            for (row, value) in values.iter().copied().enumerate() {
                if filter_values.contains(&value) {
                    selected.push(row);
                }
            }
        }
    }
}

fn primitive_topk_filter_i64_positions(
    values: &[i64],
    filter_values: &[i64],
    selected: &mut Vec<usize>,
) {
    match filter_values {
        [] => {}
        [a] => push_i64_eq_positions(values, *a, selected),
        [a, b] => push_i64_eq2_positions(values, *a, *b, selected),
        [a, b, c] => push_i64_eq3_positions(values, *a, *b, *c, selected),
        [a, b, c, d] => push_i64_eq4_positions(values, *a, *b, *c, *d, selected),
        _ => {
            for (row, value) in values.iter().copied().enumerate() {
                if filter_values.contains(&value) {
                    selected.push(row);
                }
            }
        }
    }
}

fn primitive_topk_filter_i32_positions_with_i32_min_key(
    values: &[i32],
    filter_values: &[i32],
    sort_values: &[i32],
    min_key: i32,
    selected: &mut Vec<usize>,
) {
    push_primitive_position_pairs_unrolled_with_offset(
        values,
        sort_values,
        0,
        selected,
        |value, key| key >= min_key && small_i32_filter_values_contains(filter_values, value),
    );
}

fn primitive_topk_filter_i32_positions_with_i64_min_key(
    values: &[i32],
    filter_values: &[i32],
    sort_values: &[i64],
    min_key: i64,
    selected: &mut Vec<usize>,
) {
    if let [a, b] = filter_values {
        if primitive_topk_block_max_skip_enabled() {
            push_i32_eq2_positions_with_i64_min_key_blocked(
                values,
                *a,
                *b,
                sort_values,
                min_key,
                selected,
            );
        } else {
            push_primitive_position_pairs_unrolled_with_offset(
                values,
                sort_values,
                0,
                selected,
                |value, key| key >= min_key && (value == *a || value == *b),
            );
        }
    } else {
        push_primitive_position_pairs_unrolled_with_offset(
            values,
            sort_values,
            0,
            selected,
            |value, key| key >= min_key && small_i32_filter_values_contains(filter_values, value),
        );
    }
}

fn primitive_topk_filter_i64_positions_with_i64_min_key(
    values: &[i64],
    filter_values: &[i64],
    sort_values: &[i64],
    min_key: i64,
    selected: &mut Vec<usize>,
) {
    push_primitive_position_pairs_unrolled_with_offset(
        values,
        sort_values,
        0,
        selected,
        |value, key| key >= min_key && small_i64_filter_values_contains(filter_values, value),
    );
}

fn primitive_topk_filter_i64_positions_with_i32_min_key(
    values: &[i64],
    filter_values: &[i64],
    sort_values: &[i32],
    min_key: i32,
    selected: &mut Vec<usize>,
) {
    push_primitive_position_pairs_unrolled_with_offset(
        values,
        sort_values,
        0,
        selected,
        |value, key| key >= min_key && small_i64_filter_values_contains(filter_values, value),
    );
}

fn push_i32_eq2_positions_with_i64_min_key_blocked(
    values: &[i32],
    a: i32,
    b: i32,
    keys: &[i64],
    min_key: i64,
    selected: &mut Vec<usize>,
) {
    let len = values.len().min(keys.len());
    let mut row = 0usize;
    const BLOCK: usize = 64;
    while row + BLOCK <= len {
        let block_keys = &keys[row..row + BLOCK];
        let mut max_key = block_keys[0];
        for key in block_keys.iter().copied().skip(1) {
            if key > max_key {
                max_key = key;
            }
        }
        if max_key >= min_key {
            push_primitive_position_pairs_unrolled_with_offset(
                &values[row..row + BLOCK],
                block_keys,
                row,
                selected,
                |value, key| key >= min_key && (value == a || value == b),
            );
        }
        row += BLOCK;
    }
    while row < len {
        let value = values[row];
        if keys[row] >= min_key && (value == a || value == b) {
            selected.push(row);
        }
        row += 1;
    }
}

fn small_i32_filter_values_contains(values: &[i32], value: i32) -> bool {
    match values {
        [] => false,
        [a] => value == *a,
        [a, b] => value == *a || value == *b,
        [a, b, c] => value == *a || value == *b || value == *c,
        [a, b, c, d] => value == *a || value == *b || value == *c || value == *d,
        _ => values.contains(&value),
    }
}

fn small_i64_filter_values_contains(values: &[i64], value: i64) -> bool {
    match values {
        [] => false,
        [a] => value == *a,
        [a, b] => value == *a || value == *b,
        [a, b, c] => value == *a || value == *b || value == *c,
        [a, b, c, d] => value == *a || value == *b || value == *c || value == *d,
        _ => values.contains(&value),
    }
}

fn push_i32_eq_positions(values: &[i32], a: i32, selected: &mut Vec<usize>) {
    push_primitive_positions_unrolled(values, selected, |value| value == a);
}

fn push_i32_eq2_positions(values: &[i32], a: i32, b: i32, selected: &mut Vec<usize>) {
    push_primitive_positions_unrolled(values, selected, |value| value == a || value == b);
}

fn push_i32_eq3_positions(values: &[i32], a: i32, b: i32, c: i32, selected: &mut Vec<usize>) {
    push_primitive_positions_unrolled(values, selected, |value| {
        value == a || value == b || value == c
    });
}

fn push_i32_eq4_positions(
    values: &[i32],
    a: i32,
    b: i32,
    c: i32,
    d: i32,
    selected: &mut Vec<usize>,
) {
    push_primitive_positions_unrolled(values, selected, |value| {
        value == a || value == b || value == c || value == d
    });
}

fn push_i64_eq_positions(values: &[i64], a: i64, selected: &mut Vec<usize>) {
    push_primitive_positions_unrolled(values, selected, |value| value == a);
}

fn push_i64_eq2_positions(values: &[i64], a: i64, b: i64, selected: &mut Vec<usize>) {
    push_primitive_positions_unrolled(values, selected, |value| value == a || value == b);
}

fn push_i64_eq3_positions(values: &[i64], a: i64, b: i64, c: i64, selected: &mut Vec<usize>) {
    push_primitive_positions_unrolled(values, selected, |value| {
        value == a || value == b || value == c
    });
}

fn push_i64_eq4_positions(
    values: &[i64],
    a: i64,
    b: i64,
    c: i64,
    d: i64,
    selected: &mut Vec<usize>,
) {
    push_primitive_positions_unrolled(values, selected, |value| {
        value == a || value == b || value == c || value == d
    });
}

fn push_primitive_positions_unrolled<T, F>(values: &[T], selected: &mut Vec<usize>, mut matches: F)
where
    T: Copy,
    F: FnMut(T) -> bool,
{
    let mut row = 0usize;
    let chunks = values.len() / 8 * 8;
    while row < chunks {
        let v0 = values[row];
        let v1 = values[row + 1];
        let v2 = values[row + 2];
        let v3 = values[row + 3];
        let v4 = values[row + 4];
        let v5 = values[row + 5];
        let v6 = values[row + 6];
        let v7 = values[row + 7];
        if matches(v0) {
            selected.push(row);
        }
        if matches(v1) {
            selected.push(row + 1);
        }
        if matches(v2) {
            selected.push(row + 2);
        }
        if matches(v3) {
            selected.push(row + 3);
        }
        if matches(v4) {
            selected.push(row + 4);
        }
        if matches(v5) {
            selected.push(row + 5);
        }
        if matches(v6) {
            selected.push(row + 6);
        }
        if matches(v7) {
            selected.push(row + 7);
        }
        row += 8;
    }
    while row < values.len() {
        if matches(values[row]) {
            selected.push(row);
        }
        row += 1;
    }
}

fn push_primitive_position_pairs_unrolled_with_offset<T, U, F>(
    values: &[T],
    keys: &[U],
    offset: usize,
    selected: &mut Vec<usize>,
    mut matches: F,
) where
    T: Copy,
    U: Copy,
    F: FnMut(T, U) -> bool,
{
    let len = values.len().min(keys.len());
    let mut row = 0usize;
    let chunks = len / 8 * 8;
    while row < chunks {
        let v0 = values[row];
        let v1 = values[row + 1];
        let v2 = values[row + 2];
        let v3 = values[row + 3];
        let v4 = values[row + 4];
        let v5 = values[row + 5];
        let v6 = values[row + 6];
        let v7 = values[row + 7];
        let k0 = keys[row];
        let k1 = keys[row + 1];
        let k2 = keys[row + 2];
        let k3 = keys[row + 3];
        let k4 = keys[row + 4];
        let k5 = keys[row + 5];
        let k6 = keys[row + 6];
        let k7 = keys[row + 7];
        if matches(v0, k0) {
            selected.push(offset + row);
        }
        if matches(v1, k1) {
            selected.push(offset + row + 1);
        }
        if matches(v2, k2) {
            selected.push(offset + row + 2);
        }
        if matches(v3, k3) {
            selected.push(offset + row + 3);
        }
        if matches(v4, k4) {
            selected.push(offset + row + 4);
        }
        if matches(v5, k5) {
            selected.push(offset + row + 5);
        }
        if matches(v6, k6) {
            selected.push(offset + row + 6);
        }
        if matches(v7, k7) {
            selected.push(offset + row + 7);
        }
        row += 8;
    }
    while row < len {
        if matches(values[row], keys[row]) {
            selected.push(offset + row);
        }
        row += 1;
    }
}

fn primitive_filter_i32_positions_desc(
    values: &[i32],
    filter_values: &[i32],
    selected: &mut Vec<usize>,
) {
    match filter_values {
        [] => {}
        [a] => push_i32_eq_positions_desc(values, *a, selected),
        [a, b] => push_i32_eq2_positions_desc(values, *a, *b, selected),
        [a, b, c] => push_primitive_positions_desc_unrolled(values, selected, |value| {
            value == *a || value == *b || value == *c
        }),
        [a, b, c, d] => push_primitive_positions_desc_unrolled(values, selected, |value| {
            value == *a || value == *b || value == *c || value == *d
        }),
        _ => {
            let mut row = values.len();
            while row > 0 {
                row -= 1;
                if filter_values.contains(&values[row]) {
                    selected.push(row);
                }
            }
        }
    }
}

fn primitive_filter_i64_positions_desc(
    values: &[i64],
    filter_values: &[i64],
    selected: &mut Vec<usize>,
) {
    match filter_values {
        [] => {}
        [a] => push_i64_eq_positions_desc(values, *a, selected),
        [a, b] => push_i64_eq2_positions_desc(values, *a, *b, selected),
        [a, b, c] => push_primitive_positions_desc_unrolled(values, selected, |value| {
            value == *a || value == *b || value == *c
        }),
        [a, b, c, d] => push_primitive_positions_desc_unrolled(values, selected, |value| {
            value == *a || value == *b || value == *c || value == *d
        }),
        _ => {
            let mut row = values.len();
            while row > 0 {
                row -= 1;
                if filter_values.contains(&values[row]) {
                    selected.push(row);
                }
            }
        }
    }
}

