fn rewrite_scalar_predicate_table_alias(
    expr: &SqlExpr,
    table_alias: Option<&str>,
) -> Result<SqlExpr> {
    match expr {
        SqlExpr::Identifier(_) | SqlExpr::CompoundIdentifier(_) => {
            Ok(sql_column_expr(&sql_column_name(expr, table_alias)?))
        }
        SqlExpr::BinaryOp { left, op, right } => Ok(SqlExpr::BinaryOp {
            left: Box::new(rewrite_scalar_predicate_table_alias(left, table_alias)?),
            op: op.clone(),
            right: Box::new(rewrite_scalar_predicate_table_alias(right, table_alias)?),
        }),
        SqlExpr::Nested(expr) => Ok(SqlExpr::Nested(Box::new(
            rewrite_scalar_predicate_table_alias(expr, table_alias)?,
        ))),
        SqlExpr::UnaryOp { op, expr } => Ok(SqlExpr::UnaryOp {
            op: op.clone(),
            expr: Box::new(rewrite_scalar_predicate_table_alias(expr, table_alias)?),
        }),
        SqlExpr::IsNull(expr) => Ok(SqlExpr::IsNull(Box::new(
            rewrite_scalar_predicate_table_alias(expr, table_alias)?,
        ))),
        SqlExpr::IsNotNull(expr) => Ok(SqlExpr::IsNotNull(Box::new(
            rewrite_scalar_predicate_table_alias(expr, table_alias)?,
        ))),
        SqlExpr::InList {
            expr,
            list,
            negated,
        } => Ok(SqlExpr::InList {
            expr: Box::new(rewrite_scalar_predicate_table_alias(expr, table_alias)?),
            list: list
                .iter()
                .map(|expr| rewrite_scalar_predicate_table_alias(expr, table_alias))
                .collect::<Result<Vec<_>>>()?,
            negated: *negated,
        }),
        SqlExpr::Between {
            expr,
            negated,
            low,
            high,
        } => Ok(SqlExpr::Between {
            expr: Box::new(rewrite_scalar_predicate_table_alias(expr, table_alias)?),
            negated: *negated,
            low: Box::new(rewrite_scalar_predicate_table_alias(low, table_alias)?),
            high: Box::new(rewrite_scalar_predicate_table_alias(high, table_alias)?),
        }),
        SqlExpr::Like {
            negated,
            any,
            expr,
            pattern,
            escape_char,
        } => Ok(SqlExpr::Like {
            negated: *negated,
            any: *any,
            expr: Box::new(rewrite_scalar_predicate_table_alias(expr, table_alias)?),
            pattern: Box::new(rewrite_scalar_predicate_table_alias(pattern, table_alias)?),
            escape_char: escape_char.clone(),
        }),
        SqlExpr::ILike {
            negated,
            any,
            expr,
            pattern,
            escape_char,
        } => Ok(SqlExpr::ILike {
            negated: *negated,
            any: *any,
            expr: Box::new(rewrite_scalar_predicate_table_alias(expr, table_alias)?),
            pattern: Box::new(rewrite_scalar_predicate_table_alias(pattern, table_alias)?),
            escape_char: escape_char.clone(),
        }),
        SqlExpr::Value(_) | SqlExpr::TypedString(_) => Ok(expr.clone()),
        _ => Ok(expr.clone()),
    }
}

fn parse_group_by(select: &Select, table_alias: Option<&str>) -> Result<Vec<String>> {
    match &select.group_by {
        GroupByExpr::Expressions(expressions, modifiers) if modifiers.is_empty() => {
            let expressions = resolve_group_by_projection_references(expressions, select)?;
            expressions
                .iter()
                .enumerate()
                .map(|(index, expr)| {
                    sql_column_name(expr, table_alias).or_else(|_| {
                        parse_scalar_sql_expression(expr, table_alias)
                            .map(|_| group_by_synthetic_column(index))
                    })
                })
                .collect::<Result<Vec<_>>>()
        }
        GroupByExpr::Expressions(_, _) | GroupByExpr::All(_) => Err(DodamError::UnsupportedSql(
            "GROUP BY modifiers and GROUP BY ALL are not supported".to_string(),
        )),
    }
}

fn add_column_once(columns: &mut Vec<String>, column: String) {
    if !columns.iter().any(|existing| existing == &column) {
        columns.push(column);
    }
}

fn projection_ordinal_targets(
    columns: &[String],
    aggregates: &[AggregateExpr],
    expressions: &[ProjectionExpression],
) -> Vec<String> {
    if !aggregates.is_empty() {
        columns
            .iter()
            .cloned()
            .chain(aggregates.iter().map(ToString::to_string))
            .collect::<Vec<_>>()
    } else if !expressions.is_empty() {
        expressions
            .iter()
            .map(|expression| expression.output_name.clone())
            .collect::<Vec<_>>()
    } else {
        columns.to_vec()
    }
}

fn parse_order_by(
    query: &Query,
    aliases: &[(String, String)],
    ordinal_targets: &[String],
    table_alias: Option<&str>,
) -> Result<Option<SortKey>> {
    let Some(order_by) = &query.order_by else {
        return Ok(None);
    };
    if order_by.interpolate.is_some() {
        return Err(DodamError::UnsupportedSql(
            "ORDER BY INTERPOLATE is not supported".to_string(),
        ));
    }
    let OrderByKind::Expressions(expressions) = &order_by.kind else {
        return Err(DodamError::UnsupportedSql(
            "ORDER BY ALL is not supported".to_string(),
        ));
    };
    let expressions = expressions
        .iter()
        .map(|order| {
            if order.with_fill.is_some() {
                return Err(DodamError::UnsupportedSql(
                    "ORDER BY WITH FILL is not supported".to_string(),
                ));
            }
            Ok(SortExpr {
                column: parse_order_expr(&order.expr, aliases, ordinal_targets, table_alias)?,
                descending: order.options.asc == Some(false),
                nulls_first: order.options.nulls_first.unwrap_or(false),
            })
        })
        .collect::<Result<Vec<_>>>()?;
    SortKey::new(expressions).map(Some)
}

fn parse_order_expr(
    expr: &SqlExpr,
    aliases: &[(String, String)],
    ordinal_targets: &[String],
    table_alias: Option<&str>,
) -> Result<String> {
    let column = match expr {
        SqlExpr::Value(value) => resolve_order_by_ordinal(value, ordinal_targets)?,
        SqlExpr::Identifier(_) | SqlExpr::CompoundIdentifier(_) => {
            sql_column_name(expr, table_alias)?
        }
        SqlExpr::Function(function) => parse_aggregate(function, table_alias)?.to_string(),
        _ => {
            return Err(DodamError::UnsupportedSql(format!(
                "expected ORDER BY column or aggregate expression, got {expr}"
            )));
        }
    };
    Ok(resolve_alias(&column, aliases))
}

fn resolve_alias(name: &str, aliases: &[(String, String)]) -> String {
    alias_target(name, aliases)
        .cloned()
        .unwrap_or_else(|| name.to_string())
}

fn resolve_order_by_ordinal(
    value: &sqlparser::ast::ValueWithSpan,
    ordinal_targets: &[String],
) -> Result<String> {
    let Value::Number(number, _) = &value.value else {
        return Err(DodamError::UnsupportedSql(format!(
            "expected ORDER BY column, ordinal, or aggregate expression, got {}",
            value.value
        )));
    };
    let ordinal = number
        .parse::<usize>()
        .map_err(|_| DodamError::UnsupportedSql(format!("invalid ORDER BY ordinal: {number}")))?;
    if ordinal == 0 {
        return Err(DodamError::UnsupportedSql(
            "ORDER BY ordinal must be greater than zero".to_string(),
        ));
    }
    ordinal_targets.get(ordinal - 1).cloned().ok_or_else(|| {
        DodamError::UnsupportedSql(format!("ORDER BY position {ordinal} is out of range"))
    })
}

fn alias_target<'a>(name: &str, aliases: &'a [(String, String)]) -> Option<&'a String> {
    aliases
        .iter()
        .find(|(alias, _)| alias == name)
        .map(|(_, target)| target)
}

fn parse_limit(query: &Query) -> Result<Option<usize>> {
    let Some(limit_clause) = &query.limit_clause else {
        return Ok(None);
    };
    match limit_clause {
        LimitClause::LimitOffset {
            limit: Some(limit),
            offset: _,
            limit_by,
        } if limit_by.is_empty() => parse_usize_literal(limit).map(Some),
        LimitClause::LimitOffset {
            limit: None,
            offset: _,
            limit_by,
        } if limit_by.is_empty() => Ok(None),
        _ => Err(DodamError::UnsupportedSql(
            "only LIMIT <integer> with optional OFFSET is supported".to_string(),
        )),
    }
}

fn parse_offset(query: &Query) -> Result<usize> {
    let Some(limit_clause) = &query.limit_clause else {
        return Ok(0);
    };
    match limit_clause {
        LimitClause::LimitOffset {
            offset: Some(offset),
            limit_by,
            ..
        } if limit_by.is_empty() => parse_usize_literal(&offset.value),
        LimitClause::LimitOffset {
            offset: None,
            limit_by,
            ..
        } if limit_by.is_empty() => Ok(0),
        _ => Err(DodamError::UnsupportedSql(
            "only LIMIT/OFFSET without LIMIT BY is supported".to_string(),
        )),
    }
}

fn scan_limit_with_offset(limit: Option<usize>, offset: usize) -> Result<Option<usize>> {
    limit
        .map(|limit| {
            limit
                .checked_add(offset)
                .ok_or_else(|| DodamError::UnsupportedSql("LIMIT + OFFSET overflow".to_string()))
        })
        .transpose()
}

fn parse_filter(
    expr: &SqlExpr,
    aliases: &[(String, String)],
    table_alias: Option<&str>,
    allow_aggregates: bool,
) -> Result<FilterExpr> {
    Ok(FilterExpr::new(sql_expr_to_filter_expr(
        expr,
        aliases,
        table_alias,
        allow_aggregates,
    )?))
}

fn sql_expr_to_filter_expr(
    expr: &SqlExpr,
    aliases: &[(String, String)],
    table_alias: Option<&str>,
    allow_aggregates: bool,
) -> Result<Expr> {
    match expr {
        SqlExpr::BinaryOp { left, op, right } => match op {
            BinaryOperator::And => Ok(Expr::And(
                Box::new(sql_expr_to_filter_expr(
                    left,
                    aliases,
                    table_alias,
                    allow_aggregates,
                )?),
                Box::new(sql_expr_to_filter_expr(
                    right,
                    aliases,
                    table_alias,
                    allow_aggregates,
                )?),
            )),
            BinaryOperator::Or => Ok(Expr::Or(
                Box::new(sql_expr_to_filter_expr(
                    left,
                    aliases,
                    table_alias,
                    allow_aggregates,
                )?),
                Box::new(sql_expr_to_filter_expr(
                    right,
                    aliases,
                    table_alias,
                    allow_aggregates,
                )?),
            )),
            BinaryOperator::Eq
            | BinaryOperator::NotEq
            | BinaryOperator::Gt
            | BinaryOperator::GtEq
            | BinaryOperator::Lt
            | BinaryOperator::LtEq => {
                if let (Ok(left), Ok(right)) = (sql_literal_value(left), sql_literal_value(right)) {
                    return Ok(Expr::Boolean(compare_literal_values(&left, op, &right)?));
                }
                let left = sql_filter_column(left, aliases, table_alias, allow_aggregates)?;
                let op = sql_comparison_op(op);
                if let Some(right) =
                    maybe_sql_filter_column(right, aliases, table_alias, allow_aggregates)?
                {
                    Ok(Expr::ColumnComparison { left, op, right })
                } else {
                    Ok(Expr::Comparison(ComparisonExpr {
                        column: left,
                        op,
                        value: sql_literal_value(right)?,
                    }))
                }
            }
            _ => Err(DodamError::UnsupportedSql(format!(
                "unsupported WHERE operator: {op}"
            ))),
        },
        SqlExpr::Nested(expr) => {
            sql_expr_to_filter_expr(expr, aliases, table_alias, allow_aggregates)
        }
        SqlExpr::Value(value) => match &value.value {
            Value::Boolean(value) => Ok(Expr::Boolean(Some(*value))),
            Value::Null => Ok(Expr::Boolean(None)),
            _ => Err(DodamError::UnsupportedSql(format!(
                "unsupported WHERE expression: {expr}"
            ))),
        },
        SqlExpr::Between {
            expr,
            negated,
            low,
            high,
        } => {
            let column = sql_filter_column(expr, aliases, table_alias, allow_aggregates)?;
            let low = sql_literal_value(low)?;
            let high = sql_literal_value(high)?;
            if *negated {
                Ok(Expr::Or(
                    Box::new(Expr::Comparison(ComparisonExpr {
                        column: column.clone(),
                        op: ComparisonOp::Lt,
                        value: low,
                    })),
                    Box::new(Expr::Comparison(ComparisonExpr {
                        column,
                        op: ComparisonOp::Gt,
                        value: high,
                    })),
                ))
            } else {
                Ok(Expr::And(
                    Box::new(Expr::Comparison(ComparisonExpr {
                        column: column.clone(),
                        op: ComparisonOp::GtEq,
                        value: low,
                    })),
                    Box::new(Expr::Comparison(ComparisonExpr {
                        column,
                        op: ComparisonOp::LtEq,
                        value: high,
                    })),
                ))
            }
        }
        SqlExpr::UnaryOp { op, expr } if *op == UnaryOperator::Not => Ok(Expr::Not(Box::new(
            sql_expr_to_filter_expr(expr, aliases, table_alias, allow_aggregates)?,
        ))),
        SqlExpr::IsNull(expr) => Ok(Expr::IsNull {
            column: sql_filter_column(expr, aliases, table_alias, allow_aggregates)?,
            negated: false,
        }),
        SqlExpr::IsNotNull(expr) => Ok(Expr::IsNull {
            column: sql_filter_column(expr, aliases, table_alias, allow_aggregates)?,
            negated: true,
        }),
        SqlExpr::InList {
            expr,
            list,
            negated,
        } => match sql_filter_column(expr, aliases, table_alias, allow_aggregates) {
            Ok(column) => Ok(Expr::InList {
                column,
                negated: *negated,
                has_null: literal_list_contains_null(list)?,
                values: non_null_literal_values(list)?,
            }),
            Err(error) => {
                let value = sql_literal_value(expr).map_err(|_| error)?;
                Ok(Expr::Boolean(evaluate_literal_in_list(
                    &value, list, *negated,
                )?))
            }
        },
        SqlExpr::Like {
            negated,
            any,
            expr,
            pattern,
            escape_char,
        } => {
            if *any {
                return Err(DodamError::UnsupportedSql(
                    "LIKE ANY is not supported".to_string(),
                ));
            }
            Ok(Expr::Like {
                column: sql_filter_column(expr, aliases, table_alias, allow_aggregates)?,
                pattern: sql_like_pattern(pattern)?,
                negated: *negated,
                escape: sql_like_escape(escape_char)?,
                case_insensitive: false,
            })
        }
        SqlExpr::ILike {
            negated,
            any,
            expr,
            pattern,
            escape_char,
        } => {
            if *any {
                return Err(DodamError::UnsupportedSql(
                    "ILIKE ANY is not supported".to_string(),
                ));
            }
            Ok(Expr::Like {
                column: sql_filter_column(expr, aliases, table_alias, allow_aggregates)?,
                pattern: sql_like_pattern(pattern)?,
                negated: *negated,
                escape: sql_like_escape(escape_char)?,
                case_insensitive: true,
            })
        }
        _ => Err(DodamError::UnsupportedSql(format!(
            "unsupported WHERE expression: {expr}"
        ))),
    }
}

fn sql_filter_column(
    expr: &SqlExpr,
    aliases: &[(String, String)],
    table_alias: Option<&str>,
    allow_aggregates: bool,
) -> Result<String> {
    match expr {
        SqlExpr::Identifier(_) | SqlExpr::CompoundIdentifier(_) => {
            Ok(resolve_alias(&sql_column_name(expr, table_alias)?, aliases))
        }
        SqlExpr::Function(function) if allow_aggregates => {
            Ok(parse_aggregate(function, table_alias)?.to_string())
        }
        SqlExpr::Nested(expr) => sql_filter_column(expr, aliases, table_alias, allow_aggregates),
        _ => Err(DodamError::UnsupportedSql(format!(
            "expected column or aggregate expression, got {expr}"
        ))),
    }
}

fn maybe_sql_filter_column(
    expr: &SqlExpr,
    aliases: &[(String, String)],
    table_alias: Option<&str>,
    allow_aggregates: bool,
) -> Result<Option<String>> {
    match expr {
        SqlExpr::Identifier(_) | SqlExpr::CompoundIdentifier(_) | SqlExpr::Nested(_) => {
            sql_filter_column(expr, aliases, table_alias, allow_aggregates).map(Some)
        }
        _ => Ok(None),
    }
}

fn sql_like_pattern(expr: &SqlExpr) -> Result<String> {
    match sql_literal_value(expr)? {
        LiteralValue::Utf8(pattern) => Ok(pattern),
        LiteralValue::Null => Err(DodamError::UnsupportedSql(
            "LIKE NULL patterns are not supported yet".to_string(),
        )),
        value => Err(DodamError::UnsupportedSql(format!(
            "LIKE pattern must be a string literal, got {value}"
        ))),
    }
}

fn sql_like_escape(escape_char: &Option<sqlparser::ast::ValueWithSpan>) -> Result<Option<char>> {
    let Some(escape_char) = escape_char else {
        return Ok(None);
    };
    let Value::SingleQuotedString(value) = &escape_char.value else {
        return Err(DodamError::UnsupportedSql(
            "LIKE ESCAPE must be a string literal".to_string(),
        ));
    };
    let mut chars = value.chars();
    let Some(ch) = chars.next() else {
        return Err(DodamError::UnsupportedSql(
            "LIKE ESCAPE must contain exactly one character".to_string(),
        ));
    };
    if chars.next().is_some() {
        return Err(DodamError::UnsupportedSql(
            "LIKE ESCAPE must contain exactly one character".to_string(),
        ));
    }
    Ok(Some(ch))
}

fn sql_literal_value(expr: &SqlExpr) -> Result<LiteralValue> {
    match expr {
        SqlExpr::Value(value) => match &value.value {
            Value::Number(value, false) => value
                .parse::<i64>()
                .map(LiteralValue::Int64)
                .or_else(|_| value.parse::<f64>().map(LiteralValue::Float64))
                .map_err(|_| {
                    DodamError::UnsupportedSql(format!("unsupported numeric literal: {value}"))
                }),
            Value::SingleQuotedString(value) | Value::DoubleQuotedString(value) => {
                Ok(LiteralValue::Utf8(value.clone()))
            }
            Value::Boolean(value) => Ok(LiteralValue::Boolean(*value)),
            Value::Null => Ok(LiteralValue::Null),
            value => Err(DodamError::UnsupportedSql(format!(
                "unsupported literal: {value}"
            ))),
        },
        SqlExpr::TypedString(typed) if typed.data_type.to_string().eq_ignore_ascii_case("date") => {
            match &typed.value.value {
                Value::SingleQuotedString(value) | Value::DoubleQuotedString(value) => {
                    Ok(LiteralValue::Utf8(value.clone()))
                }
                value => Err(DodamError::UnsupportedSql(format!(
                    "unsupported DATE literal: {value}"
                ))),
            }
        }
        SqlExpr::BinaryOp { left, op, right }
            if matches!(op, BinaryOperator::Plus | BinaryOperator::Minus) =>
        {
            if let Some(value) = decimal_number_literal_arithmetic(left, op, right)? {
                return Ok(value);
            }
            let left_value = sql_literal_value(left)?;
            if let Some((amount, field)) = interval_literal(right)? {
                return apply_date_interval(left_value, op.clone(), amount, field);
            }
            let right_value = sql_literal_value(right)?;
            apply_literal_arithmetic(left_value, op.clone(), right_value)
        }
        SqlExpr::UnaryOp { op, expr }
            if matches!(op, UnaryOperator::Minus | UnaryOperator::Plus) =>
        {
            let value = sql_literal_value(expr)?;
            match (op, value) {
                (UnaryOperator::Plus, value) => Ok(value),
                (UnaryOperator::Minus, LiteralValue::Int64(value)) => {
                    Ok(LiteralValue::Int64(value.checked_neg().ok_or_else(
                        || DodamError::UnsupportedSql("integer literal overflow".to_string()),
                    )?))
                }
                (UnaryOperator::Minus, LiteralValue::Float64(value)) => {
                    Ok(LiteralValue::Float64(-value))
                }
                (UnaryOperator::Minus, value) => Err(DodamError::UnsupportedSql(format!(
                    "unary minus requires a numeric literal, got {value}"
                ))),
                _ => unreachable!("validated unary operator"),
            }
        }
        SqlExpr::Substring {
            expr,
            substring_from,
            substring_for,
            ..
        } => {
            let LiteralValue::Utf8(value) = sql_literal_value(expr)? else {
                return Err(DodamError::UnsupportedSql(format!(
                    "SUBSTRING literal input must be a string, got {expr}"
                )));
            };
            let Some(start) = substring_from else {
                return Err(DodamError::UnsupportedSql(
                    "SUBSTRING requires a FROM/start expression".to_string(),
                ));
            };
            let start = literal_usize(start, "SUBSTRING start")?;
            let length = substring_for
                .as_ref()
                .map(|expr| literal_usize(expr, "SUBSTRING length"))
                .transpose()?;
            Ok(LiteralValue::Utf8(substring_literal(&value, start, length)))
        }
        _ => Err(DodamError::UnsupportedSql(format!(
            "expected literal, got {expr}"
        ))),
    }
}

fn evaluate_literal_in_list(
    value: &LiteralValue,
    list: &[SqlExpr],
    negated: bool,
) -> Result<Option<bool>> {
    let mut has_null = false;
    for candidate in list {
        let candidate = sql_literal_value(candidate)?;
        if matches!(candidate, LiteralValue::Null) {
            has_null = true;
            continue;
        }
        if compare_literal_values(value, &BinaryOperator::Eq, &candidate)? == Some(true) {
            return Ok(Some(!negated));
        }
    }
    if has_null {
        Ok(None)
    } else {
        Ok(Some(negated))
    }
}

fn literal_usize(expr: &SqlExpr, context: &str) -> Result<usize> {
    let LiteralValue::Int64(value) = sql_literal_value(expr)? else {
        return Err(DodamError::UnsupportedSql(format!(
            "{context} must be an integer literal"
        )));
    };
    usize::try_from(value)
        .map_err(|_| DodamError::UnsupportedSql(format!("{context} must be non-negative")))
}

fn substring_literal(value: &str, start: usize, length: Option<usize>) -> String {
    let start = start.saturating_sub(1);
    value
        .chars()
        .skip(start)
        .take(length.unwrap_or(usize::MAX))
        .collect()
}

fn decimal_number_literal_arithmetic(
    left: &SqlExpr,
    op: &BinaryOperator,
    right: &SqlExpr,
) -> Result<Option<LiteralValue>> {
    let Some(left) = numeric_literal_text(left) else {
        return Ok(None);
    };
    let Some(right) = numeric_literal_text(right) else {
        return Ok(None);
    };
    let scale = decimal_scale(left).max(decimal_scale(right));
    let left = decimal_literal_to_scaled(left, scale)?;
    let right = decimal_literal_to_scaled(right, scale)?;
    let value = match op {
        BinaryOperator::Plus => left + right,
        BinaryOperator::Minus => left - right,
        _ => unreachable!("validated arithmetic operator"),
    };
    if scale == 0 {
        return Ok(Some(LiteralValue::Int64(i64::try_from(value).map_err(
            |_| DodamError::UnsupportedSql("numeric literal overflow".to_string()),
        )?)));
    }
    let negative = value < 0;
    let value = value.abs();
    let factor =
        10_i128.pow(u32::try_from(scale).map_err(|_| {
            DodamError::UnsupportedSql("numeric literal scale overflow".to_string())
        })?);
    let whole = value / factor;
    let fractional = value % factor;
    let literal = format!(
        "{}{}.{:0width$}",
        if negative { "-" } else { "" },
        whole,
        fractional,
        width = scale
    );
    Ok(Some(LiteralValue::Float64(
        literal.parse::<f64>().map_err(|_| {
            DodamError::UnsupportedSql(format!("unsupported numeric literal: {literal}"))
        })?,
    )))
}

fn numeric_literal_text(expr: &SqlExpr) -> Option<&str> {
    let SqlExpr::Value(value) = expr else {
        return None;
    };
    let Value::Number(value, false) = &value.value else {
        return None;
    };
    Some(value)
}

fn decimal_scale(value: &str) -> usize {
    value
        .split_once('.')
        .map(|(_, fractional)| fractional.len())
        .unwrap_or(0)
}

fn decimal_literal_to_scaled(value: &str, scale: usize) -> Result<i128> {
    let negative = value.starts_with('-');
    let unsigned = value.strip_prefix(['-', '+']).unwrap_or(value);
    let (whole, fractional) = unsigned.split_once('.').unwrap_or((unsigned, ""));
    if whole.is_empty()
        || !whole.chars().all(|ch| ch.is_ascii_digit())
        || !fractional.chars().all(|ch| ch.is_ascii_digit())
        || fractional.len() > scale
    {
        return Err(DodamError::UnsupportedSql(format!(
            "unsupported numeric literal: {value}"
        )));
    }
    let mut result = whole
        .parse::<i128>()
        .map_err(|_| DodamError::UnsupportedSql(format!("unsupported numeric literal: {value}")))?
        .checked_mul(10_i128.pow(u32::try_from(scale).map_err(|_| {
            DodamError::UnsupportedSql("numeric literal scale overflow".to_string())
        })?))
        .ok_or_else(|| DodamError::UnsupportedSql("numeric literal overflow".to_string()))?;
    let mut fractional_value = fractional.parse::<i128>().unwrap_or(0);
    for _ in fractional.len()..scale {
        fractional_value = fractional_value
            .checked_mul(10)
            .ok_or_else(|| DodamError::UnsupportedSql("numeric literal overflow".to_string()))?;
    }
    result = result
        .checked_add(fractional_value)
        .ok_or_else(|| DodamError::UnsupportedSql("numeric literal overflow".to_string()))?;
    if negative {
        result = -result;
    }
    Ok(result)
}

fn apply_literal_arithmetic(
    left: LiteralValue,
    op: BinaryOperator,
    right: LiteralValue,
) -> Result<LiteralValue> {
    match (left, right) {
        (LiteralValue::Int64(left), LiteralValue::Int64(right)) => {
            Ok(LiteralValue::Int64(match op {
                BinaryOperator::Plus => left + right,
                BinaryOperator::Minus => left - right,
                _ => unreachable!("validated arithmetic operator"),
            }))
        }
        (left, right) => {
            let left = literal_as_f64(&left)?;
            let right = literal_as_f64(&right)?;
            Ok(LiteralValue::Float64(match op {
                BinaryOperator::Plus => left + right,
                BinaryOperator::Minus => left - right,
                _ => unreachable!("validated arithmetic operator"),
            }))
        }
    }
}

fn literal_as_f64(value: &LiteralValue) -> Result<f64> {
    match value {
        LiteralValue::Int64(value) => Ok(*value as f64),
        LiteralValue::Float64(value) => Ok(*value),
        _ => Err(DodamError::UnsupportedSql(format!(
            "expected numeric literal, got {value}"
        ))),
    }
}

fn interval_literal(expr: &SqlExpr) -> Result<Option<(i64, DateTimeField)>> {
    let SqlExpr::Interval(interval) = expr else {
        return Ok(None);
    };
    let SqlExpr::Value(value) = interval.value.as_ref() else {
        return Err(DodamError::UnsupportedSql(format!(
            "unsupported INTERVAL value: {}",
            interval.value
        )));
    };
    let amount = match &value.value {
        Value::SingleQuotedString(value) | Value::DoubleQuotedString(value) => value,
        value => {
            return Err(DodamError::UnsupportedSql(format!(
                "unsupported INTERVAL literal: {value}"
            )));
        }
    }
    .parse::<i64>()
    .map_err(|_| DodamError::UnsupportedSql(format!("unsupported INTERVAL: {expr}")))?;
    let field = interval.leading_field.clone().ok_or_else(|| {
        DodamError::UnsupportedSql(format!("INTERVAL requires a leading field: {expr}"))
    })?;
    Ok(Some((amount, field)))
}

fn apply_date_interval(
    value: LiteralValue,
    op: BinaryOperator,
    amount: i64,
    field: DateTimeField,
) -> Result<LiteralValue> {
    let LiteralValue::Utf8(date) = value else {
        return Err(DodamError::UnsupportedSql(
            "INTERVAL arithmetic currently requires a DATE literal".to_string(),
        ));
    };
    let amount = match op {
        BinaryOperator::Plus => amount,
        BinaryOperator::Minus => -amount,
        _ => unreachable!("validated arithmetic operator"),
    };
    let (year, month, day) = parse_ymd(&date)?;
    let (year, month, day) = match field {
        DateTimeField::Day => {
            let days = days_from_civil(year, month, day)? + amount;
            civil_from_days(days)?
        }
        DateTimeField::Month => add_months(year, month, day, amount)?,
        DateTimeField::Year => add_months(year, month, day, amount * 12)?,
        field => {
            return Err(DodamError::UnsupportedSql(format!(
                "unsupported INTERVAL field for DATE arithmetic: {field}"
            )));
        }
    };
    Ok(LiteralValue::Utf8(format!("{year:04}-{month:02}-{day:02}")))
}

fn parse_ymd(value: &str) -> Result<(i32, u32, u32)> {
    let mut parts = value.split('-');
    let year = parts
        .next()
        .and_then(|value| value.parse::<i32>().ok())
        .ok_or_else(|| DodamError::UnsupportedSql(format!("invalid DATE literal: {value}")))?;
    let month = parts
        .next()
        .and_then(|value| value.parse::<u32>().ok())
        .ok_or_else(|| DodamError::UnsupportedSql(format!("invalid DATE literal: {value}")))?;
    let day = parts
        .next()
        .and_then(|value| value.parse::<u32>().ok())
        .ok_or_else(|| DodamError::UnsupportedSql(format!("invalid DATE literal: {value}")))?;
    if parts.next().is_some()
        || !(1..=12).contains(&month)
        || day == 0
        || day > days_in_month(year, month)
    {
        return Err(DodamError::UnsupportedSql(format!(
            "invalid DATE literal: {value}"
        )));
    }
    Ok((year, month, day))
}

fn add_months(year: i32, month: u32, day: u32, months: i64) -> Result<(i32, u32, u32)> {
    let month_index = i64::from(year) * 12 + i64::from(month - 1) + months;
    let year = month_index.div_euclid(12);
    let month = month_index.rem_euclid(12) + 1;
    let year = i32::try_from(year)
        .map_err(|_| DodamError::UnsupportedSql("DATE arithmetic overflow".to_string()))?;
    let month = u32::try_from(month)
        .map_err(|_| DodamError::UnsupportedSql("DATE arithmetic overflow".to_string()))?;
    Ok((year, month, day.min(days_in_month(year, month))))
}

fn days_in_month(year: i32, month: u32) -> u32 {
    match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 if is_leap_year(year) => 29,
        2 => 28,
        _ => 0,
    }
}

fn is_leap_year(year: i32) -> bool {
    (year % 4 == 0 && year % 100 != 0) || year % 400 == 0
}

fn days_from_civil(year: i32, month: u32, day: u32) -> Result<i64> {
    let year = i64::from(year) - i64::from(month <= 2);
    let era = if year >= 0 { year } else { year - 399 } / 400;
    let yoe = year - era * 400;
    let month = i64::from(month);
    let day = i64::from(day);
    let doy = (153 * (month + if month > 2 { -3 } else { 9 }) + 2) / 5 + day - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    Ok(era * 146_097 + doe - 719_468)
}

fn civil_from_days(days: i64) -> Result<(i32, u32, u32)> {
    let days = days + 719_468;
    let era = if days >= 0 { days } else { days - 146_096 } / 146_097;
    let doe = days - era * 146_097;
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let year = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let day = doy - (153 * mp + 2) / 5 + 1;
    let month = mp + if mp < 10 { 3 } else { -9 };
    let year = year + i64::from(month <= 2);
    Ok((
        i32::try_from(year)
            .map_err(|_| DodamError::UnsupportedSql("DATE arithmetic overflow".to_string()))?,
        u32::try_from(month)
            .map_err(|_| DodamError::UnsupportedSql("DATE arithmetic overflow".to_string()))?,
        u32::try_from(day)
            .map_err(|_| DodamError::UnsupportedSql("DATE arithmetic overflow".to_string()))?,
    ))
}

fn year_from_days(days: i64) -> Result<i32> {
    let days = days + 719_468;
    let era = if days >= 0 { days } else { days - 146_096 } / 146_097;
    let doe = days - era * 146_097;
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let year = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let month = mp + if mp < 10 { 3 } else { -9 };
    i32::try_from(year + i64::from(month <= 2))
        .map_err(|_| DodamError::UnsupportedSql("DATE arithmetic overflow".to_string()))
}

#[derive(Default)]
struct Date32YearCache {
    base_day: i32,
    years: Vec<i32>,
    disabled: bool,
}

impl Date32YearCache {
    const MAX_SPAN_DAYS: usize = 20_000;

    fn year(&mut self, day: i32) -> Result<i32> {
        if self.disabled {
            return year_from_days(i64::from(day));
        }
        if self.years.is_empty() {
            self.base_day = day;
            self.years.push(year_from_days(i64::from(day))?);
            return Ok(self.years[0]);
        }
        if day < self.base_day {
            let prepend = usize::try_from(self.base_day - day)
                .map_err(|_| DodamError::UnsupportedSql("DATE arithmetic overflow".to_string()))?;
            if prepend + self.years.len() > Self::MAX_SPAN_DAYS {
                self.disabled = true;
                self.years.clear();
                return year_from_days(i64::from(day));
            }
            let mut years = Vec::with_capacity(prepend + self.years.len());
            for offset in 0..prepend {
                years.push(year_from_days(i64::from(day) + offset as i64)?);
            }
            years.extend_from_slice(&self.years);
            self.base_day = day;
            self.years = years;
            return Ok(self.years[0]);
        }
        let index = usize::try_from(day - self.base_day)
            .map_err(|_| DodamError::UnsupportedSql("DATE arithmetic overflow".to_string()))?;
        if index >= self.years.len() {
            if index + 1 > Self::MAX_SPAN_DAYS {
                self.disabled = true;
                self.years.clear();
                return year_from_days(i64::from(day));
            }
            let start = self.years.len();
            self.years.reserve(index + 1 - start);
            for offset in start..=index {
                self.years
                    .push(year_from_days(i64::from(self.base_day) + offset as i64)?);
            }
        }
        Ok(self.years[index])
    }
}

fn sql_comparison_op(op: &BinaryOperator) -> ComparisonOp {
    match op {
        BinaryOperator::Eq => ComparisonOp::Eq,
        BinaryOperator::NotEq => ComparisonOp::NotEq,
        BinaryOperator::Gt => ComparisonOp::Gt,
        BinaryOperator::GtEq => ComparisonOp::GtEq,
        BinaryOperator::Lt => ComparisonOp::Lt,
        BinaryOperator::LtEq => ComparisonOp::LtEq,
        _ => unreachable!("validated comparison operator"),
    }
}

fn sql_column_name(expr: &SqlExpr, table_alias: Option<&str>) -> Result<String> {
    ColumnResolver::single(table_alias).resolve_single_column(expr)
}

fn parse_usize_literal(expr: &SqlExpr) -> Result<usize> {
    let SqlExpr::Value(value) = expr else {
        return Err(DodamError::UnsupportedSql(format!(
            "expected integer literal, got {expr}"
        )));
    };
    match value.value.clone() {
        Value::Number(value, false) => value.parse::<usize>().map_err(|_| {
            DodamError::UnsupportedSql(format!(
                "expected non-negative integer literal, got {value}"
            ))
        }),
        value => Err(DodamError::UnsupportedSql(format!(
            "expected integer literal, got {value}"
        ))),
    }
}

fn object_name_to_string(name: &ObjectName) -> Result<String> {
    let [part] = name.0.as_slice() else {
        return Err(DodamError::UnsupportedSql(format!(
            "compound object names are not supported: {name}"
        )));
    };
    match part {
        ObjectNamePart::Identifier(ident) => Ok(ident.value.clone()),
        _ => Err(DodamError::UnsupportedSql(format!(
            "unsupported object name: {name}"
        ))),
    }
}

fn collect_batches(mut stream: SendableBatchStream) -> Result<Vec<RecordBatch>> {
    let mut batches = Vec::new();
    for batch in stream.by_ref() {
        let batch = batch?;
        if batch.num_rows() > 0 {
            batches.push(batch);
        }
    }
    Ok(batches)
}

fn collect_ordered_stream_limit_batches(
    mut stream: SendableBatchStream,
    limit: Option<usize>,
    offset: usize,
) -> Result<Vec<RecordBatch>> {
    let mut to_skip = offset;
    let mut remaining = limit.unwrap_or(usize::MAX);
    let mut batches = Vec::new();
    if remaining == 0 {
        return Ok(batches);
    }
    for batch in stream.by_ref() {
        let batch = batch?;
        if batch.num_rows() == 0 {
            continue;
        }
        if to_skip >= batch.num_rows() {
            to_skip -= batch.num_rows();
            continue;
        }
        let batch = if to_skip > 0 {
            let sliced = batch.slice(to_skip, batch.num_rows() - to_skip);
            to_skip = 0;
            sliced
        } else {
            batch
        };
        let rows = remaining.min(batch.num_rows());
        remaining -= rows;
        if rows > 0 {
            batches.push(batch.slice(0, rows));
        }
        if remaining == 0 {
            break;
        }
    }
    Ok(batches)
}

fn collect_expression_filtered_limit_batches(
    mut stream: SendableBatchStream,
    predicate: &SqlExpr,
    table_alias: Option<&str>,
    limit: usize,
) -> Result<Vec<RecordBatch>> {
    if limit == 0 {
        return Ok(Vec::new());
    }
    let mut batches = Vec::new();
    let mut remaining = limit;
    for batch in stream.by_ref() {
        let batch = batch?;
        if batch.num_rows() == 0 {
            continue;
        }
        let mut filtered = apply_output_expression_filter(vec![batch], predicate, table_alias)?;
        for batch in filtered.drain(..) {
            if remaining == 0 {
                return Ok(batches);
            }
            if batch.num_rows() > remaining {
                batches.push(batch.slice(0, remaining));
                return Ok(batches);
            }
            remaining -= batch.num_rows();
            batches.push(batch);
        }
    }
    Ok(batches)
}

fn apply_output_filter_stream(
    stream: SendableBatchStream,
    filter: Option<FilterExpr>,
) -> SendableBatchStream {
    let Some(filter) = filter else {
        return stream;
    };
    let (input, metrics) = stream.into_parts();
    SendableBatchStream::new(Box::new(OutputFilterStream { input, filter }), metrics)
}

struct OutputFilterStream {
    input: Box<dyn Iterator<Item = Result<RecordBatch>> + Send>,
    filter: FilterExpr,
}

impl Iterator for OutputFilterStream {
    type Item = Result<RecordBatch>;

    fn next(&mut self) -> Option<Self::Item> {
        for batch in &mut self.input {
            match batch {
                Ok(batch) => match filter_batch(batch, &self.filter) {
                    Ok(batch) if batch.num_rows() == 0 => continue,
                    result => return Some(result),
                },
                Err(error) => return Some(Err(error)),
            }
        }
        None
    }
}

fn apply_output_order_limit(
    batches: Vec<RecordBatch>,
    order_by: Option<&SortKey>,
    limit: Option<usize>,
    offset: usize,
) -> Result<Vec<RecordBatch>> {
    let Some(order_by) = order_by else {
        return Ok(limit_batches(batches, limit, offset));
    };
    if batches.is_empty() {
        return Ok(batches);
    }
    if let Some(limit) = limit
        && offset == 0
        && let Some(batches) = try_streaming_primitive_topk_batches(&batches, order_by, limit)?
    {
        return Ok(batches);
    }
    if topk_batch_prune_enabled()
        && let Some(limit) = limit
        && offset == 0
        && batches.len() > 1
        && batches.iter().any(|batch| batch.num_rows() > limit)
    {
        let candidates = batches
            .iter()
            .filter(|batch| batch.num_rows() > 0)
            .map(|batch| sort_output_batch(batch, order_by, Some(limit)))
            .collect::<Result<Vec<_>>>()?;
        if candidates.is_empty() {
            return Ok(Vec::new());
        }
        let schema = candidates[0].schema();
        let batch = if candidates.len() == 1 {
            candidates[0].clone()
        } else {
            concat_batches(&schema, candidates.iter())?
        };
        return Ok(vec![sort_output_batch(&batch, order_by, Some(limit))?]);
    }

    let schema = batches[0].schema();
    let batch = if batches.len() == 1 {
        batches[0].clone()
    } else {
        concat_batches(&schema, batches.iter())?
    };
    if output_batch_satisfies_order(&batch, order_by)? {
        return Ok(limit_batches(vec![batch], limit, offset));
    }
    let sorted_limit = limit.and_then(|limit| limit.checked_add(offset));
    let sorted = sort_output_batch(&batch, order_by, sorted_limit)?;
    Ok(limit_batches(vec![sorted], limit, offset))
}

type StreamingTopKSelected = (StreamingTopKKey, u64, usize, u32);

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
enum StreamingTopKKey {
    I32I64I64(i32, i64, i64),
    NullableI32I64(bool, i32, i64),
}

fn try_streaming_primitive_topk_batches(
    batches: &[RecordBatch],
    order_by: &SortKey,
    limit: usize,
) -> Result<Option<Vec<RecordBatch>>> {
    if !streaming_primitive_topk_sort_enabled()
        || limit == 0
        || batches.len() < 2
        || order_by.expressions.iter().any(|sort| sort.descending)
    {
        return Ok(None);
    }
    let Some(shape) = streaming_topk_sort_shape(batches, order_by)? else {
        return Ok(None);
    };
    let mut heap = BinaryHeap::<StreamingTopKSelected>::with_capacity(limit.saturating_add(1));
    let mut sequence = 0_u64;
    for (batch_index, batch) in batches.iter().enumerate() {
        if batch.num_rows() == 0 {
            continue;
        }
        match shape {
            StreamingTopKSortShape::I32I64I64(first, second, third) => {
                let first = batch
                    .column(first)
                    .as_any()
                    .downcast_ref::<Int32Array>()
                    .expect("streaming top-k i32 sort key");
                let second = batch
                    .column(second)
                    .as_any()
                    .downcast_ref::<Int64Array>()
                    .expect("streaming top-k i64 sort key");
                let third = batch
                    .column(third)
                    .as_any()
                    .downcast_ref::<Int64Array>()
                    .expect("streaming top-k i64 sort key");
                if heap.len() >= limit
                    && let Some(worst) = heap.peek()
                    && let Some(min_key) =
                        streaming_topk_batch_min_i32_i64_i64(first, second, third)
                    && (min_key, 0_u64, batch_index, 0_u32) >= *worst
                {
                    sequence = sequence.wrapping_add(batch.num_rows() as u64);
                    continue;
                }
                for row in 0..batch.num_rows() {
                    let item = (
                        StreamingTopKKey::I32I64I64(
                            first.value(row),
                            second.value(row),
                            third.value(row),
                        ),
                        sequence,
                        batch_index,
                        row as u32,
                    );
                    streaming_topk_push(limit, &mut heap, item);
                    sequence = sequence.wrapping_add(1);
                }
            }
            StreamingTopKSortShape::NullableI32I64(first, second) => {
                let first = batch
                    .column(first)
                    .as_any()
                    .downcast_ref::<Int32Array>()
                    .expect("streaming top-k i32 sort key");
                let second = batch
                    .column(second)
                    .as_any()
                    .downcast_ref::<Int64Array>()
                    .expect("streaming top-k i64 sort key");
                if heap.len() >= limit
                    && let Some(worst) = heap.peek()
                    && let Some(min_key) = streaming_topk_batch_min_nullable_i32_i64(first, second)
                    && (min_key, 0_u64, batch_index, 0_u32) >= *worst
                {
                    sequence = sequence.wrapping_add(batch.num_rows() as u64);
                    continue;
                }
                for row in 0..batch.num_rows() {
                    let present = !first.is_null(row);
                    let value = if present { first.value(row) } else { 0 };
                    let item = (
                        StreamingTopKKey::NullableI32I64(present, value, second.value(row)),
                        sequence,
                        batch_index,
                        row as u32,
                    );
                    streaming_topk_push(limit, &mut heap, item);
                    sequence = sequence.wrapping_add(1);
                }
            }
        }
    }
    if heap.is_empty() {
        return Ok(Some(Vec::new()));
    }
    let mut selected = heap.into_vec();
    selected.sort_unstable();
    let materialize_selected = selected
        .into_iter()
        .map(|(_, sequence, batch_index, row)| (0_i128, sequence, batch_index, row))
        .collect::<Vec<_>>();
    Ok(Some(vec![materialize_topk_selected_rows(
        batches,
        &materialize_selected,
    )?]))
}

fn streaming_topk_batch_min_i32_i64_i64(
    first: &Int32Array,
    second: &Int64Array,
    third: &Int64Array,
) -> Option<StreamingTopKKey> {
    let mut min_key = None;
    for row in 0..first.len() {
        let key =
            StreamingTopKKey::I32I64I64(first.value(row), second.value(row), third.value(row));
        min_key = Some(min_key.map_or(key, |min: StreamingTopKKey| min.min(key)));
    }
    min_key
}

fn streaming_topk_batch_min_nullable_i32_i64(
    first: &Int32Array,
    second: &Int64Array,
) -> Option<StreamingTopKKey> {
    let mut min_key = None;
    for row in 0..first.len() {
        let present = !first.is_null(row);
        let value = if present { first.value(row) } else { 0 };
        let key = StreamingTopKKey::NullableI32I64(present, value, second.value(row));
        min_key = Some(min_key.map_or(key, |min: StreamingTopKKey| min.min(key)));
    }
    min_key
}

fn streaming_topk_push(
    limit: usize,
    heap: &mut BinaryHeap<StreamingTopKSelected>,
    item: StreamingTopKSelected,
) {
    if heap.len() < limit {
        heap.push(item);
        return;
    }
    if let Some(mut worst) = heap.peek_mut()
        && item < *worst
    {
        *worst = item;
    }
}

#[derive(Clone, Copy)]
enum StreamingTopKSortShape {
    I32I64I64(usize, usize, usize),
    NullableI32I64(usize, usize),
}

fn streaming_topk_sort_shape(
    batches: &[RecordBatch],
    order_by: &SortKey,
) -> Result<Option<StreamingTopKSortShape>> {
    let Some(first_batch) = batches.iter().find(|batch| batch.num_rows() > 0) else {
        return Ok(None);
    };
    let expressions = order_by.expressions.as_slice();
    if let [first, second, third] = expressions
        && !first.nulls_first
        && !second.nulls_first
        && !third.nulls_first
    {
        let first_index = output_batch_column_index(first_batch, &first.column)?;
        let second_index = output_batch_column_index(first_batch, &second.column)?;
        let third_index = output_batch_column_index(first_batch, &third.column)?;
        if streaming_topk_column_is_non_null_i32(batches, first_index)
            && streaming_topk_column_is_non_null_i64(batches, second_index)
            && streaming_topk_column_is_non_null_i64(batches, third_index)
        {
            return Ok(Some(StreamingTopKSortShape::I32I64I64(
                first_index,
                second_index,
                third_index,
            )));
        }
    }
    if let [first, second] = expressions
        && first.nulls_first
        && !second.nulls_first
    {
        let first_index = output_batch_column_index(first_batch, &first.column)?;
        let second_index = output_batch_column_index(first_batch, &second.column)?;
        if streaming_topk_column_is_i32(batches, first_index)
            && streaming_topk_column_is_non_null_i64(batches, second_index)
        {
            return Ok(Some(StreamingTopKSortShape::NullableI32I64(
                first_index,
                second_index,
            )));
        }
    }
    Ok(None)
}

fn streaming_topk_column_is_i32(batches: &[RecordBatch], index: usize) -> bool {
    batches.iter().all(|batch| {
        batch
            .column(index)
            .as_any()
            .downcast_ref::<Int32Array>()
            .is_some()
    })
}

fn streaming_topk_column_is_non_null_i32(batches: &[RecordBatch], index: usize) -> bool {
    batches.iter().all(|batch| {
        batch
            .column(index)
            .as_any()
            .downcast_ref::<Int32Array>()
            .is_some_and(|array| array.null_count() == 0)
    })
}

fn streaming_topk_column_is_non_null_i64(batches: &[RecordBatch], index: usize) -> bool {
    batches.iter().all(|batch| {
        batch
            .column(index)
            .as_any()
            .downcast_ref::<Int64Array>()
            .is_some_and(|array| array.null_count() == 0)
    })
}

fn streaming_primitive_topk_sort_enabled() -> bool {
    std::env::var("DODAM_ENABLE_STREAMING_PRIMITIVE_TOPK_SORT")
        .map(|value| value == "1" || value.eq_ignore_ascii_case("true"))
        .unwrap_or(false)
}

fn output_batch_satisfies_order(batch: &RecordBatch, order_by: &SortKey) -> Result<bool> {
    let [sort] = order_by.expressions.as_slice() else {
        return Ok(false);
    };
    if sort.descending || sort.nulls_first {
        return Ok(false);
    }
    let index = output_batch_column_index(batch, &sort.column)?;
    let column = batch.column(index);
    match column.data_type() {
        DataType::Int32 => {
            let values = column
                .as_any()
                .downcast_ref::<Int32Array>()
                .expect("Int32 data type");
            for row in 1..values.len() {
                if values.is_null(row - 1) || values.is_null(row) {
                    return Ok(false);
                }
                if values.value(row - 1) > values.value(row) {
                    return Ok(false);
                }
            }
            Ok(true)
        }
        DataType::Date32 => {
            let values = column
                .as_any()
                .downcast_ref::<Date32Array>()
                .expect("Date32 data type");
            for row in 1..values.len() {
                if values.is_null(row - 1) || values.is_null(row) {
                    return Ok(false);
                }
                if values.value(row - 1) > values.value(row) {
                    return Ok(false);
                }
            }
            Ok(true)
        }
        DataType::Int64 => {
            let values = column
                .as_any()
                .downcast_ref::<Int64Array>()
                .expect("Int64 data type");
            for row in 1..values.len() {
                if values.is_null(row - 1) || values.is_null(row) {
                    return Ok(false);
                }
                if values.value(row - 1) > values.value(row) {
                    return Ok(false);
                }
            }
            Ok(true)
        }
        DataType::Utf8 => {
            let values = column
                .as_any()
                .downcast_ref::<StringArray>()
                .expect("Utf8 data type");
            for row in 1..values.len() {
                if values.is_null(row - 1) || values.is_null(row) {
                    return Ok(false);
                }
                if values.value(row - 1) > values.value(row) {
                    return Ok(false);
                }
            }
            Ok(true)
        }
        _ => Ok(false),
    }
}

fn output_batches_satisfy_order(batches: &[RecordBatch], order_by: &SortKey) -> Result<bool> {
    if batches.is_empty() {
        return Ok(true);
    }
    for batch in batches {
        if !output_batch_satisfies_order(batch, order_by)? {
            return Ok(false);
        }
    }
    let [sort] = order_by.expressions.as_slice() else {
        return Ok(false);
    };
    if sort.descending || sort.nulls_first {
        return Ok(false);
    }
    let mut previous = None::<ScalarOrderValue>;
    for batch in batches {
        if batch.num_rows() == 0 {
            continue;
        }
        let index = output_batch_column_index(batch, &sort.column)?;
        let column = batch.column(index);
        let first = scalar_order_value(column, 0)?;
        let last = scalar_order_value(column, batch.num_rows() - 1)?;
        if let Some(previous) = previous
            && previous > first
        {
            return Ok(false);
        }
        previous = Some(last);
    }
    Ok(true)
}

#[derive(Clone, PartialEq, Eq, PartialOrd, Ord)]
enum ScalarOrderValue {
    Int32(i32),
    Date32(i32),
    Int64(i64),
    Utf8(String),
}

fn scalar_order_value(column: &ArrayRef, row: usize) -> Result<ScalarOrderValue> {
    match column.data_type() {
        DataType::Int32 => {
            let values = column
                .as_any()
                .downcast_ref::<Int32Array>()
                .expect("Int32 data type");
            if values.is_null(row) {
                return Err(DodamError::UnsupportedSql(
                    "ordered batch boundary contains NULL".to_string(),
                ));
            }
            Ok(ScalarOrderValue::Int32(values.value(row)))
        }
        DataType::Date32 => {
            let values = column
                .as_any()
                .downcast_ref::<Date32Array>()
                .expect("Date32 data type");
            if values.is_null(row) {
                return Err(DodamError::UnsupportedSql(
                    "ordered batch boundary contains NULL".to_string(),
                ));
            }
            Ok(ScalarOrderValue::Date32(values.value(row)))
        }
        DataType::Int64 => {
            let values = column
                .as_any()
                .downcast_ref::<Int64Array>()
                .expect("Int64 data type");
            if values.is_null(row) {
                return Err(DodamError::UnsupportedSql(
                    "ordered batch boundary contains NULL".to_string(),
                ));
            }
            Ok(ScalarOrderValue::Int64(values.value(row)))
        }
        DataType::Utf8 => {
            let values = column
                .as_any()
                .downcast_ref::<StringArray>()
                .expect("Utf8 data type");
            if values.is_null(row) {
                return Err(DodamError::UnsupportedSql(
                    "ordered batch boundary contains NULL".to_string(),
                ));
            }
            Ok(ScalarOrderValue::Utf8(values.value(row).to_string()))
        }
        _ => Err(DodamError::UnsupportedSql(
            "ordered batch boundary type is unsupported".to_string(),
        )),
    }
}

fn apply_aggregate_output_order_limit(
    batches: Vec<RecordBatch>,
    order_by: Option<&SortKey>,
    limit: Option<usize>,
    offset: usize,
    metrics: &AggregateMetrics,
    group_by: &[String],
) -> Result<Vec<RecordBatch>> {
    if aggregate_output_already_ordered(metrics, group_by, order_by) {
        return Ok(limit_batches(batches, limit, offset));
    }
    apply_output_order_limit(batches, order_by, limit, offset)
}

fn aggregate_output_already_ordered(
    metrics: &AggregateMetrics,
    group_by: &[String],
    order_by: Option<&SortKey>,
) -> bool {
    let Some(order_by) = order_by else {
        return false;
    };
    if order_by.expressions.is_empty() || order_by.expressions.len() > group_by.len() {
        return false;
    }
    for (index, expression) in order_by.expressions.iter().enumerate() {
        if expression.descending || expression.column != group_by[index] {
            return false;
        }
        if !expression.nulls_first
            && metrics
                .groups
                .iter()
                .any(|group| group.keys.get(index).is_some_and(group_value_is_null))
        {
            return false;
        }
    }
    true
}

fn group_value_is_null(value: &GroupValue) -> bool {
    match value {
        GroupValue::Int64(value) => value.is_none(),
        GroupValue::UInt64(value) => value.is_none(),
        GroupValue::Decimal128(value, _, _) => value.is_none(),
        GroupValue::Date32(value) => value.is_none(),
        GroupValue::Date64(value) => value.is_none(),
        GroupValue::Utf8(value) => value.is_none(),
    }
}

fn apply_output_distinct(batches: Vec<RecordBatch>, distinct: bool) -> Result<Vec<RecordBatch>> {
    if !distinct {
        return Ok(batches);
    }
    collect_batches(Box::new(DistinctExec::new(Box::new(MemoryExec::new(batches)))).execute()?)
}

fn apply_output_expression_projection_order_limit(
    mut batches: Vec<RecordBatch>,
    expressions: &[ProjectionExpression],
    order_by: Option<&SortKey>,
    limit: Option<usize>,
    offset: usize,
) -> Result<Vec<RecordBatch>> {
    if sort_key_available_in_batches(&batches, order_by) {
        batches = apply_output_order_limit(batches, order_by, limit, offset)?;
        apply_output_expression_projection(batches, expressions)
    } else {
        batches = apply_output_expression_projection(batches, expressions)?;
        apply_output_order_limit(batches, order_by, limit, offset)
    }
}

fn sort_key_available_in_batches(batches: &[RecordBatch], order_by: Option<&SortKey>) -> bool {
    let Some(order_by) = order_by else {
        return false;
    };
    let Some(batch) = batches.first() else {
        return false;
    };
    order_by
        .expressions
        .iter()
        .all(|sort| output_batch_column_index(batch, &sort.column).is_ok())
}

fn topk_batch_prune_enabled() -> bool {
    std::env::var("DODAM_DISABLE_TOPK_BATCH_PRUNE")
        .map(|value| value != "1" && !value.eq_ignore_ascii_case("true"))
        .unwrap_or(true)
}

fn sort_output_batch(
    batch: &RecordBatch,
    order_by: &SortKey,
    limit: Option<usize>,
) -> Result<RecordBatch> {
    if let Some(batch) = sort_nullable_i32_then_ordered_i64_batch(batch, order_by, limit)? {
        return Ok(batch);
    }
    if let Some(batch) = sort_fixed_primitive_output_batch(batch, order_by, limit)? {
        return Ok(batch);
    }
    if let Some(batch) = sort_primitive_output_batch(batch, order_by, limit)? {
        return Ok(batch);
    }
    let sort_columns = order_by
        .expressions
        .iter()
        .map(|sort| {
            let column_index = batch
                .schema()
                .fields()
                .iter()
                .position(|field| field.name() == &sort.column)
                .ok_or_else(|| DodamError::UnknownColumn(sort.column.clone()))?;
            Ok(SortColumn {
                values: batch.column(column_index).clone(),
                options: Some(SortOptions {
                    descending: sort.descending,
                    nulls_first: sort.nulls_first,
                }),
            })
        })
        .collect::<Result<Vec<_>>>()?;
    let indices = lexsort_to_indices(&sort_columns, limit)?;
    if let Some(batch) = take_primitive_record_batch_by_indices(batch, &indices)? {
        return Ok(batch);
    }
    Ok(take_record_batch(batch, &indices)?)
}

fn sort_nullable_i32_then_ordered_i64_batch(
    batch: &RecordBatch,
    order_by: &SortKey,
    limit: Option<usize>,
) -> Result<Option<RecordBatch>> {
    let Some(limit) = limit else {
        return Ok(None);
    };
    if limit == 0 || batch.num_rows() == 0 || limit >= batch.num_rows() {
        return Ok(None);
    }
    let [first_sort, second_sort] = order_by.expressions.as_slice() else {
        return Ok(None);
    };
    if first_sort.descending
        || second_sort.descending
        || !first_sort.nulls_first
        || second_sort.nulls_first
    {
        return Ok(None);
    }
    let first_index = output_batch_column_index(batch, &first_sort.column)?;
    let second_index = output_batch_column_index(batch, &second_sort.column)?;
    let first = batch.column(first_index);
    let second = batch.column(second_index);
    let Some(first) = first.as_any().downcast_ref::<Int32Array>() else {
        return Ok(None);
    };
    if !primitive_integer_array_is_ascending(second) {
        return Ok(None);
    }
    let Some((min, slot_count)) = dense_i32_array_range(first) else {
        return Ok(None);
    };
    let mut null_rows = Vec::new();
    let mut buckets = (0..slot_count).map(|_| Vec::new()).collect::<Vec<_>>();
    for row in 0..first.len() {
        let row = u32::try_from(row).map_err(|_| {
            DodamError::UnsupportedSql("nullable i32/i64 ordered sort row overflow".to_string())
        })?;
        if first.is_null(row as usize) {
            null_rows.push(row);
        } else {
            let slot = (first.value(row as usize) - min) as usize;
            buckets[slot].push(row);
        }
    }
    let mut indices = Vec::with_capacity(limit);
    for row in null_rows {
        indices.push(row);
        if indices.len() == limit {
            return take_primitive_record_batch_by_raw_indices(batch, &indices).map(Some);
        }
    }
    for bucket in buckets {
        for row in bucket {
            indices.push(row);
            if indices.len() == limit {
                return take_primitive_record_batch_by_raw_indices(batch, &indices).map(Some);
            }
        }
    }
    take_primitive_record_batch_by_raw_indices(batch, &indices).map(Some)
}

fn primitive_integer_array_is_ascending(values: &ArrayRef) -> bool {
    match values.data_type() {
        DataType::Int32 => {
            let values = values
                .as_any()
                .downcast_ref::<Int32Array>()
                .expect("Int32 data type");
            if values.null_count() != 0 {
                return false;
            }
            for row in 1..values.len() {
                if values.value(row - 1) > values.value(row) {
                    return false;
                }
            }
            true
        }
        DataType::Int64 => {
            let values = values
                .as_any()
                .downcast_ref::<Int64Array>()
                .expect("Int64 data type");
            if values.null_count() != 0 {
                return false;
            }
            for row in 1..values.len() {
                if values.value(row - 1) > values.value(row) {
                    return false;
                }
            }
            true
        }
        _ => false,
    }
}

fn dense_i32_array_range(values: &Int32Array) -> Option<(i32, usize)> {
    let mut min = i32::MAX;
    let mut max = i32::MIN;
    let mut has_value = false;
    for row in 0..values.len() {
        if values.is_null(row) {
            continue;
        }
        let value = values.value(row);
        min = min.min(value);
        max = max.max(value);
        has_value = true;
    }
    if !has_value {
        return Some((0, 0));
    }
    let slot_count = usize::try_from(i64::from(max) - i64::from(min) + 1).ok()?;
    (slot_count <= values.len().saturating_mul(4) && slot_count <= 1_000_000)
        .then_some((min, slot_count))
}

fn sort_fixed_primitive_output_batch(
    batch: &RecordBatch,
    order_by: &SortKey,
    limit: Option<usize>,
) -> Result<Option<RecordBatch>> {
    if !fixed_primitive_partial_sort_enabled() {
        return Ok(None);
    }
    let Some(limit) = limit else {
        return Ok(None);
    };
    if batch.num_rows() == 0 || limit == 0 || limit >= batch.num_rows() {
        return Ok(None);
    }
    if order_by.expressions.iter().any(|sort| sort.descending) {
        return Ok(None);
    }
    if let Some(batch) = sort_i32_i64_i64_output_batch(batch, order_by, limit)? {
        return Ok(Some(batch));
    }
    sort_nullable_i32_i64_output_batch(batch, order_by, limit)
}

fn sort_i32_i64_i64_output_batch(
    batch: &RecordBatch,
    order_by: &SortKey,
    limit: usize,
) -> Result<Option<RecordBatch>> {
    let [first, second, third] = order_by.expressions.as_slice() else {
        return Ok(None);
    };
    if first.nulls_first || second.nulls_first || third.nulls_first {
        return Ok(None);
    }
    let first = batch.column(output_batch_column_index(batch, &first.column)?);
    let second = batch.column(output_batch_column_index(batch, &second.column)?);
    let third = batch.column(output_batch_column_index(batch, &third.column)?);
    if first.null_count() != 0 || second.null_count() != 0 || third.null_count() != 0 {
        return Ok(None);
    }
    let (Some(first), Some(second), Some(third)) = (
        first.as_any().downcast_ref::<Int32Array>(),
        second.as_any().downcast_ref::<Int64Array>(),
        third.as_any().downcast_ref::<Int64Array>(),
    ) else {
        return Ok(None);
    };
    let mut keys = (0..batch.num_rows())
        .map(|row| {
            (
                first.value(row),
                second.value(row),
                third.value(row),
                row as u32,
            )
        })
        .collect::<Vec<_>>();
    keys.select_nth_unstable_by(limit, |left, right| {
        (left.0, left.1, left.2, left.3).cmp(&(right.0, right.1, right.2, right.3))
    });
    keys.truncate(limit);
    keys.sort_unstable_by(|left, right| {
        (left.0, left.1, left.2, left.3).cmp(&(right.0, right.1, right.2, right.3))
    });
    let indices = keys
        .into_iter()
        .map(|(_, _, _, row)| row)
        .collect::<Vec<_>>();
    Ok(Some(take_primitive_record_batch_by_raw_indices(
        batch, &indices,
    )?))
}

fn sort_nullable_i32_i64_output_batch(
    batch: &RecordBatch,
    order_by: &SortKey,
    limit: usize,
) -> Result<Option<RecordBatch>> {
    let [first, second] = order_by.expressions.as_slice() else {
        return Ok(None);
    };
    if !first.nulls_first || second.nulls_first {
        return Ok(None);
    }
    let first = batch.column(output_batch_column_index(batch, &first.column)?);
    let second = batch.column(output_batch_column_index(batch, &second.column)?);
    if second.null_count() != 0 {
        return Ok(None);
    }
    let (Some(first), Some(second)) = (
        first.as_any().downcast_ref::<Int32Array>(),
        second.as_any().downcast_ref::<Int64Array>(),
    ) else {
        return Ok(None);
    };
    let mut keys = (0..batch.num_rows())
        .map(|row| {
            let present = !first.is_null(row);
            let value = if present { first.value(row) } else { 0 };
            (present, value, second.value(row), row as u32)
        })
        .collect::<Vec<_>>();
    keys.select_nth_unstable_by(limit, |left, right| {
        (left.0, left.1, left.2, left.3).cmp(&(right.0, right.1, right.2, right.3))
    });
    keys.truncate(limit);
    keys.sort_unstable_by(|left, right| {
        (left.0, left.1, left.2, left.3).cmp(&(right.0, right.1, right.2, right.3))
    });
    let indices = keys
        .into_iter()
        .map(|(_, _, _, row)| row)
        .collect::<Vec<_>>();
    Ok(Some(take_primitive_record_batch_by_raw_indices(
        batch, &indices,
    )?))
}

fn fixed_primitive_partial_sort_enabled() -> bool {
    std::env::var("DODAM_ENABLE_FIXED_PRIMITIVE_PARTIAL_SORT")
        .map(|value| value == "1" || value.eq_ignore_ascii_case("true"))
        .unwrap_or(false)
}

enum PrimitiveSortColumn<'a> {
    Int32(&'a Int32Array),
    Int64(&'a Int64Array),
    UInt64(&'a UInt64Array),
    Float64(&'a Float64Array),
    Date32(&'a Date32Array),
}

impl PrimitiveSortColumn<'_> {
    fn compare(&self, left: usize, right: usize) -> std::cmp::Ordering {
        match self {
            Self::Int32(values) => values.value(left).cmp(&values.value(right)),
            Self::Int64(values) => values.value(left).cmp(&values.value(right)),
            Self::UInt64(values) => values.value(left).cmp(&values.value(right)),
            Self::Float64(values) => values.value(left).total_cmp(&values.value(right)),
            Self::Date32(values) => values.value(left).cmp(&values.value(right)),
        }
    }
}

fn sort_primitive_output_batch(
    batch: &RecordBatch,
    order_by: &SortKey,
    limit: Option<usize>,
) -> Result<Option<RecordBatch>> {
    if !primitive_partial_sort_enabled() {
        return Ok(None);
    }
    let Some(limit) = limit else {
        return Ok(None);
    };
    if batch.num_rows() == 0 || limit == 0 || limit >= batch.num_rows() {
        return Ok(None);
    }
    if order_by.expressions.is_empty() || order_by.expressions.len() > 4 {
        return Ok(None);
    }
    let mut sort_columns = Vec::with_capacity(order_by.expressions.len());
    let mut descending = Vec::with_capacity(order_by.expressions.len());
    for sort in &order_by.expressions {
        let column_index = output_batch_column_index(batch, &sort.column)?;
        let column = batch.column(column_index);
        if column.null_count() != 0 || sort.nulls_first {
            return Ok(None);
        }
        let Some(sort_column) = primitive_sort_column(column) else {
            return Ok(None);
        };
        sort_columns.push(sort_column);
        descending.push(sort.descending);
    }
    if !batch.columns().iter().all(|column| {
        column.null_count() == 0
            && matches!(
                column.data_type(),
                DataType::Int32
                    | DataType::Int64
                    | DataType::UInt64
                    | DataType::Float64
                    | DataType::Date32
            )
    }) {
        return Ok(None);
    }
    let row_count = u32::try_from(batch.num_rows()).map_err(|_| {
        DodamError::UnsupportedSql("primitive partial sort row count overflow".to_string())
    })?;
    let mut indices = (0..row_count).collect::<Vec<_>>();
    {
        let compare_rows = |left: &u32, right: &u32| {
            let left = *left as usize;
            let right = *right as usize;
            for (column, descending) in sort_columns.iter().zip(&descending) {
                let ordering = column.compare(left, right);
                if ordering != std::cmp::Ordering::Equal {
                    return if *descending {
                        ordering.reverse()
                    } else {
                        ordering
                    };
                }
            }
            left.cmp(&right)
        };
        indices.select_nth_unstable_by(limit, compare_rows);
        indices.truncate(limit);
        indices.sort_unstable_by(compare_rows);
    }
    take_primitive_record_batch_by_raw_indices(batch, &indices).map(Some)
}

fn primitive_sort_column(column: &ArrayRef) -> Option<PrimitiveSortColumn<'_>> {
    match column.data_type() {
        DataType::Int32 => column
            .as_any()
            .downcast_ref::<Int32Array>()
            .map(PrimitiveSortColumn::Int32),
        DataType::Int64 => column
            .as_any()
            .downcast_ref::<Int64Array>()
            .map(PrimitiveSortColumn::Int64),
        DataType::UInt64 => column
            .as_any()
            .downcast_ref::<UInt64Array>()
            .map(PrimitiveSortColumn::UInt64),
        DataType::Float64 => column
            .as_any()
            .downcast_ref::<Float64Array>()
            .map(PrimitiveSortColumn::Float64),
        DataType::Date32 => column
            .as_any()
            .downcast_ref::<Date32Array>()
            .map(PrimitiveSortColumn::Date32),
        _ => None,
    }
}

fn take_primitive_record_batch_by_indices(
    batch: &RecordBatch,
    indices: &UInt32Array,
) -> Result<Option<RecordBatch>> {
    if indices.null_count() != 0 || batch.num_rows() == 0 {
        return Ok(None);
    }
    let mut raw_indices = Vec::with_capacity(indices.len());
    for row in 0..indices.len() {
        raw_indices.push(indices.value(row));
    }
    take_primitive_record_batch_by_raw_indices(batch, &raw_indices).map(Some)
}

fn take_primitive_record_batch_by_raw_indices(
    batch: &RecordBatch,
    raw_indices: &[u32],
) -> Result<RecordBatch> {
    let mut columns = Vec::with_capacity(batch.num_columns());
    for column in batch.columns() {
        let Some(array) = gather_primitive_array(column, &raw_indices) else {
            return Ok(take_record_batch(
                batch,
                &UInt32Array::from(raw_indices.to_vec()),
            )?);
        };
        columns.push(array);
    }
    Ok(RecordBatch::try_new(batch.schema(), columns)?)
}

fn primitive_partial_sort_enabled() -> bool {
    std::env::var("DODAM_ENABLE_PRIMITIVE_PARTIAL_SORT")
        .map(|value| value == "1" || value.eq_ignore_ascii_case("true"))
        .unwrap_or(false)
}

fn limit_batches(
    batches: Vec<RecordBatch>,
    limit: Option<usize>,
    offset: usize,
) -> Vec<RecordBatch> {
    let mut to_skip = offset;
    let mut remaining = limit.unwrap_or(usize::MAX);
    let mut limited = Vec::new();
    for batch in batches {
        if to_skip >= batch.num_rows() {
            to_skip -= batch.num_rows();
            continue;
        }
        let batch = if to_skip > 0 {
            let sliced = batch.slice(to_skip, batch.num_rows() - to_skip);
            to_skip = 0;
            sliced
        } else {
            batch
        };
        if remaining == 0 {
            break;
        }
        let rows = remaining.min(batch.num_rows());
        remaining -= rows;
        if rows > 0 {
            limited.push(batch.slice(0, rows));
        }
    }
    limited
}

fn apply_output_filter(
    batches: Vec<RecordBatch>,
    filter: Option<&FilterExpr>,
) -> Result<Vec<RecordBatch>> {
    let Some(filter) = filter else {
        return Ok(batches);
    };

    let mut filtered = Vec::new();
    for batch in batches {
        let batch = filter_batch(batch, filter)?;
        if batch.num_rows() > 0 {
            filtered.push(batch);
        }
    }
    Ok(filtered)
}

fn apply_output_expression_filter(
    batches: Vec<RecordBatch>,
    predicate: &SqlExpr,
    table_alias: Option<&str>,
) -> Result<Vec<RecordBatch>> {
    let mut filtered = Vec::new();
    for batch in batches {
        let mask = evaluate_scalar_predicate(&batch, predicate, table_alias)?;
        let batch = filter_record_batch(&batch, &mask)?;
        if batch.num_rows() > 0 {
            filtered.push(batch);
        }
    }
    Ok(filtered)
}

fn apply_output_join_expression_filter(
    batches: Vec<RecordBatch>,
    predicate: &SqlExpr,
    table_aliases: &[&str],
) -> Result<Vec<RecordBatch>> {
    let mut filtered = Vec::new();
    for batch in batches {
        let mask = evaluate_join_scalar_predicate(&batch, predicate, table_aliases)?;
        let batch = filter_record_batch(&batch, &mask)?;
        if batch.num_rows() > 0 {
            filtered.push(batch);
        }
    }
    Ok(filtered)
}

fn evaluate_join_scalar_predicate(
    batch: &RecordBatch,
    predicate: &SqlExpr,
    table_aliases: &[&str],
) -> Result<BooleanArray> {
    evaluate_scalar_predicate_with_parser(
        batch,
        predicate,
        ScalarPredicateParser::Join(table_aliases),
    )
}

fn evaluate_scalar_predicate(
    batch: &RecordBatch,
    predicate: &SqlExpr,
    table_alias: Option<&str>,
) -> Result<BooleanArray> {
    evaluate_scalar_predicate_with_parser(
        batch,
        predicate,
        ScalarPredicateParser::Single(table_alias),
    )
}

#[derive(Clone, Copy)]
enum ScalarPredicateParser<'a> {
    Single(Option<&'a str>),
    Join(&'a [&'a str]),
}

impl ScalarPredicateParser<'_> {
    fn parse(self, expr: &SqlExpr) -> Result<ScalarSqlExpression> {
        match self {
            ScalarPredicateParser::Single(table_alias) => {
                parse_scalar_sql_expression(expr, table_alias)
            }
            ScalarPredicateParser::Join(table_aliases) => {
                parse_join_scalar_sql_expression(expr, table_aliases)
            }
        }
    }

    fn unsupported_context(self) -> &'static str {
        match self {
            ScalarPredicateParser::Single(_) => "expression",
            ScalarPredicateParser::Join(_) => "JOIN expression",
        }
    }
}

fn evaluate_scalar_predicate_with_parser(
    batch: &RecordBatch,
    predicate: &SqlExpr,
    parser: ScalarPredicateParser<'_>,
) -> Result<BooleanArray> {
    if let Some(mask) = try_evaluate_vector_scalar_predicate(batch, predicate, parser)? {
        return Ok(mask);
    }
    match predicate {
        SqlExpr::BinaryOp { left, op, right } if *op == BinaryOperator::And => {
            let left = evaluate_scalar_predicate_with_parser(batch, left, parser)?;
            let right = evaluate_scalar_predicate_with_parser(batch, right, parser)?;
            Ok(boolean_and(&left, &right))
        }
        SqlExpr::BinaryOp { left, op, right } if *op == BinaryOperator::Or => {
            let left = evaluate_scalar_predicate_with_parser(batch, left, parser)?;
            let right = evaluate_scalar_predicate_with_parser(batch, right, parser)?;
            Ok(boolean_or(&left, &right))
        }
        SqlExpr::UnaryOp { op, expr } if *op == UnaryOperator::Not => {
            let mask = evaluate_scalar_predicate_with_parser(batch, expr, parser)?;
            Ok(boolean_not(&mask))
        }
        SqlExpr::Nested(expr) => evaluate_scalar_predicate_with_parser(batch, expr, parser),
        SqlExpr::BinaryOp { left, op, right }
            if matches!(
                op,
                BinaryOperator::Eq
                    | BinaryOperator::NotEq
                    | BinaryOperator::Gt
                    | BinaryOperator::GtEq
                    | BinaryOperator::Lt
                    | BinaryOperator::LtEq
            ) =>
        {
            let left = evaluate_scalar_expression(batch, &parser.parse(left)?)?;
            let right = evaluate_scalar_expression(batch, &parser.parse(right)?)?;
            Ok(BooleanArray::from(compare_evaluated_scalars(
                left, op, right,
            )?))
        }
        SqlExpr::IsNull(expr) | SqlExpr::IsNotNull(expr) => {
            let value = evaluate_scalar_expression(batch, &parser.parse(expr)?)?;
            let is_not_null = matches!(predicate, SqlExpr::IsNotNull(_));
            if let EvaluatedScalar::Array(array) = &value {
                return Ok(BooleanArray::from(
                    (0..array.len())
                        .map(|row| {
                            let is_null = array.is_null(row);
                            if is_not_null { !is_null } else { is_null }
                        })
                        .collect::<Vec<_>>(),
                ));
            }
            Ok(BooleanArray::from(
                scalar_null_mask(value)
                    .into_iter()
                    .map(|is_null| Some(if is_not_null { !is_null } else { is_null }))
                    .collect::<Vec<_>>(),
            ))
        }
        SqlExpr::InList {
            expr,
            list,
            negated,
        } => {
            let value = evaluate_scalar_expression(batch, &parser.parse(expr)?)?;
            let values = list
                .iter()
                .map(|expr| evaluate_scalar_expression(batch, &parser.parse(expr)?))
                .collect::<Result<Vec<_>>>()?;
            Ok(BooleanArray::from(evaluate_scalar_in_list(
                value, &values, *negated,
            )?))
        }
        SqlExpr::Between {
            expr,
            negated,
            low,
            high,
        } => {
            let lower = evaluate_scalar_predicate_with_parser(
                batch,
                &SqlExpr::BinaryOp {
                    left: expr.clone(),
                    op: if *negated {
                        BinaryOperator::Lt
                    } else {
                        BinaryOperator::GtEq
                    },
                    right: low.clone(),
                },
                parser,
            )?;
            let upper = evaluate_scalar_predicate_with_parser(
                batch,
                &SqlExpr::BinaryOp {
                    left: expr.clone(),
                    op: if *negated {
                        BinaryOperator::Gt
                    } else {
                        BinaryOperator::LtEq
                    },
                    right: high.clone(),
                },
                parser,
            )?;
            if *negated {
                Ok(boolean_or(&lower, &upper))
            } else {
                Ok(boolean_and(&lower, &upper))
            }
        }
        SqlExpr::Like {
            negated,
            any,
            expr,
            pattern,
            escape_char,
        }
        | SqlExpr::ILike {
            negated,
            any,
            expr,
            pattern,
            escape_char,
        } => {
            if *any {
                return Err(DodamError::UnsupportedSql(
                    "LIKE ANY is not supported".to_string(),
                ));
            }
            let value = scalar_as_utf8(evaluate_scalar_expression(batch, &parser.parse(expr)?)?)?;
            let case_insensitive = matches!(predicate, SqlExpr::ILike { .. });
            let mut pattern = sql_like_pattern(pattern)?;
            if case_insensitive {
                pattern = pattern.to_lowercase();
            }
            let escape = sql_like_escape(escape_char)?;
            let tokens = scalar_like_pattern_tokens(&pattern, escape)?;
            Ok(BooleanArray::from(
                value
                    .into_iter()
                    .map(|value| {
                        value.map(|value| {
                            let normalized_value;
                            let value = if case_insensitive {
                                normalized_value = value.to_lowercase();
                                normalized_value.as_str()
                            } else {
                                value.as_str()
                            };
                            let matched = scalar_like_matches(value, &tokens);
                            if *negated { !matched } else { matched }
                        })
                    })
                    .collect::<Vec<_>>(),
            ))
        }
        _ => Err(DodamError::UnsupportedSql(format!(
            "unsupported {} WHERE predicate: {predicate}",
            parser.unsupported_context()
        ))),
    }
}

fn try_evaluate_vector_scalar_predicate(
    batch: &RecordBatch,
    predicate: &SqlExpr,
    parser: ScalarPredicateParser<'_>,
) -> Result<Option<BooleanArray>> {
    match predicate {
        SqlExpr::BinaryOp { left, op, right }
            if matches!(
                op,
                BinaryOperator::Eq
                    | BinaryOperator::NotEq
                    | BinaryOperator::Gt
                    | BinaryOperator::GtEq
                    | BinaryOperator::Lt
                    | BinaryOperator::LtEq
            ) =>
        {
            let left = parser.parse(left)?;
            let right = parser.parse(right)?;
            if let Some(mask) = vector_list_length_literal_compare(batch, &left, op, &right)? {
                return Ok(Some(mask));
            }
            if let Some(mask) = vector_list_length_literal_compare(
                batch,
                &right,
                &reverse_binary_operator(op),
                &left,
            )? {
                return Ok(Some(mask));
            }
            if let Some(mask) = vector_column_literal_compare(batch, &left, op, &right)? {
                return Ok(Some(mask));
            }
            if let Some(mask) =
                vector_column_literal_compare(batch, &right, &reverse_binary_operator(op), &left)?
            {
                return Ok(Some(mask));
            }
            Ok(None)
        }
        SqlExpr::InList {
            expr,
            list,
            negated,
        } => {
            let expr = parser.parse(expr)?;
            let values = list
                .iter()
                .map(|expr| parser.parse(expr))
                .collect::<Result<Vec<_>>>()?;
            vector_i64_expression_in_list(batch, &expr, &values, *negated)
        }
        SqlExpr::Like {
            negated,
            any,
            expr,
            pattern,
            escape_char,
        }
        | SqlExpr::ILike {
            negated,
            any,
            expr,
            pattern,
            escape_char,
        } => {
            if *any {
                return Ok(None);
            }
            let expr = parser.parse(expr)?;
            let case_insensitive = matches!(predicate, SqlExpr::ILike { .. });
            vector_string_like_literal(
                batch,
                &expr,
                pattern,
                sql_like_escape(escape_char)?,
                *negated,
                case_insensitive,
            )
        }
        _ => Ok(None),
    }
}

fn reverse_binary_operator(op: &BinaryOperator) -> BinaryOperator {
    match op {
        BinaryOperator::Gt => BinaryOperator::Lt,
        BinaryOperator::GtEq => BinaryOperator::LtEq,
        BinaryOperator::Lt => BinaryOperator::Gt,
        BinaryOperator::LtEq => BinaryOperator::GtEq,
        _ => op.clone(),
    }
}

fn vector_list_length_literal_compare(
    batch: &RecordBatch,
    left: &ScalarSqlExpression,
    op: &BinaryOperator,
    right: &ScalarSqlExpression,
) -> Result<Option<BooleanArray>> {
    let ScalarSqlExpression::ListLength { column, field } = left else {
        return Ok(None);
    };
    let Some(literal) = scalar_i64_literal(right) else {
        return Ok(None);
    };
    let list = list_array_column(batch, column, field.as_deref())?;
    Ok(Some(BooleanArray::from(
        (0..list.len())
            .map(|row| {
                if list.is_null(row) {
                    None
                } else {
                    compare_optional_values(
                        Some(i64::from(list.value_length(row))),
                        op,
                        Some(literal),
                    )
                }
            })
            .collect::<Vec<_>>(),
    )))
}

fn vector_column_literal_compare(
    batch: &RecordBatch,
    left: &ScalarSqlExpression,
    op: &BinaryOperator,
    right: &ScalarSqlExpression,
) -> Result<Option<BooleanArray>> {
    let ScalarSqlExpression::Column(column) = left else {
        return Ok(None);
    };
    let ScalarSqlExpression::Literal(literal) = right else {
        return Ok(None);
    };
    if matches!(literal, LiteralValue::Null) {
        return Ok(Some(BooleanArray::from(vec![None; batch.num_rows()])));
    }
    let column_index = output_batch_column_index(batch, column)?;
    let array = batch.column(column_index);
    match array.data_type() {
        DataType::Int32 => {
            let values = array.as_any().downcast_ref::<Int32Array>().expect("Int32");
            let literal = literal_as_i64_for_type(literal)?;
            if values.null_count() == 0 {
                return Ok(Some(BooleanArray::from(
                    (0..values.len())
                        .map(|row| {
                            compare_optional_values(Some(i64::from(values.value(row))), op, literal)
                                .unwrap_or(false)
                        })
                        .collect::<Vec<_>>(),
                )));
            }
            Ok(Some(BooleanArray::from(
                (0..values.len())
                    .map(|row| {
                        if values.is_null(row) {
                            None
                        } else {
                            compare_optional_values(Some(i64::from(values.value(row))), op, literal)
                        }
                    })
                    .collect::<Vec<_>>(),
            )))
        }
        DataType::Int64 => {
            let values = array.as_any().downcast_ref::<Int64Array>().expect("Int64");
            let literal = literal_as_i64_for_type(literal)?;
            if values.null_count() == 0 {
                return Ok(Some(BooleanArray::from(
                    (0..values.len())
                        .map(|row| {
                            compare_optional_values(Some(values.value(row)), op, literal)
                                .unwrap_or(false)
                        })
                        .collect::<Vec<_>>(),
                )));
            }
            Ok(Some(BooleanArray::from(
                (0..values.len())
                    .map(|row| {
                        if values.is_null(row) {
                            None
                        } else {
                            compare_optional_values(Some(values.value(row)), op, literal)
                        }
                    })
                    .collect::<Vec<_>>(),
            )))
        }
        DataType::Float64 => {
            let values = array
                .as_any()
                .downcast_ref::<Float64Array>()
                .expect("Float64");
            let literal = literal_as_f64_for_type(literal)?;
            if values.null_count() == 0 {
                return Ok(Some(BooleanArray::from(
                    (0..values.len())
                        .map(|row| {
                            compare_optional_f64(Some(values.value(row)), op, literal)
                                .unwrap_or(false)
                        })
                        .collect::<Vec<_>>(),
                )));
            }
            Ok(Some(BooleanArray::from(
                (0..values.len())
                    .map(|row| {
                        if values.is_null(row) {
                            None
                        } else {
                            compare_optional_f64(Some(values.value(row)), op, literal)
                        }
                    })
                    .collect::<Vec<_>>(),
            )))
        }
        DataType::Boolean => {
            let values = array
                .as_any()
                .downcast_ref::<BooleanArray>()
                .expect("Boolean");
            let literal = literal_as_bool_for_type(literal)?;
            if values.null_count() == 0 {
                return Ok(Some(BooleanArray::from(
                    (0..values.len())
                        .map(|row| {
                            compare_optional_values(Some(values.value(row)), op, literal)
                                .unwrap_or(false)
                        })
                        .collect::<Vec<_>>(),
                )));
            }
            Ok(Some(BooleanArray::from(
                (0..values.len())
                    .map(|row| {
                        if values.is_null(row) {
                            None
                        } else {
                            compare_optional_values(Some(values.value(row)), op, literal)
                        }
                    })
                    .collect::<Vec<_>>(),
            )))
        }
        DataType::Date32 => {
            let values = array
                .as_any()
                .downcast_ref::<Date32Array>()
                .expect("Date32");
            let literal = literal_as_date32_for_type(literal)?;
            if values.null_count() == 0 {
                return Ok(Some(BooleanArray::from(
                    (0..values.len())
                        .map(|row| {
                            compare_optional_values(Some(values.value(row)), op, literal)
                                .unwrap_or(false)
                        })
                        .collect::<Vec<_>>(),
                )));
            }
            Ok(Some(BooleanArray::from(
                (0..values.len())
                    .map(|row| {
                        if values.is_null(row) {
                            None
                        } else {
                            compare_optional_values(Some(values.value(row)), op, literal)
                        }
                    })
                    .collect::<Vec<_>>(),
            )))
        }
        DataType::Decimal128(precision, scale) => {
            let values = array
                .as_any()
                .downcast_ref::<Decimal128Array>()
                .expect("Decimal128");
            let literal = literal_as_decimal128_for_type(literal, *precision, *scale)?;
            if values.null_count() == 0 {
                return Ok(Some(BooleanArray::from(
                    (0..values.len())
                        .map(|row| {
                            compare_optional_values(Some(values.value(row)), op, literal)
                                .unwrap_or(false)
                        })
                        .collect::<Vec<_>>(),
                )));
            }
            Ok(Some(BooleanArray::from(
                (0..values.len())
                    .map(|row| {
                        if values.is_null(row) {
                            None
                        } else {
                            compare_optional_values(Some(values.value(row)), op, literal)
                        }
                    })
                    .collect::<Vec<_>>(),
            )))
        }
        DataType::Utf8 => {
            let values = array.as_any().downcast_ref::<StringArray>().expect("Utf8");
            let literal = literal_as_utf8_for_type(literal)?;
            Ok(Some(BooleanArray::from(
                (0..values.len())
                    .map(|row| {
                        if values.is_null(row) {
                            None
                        } else {
                            compare_optional_values(
                                Some(values.value(row).to_string()),
                                op,
                                literal.clone(),
                            )
                        }
                    })
                    .collect::<Vec<_>>(),
            )))
        }
        _ => Ok(None),
    }
}

fn vector_i64_expression_in_list(
    batch: &RecordBatch,
    expr: &ScalarSqlExpression,
    values: &[ScalarSqlExpression],
    negated: bool,
) -> Result<Option<BooleanArray>> {
    let Some(probe) = vector_i64_expression(batch, expr)? else {
        return Ok(None);
    };
    let mut literals = Vec::new();
    let mut has_null = false;
    for value in values {
        match scalar_i64_literal(value) {
            Some(value) => literals.push(value),
            None if matches!(value, ScalarSqlExpression::Literal(LiteralValue::Null)) => {
                has_null = true
            }
            None => return Ok(None),
        }
    }
    Ok(Some(BooleanArray::from(
        probe
            .into_iter()
            .map(|value| {
                let Some(value) = value else {
                    return None;
                };
                let matched = literals.contains(&value);
                if matched {
                    Some(!negated)
                } else if has_null {
                    None
                } else {
                    Some(negated)
                }
            })
            .collect::<Vec<_>>(),
    )))
}

fn vector_i64_expression(
    batch: &RecordBatch,
    expr: &ScalarSqlExpression,
) -> Result<Option<Vec<Option<i64>>>> {
    match expr {
        ScalarSqlExpression::Column(column) => vector_i64_array(batch_column(batch, column)?),
        ScalarSqlExpression::StructField { column, field } => {
            vector_i64_array(struct_field_array(batch, column, field)?)
        }
        _ => Ok(None),
    }
}

#[derive(Clone, Copy)]
enum SimpleLikeLiteral<'a> {
    Exact(&'a str),
    Prefix(&'a str),
    Suffix(&'a str),
    Contains(&'a str),
}

fn vector_string_like_literal(
    batch: &RecordBatch,
    expr: &ScalarSqlExpression,
    pattern: &SqlExpr,
    escape: Option<char>,
    negated: bool,
    case_insensitive: bool,
) -> Result<Option<BooleanArray>> {
    let ScalarSqlExpression::Column(column) = expr else {
        return Ok(None);
    };
    let pattern = sql_like_pattern(pattern)?;
    let Some(pattern) = simple_like_literal(&pattern, escape) else {
        return Ok(None);
    };
    let values = batch_column(batch, column)?;
    let Some(values) = values.as_any().downcast_ref::<StringArray>() else {
        return Ok(None);
    };
    Ok(Some(BooleanArray::from(
        (0..values.len())
            .map(|row| {
                if values.is_null(row) {
                    return None;
                }
                let matched = simple_like_matches(values.value(row), pattern, case_insensitive);
                Some(if negated { !matched } else { matched })
            })
            .collect::<Vec<_>>(),
    )))
}

fn simple_like_literal(pattern: &str, escape: Option<char>) -> Option<SimpleLikeLiteral<'_>> {
    if escape.is_some() || pattern.as_bytes().contains(&b'_') {
        return None;
    }
    let percent_count = pattern
        .as_bytes()
        .iter()
        .filter(|byte| **byte == b'%')
        .count();
    match percent_count {
        0 => Some(SimpleLikeLiteral::Exact(pattern)),
        1 if pattern.ends_with('%') => {
            Some(SimpleLikeLiteral::Prefix(&pattern[..pattern.len() - 1]))
        }
        1 if pattern.starts_with('%') => Some(SimpleLikeLiteral::Suffix(&pattern[1..])),
        2 if pattern.starts_with('%') && pattern.ends_with('%') => {
            Some(SimpleLikeLiteral::Contains(&pattern[1..pattern.len() - 1]))
        }
        _ => None,
    }
}

fn simple_like_matches(
    value: &str,
    pattern: SimpleLikeLiteral<'_>,
    case_insensitive: bool,
) -> bool {
    if case_insensitive {
        let value = value.to_lowercase();
        return match pattern {
            SimpleLikeLiteral::Exact(pattern) => value == pattern.to_lowercase(),
            SimpleLikeLiteral::Prefix(pattern) => value.starts_with(&pattern.to_lowercase()),
            SimpleLikeLiteral::Suffix(pattern) => value.ends_with(&pattern.to_lowercase()),
            SimpleLikeLiteral::Contains(pattern) => value.contains(&pattern.to_lowercase()),
        };
    }
    match pattern {
        SimpleLikeLiteral::Exact(pattern) => value == pattern,
        SimpleLikeLiteral::Prefix(pattern) => value.starts_with(pattern),
        SimpleLikeLiteral::Suffix(pattern) => value.ends_with(pattern),
        SimpleLikeLiteral::Contains(pattern) => value.contains(pattern),
    }
}

fn vector_i64_array(array: &dyn Array) -> Result<Option<Vec<Option<i64>>>> {
    match array.data_type() {
        DataType::Int32 => {
            let values = array.as_any().downcast_ref::<Int32Array>().expect("Int32");
            if values.null_count() == 0 {
                Ok(Some(
                    values
                        .values()
                        .iter()
                        .map(|value| Some(i64::from(*value)))
                        .collect(),
                ))
            } else {
                Ok(Some(
                    values.iter().map(|value| value.map(i64::from)).collect(),
                ))
            }
        }
        DataType::Int64 => {
            let values = array.as_any().downcast_ref::<Int64Array>().expect("Int64");
            if values.null_count() == 0 {
                Ok(Some(
                    values.values().iter().map(|value| Some(*value)).collect(),
                ))
            } else {
                Ok(Some(values.iter().collect()))
            }
        }
        _ => Ok(None),
    }
}

fn scalar_i64_literal(expr: &ScalarSqlExpression) -> Option<i64> {
    match expr {
        ScalarSqlExpression::Literal(LiteralValue::Int64(value)) => Some(*value),
        _ => None,
    }
}

fn boolean_and(left: &BooleanArray, right: &BooleanArray) -> BooleanArray {
    BooleanArray::from(
        (0..left.len())
            .map(
                |row| match (boolean_value(left, row), boolean_value(right, row)) {
                    (Some(false), _) | (_, Some(false)) => Some(false),
                    (Some(true), Some(true)) => Some(true),
                    _ => None,
                },
            )
            .collect::<Vec<_>>(),
    )
}

fn boolean_or(left: &BooleanArray, right: &BooleanArray) -> BooleanArray {
    BooleanArray::from(
        (0..left.len())
            .map(
                |row| match (boolean_value(left, row), boolean_value(right, row)) {
                    (Some(true), _) | (_, Some(true)) => Some(true),
                    (Some(false), Some(false)) => Some(false),
                    _ => None,
                },
            )
            .collect::<Vec<_>>(),
    )
}

fn boolean_not(mask: &BooleanArray) -> BooleanArray {
    BooleanArray::from(
        (0..mask.len())
            .map(|row| boolean_value(mask, row).map(|value| !value))
            .collect::<Vec<_>>(),
    )
}

fn boolean_value(mask: &BooleanArray, row: usize) -> Option<bool> {
    if mask.is_null(row) {
        None
    } else {
        Some(mask.value(row))
    }
}

fn apply_output_projection(
    batches: Vec<RecordBatch>,
    projection: &Projection,
) -> Result<Vec<RecordBatch>> {
    let Projection::Columns(columns) = projection else {
        return Ok(batches);
    };

    batches
        .into_iter()
        .map(|batch| {
            if projection_matches_batch_schema(&batch, columns) {
                return Ok(batch);
            }
            let indices = columns
                .iter()
                .map(|column| output_batch_column_index(&batch, column))
                .collect::<Result<Vec<_>>>()?;
            Ok(batch.project(&indices)?)
        })
        .collect()
}

fn projection_matches_batch_schema(batch: &RecordBatch, columns: &[String]) -> bool {
    batch.num_columns() == columns.len()
        && batch
            .schema()
            .fields()
            .iter()
            .zip(columns)
            .all(|(field, column)| field.name() == column)
}

fn apply_qualified_wildcard_projection(
    batches: Vec<RecordBatch>,
    qualified_wildcards: &[String],
    projection: &Projection,
) -> Result<Vec<RecordBatch>> {
    if batches.is_empty() {
        return Ok(batches);
    }
    batches
        .into_iter()
        .map(|batch| {
            let mut columns = Vec::new();
            for qualifier in qualified_wildcards {
                let prefix = format!("{qualifier}.");
                for field in batch.schema().fields() {
                    if field.name().starts_with(&prefix) {
                        add_column_once(&mut columns, field.name().clone());
                    }
                }
            }
            if let Projection::Columns(projected) = projection {
                for column in projected {
                    add_column_once(&mut columns, column.clone());
                }
            }
            if columns.is_empty() {
                return Err(DodamError::UnsupportedSql(
                    "qualified wildcard did not match any output columns".to_string(),
                ));
            }
            let indices = columns
                .iter()
                .map(|column| output_batch_column_index(&batch, column))
                .collect::<Result<Vec<_>>>()?;
            Ok(batch.project(&indices)?)
        })
        .collect()
}

fn output_batch_column_index(batch: &RecordBatch, column: &str) -> Result<usize> {
    if let Some(bound) = resolve_batch_column(batch, column)? {
        return batch_column_index(batch, &bound.physical_name);
    }
    Err(DodamError::UnknownColumn(column.to_string()))
}

fn apply_output_expression_projection(
    batches: Vec<RecordBatch>,
    expressions: &[ProjectionExpression],
) -> Result<Vec<RecordBatch>> {
    if expressions.is_empty() {
        return Ok(batches);
    }
    batches
        .into_iter()
        .map(|batch| {
            let mut fields = Vec::with_capacity(expressions.len());
            let mut columns = Vec::with_capacity(expressions.len());
            for expression in expressions {
                let value = evaluate_scalar_expression(&batch, &expression.expr)?;
                fields.push(Field::new(
                    expression.output_name.clone(),
                    value.data_type(),
                    value.is_nullable(),
                ));
                columns.push(value.into_array(batch.num_rows()));
            }
            Ok(RecordBatch::try_new(
                Arc::new(Schema::new(fields)),
                columns,
            )?)
        })
        .collect()
}

fn append_aggregate_expression_columns(
    batches: Vec<RecordBatch>,
    expressions: &[ProjectionExpression],
) -> Result<Vec<RecordBatch>> {
    if expressions.is_empty() {
        return Ok(batches);
    }
    batches
        .into_iter()
        .map(|batch| append_aggregate_expression_batch(batch, expressions))
        .collect()
}

fn append_aggregate_expression_stream(
    stream: SendableBatchStream,
    expressions: Vec<ProjectionExpression>,
) -> SendableBatchStream {
    if expressions.is_empty() {
        return stream;
    }
    let (inner, metrics) = stream.into_parts();
    SendableBatchStream::new(
        Box::new(inner.map(move |batch| append_aggregate_expression_batch(batch?, &expressions))),
        metrics,
    )
}

fn append_aggregate_expression_batch(
    batch: RecordBatch,
    expressions: &[ProjectionExpression],
) -> Result<RecordBatch> {
    if expressions.is_empty() {
        return Ok(batch);
    }
    let mut fields = batch.schema().fields().to_vec();
    let mut columns = batch.columns().to_vec();
    for expression in expressions {
        let value = evaluate_scalar_expression(&batch, &expression.expr)?;
        fields.push(Arc::new(Field::new(
            expression.output_name.clone(),
            value.data_type(),
            value.is_nullable(),
        )));
        columns.push(value.into_array(batch.num_rows()));
    }
    Ok(RecordBatch::try_new(
        Arc::new(Schema::new(fields)),
        columns,
    )?)
}

fn collect_aggregates_with_optional_expression_views(
    stream: SendableBatchStream,
    fragments: usize,
    group_by: &[String],
    aggregates: &[AggregateExpr],
    filtered_aggregates: &[NativeFilteredAggregateSpec],
    expressions: &[ProjectionExpression],
) -> Result<AggregateMetrics> {
    let started = generic_profile_start();
    if group_by.len() <= 1 && !filtered_aggregates.is_empty() {
        let metrics = collect_native_filtered_aggregates(
            stream,
            fragments,
            group_by,
            filtered_aggregates.to_vec(),
        )?;
        generic_profile_elapsed("aggregate filtered", started);
        return Ok(metrics);
    }
    if group_by.len() <= 1
        && let Some(specs) = legacy_case_filtered_aggregate_specs(aggregates, expressions)
    {
        let metrics = collect_native_filtered_aggregates(stream, fragments, group_by, specs)?;
        generic_profile_elapsed("aggregate legacy case filtered", started);
        return Ok(metrics);
    }
    let started = generic_profile_start();
    if group_by.is_empty() {
        let stream = append_aggregate_expression_stream(stream, expressions.to_vec());
        let metrics = collect_aggregates(stream, fragments, aggregates)?;
        generic_profile_elapsed("aggregate global append/fold", started);
        return Ok(metrics);
    }
    if let Some(group_key_exprs) = group_key_exprs_for_aggregate(group_by, aggregates, expressions)
    {
        let metrics = collect_grouped_aggregates_with_key_exprs(
            stream,
            fragments,
            &group_key_exprs,
            aggregates,
        )?
        .expect("expression-view aggregate precondition");
        generic_profile_elapsed("aggregate grouped expression-view", started);
        return Ok(metrics);
    }
    let stream = append_aggregate_expression_stream(stream, expressions.to_vec());
    let metrics = collect_grouped_aggregates(stream, fragments, group_by, aggregates)?;
    generic_profile_elapsed("aggregate grouped append/fold", started);
    Ok(metrics)
}

#[derive(Debug, Clone, PartialEq)]
struct NativeFilteredAggregateSpec {
    expr: AggregateExpr,
    condition: SqlExpr,
    input: ScalarSqlExpression,
    input_kind: NativeFilteredInputKind,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum NativeFilteredInputKind {
    AlwaysSome,
    Nullable,
}

#[derive(Clone)]
enum NativeFilteredAggregateState {
    Count(u64),
    SumI64 { sum: i64, count: u64 },
    AvgI64 { sum: i64, count: u64 },
    MinI64(Option<i64>),
    MaxI64(Option<i64>),
}

fn collect_native_filtered_aggregates(
    mut stream: SendableBatchStream,
    fragments: usize,
    group_by: &[String],
    specs: Vec<NativeFilteredAggregateSpec>,
) -> Result<AggregateMetrics> {
    let started = Instant::now();
    let mut metrics = AggregateMetrics {
        fragments,
        ..AggregateMetrics::default()
    };
    if group_by.is_empty() {
        let mut states = native_filtered_initial_states(&specs);
        for batch in stream.by_ref() {
            let batch = batch?;
            if batch.num_rows() == 0 {
                continue;
            }
            metrics.batches += 1;
            metrics.rows += batch.num_rows();
            native_filtered_update_states(&batch, &specs, &mut states)?;
        }
        metrics.values = native_filtered_finish_states(&specs, states);
        metrics.aggregate_nanos = elapsed_micros_to_nanos(started.elapsed());
        return Ok(metrics);
    }
    debug_assert_eq!(group_by.len(), 1);
    let group_column = &group_by[0];
    const MAX_DENSE_GROUP_KEY: usize = 1_000_000;
    let mut dense: Vec<Option<Vec<NativeFilteredAggregateState>>> = Vec::new();
    let mut null_i64_group: Option<Vec<NativeFilteredAggregateState>> = None;
    let mut groups: HashMap<GroupValue, Vec<NativeFilteredAggregateState>> = HashMap::new();
    for batch in stream.by_ref() {
        let batch = batch?;
        if batch.num_rows() == 0 {
            continue;
        }
        metrics.batches += 1;
        metrics.rows += batch.num_rows();
        let group_values = evaluated_column(&batch, group_column)?;
        let group_keys = NativeFilteredGroupKeys::new(&group_values);
        let masks = native_filtered_batch_masks(&batch, &specs)?;
        let inputs = native_filtered_batch_inputs(&batch, &specs)?;
        for row in 0..batch.num_rows() {
            let states = if group_keys.is_i64_like() {
                match group_keys.i64_key_at(row)? {
                    None => {
                        null_i64_group.get_or_insert_with(|| native_filtered_initial_states(&specs))
                    }
                    Some(key) if key >= 0 && (key as usize) <= MAX_DENSE_GROUP_KEY => {
                        let index = key as usize;
                        if dense.len() <= index {
                            dense.resize_with(index + 1, || None);
                        }
                        dense[index].get_or_insert_with(|| native_filtered_initial_states(&specs))
                    }
                    Some(key) => groups
                        .entry(GroupValue::Int64(Some(key)))
                        .or_insert_with(|| native_filtered_initial_states(&specs)),
                }
            } else {
                let key = native_group_value_at(&group_values, row)?;
                groups
                    .entry(key)
                    .or_insert_with(|| native_filtered_initial_states(&specs))
            };
            for (index, ((spec, mask), input)) in specs.iter().zip(&masks).zip(&inputs).enumerate()
            {
                if mask.selected(row) {
                    native_filtered_update_state(&mut states[index], spec, input, row)?;
                }
            }
        }
    }
    metrics.groups = groups
        .into_iter()
        .map(|(key, states)| GroupAggregateResult {
            keys: vec![key],
            values: native_filtered_finish_states(&specs, states),
        })
        .collect();
    if let Some(states) = null_i64_group {
        metrics.groups.push(GroupAggregateResult {
            keys: vec![GroupValue::Int64(None)],
            values: native_filtered_finish_states(&specs, states),
        });
    }
    metrics
        .groups
        .extend(dense.into_iter().enumerate().filter_map(|(key, states)| {
            states.map(|states| GroupAggregateResult {
                keys: vec![GroupValue::Int64(Some(key as i64))],
                values: native_filtered_finish_states(&specs, states),
            })
        }));
    metrics
        .groups
        .sort_by(|left, right| compare_native_group_keys(&left.keys, &right.keys));
    metrics.aggregate_nanos = elapsed_micros_to_nanos(started.elapsed());
    Ok(metrics)
}

enum NativeFilteredGroupKeys {
    I32(Int32Array),
    I64(Int64Array),
    Other,
}

impl NativeFilteredGroupKeys {
    fn new(value: &EvaluatedScalar) -> Self {
        let EvaluatedScalar::Array(array) = value else {
            return Self::Other;
        };
        if let Some(values) = array.as_any().downcast_ref::<Int32Array>() {
            return Self::I32(values.clone());
        }
        if let Some(values) = array.as_any().downcast_ref::<Int64Array>() {
            return Self::I64(values.clone());
        }
        Self::Other
    }

    fn is_i64_like(&self) -> bool {
        !matches!(self, Self::Other)
    }

    fn i64_key_at(&self, row: usize) -> Result<Option<i64>> {
        Ok(match self {
            Self::I32(values) => {
                if values.is_null(row) {
                    None
                } else {
                    Some(i64::from(values.value(row)))
                }
            }
            Self::I64(values) => {
                if values.is_null(row) {
                    None
                } else {
                    Some(values.value(row))
                }
            }
            Self::Other => {
                return Err(DodamError::UnsupportedSql(
                    "native filtered aggregate expected integer group key".to_string(),
                ));
            }
        })
    }
}

fn compare_native_group_keys(left: &[GroupValue], right: &[GroupValue]) -> std::cmp::Ordering {
    left.iter()
        .zip(right)
        .map(|(left, right)| compare_native_group_value(left, right))
        .find(|ordering| *ordering != std::cmp::Ordering::Equal)
        .unwrap_or_else(|| left.len().cmp(&right.len()))
}

fn compare_native_group_value(left: &GroupValue, right: &GroupValue) -> std::cmp::Ordering {
    use std::cmp::Ordering;
    match (left, right) {
        (GroupValue::Int64(None), GroupValue::Int64(None)) => Ordering::Equal,
        (GroupValue::Int64(None), GroupValue::Int64(_)) => Ordering::Less,
        (GroupValue::Int64(_), GroupValue::Int64(None)) => Ordering::Greater,
        (GroupValue::Int64(Some(left)), GroupValue::Int64(Some(right))) => left.cmp(right),
        (GroupValue::Utf8(None), GroupValue::Utf8(None)) => Ordering::Equal,
        (GroupValue::Utf8(None), GroupValue::Utf8(_)) => Ordering::Less,
        (GroupValue::Utf8(_), GroupValue::Utf8(None)) => Ordering::Greater,
        (GroupValue::Utf8(Some(left)), GroupValue::Utf8(Some(right))) => left.cmp(right),
        (GroupValue::Date32(None), GroupValue::Date32(None)) => Ordering::Equal,
        (GroupValue::Date32(None), GroupValue::Date32(_)) => Ordering::Less,
        (GroupValue::Date32(_), GroupValue::Date32(None)) => Ordering::Greater,
        (GroupValue::Date32(Some(left)), GroupValue::Date32(Some(right))) => left.cmp(right),
        _ => Ordering::Equal,
    }
}

fn elapsed_micros_to_nanos(duration: Duration) -> u64 {
    duration.as_nanos().min(u128::from(u64::MAX)) as u64
}

fn legacy_case_filtered_aggregate_specs(
    aggregates: &[AggregateExpr],
    expressions: &[ProjectionExpression],
) -> Option<Vec<NativeFilteredAggregateSpec>> {
    if aggregates.is_empty() || expressions.is_empty() {
        return None;
    }
    let mut specs = Vec::with_capacity(aggregates.len());
    for aggregate in aggregates {
        let column = aggregate.referenced_column()?;
        let expression = expressions
            .iter()
            .find(|expression| expression.output_name == column)?;
        let ScalarSqlExpression::Case {
            conditions,
            results,
            else_result,
        } = &expression.expr
        else {
            return None;
        };
        let ([condition], [input], None) = (
            conditions.as_slice(),
            results.as_slice(),
            else_result.as_deref(),
        ) else {
            return None;
        };
        if !matches!(
            aggregate,
            AggregateExpr::Count(_)
                | AggregateExpr::Sum(_)
                | AggregateExpr::Avg(_)
                | AggregateExpr::Min(_)
                | AggregateExpr::Max(_)
        ) {
            return None;
        }
        specs.push(NativeFilteredAggregateSpec {
            expr: aggregate.clone(),
            condition: condition.clone(),
            input: input.clone(),
            input_kind: native_filtered_input_kind(aggregate, input),
        });
    }
    Some(specs)
}

fn native_filtered_input_kind(
    aggregate: &AggregateExpr,
    input: &ScalarSqlExpression,
) -> NativeFilteredInputKind {
    match aggregate {
        AggregateExpr::Count(_)
            if matches!(
                input,
                ScalarSqlExpression::Literal(LiteralValue::Boolean(_))
                    | ScalarSqlExpression::Literal(LiteralValue::Int64(_))
                    | ScalarSqlExpression::Literal(LiteralValue::Float64(_))
                    | ScalarSqlExpression::Literal(LiteralValue::Utf8(_))
            ) =>
        {
            NativeFilteredInputKind::AlwaysSome
        }
        _ => NativeFilteredInputKind::Nullable,
    }
}

fn native_filtered_initial_states(
    specs: &[NativeFilteredAggregateSpec],
) -> Vec<NativeFilteredAggregateState> {
    specs
        .iter()
        .map(|spec| match spec.expr {
            AggregateExpr::Count(_) => NativeFilteredAggregateState::Count(0),
            AggregateExpr::Sum(_) => NativeFilteredAggregateState::SumI64 { sum: 0, count: 0 },
            AggregateExpr::Avg(_) => NativeFilteredAggregateState::AvgI64 { sum: 0, count: 0 },
            AggregateExpr::Min(_) => NativeFilteredAggregateState::MinI64(None),
            AggregateExpr::Max(_) => NativeFilteredAggregateState::MaxI64(None),
            _ => unreachable!("validated native filtered aggregate"),
        })
        .collect()
}

fn native_filtered_update_states(
    batch: &RecordBatch,
    specs: &[NativeFilteredAggregateSpec],
    states: &mut [NativeFilteredAggregateState],
) -> Result<()> {
    let masks = native_filtered_batch_masks(batch, specs)?;
    let inputs = native_filtered_batch_inputs(batch, specs)?;
    for row in 0..batch.num_rows() {
        for (index, spec) in specs.iter().enumerate() {
            if masks[index].selected(row) {
                native_filtered_update_state(&mut states[index], spec, &inputs[index], row)?;
            }
        }
    }
    Ok(())
}

struct NativeFilteredBatchMask {
    mask: BooleanArray,
    nullable: bool,
}

impl NativeFilteredBatchMask {
    fn new(mask: BooleanArray) -> Self {
        let nullable = mask.null_count() > 0;
        Self { mask, nullable }
    }

    fn selected(&self, row: usize) -> bool {
        if self.nullable {
            self.mask.is_valid(row) && self.mask.value(row)
        } else {
            self.mask.value(row)
        }
    }
}

fn native_filtered_batch_masks(
    batch: &RecordBatch,
    specs: &[NativeFilteredAggregateSpec],
) -> Result<Vec<NativeFilteredBatchMask>> {
    specs
        .iter()
        .map(|spec| {
            evaluate_scalar_predicate(batch, &spec.condition, None)
                .map(NativeFilteredBatchMask::new)
        })
        .collect()
}

enum NativeFilteredBatchInput {
    AlwaysSome,
    NonNull,
    I64Array(Int64Array),
    I32Array(Int32Array),
    Other(EvaluatedScalar),
}

fn native_filtered_batch_inputs(
    batch: &RecordBatch,
    specs: &[NativeFilteredAggregateSpec],
) -> Result<Vec<NativeFilteredBatchInput>> {
    specs
        .iter()
        .map(|spec| native_filtered_batch_input(batch, spec))
        .collect()
}

fn native_filtered_batch_input(
    batch: &RecordBatch,
    spec: &NativeFilteredAggregateSpec,
) -> Result<NativeFilteredBatchInput> {
    if spec.input_kind == NativeFilteredInputKind::AlwaysSome {
        return Ok(NativeFilteredBatchInput::AlwaysSome);
    }
    let value = evaluate_scalar_expression(batch, &spec.input)?;
    match (&spec.expr, &value) {
        (AggregateExpr::Count(_), EvaluatedScalar::Array(array)) if array.null_count() == 0 => {
            Ok(NativeFilteredBatchInput::NonNull)
        }
        (
            AggregateExpr::Sum(_)
            | AggregateExpr::Avg(_)
            | AggregateExpr::Min(_)
            | AggregateExpr::Max(_),
            EvaluatedScalar::Array(array),
        ) if array.data_type() == &DataType::Int64 => Ok(NativeFilteredBatchInput::I64Array(
            array
                .as_any()
                .downcast_ref::<Int64Array>()
                .expect("Int64")
                .clone(),
        )),
        (
            AggregateExpr::Sum(_)
            | AggregateExpr::Avg(_)
            | AggregateExpr::Min(_)
            | AggregateExpr::Max(_),
            EvaluatedScalar::Array(array),
        ) if array.data_type() == &DataType::Int32 => Ok(NativeFilteredBatchInput::I32Array(
            array
                .as_any()
                .downcast_ref::<Int32Array>()
                .expect("Int32")
                .clone(),
        )),
        _ => Ok(NativeFilteredBatchInput::Other(value)),
    }
}

fn native_filtered_update_state(
    state: &mut NativeFilteredAggregateState,
    spec: &NativeFilteredAggregateSpec,
    input: &NativeFilteredBatchInput,
    row: usize,
) -> Result<()> {
    match state {
        NativeFilteredAggregateState::Count(count) => {
            if native_filtered_input_is_some(input, row)? {
                *count += 1;
            }
        }
        NativeFilteredAggregateState::SumI64 { sum, count }
        | NativeFilteredAggregateState::AvgI64 { sum, count } => {
            if let Some(value) = native_filtered_input_i64(input, row)? {
                *sum += value;
                *count += 1;
            }
        }
        NativeFilteredAggregateState::MinI64(value) => {
            if let Some(input) = native_filtered_input_i64(input, row)? {
                *value = Some(value.map_or(input, |current| current.min(input)));
            }
        }
        NativeFilteredAggregateState::MaxI64(value) => {
            if let Some(input) = native_filtered_input_i64(input, row)? {
                *value = Some(value.map_or(input, |current| current.max(input)));
            }
        }
    }
    let _ = spec;
    Ok(())
}

fn native_filtered_input_is_some(input: &NativeFilteredBatchInput, row: usize) -> Result<bool> {
    Ok(match input {
        NativeFilteredBatchInput::AlwaysSome | NativeFilteredBatchInput::NonNull => true,
        NativeFilteredBatchInput::I64Array(values) => !values.is_null(row),
        NativeFilteredBatchInput::I32Array(values) => !values.is_null(row),
        NativeFilteredBatchInput::Other(value) => scalar_value_at(value, row)?.is_some(),
    })
}

fn native_filtered_input_i64(input: &NativeFilteredBatchInput, row: usize) -> Result<Option<i64>> {
    match input {
        NativeFilteredBatchInput::AlwaysSome | NativeFilteredBatchInput::NonNull => Ok(None),
        NativeFilteredBatchInput::I64Array(values) => {
            if values.is_null(row) {
                Ok(None)
            } else {
                Ok(Some(values.value(row)))
            }
        }
        NativeFilteredBatchInput::I32Array(values) => {
            if values.is_null(row) {
                Ok(None)
            } else {
                Ok(Some(i64::from(values.value(row))))
            }
        }
        NativeFilteredBatchInput::Other(value) => scalar_value_as_i64(value, row),
    }
}

fn native_filtered_finish_states(
    specs: &[NativeFilteredAggregateSpec],
    states: Vec<NativeFilteredAggregateState>,
) -> Vec<AggregateResult> {
    specs
        .iter()
        .zip(states)
        .map(|(spec, state)| AggregateResult {
            expr: spec.expr.clone(),
            value: match state {
                NativeFilteredAggregateState::Count(count) => AggregateValue::Count(count),
                NativeFilteredAggregateState::SumI64 { sum, count } => {
                    AggregateValue::Int64((count > 0).then_some(sum))
                }
                NativeFilteredAggregateState::AvgI64 { sum, count } => {
                    AggregateValue::Float64((count > 0).then_some(sum as f64 / count as f64))
                }
                NativeFilteredAggregateState::MinI64(value)
                | NativeFilteredAggregateState::MaxI64(value) => AggregateValue::Int64(value),
            },
        })
        .collect()
}

fn native_group_value_at(value: &EvaluatedScalar, row: usize) -> Result<GroupValue> {
    Ok(match scalar_value_at(value, row)? {
        Some(ScalarValue::Int64(value)) => GroupValue::Int64(Some(value)),
        Some(ScalarValue::Float64(value)) => GroupValue::Int64(Some(value as i64)),
        Some(ScalarValue::Utf8(value)) => GroupValue::Utf8(Some(value)),
        Some(ScalarValue::Date32(value)) => GroupValue::Date32(Some(value)),
        Some(ScalarValue::Decimal128(value, precision, scale)) => {
            GroupValue::Decimal128(Some(value), precision, scale)
        }
        None => GroupValue::Int64(None),
        Some(other) => {
            return Err(DodamError::UnsupportedSql(format!(
                "native filtered aggregate group key does not support {}",
                scalar_value_type_name(&other)
            )));
        }
    })
}

fn scalar_value_type_name(value: &ScalarValue) -> &'static str {
    match value {
        ScalarValue::Int64(_) => "INTEGER",
        ScalarValue::Float64(_) => "DOUBLE",
        ScalarValue::Decimal128(_, _, _) => "DECIMAL",
        ScalarValue::Utf8(_) => "VARCHAR",
        ScalarValue::Boolean(_) => "BOOLEAN",
        ScalarValue::Date32(_) => "DATE",
        ScalarValue::TimestampMillisecond(_) => "TIMESTAMP",
    }
}

#[allow(clippy::too_many_arguments)]
async fn try_collect_expression_aggregate_late_materialized(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    filter: Option<FilterExpr>,
    group_by: &[String],
    aggregates: &[AggregateExpr],
    expressions: &[ProjectionExpression],
    ordered_output: bool,
    output_limit: Option<usize>,
) -> Result<Option<AggregateMetrics>> {
    if !expression_aggregate_late_materialized_enabled() {
        return Ok(None);
    }
    let Some(filter) = filter else {
        return Ok(None);
    };
    let Some(group_keys) = group_key_exprs_for_aggregate(group_by, aggregates, expressions) else {
        return Ok(None);
    };
    if CoalesceKeyCountSumCollector::new(&group_keys, aggregates).is_none() {
        return Ok(None);
    }
    let payload_projection =
        expression_aggregate_payload_projection(&group_keys, aggregates, expressions);
    let Projection::Columns(payload_projected_columns) = &payload_projection else {
        return Ok(None);
    };
    let payload_projected_columns = payload_projected_columns.clone();
    let predicate_columns = filter.referenced_columns();
    let predicate_projection = Projection::Columns(predicate_columns.clone());
    let aggregates = aggregates.to_vec();
    let group_keys_for_state = group_keys.clone();
    let aggregates_for_state = aggregates.clone();
    let Some(partials) = engine
        .late_materialized_parquet_map_pruned_with_policy_view_dictionary_columns(
            path,
            batch_size,
            predicate_projection,
            payload_projection,
            expression_aggregate_dictionary_columns(&group_keys),
            Vec::new(),
            expression_aggregate_late_row_group_chunk(ordered_output, output_limit),
            LateMaterializationPolicy::selective_with_selector_run_ratio(
                expression_aggregate_late_max_selected_ratio(),
                expression_aggregate_late_max_selector_run_ratio(),
            )
            .with_io_cost_gate(!ordered_output && expression_aggregate_late_io_cost_gate_enabled()),
            move || {
                CoalesceKeyCountSumCollector::new_with_composite_hash(
                    &group_keys_for_state,
                    &aggregates_for_state,
                    !ordered_output,
                )
                .expect("expression aggregate late materialization precondition")
            },
            {
                let filter = filter.clone();
                let predicate_columns = predicate_columns.clone();
                move |view, selection, _collector: &mut CoalesceKeyCountSumCollector| {
                    if push_projected_view_filter_selection(
                        view,
                        &predicate_columns,
                        &filter,
                        selection,
                    )? {
                        return Ok(Some(()));
                    }
                    let mask = if let Some(mask) =
                        evaluate_projected_view_filter_mask(view, &predicate_columns, &filter)?
                    {
                        mask
                    } else {
                        if !expression_aggregate_row_at_time_fallback_enabled() {
                            return Ok(None);
                        }
                        let Some(batch) = view.try_record_batch() else {
                            return Ok(None);
                        };
                        evaluate_filter_mask(batch, &filter)?
                    };
                    push_boolean_mask_selection(&mask, selection);
                    Ok(Some(()))
                }
            },
            {
                let payload_projected_columns = payload_projected_columns.clone();
                move |view, collector: &mut CoalesceKeyCountSumCollector| {
                    if expression_aggregate_row_at_time_fallback_enabled() {
                        collector.consume_projected_view(view, &payload_projected_columns)?;
                    } else if !collector
                        .try_consume_projected_view_vectorized(view, &payload_projected_columns)?
                    {
                        return Ok(None);
                    }
                    Ok(Some(()))
                }
            },
            |collector, _metrics| Ok(Some(collector)),
        )
        .await?
    else {
        return Ok(None);
    };
    let collectors = partials
        .into_iter()
        .map(|partial| {
            log_expression_aggregate_late_profile(&partial.metrics);
            partial.output
        })
        .collect::<Vec<_>>();
    Ok(Some(
        CoalesceKeyCountSumCollector::merge_partials_with_order_and_output(
            collectors,
            1,
            &aggregates,
            Some(group_by),
            ordered_output,
            output_limit,
        )?,
    ))
}

#[allow(clippy::too_many_arguments)]
async fn try_collect_expression_aggregate_fused_dictionary_selected(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    filter: Option<FilterExpr>,
    group_by: &[String],
    aggregates: &[AggregateExpr],
    expressions: &[ProjectionExpression],
    ordered_output: bool,
    output_limit: Option<usize>,
) -> Result<Option<AggregateMetrics>> {
    let Some(filter) = filter else {
        return Ok(None);
    };
    let Some(group_keys) = group_key_exprs_for_aggregate(group_by, aggregates, expressions) else {
        return Ok(None);
    };
    let [
        GroupKeyExpr::Column(first_column),
        GroupKeyExpr::Column(second_column),
        GroupKeyExpr::CoalesceLiteral {
            column: dictionary_column,
            fallback: GroupKeyLiteral::Utf8(fallback),
        },
    ] = group_keys.as_slice()
    else {
        return Ok(None);
    };
    let [AggregateExpr::CountStar, AggregateExpr::Sum(sum_column)] = aggregates else {
        return Ok(None);
    };
    let Some((decimal_column, _precision, _decimal_scale, decimal_filter)) =
        expression_aggregate_decimal_filter(engine, &path, &filter).await?
    else {
        return Ok(None);
    };
    let forced_fused_selected = fused_dictionary_selected_aggregate_enabled();
    let auto_fused_selected = !forced_fused_selected
        && fused_dictionary_selected_aggregate_auto_accepts(
            engine,
            &path,
            &decimal_column,
            &decimal_filter,
        )?;
    if !forced_fused_selected && !auto_fused_selected {
        return Ok(None);
    }
    let row_groups = (0..engine.parquet_row_group_count(&path)?).collect::<Vec<_>>();
    let group_keys_for_state = group_keys.clone();
    let aggregates_for_state = aggregates.to_vec();
    let decimal_min = option_i128_to_i64_local(decimal_filter.decimal_min)?;
    let decimal_max = option_i128_to_i64_local(decimal_filter.decimal_max)?;
    let Some((collector, scan_metrics)) = engine
        .scan_parquet_i32_i32_dictionary_i64_decimal_selected_fold(
            path,
            batch_size,
            &row_groups,
            [
                first_column.as_str(),
                second_column.as_str(),
                dictionary_column.as_str(),
                sum_column.as_str(),
                decimal_column.as_str(),
            ],
            fallback.as_bytes(),
            decimal_min,
            decimal_max,
            auto_fused_selected.then(fused_dictionary_selected_auto_workers),
            || {
                CoalesceKeyCountSumCollector::new_with_composite_hash(
                    &group_keys_for_state,
                    &aggregates_for_state,
                    !ordered_output,
                )
                .expect("fused dictionary selected aggregate precondition")
            },
            |collector, batch| {
                if let Some((chunks, sums, selected_rows)) = batch.sum_chunk_ranges() {
                    collector.consume_i32_date_dictionary_i64_sum_chunk_ranges(
                        batch.first(),
                        batch.second(),
                        batch.dictionary_ids(),
                        batch.dictionary(),
                        chunks,
                        sums,
                        selected_rows,
                    )
                } else if let Some(selection) = batch.selection() {
                    collector.consume_i32_date_dictionary_i64_masked(
                        batch.first(),
                        batch.second(),
                        batch.dictionary_ids(),
                        batch.dictionary(),
                        batch.sums(),
                        selection,
                    )
                } else {
                    collector.consume_i32_date_dictionary_i64_slices(
                        batch.first(),
                        batch.second(),
                        batch.dictionary_ids(),
                        batch.dictionary(),
                        batch.sums(),
                    )
                }
            },
            |collector, partial| collector.merge_partial(partial),
        )?
    else {
        return Ok(None);
    };
    log_fused_dictionary_selected_profile(&scan_metrics);
    Ok(Some(
        CoalesceKeyCountSumCollector::merge_partials_with_order_and_output(
            vec![collector],
            1,
            aggregates,
            Some(group_by),
            ordered_output,
            output_limit,
        )?,
    ))
}

fn log_fused_dictionary_selected_profile(metrics: &DirectPrimitiveColumnScanMetrics) {
    if !std::env::var("DODAM_COALESCE_AGG_PROFILE")
        .is_ok_and(|value| matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES"))
    {
        return;
    }
    eprintln!(
        "[dodam:coalesce-agg-profile] fused_selected row_groups={} batches={} rows={} selected={} runs={} read={:.3}ms consume={:.3}ms predicate={:.3}ms payload={:.3}ms dictionary={:.3}ms full_payload_batches={} selected_payload_batches={} selected_read_rows={} selected_skipped_rows={}",
        metrics.row_groups,
        metrics.batches,
        metrics.rows,
        metrics.selected_rows,
        metrics.selected_runs,
        sql_nanos_to_millis(metrics.read_nanos),
        sql_nanos_to_millis(metrics.consume_nanos),
        sql_nanos_to_millis(metrics.selected_predicate_nanos),
        sql_nanos_to_millis(metrics.selected_payload_nanos),
        sql_nanos_to_millis(metrics.selected_dictionary_nanos),
        metrics.full_payload_batches,
        metrics.selected_payload_batches,
        metrics.selected_read_rows,
        metrics.selected_skipped_rows,
    );
}

#[allow(clippy::too_many_arguments)]
async fn try_collect_expression_aggregate_scan_fold(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    projection: Projection,
    filter: Option<FilterExpr>,
    group_by: &[String],
    aggregates: &[AggregateExpr],
    expressions: &[ProjectionExpression],
    ordered_output: bool,
    output_limit: Option<usize>,
) -> Result<Option<AggregateMetrics>> {
    if !expression_aggregate_scan_fold_enabled() {
        return Ok(None);
    }
    let Some(group_keys) = group_key_exprs_for_aggregate(group_by, aggregates, expressions) else {
        return Ok(None);
    };
    let Some(collector) = CoalesceKeyCountSumCollector::new_with_composite_hash(
        &group_keys,
        aggregates,
        !ordered_output,
    ) else {
        return Ok(None);
    };
    let mut projection = projection;
    if let Some(filter) = filter.as_ref() {
        add_projection_columns(&mut projection, filter.referenced_columns());
    }
    let Projection::Columns(projected_columns) = &projection else {
        return Ok(None);
    };
    let projected_columns = projected_columns.clone();
    let aggregates = aggregates.to_vec();
    let dictionary_columns = expression_aggregate_dictionary_columns(&group_keys);
    if !dictionary_columns.is_empty()
        && expression_aggregate_dictionary_scan_fold_enabled()
        && let Some(filter_for_dictionary) = filter.clone()
    {
        let predicates = PredicateSet::new(Some(filter_for_dictionary.clone()));
        let group_keys_for_state = group_keys.clone();
        let aggregates_for_state = aggregates.clone();
        if let Some(partials) = engine
            .parquet_row_group_map_dictionary_columns_pruned_view(
                path.clone(),
                batch_size,
                projection.clone(),
                dictionary_columns,
                predicates.pushdown().to_vec(),
                expression_aggregate_dictionary_scan_fold_row_group_chunk(),
                move || {
                    CoalesceKeyCountSumCollector::new_with_composite_hash(
                        &group_keys_for_state,
                        &aggregates_for_state,
                        !ordered_output,
                    )
                    .expect("expression aggregate dictionary scan-fold precondition")
                },
                {
                    let projected_columns = projected_columns.clone();
                    move |view, collector: &mut CoalesceKeyCountSumCollector| {
                        let mask = if let Some(mask) = evaluate_projected_view_filter_mask(
                            view,
                            &projected_columns,
                            &filter_for_dictionary,
                        )? {
                            mask
                        } else {
                            if !expression_aggregate_row_at_time_fallback_enabled() {
                                return Ok(None);
                            }
                            let Some(batch) = view.try_record_batch() else {
                                return Ok(None);
                            };
                            evaluate_filter_mask(batch, &filter_for_dictionary)?
                        };
                        if mask.true_count() == 0 {
                            return Ok(Some(()));
                        }
                        if expression_aggregate_row_at_time_fallback_enabled() {
                            collector.consume_projected_view_masked_with_record_batch_fallback(
                                view,
                                &projected_columns,
                                &mask,
                            )?;
                        } else if !collector.try_consume_projected_view_masked_vectorized(
                            view,
                            &projected_columns,
                            &mask,
                        )? {
                            return Ok(None);
                        }
                        Ok(Some(()))
                    }
                },
                |collector| Ok(Some(collector)),
            )
            .await?
        {
            return Ok(Some(
                CoalesceKeyCountSumCollector::merge_partials_with_order_and_output(
                    partials,
                    1,
                    &aggregates,
                    Some(group_by),
                    ordered_output,
                    output_limit,
                )?,
            ));
        }
    }
    let collector = engine
        .scan_parquet_batches_fold_view(
            path,
            batch_size,
            None,
            projection.clone(),
            filter,
            collector,
            move |view, collector| collector.consume_projected_view(view, &projected_columns),
            Ok,
        )
        .await?;
    Ok(Some(
        CoalesceKeyCountSumCollector::merge_partials_with_order_and_output(
            vec![collector],
            1,
            &aggregates,
            Some(group_by),
            ordered_output,
            output_limit,
        )?,
    ))
}

fn expression_aggregate_output_limit(
    group_by: &[String],
    order_by: Option<&SortKey>,
    limit: Option<usize>,
    offset: usize,
) -> Option<usize> {
    let limit = limit?;
    if offset != 0 || !aggregate_order_by_prefix_matches(group_by, order_by) {
        return None;
    }
    Some(limit)
}

fn aggregate_order_by_prefix_matches(group_by: &[String], order_by: Option<&SortKey>) -> bool {
    let Some(order_by) = order_by else {
        return false;
    };
    if order_by.expressions.is_empty() || order_by.expressions.len() > group_by.len() {
        return false;
    }
    order_by
        .expressions
        .iter()
        .zip(group_by)
        .all(|(sort, group)| !sort.descending && !sort.nulls_first && sort.column == *group)
}

#[allow(dead_code)]
fn evaluate_filter_mask_for_projected_view(
    view: BatchView<'_>,
    columns: &[String],
    filter: &FilterExpr,
) -> Result<Option<BooleanArray>> {
    evaluate_expr_mask_for_projected_view(view, columns, filter.expr())
}

fn push_projected_view_filter_selection(
    view: BatchView<'_>,
    columns: &[String],
    filter: &FilterExpr,
    selection: &mut LateSelectionBuilder,
) -> Result<bool> {
    if std::env::var("DODAM_DISABLE_DIRECT_LATE_SELECTION")
        .is_ok_and(|value| matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES"))
    {
        return Ok(false);
    }
    push_projected_view_expr_selection(view, columns, filter.expr(), selection)
}

fn push_boolean_mask_selection(mask: &BooleanArray, selection: &mut LateSelectionBuilder) {
    if mask.true_count() == 0 {
        selection.push_repeated(mask.len(), false);
        return;
    }
    if mask.true_count() == mask.len() && mask.null_count() == 0 {
        selection.push_repeated(mask.len(), true);
        return;
    }
    selection.push_selected_offsets(
        mask.len(),
        (0..mask.len()).filter(|row| mask.is_valid(*row) && mask.value(*row)),
    );
}

fn push_projected_view_expr_selection(
    view: BatchView<'_>,
    columns: &[String],
    expr: &Expr,
    selection: &mut LateSelectionBuilder,
) -> Result<bool> {
    match expr {
        Expr::Boolean(value) => {
            let value = value.unwrap_or(false);
            selection.push_repeated(view.num_rows(), value);
            Ok(true)
        }
        Expr::Comparison(comparison) => {
            push_comparison_selection_for_projected_view(view, columns, comparison, selection)
        }
        Expr::InList {
            column,
            values,
            negated,
            has_null,
        } => push_in_list_selection_for_projected_view(
            view, columns, column, values, *negated, *has_null, selection,
        ),
        Expr::Not(_)
        | Expr::And(_, _)
        | Expr::Or(_, _)
        | Expr::ColumnComparison { .. }
        | Expr::Like { .. }
        | Expr::IsNull { .. } => Ok(false),
    }
}

fn push_comparison_selection_for_projected_view(
    view: BatchView<'_>,
    columns: &[String],
    comparison: &ComparisonExpr,
    selection: &mut LateSelectionBuilder,
) -> Result<bool> {
    if matches!(comparison.value, LiteralValue::Null) {
        selection.push_repeated(view.num_rows(), false);
        return Ok(true);
    }
    let Some(index) = projected_view_column_index(columns, &comparison.column) else {
        return Ok(false);
    };
    if let Some(values) = view.i64_vector(index) {
        let literal = comparison.value.as_i64(&comparison.column)?;
        if let Some(raw) = values.values_if_null_free() {
            selection.push_selected_offsets(
                raw.len(),
                raw.iter().enumerate().filter_map(|(row, value)| {
                    compare_i64(*value, comparison.op, literal).then_some(row)
                }),
            );
        } else if let Some((data, len)) = values.raw_bytes() {
            selection.push_selected_offsets(
                len,
                (0..len).filter(|row| {
                    compare_i64(read_i64_le_unaligned(data, *row), comparison.op, literal)
                }),
            );
        } else {
            selection.push_selected_offsets(
                values.len(),
                (0..values.len()).filter(|row| {
                    !values.is_null(*row) && compare_i64(values.value(*row), comparison.op, literal)
                }),
            );
        }
        return Ok(true);
    }
    if let Some(values) = view.i32_vector(index) {
        let literal = comparison.value.as_i32(&comparison.column)?;
        if let Some(raw) = values.values_if_null_free() {
            selection.push_selected_offsets(
                raw.len(),
                raw.iter().enumerate().filter_map(|(row, value)| {
                    compare_i32(*value, comparison.op, literal).then_some(row)
                }),
            );
        } else if let Some((data, len)) = values.raw_bytes() {
            selection.push_selected_offsets(
                len,
                (0..len).filter(|row| {
                    compare_i32(read_i32_le_unaligned(data, *row), comparison.op, literal)
                }),
            );
        } else {
            selection.push_selected_offsets(
                values.len(),
                (0..values.len()).filter(|row| {
                    !values.is_null(*row) && compare_i32(values.value(*row), comparison.op, literal)
                }),
            );
        }
        return Ok(true);
    }
    if let Some(values) = view.date32_vector(index) {
        let Some(literal) = literal_as_date32_for_type(&comparison.value)? else {
            return Ok(false);
        };
        if let Some(raw) = values.values_if_null_free() {
            selection.push_selected_offsets(
                raw.len(),
                raw.iter().enumerate().filter_map(|(row, value)| {
                    compare_i32(*value, comparison.op, literal).then_some(row)
                }),
            );
        } else if let Some((data, len)) = values.raw_bytes() {
            selection.push_selected_offsets(
                len,
                (0..len).filter(|row| {
                    compare_i32(read_i32_le_unaligned(data, *row), comparison.op, literal)
                }),
            );
        } else {
            selection.push_selected_offsets(
                values.len(),
                (0..values.len()).filter(|row| {
                    !values.is_null(*row) && compare_i32(values.value(*row), comparison.op, literal)
                }),
            );
        }
        return Ok(true);
    }
    if let Some(values) = view.decimal128_vector(index) {
        let Some(literal) = literal_to_decimal_scaled(&comparison.value, values.scale_i64())?
        else {
            return Ok(false);
        };
        if let Some(raw) = values.raw_i64_values() {
            selection.push_selected_offsets(
                raw.len(),
                raw.iter().enumerate().filter_map(|(row, value)| {
                    (!values.is_null(row)
                        && compare_i128(i128::from(*value), comparison.op, literal))
                    .then_some(row)
                }),
            );
        } else if let Some((data, len)) = values.raw_i64_bytes() {
            selection.push_selected_offsets(
                len,
                (0..len).filter(|row| {
                    compare_i128(
                        i128::from(read_i64_le_unaligned(data, *row)),
                        comparison.op,
                        literal,
                    )
                }),
            );
        } else {
            let raw = values.raw_values();
            selection.push_selected_offsets(
                raw.len(),
                raw.iter().enumerate().filter_map(|(row, value)| {
                    (!values.is_null(row) && compare_i128(*value, comparison.op, literal))
                        .then_some(row)
                }),
            );
        }
        return Ok(true);
    }
    Ok(false)
}

fn push_in_list_selection_for_projected_view(
    view: BatchView<'_>,
    columns: &[String],
    column: &str,
    values: &[LiteralValue],
    negated: bool,
    has_null: bool,
    selection: &mut LateSelectionBuilder,
) -> Result<bool> {
    let Some(index) = projected_view_column_index(columns, column) else {
        return Ok(false);
    };
    if let Some(probe) = view.i64_vector(index) {
        let values = values
            .iter()
            .filter(|value| !matches!(value, LiteralValue::Null))
            .map(|value| value.as_i64(column))
            .collect::<Result<Vec<_>>>()?;
        if let Some(raw) = probe.values_if_null_free() {
            selection.push_selected_offsets(
                raw.len(),
                raw.iter().enumerate().filter_map(|(row, value)| {
                    selected_in_list_result(
                        small_in_list_match_i64(*value, &values),
                        negated,
                        has_null,
                    )
                    .then_some(row)
                }),
            );
        } else {
            selection.push_selected_offsets(
                probe.len(),
                (0..probe.len()).filter(|row| {
                    !probe.is_null(*row)
                        && selected_in_list_result(
                            small_in_list_match_i64(probe.value(*row), &values),
                            negated,
                            has_null,
                        )
                }),
            );
        }
        return Ok(true);
    }
    if let Some(probe) = view.i32_vector(index) {
        let values = values
            .iter()
            .filter(|value| !matches!(value, LiteralValue::Null))
            .map(|value| value.as_i32(column))
            .collect::<Result<Vec<_>>>()?;
        if let Some(raw) = probe.values_if_null_free() {
            selection.push_selected_offsets(
                raw.len(),
                raw.iter().enumerate().filter_map(|(row, value)| {
                    selected_in_list_result(
                        small_in_list_match_i32(*value, &values),
                        negated,
                        has_null,
                    )
                    .then_some(row)
                }),
            );
        } else {
            selection.push_selected_offsets(
                probe.len(),
                (0..probe.len()).filter(|row| {
                    !probe.is_null(*row)
                        && selected_in_list_result(
                            small_in_list_match_i32(probe.value(*row), &values),
                            negated,
                            has_null,
                        )
                }),
            );
        }
        return Ok(true);
    }
    Ok(false)
}

fn evaluate_expr_mask_for_projected_view(
    view: BatchView<'_>,
    columns: &[String],
    expr: &Expr,
) -> Result<Option<BooleanArray>> {
    match expr {
        Expr::Boolean(value) => Ok(Some(BooleanArray::from(vec![*value; view.num_rows()]))),
        Expr::Comparison(comparison) => {
            evaluate_comparison_mask_for_projected_view(view, columns, comparison)
        }
        Expr::InList {
            column,
            values,
            negated,
            has_null,
        } => evaluate_in_list_mask_for_projected_view(
            view, columns, column, values, *negated, *has_null,
        ),
        Expr::Not(expr) => {
            let Some(mask) = evaluate_expr_mask_for_projected_view(view, columns, expr)? else {
                return Ok(None);
            };
            Ok(Some(boolean_not(&mask)))
        }
        Expr::And(left, right) => {
            let Some(left) = evaluate_expr_mask_for_projected_view(view, columns, left)? else {
                return Ok(None);
            };
            let Some(right) = evaluate_expr_mask_for_projected_view(view, columns, right)? else {
                return Ok(None);
            };
            Ok(Some(boolean_and(&left, &right)))
        }
        Expr::Or(left, right) => {
            let Some(left) = evaluate_expr_mask_for_projected_view(view, columns, left)? else {
                return Ok(None);
            };
            let Some(right) = evaluate_expr_mask_for_projected_view(view, columns, right)? else {
                return Ok(None);
            };
            Ok(Some(boolean_or(&left, &right)))
        }
        Expr::ColumnComparison { .. } | Expr::Like { .. } | Expr::IsNull { .. } => Ok(None),
    }
}

fn evaluate_comparison_mask_for_projected_view(
    view: BatchView<'_>,
    columns: &[String],
    comparison: &ComparisonExpr,
) -> Result<Option<BooleanArray>> {
    if matches!(comparison.value, LiteralValue::Null) {
        return Ok(Some(BooleanArray::from(vec![None; view.num_rows()])));
    }
    let Some(index) = projected_view_column_index(columns, &comparison.column) else {
        return Ok(None);
    };
    if let Some(values) = view.i64_vector(index) {
        let value = comparison.value.as_i64(&comparison.column)?;
        return Ok(Some(compare_i64_view(values, comparison.op, value)));
    }
    if let Some(values) = view.i32_vector(index) {
        let value = comparison.value.as_i32(&comparison.column)?;
        return Ok(Some(compare_i32_view(values, comparison.op, value)));
    }
    if let Some(values) = view.date32_vector(index) {
        let Some(value) = literal_as_date32_for_type(&comparison.value)? else {
            return Ok(None);
        };
        return Ok(Some(compare_date32_view(values, comparison.op, value)));
    }
    if let Some(values) = view.decimal128_vector(index) {
        let Some(value) = literal_to_decimal_scaled(&comparison.value, values.scale_i64())? else {
            return Ok(None);
        };
        return Ok(Some(compare_decimal128_view(values, comparison.op, value)));
    }
    Ok(None)
}

fn evaluate_in_list_mask_for_projected_view(
    view: BatchView<'_>,
    columns: &[String],
    column: &str,
    values: &[LiteralValue],
    negated: bool,
    has_null: bool,
) -> Result<Option<BooleanArray>> {
    let Some(index) = projected_view_column_index(columns, column) else {
        return Ok(None);
    };
    if let Some(probe) = view.i64_vector(index) {
        let values = values
            .iter()
            .filter(|value| !matches!(value, LiteralValue::Null))
            .map(|value| value.as_i64(column))
            .collect::<Result<Vec<_>>>()?;
        return Ok(Some(in_list_i64_view(probe, &values, negated, has_null)));
    }
    if let Some(probe) = view.i32_vector(index) {
        let values = values
            .iter()
            .filter(|value| !matches!(value, LiteralValue::Null))
            .map(|value| value.as_i32(column))
            .collect::<Result<Vec<_>>>()?;
        return Ok(Some(in_list_i32_view(probe, &values, negated, has_null)));
    }
    Ok(None)
}

fn projected_view_column_index(columns: &[String], column: &str) -> Option<usize> {
    columns.iter().position(|candidate| candidate == column)
}

fn compare_i64_view(values: I64VectorView<'_>, op: ComparisonOp, literal: i64) -> BooleanArray {
    if let Some(raw) = values.values_if_null_free() {
        return boolean_array_no_nulls_from_len(raw.len(), |row| {
            compare_i64(raw[row], op, literal)
        });
    }
    if let Some((data, len)) = values.raw_bytes() {
        return boolean_array_no_nulls_from_i64_bytes(data, len, |value| {
            compare_i64(value, op, literal)
        });
    }
    let mut output = BooleanBuilder::with_capacity(values.len());
    for row in 0..values.len() {
        if values.is_null(row) {
            output.append_null();
        } else {
            output.append_value(compare_i64(values.value(row), op, literal));
        }
    }
    output.finish()
}

fn compare_i32_view(values: I32VectorView<'_>, op: ComparisonOp, literal: i32) -> BooleanArray {
    if let Some(raw) = values.values_if_null_free() {
        return boolean_array_no_nulls_from_len(raw.len(), |row| {
            compare_i32(raw[row], op, literal)
        });
    }
    if let Some((data, len)) = values.raw_bytes() {
        return boolean_array_no_nulls_from_i32_bytes(data, len, |value| {
            compare_i32(value, op, literal)
        });
    }
    let mut output = BooleanBuilder::with_capacity(values.len());
    for row in 0..values.len() {
        if values.is_null(row) {
            output.append_null();
        } else {
            output.append_value(compare_i32(values.value(row), op, literal));
        }
    }
    output.finish()
}

fn compare_date32_view(
    values: Date32VectorView<'_>,
    op: ComparisonOp,
    literal: i32,
) -> BooleanArray {
    if let Some(raw) = values.values_if_null_free() {
        return boolean_array_no_nulls_from_len(raw.len(), |row| {
            compare_i32(raw[row], op, literal)
        });
    }
    if let Some((data, len)) = values.raw_bytes() {
        return boolean_array_no_nulls_from_i32_bytes(data, len, |value| {
            compare_i32(value, op, literal)
        });
    }
    let mut output = BooleanBuilder::with_capacity(values.len());
    for row in 0..values.len() {
        if values.is_null(row) {
            output.append_null();
        } else {
            output.append_value(compare_i32(values.value(row), op, literal));
        }
    }
    output.finish()
}

fn compare_decimal128_view(
    values: Decimal128VectorView<'_>,
    op: ComparisonOp,
    literal: i128,
) -> BooleanArray {
    let mut output = BooleanBuilder::with_capacity(values_len_decimal128(values));
    if let Some(raw) = values.raw_i64_values() {
        for row in 0..raw.len() {
            if values.is_null(row) {
                output.append_null();
            } else {
                output.append_value(compare_i128(i128::from(raw[row]), op, literal));
            }
        }
    } else if let Some((data, len)) = values.raw_i64_bytes() {
        for row in 0..len {
            output.append_value(compare_i128(
                i128::from(read_i64_le_unaligned(data, row)),
                op,
                literal,
            ));
        }
    } else {
        let raw = values.raw_values();
        for row in 0..raw.len() {
            if values.is_null(row) {
                output.append_null();
            } else {
                output.append_value(compare_i128(raw[row], op, literal));
            }
        }
    }
    output.finish()
}

fn values_len_decimal128(values: Decimal128VectorView<'_>) -> usize {
    values.len()
}

fn in_list_i64_view(
    values: I64VectorView<'_>,
    list: &[i64],
    negated: bool,
    has_null: bool,
) -> BooleanArray {
    if !has_null && let Some(raw) = values.values_if_null_free() {
        return boolean_array_no_nulls_from_len(raw.len(), |row| {
            selected_in_list_result(small_in_list_match_i64(raw[row], list), negated, false)
        });
    }
    if !has_null && let Some((data, len)) = values.raw_bytes() {
        return boolean_array_no_nulls_from_i64_bytes(data, len, |value| {
            selected_in_list_result(small_in_list_match_i64(value, list), negated, false)
        });
    }
    let mut output = BooleanBuilder::with_capacity(values.len());
    for row in 0..values.len() {
        if values.is_null(row) {
            output.append_null();
            continue;
        }
        append_in_list_result(
            &mut output,
            small_in_list_match_i64(values.value(row), list),
            negated,
            has_null,
        );
    }
    output.finish()
}

fn in_list_i32_view(
    values: I32VectorView<'_>,
    list: &[i32],
    negated: bool,
    has_null: bool,
) -> BooleanArray {
    if !has_null && let Some(raw) = values.values_if_null_free() {
        return boolean_array_no_nulls_from_len(raw.len(), |row| {
            selected_in_list_result(small_in_list_match_i32(raw[row], list), negated, false)
        });
    }
    if !has_null && let Some((data, len)) = values.raw_bytes() {
        return boolean_array_no_nulls_from_i32_bytes(data, len, |value| {
            selected_in_list_result(small_in_list_match_i32(value, list), negated, false)
        });
    }
    let mut output = BooleanBuilder::with_capacity(values.len());
    for row in 0..values.len() {
        if values.is_null(row) {
            output.append_null();
            continue;
        }
        append_in_list_result(
            &mut output,
            small_in_list_match_i32(values.value(row), list),
            negated,
            has_null,
        );
    }
    output.finish()
}

fn small_in_list_match_i64(value: i64, list: &[i64]) -> bool {
    match list {
        [] => false,
        [a] => value == *a,
        [a, b] => value == *a || value == *b,
        [a, b, c] => value == *a || value == *b || value == *c,
        [a, b, c, d] => value == *a || value == *b || value == *c || value == *d,
        _ => list.contains(&value),
    }
}

fn small_in_list_match_i32(value: i32, list: &[i32]) -> bool {
    match list {
        [] => false,
        [a] => value == *a,
        [a, b] => value == *a || value == *b,
        [a, b, c] => value == *a || value == *b || value == *c,
        [a, b, c, d] => value == *a || value == *b || value == *c || value == *d,
        _ => list.contains(&value),
    }
}

fn append_in_list_result(
    output: &mut BooleanBuilder,
    matched: bool,
    negated: bool,
    has_null: bool,
) {
    if matched {
        output.append_value(!negated);
    } else if has_null {
        output.append_null();
    } else {
        output.append_value(negated);
    }
}

fn selected_in_list_result(matched: bool, negated: bool, has_null: bool) -> bool {
    if matched {
        !negated
    } else if has_null {
        false
    } else {
        negated
    }
}

fn boolean_array_no_nulls_from_len(
    len: usize,
    mut value_at: impl FnMut(usize) -> bool,
) -> BooleanArray {
    let mut values = BooleanBufferBuilder::new(len);
    for row in 0..len {
        values.append(value_at(row));
    }
    BooleanArray::new(values.build(), None)
}

fn boolean_array_no_nulls_from_i32_bytes(
    data: &[u8],
    len: usize,
    mut value_at: impl FnMut(i32) -> bool,
) -> BooleanArray {
    debug_assert!(data.len() >= len.saturating_mul(std::mem::size_of::<i32>()));
    let mut values = BooleanBufferBuilder::new(len);
    for row in 0..len {
        values.append(value_at(read_i32_le_unaligned(data, row)));
    }
    BooleanArray::new(values.build(), None)
}

fn boolean_array_no_nulls_from_i64_bytes(
    data: &[u8],
    len: usize,
    mut value_at: impl FnMut(i64) -> bool,
) -> BooleanArray {
    debug_assert!(data.len() >= len.saturating_mul(std::mem::size_of::<i64>()));
    let mut values = BooleanBufferBuilder::new(len);
    for row in 0..len {
        values.append(value_at(read_i64_le_unaligned(data, row)));
    }
    BooleanArray::new(values.build(), None)
}

fn compare_i64(left: i64, op: ComparisonOp, right: i64) -> bool {
    match op {
        ComparisonOp::Eq => left == right,
        ComparisonOp::NotEq => left != right,
        ComparisonOp::Lt => left < right,
        ComparisonOp::LtEq => left <= right,
        ComparisonOp::Gt => left > right,
        ComparisonOp::GtEq => left >= right,
    }
}

fn compare_i32(left: i32, op: ComparisonOp, right: i32) -> bool {
    compare_i64(i64::from(left), op, i64::from(right))
}

fn compare_i128(left: i128, op: ComparisonOp, right: i128) -> bool {
    match op {
        ComparisonOp::Eq => left == right,
        ComparisonOp::NotEq => left != right,
        ComparisonOp::Lt => left < right,
        ComparisonOp::LtEq => left <= right,
        ComparisonOp::Gt => left > right,
        ComparisonOp::GtEq => left >= right,
    }
}

fn literal_to_decimal_scaled(
    value: &LiteralValue,
    scale_factor: Option<i64>,
) -> Result<Option<i128>> {
    let Some(scale_factor) = scale_factor else {
        return Ok(None);
    };
    match value {
        LiteralValue::Null => Ok(None),
        LiteralValue::Int64(value) => Ok(i128::from(*value)
            .checked_mul(i128::from(scale_factor))
            .map(Some)
            .unwrap_or(None)),
        LiteralValue::Float64(value) => {
            decimal_literal_to_scaled_factor(&value.to_string(), scale_factor)
        }
        LiteralValue::Utf8(value) => decimal_literal_to_scaled_factor(value, scale_factor),
        LiteralValue::Boolean(_) => Ok(None),
    }
}

fn decimal_literal_to_scaled_factor(value: &str, scale_factor: i64) -> Result<Option<i128>> {
    let Some(scale_digits) = decimal_scale_digits(scale_factor) else {
        return Ok(None);
    };
    let value = value.trim();
    let negative = value.starts_with('-');
    let unsigned = value.strip_prefix(['-', '+']).unwrap_or(value);
    let (whole, fractional) = unsigned.split_once('.').unwrap_or((unsigned, ""));
    if whole.is_empty() || !whole.chars().all(|ch| ch.is_ascii_digit()) {
        return Ok(None);
    }
    if !fractional.chars().all(|ch| ch.is_ascii_digit()) {
        return Ok(None);
    }
    let mut scaled = whole
        .parse::<i128>()
        .map_err(|_| DodamError::InvalidCast(format!("decimal literal {value} is out of range")))?;
    scaled = scaled
        .checked_mul(i128::from(scale_factor))
        .ok_or_else(|| DodamError::InvalidCast("decimal literal overflow".to_string()))?;
    let kept = &fractional[..fractional.len().min(scale_digits)];
    let mut frac = if kept.is_empty() {
        0
    } else {
        kept.parse::<i128>().map_err(|_| {
            DodamError::InvalidCast(format!("decimal literal {value} is out of range"))
        })?
    };
    for _ in kept.len()..scale_digits {
        frac *= 10;
    }
    scaled = scaled
        .checked_add(frac)
        .ok_or_else(|| DodamError::InvalidCast("decimal literal overflow".to_string()))?;
    Ok(Some(if negative { -scaled } else { scaled }))
}

fn decimal_scale_digits(mut scale_factor: i64) -> Option<usize> {
    if scale_factor <= 0 {
        return None;
    }
    let mut digits = 0usize;
    while scale_factor > 1 {
        if scale_factor % 10 != 0 {
            return None;
        }
        scale_factor /= 10;
        digits += 1;
    }
    Some(digits)
}

#[allow(clippy::too_many_arguments)]
async fn try_collect_expression_aggregate_row_group_map(
    engine: &DodamEngine,
    path: PathBuf,
    batch_size: usize,
    projection: Projection,
    filter: Option<FilterExpr>,
    group_by: &[String],
    aggregates: &[AggregateExpr],
    expressions: &[ProjectionExpression],
) -> Result<Option<AggregateMetrics>> {
    if !expression_aggregate_row_group_map_enabled() {
        return Ok(None);
    }
    let Some(group_keys) = group_key_exprs_for_aggregate(group_by, aggregates, expressions) else {
        return Ok(None);
    };
    let mut projection = projection;
    if let Some(filter) = filter.as_ref() {
        add_projection_columns(&mut projection, filter.referenced_columns());
    }
    let aggregates = aggregates.to_vec();
    let group_keys_for_state = group_keys.clone();
    let aggregates_for_state = aggregates.clone();
    let Some(partials) = engine
        .parquet_row_group_map_pruned(
            path,
            batch_size,
            projection,
            Vec::new(),
            expression_aggregate_row_group_map_chunk(),
            move || {
                CoalesceKeyCountSumCollector::new(&group_keys_for_state, &aggregates_for_state)
                    .expect("expression aggregate row-group map precondition")
            },
            {
                let filter = filter.clone();
                move |batch, collector: &mut CoalesceKeyCountSumCollector| {
                    let batch = if let Some(filter) = filter.as_ref() {
                        filter_batch(batch, filter)?
                    } else {
                        batch
                    };
                    if batch.num_rows() > 0 {
                        collector.consume_batch(&batch)?;
                    }
                    Ok(Some(()))
                }
            },
            |collector| Ok(Some(collector)),
        )
        .await?
    else {
        return Ok(None);
    };
    Ok(Some(CoalesceKeyCountSumCollector::merge_partials(
        partials,
        1,
        &aggregates,
    )?))
}

